def ot_master_transform(x):
    """Operator-theory re-encoding of the master bus (gated, default off).

    Deterministic float64 whole-buffer map of the book's nested dynamics:
    band-hop add (rule e), Meum residual refinement (rule f), negative-run
    composition (rule 1).  NO peak normalization and NO soft-clip saturation.
    """
    x = np.asarray(x, dtype=np.float64)
    n = x.size
    if n == 0:
        return x.astype(np.float32)
    band = np.select(
        [np.abs(x) <= 1.0, np.abs(x) <= 2.0, np.abs(x) <= 3.0],
        [1.0, 2.0, 3.0],
        default=1.0,
    )
    hop = np.sign(x) * band
    out = x + 0.35 * hop
    # Nested Meum residual factor (no unit-ceiling division).
    out = out * (1.0 + MEUM_NORM * 0.15 / (1.0 + np.abs(out)))
    prev = np.empty_like(out)
    prev[0] = out[0]
    prev[1:] = out[:-1]
    negrun = (out < 0.0) & (prev < 0.0)
    out = np.where(negrun, -np.abs(out) * 1.15, out)
    return out.astype(np.float32)


def book_isn_envelope_shape(u, decay):
    """Smart isn()-based PKP envelope over one step (u∈[0,1] = one step).

    Balanced to *fit a step*: starts/ends at 0 when the shape is cyclic or
    two-step (no bleed into the next step); sustain mode holds through the
    step end.  Peak is balanced to 1.0 so all decay settings share the same
    crest.  Mean level is gently equalized so 0 / 0.5 / 1 do not jump in loudness.

    decay ∈ [0,1]:
      0.0 → single isn() cycle over the step (θ: 0→2π).
      0.5 → 2-step: isn ramp [0→0.5], solid mid, isn release [1.5→2].
      1.0 → isn cycle then flat sustain to the end of the step/row.
    """
    u = np.asarray(u, dtype=np.float64)
    # Clamp into the open-closed step unit interval.
    u = np.clip(u, 0.0, 1.0)
    d = float(np.clip(decay, 0.0, 1.0))

    def _isn_cycle(uu):
        # Full book-isn cycle fits exactly in the step: 0 at edges, 1 at mid.
        theta = uu * 2.0 * np.pi
        return book_isn_vec(theta) * 0.5

    def _two_step(uu):
        # Phase domain p∈[0,2] mapped from the step — edges at 0.
        p = uu * 2.0
        env = np.zeros_like(p)
        m = p <= 0.5
        env[m] = book_isn_vec((p[m] / 0.5) * np.pi) * 0.5
        m = (p > 0.5) & (p < 1.5)
        env[m] = 1.0
        m = p >= 1.5
        env[m] = book_isn_vec(np.pi - ((p[m] - 1.5) / 0.5) * np.pi) * 0.5
        return env

    def _cycle_then_sustain(uu, cycle_frac=0.35):
        # isn attack fits the first fraction of the step; solid hold to step end.
        env = np.ones_like(uu)
        m = uu <= cycle_frac
        if np.any(m):
            env[m] = _isn_cycle(uu[m] / max(cycle_frac, 1e-9))
        return env

    if d <= 1e-9:
        shape = _isn_cycle(u)
    elif d >= 1.0 - 1e-9:
        shape = _cycle_then_sustain(u)
    elif d <= 0.5:
        a = d / 0.5
        shape = (1.0 - a) * _isn_cycle(u) + a * _two_step(u)
    else:
        a = (d - 0.5) / 0.5
        shape = (1.0 - a) * _two_step(u) + a * _cycle_then_sustain(u)

    # Balance crest to 1.0 so every decay setting fits the same step height.
    peak = float(np.max(shape)) if shape.size else 1.0
    if peak > 1e-12:
        shape = shape / peak
    # Soft mean balance toward ~0.5 so step energy is comparable across morphs
    # without a hard equalizer (scale only, no compression).
    mean = float(np.mean(shape)) if shape.size else 0.5
    if mean > 1e-12:
        target_mean = 0.50
        bal = target_mean / mean
        # Keep peak ≤ 1 after balance.
        bal = min(bal, 1.0 / max(float(np.max(shape)), 0.0))
        shape = shape * bal
    return shape.astype(np.float32)


def build_master_follow_env(
    master,
    bpm,
    sample_rate,
    pkp_envelope,
    row_length_samples=None,
    step_length_samples=None,
):
    """PKP isn envelope shared by EQR, Fractallizer, and PKP master stages.

    Balanced to fit a playlist STEP (16th / quarter-beat) by default so each
    envelope cycle lands cleanly on the step grid with no phase drift:

      0.0 = one isn() cycle per step
      0.5 = 2-step isn ramp / solid / isn release, still one shape per step
      1.0 = isn cycle then flat sustain; tile length grows toward row length

    Tile length morphs with decay: step at 0 → row at 1 (when row is known),
    so the envelope always *fits* an integer number of tiles in the buffer
    as closely as possible.  No peak-norm.
    """
    m = np.asarray(master, dtype=np.float64).ravel()
    n = m.size
    if n == 0:
        return np.ones(1, dtype=np.float32)

    raw = float(pkp_envelope)
    if raw > 1.0:
        decay = max(0.0, min(1.0, raw / 1000.0))
    else:
        decay = max(0.0, min(1.0, raw))

    # Canonical step = one 16th (quarter of a beat) from BPM/SR.
    sr = max(float(sample_rate), 1.0)
    bpm_f = float(bpm)
    if not math.isfinite(bpm_f) or bpm_f <= 0.0:
        bpm_f = 120.0
    beat_samples = sr * (60.0 / bpm_f)
    default_step = max(1, int(round(beat_samples / 4.0)))
    step = max(1, int(step_length_samples)) if step_length_samples else default_step
    row = max(step, int(row_length_samples)) if row_length_samples else max(step, default_step * 16)

    # Decay morphs tile length: step (0) → row (1).  Always ≥ step.
    tile = int(round(step + decay * (row - step)))
    tile = max(step, min(n, tile))

    # Snap tile so an integer number of tiles fills the buffer when possible
    # (balance: no orphan partial cycle mid-buffer on exact grid lengths).
    if tile > 1 and n >= tile:
        n_tiles = max(1, int(round(n / float(tile))))
        snapped = max(step, int(round(n / float(n_tiles))))
        # Prefer snapped only when close to intended tile (keeps step/row intent).
        if abs(snapped - tile) <= max(1, tile // 16):
            tile = snapped

    env = np.empty(n, dtype=np.float32)
    pos = 0
    while pos < n:
        hi = min(n, pos + tile)
        seg_n = hi - pos
        # Full 0→1 span over this tile so the isn shape always completes
        # (fits the step/tile even on a short final remainder).
        u = np.linspace(0.0, 1.0, seg_n, endpoint=False)
        env[pos:hi] = book_isn_envelope_shape(u, decay)
        pos = hi
    return env

# ---------------------------------------------------------------------------
# DETERMINISTIC COMPOSITION KERNEL
# ---------------------------------------------------------------------------
# Processor syntax is intentionally uniform:
#   canonical_input -> labelled hash/residue -> bounded transform -> consumer.
# A processor never uses process-global random state for identity-bearing data.
# The cyclic residue is a group-theoretic index; the affine permutation below
# is a bijection on Z/n whenever gcd(a,n)=1, which prevents duplicate indices
# inside a finite orbit while still allowing every seed to choose a new orbit.
def deterministic_u64(*parts):
    """Return a platform-stable 64-bit digest for identity-bearing state."""
    payload = "|".join(str(p) for p in parts).encode("utf-8")
    return int.from_bytes(hashlib.sha256(payload).digest()[:8], "big")

def cyclic_permutation(length, key):
    """Return a non-repeating orbit of Z/n using p(i)=a*i+b (mod n)."""
    n = max(1, int(length))
    if n == 1:
        return [0]
    a = 1 + int(key) % (n - 1)
    while math.gcd(a, n) != 1:
        a = (a + 1) % n or 1
    b = (int(key) >> 16) % n
    return [(a * i + b) % n for i in range(n)]

def group_orbit_index(index, order, seed, goava=False):
    """Map an ordinal to a seed-stable cyclic-group residue."""
    n = max(1, int(order))
    if n == 1:
        return 0
    key = deterministic_u64("group-orbit", _safe_int_seed(seed), n, int(bool(goava)))
    perm = cyclic_permutation(n, key)
    return perm[int(index) % n]

# UI design tokens derived from M (self-similar spacing / translucency)
UI_OPACITY = max(1.0, min(0.0, MEUM_NORM * PHI))          # pane glass
UI_RADIUS = max(4, int(round(3.0 * MEUM)))                    # corner radius
UI_TICK_MS = max(48, int(round(1000.0 / (MEUM_TWO_POW * 5.0))))  # decor frame period (perf: fewer background paints)
UI_DRIFT = MEUM_NORM * PHI_INV                                  # caption micro-wiggle scale
PAINT_RATE_HZ = 2.395                                           # max single-cell stack rate
PAINT_PERIOD_S = 1.0 / PAINT_RATE_HZ                            # ~0.418 s between stacks
PAINT_INSTANCE_LIMIT = 8
import numpy as np
import math
class DeterministicPanelManager:
    """
    Manages deterministic parameter overrides across multi-sequence channels
    using invariant Meum constants and golden ratios.
    """
    def __init__(self, channels: int = 4) -> None:
        self.channels = channels
        self.MEUM_NORM = 1.19758073433
        self.MEUM_INV = 1.0 / self.MEUM_NORM
        self.PHI = 1.61803398875

    def get_channel_overrides(self, channel_id: int, ctx: float) -> dict:
        """Computes invariant-mapped parameter overrides for a given channel."""
        return {
            "gain": float(np.clip(self.MEUM_NORM * 0.5 + (self.PHI - 1.0) * ctx * channel_id, 0.0, 1.0)),
            "modulation_skew": float(math.fmod(channel_id * self.PHI, 1.0)),
            "phase_offset": float(math.tau * ((channel_id * self.MEUM_NORM * (self.PHI - 1.0)) % 1.0))
        }


class DeterministicPanelOverride:
    def __init__(self, channels=4):
        self.channels = channels
        self.MEUM_NORM = 1.19758073433
        self.PHI = 1.61803398875

    def compute_override(self, channel_id, ctx):
        return {
            "gain": float(np.clip(self.MEUM_NORM * 0.5 + (self.PHI - 1.0) * ctx * channel_id, 0.0, 1.0)),
            "modulation_skew": float(math.fmod(channel_id * self.PHI, 1.0))
        }


def _meum_params(params):
    """Normalize Meum phase/AM/FM/PM parameters safely."""
    p = params if isinstance(params, dict) else {}
    import math as _m

    def _f(key, default=0.0):
        try:
            v = float(p.get(key, default))
            return v if _m.isfinite(v) else float(default)
        except Exception:
            return float(default)

    return {
        "phase_shift": _f("phase_shift", 0.0),
        "am_depth": max(0.0, min(1.0, _f("am_depth", 0.0))),
        "am_rate": max(0.0, _f("am_rate", 1.0)),
        "fm_depth": max(0.0, min(1.0, _f("fm_depth", 0.0))),
        "fm_rate": max(0.0, _f("fm_rate", 1.0)),
        "pm_depth": max(-_m.pi, min(_m.pi, _f("pm_depth", 0.0))),
        "pm_rate": max(0.0, _f("pm_rate", 1.0)),
        "pm_feedback": max(-1.0, min(1.0, _f("pm_feedback", 0.0))),
        "meum_depth": max(0.0, min(1.0, _f("meum_depth", 0.0))),
        "canonical_unison": bool(p.get("canonical_unison", False)),
        "canonical_count": max(1, int(p.get("canonical_count", 1) or 1)),
        "canonical_phase_lock": bool(p.get("canonical_phase_lock", False)),
        "unison_phase_spread": _f("unison_phase_spread", 0.0),
        "waveform": str(p.get("waveform", "isn") or "isn"),
    }
def _meum_phase_modulation(
    t,
    *,
    phase_shift=0.0,
    pm_depth=0.0,
    pm_rate=1.0,
    pm_feedback=0.0,
    meum_depth=0.0,
):
    """Direct phase modulation in radians.
    Syntax: carrier_phase + PM(t) + feedback*MeumField(t).  Phase is used rather
    than amplitude because PM preserves the canonical oscillator identity while
    producing a deterministic sideband family from the same seed.
    """

    field = meum_phase_field(
        t,
        rate=pm_rate,
        phase=phase_shift,
    )

    pm = math.sin(
        2.0 * math.pi * t * float(pm_rate)
        + float(phase_shift)
    )

    return (
        float(pm_depth) * pm
        + float(pm_feedback) * float(meum_depth) * field
    )
def _meum_amplitude_modulation(
    t,
    *,
    am_depth=0.0,
    am_rate=1.0,
    phase_shift=0.0,
    meum_depth=0.0,
):
    """Amplitude modulation with bounded Meum contribution.
    Syntax: gain = 1 + depth * (LFO + MeumDepth*field), clipped at zero.
    This keeps the signal physically usable while retaining a reversible,
    seed-derived envelope transformation.
    """

    field = meum_phase_field(
        t,
        rate=am_rate,
        phase=phase_shift,
    )

    lfo = math.sin(
        2.0 * math.pi * t * float(am_rate)
        + float(phase_shift)
    )

    gain = 1.0 + float(am_depth) * (
        lfo + float(meum_depth) * field
    )

    return max(0.0, gain)
def _meum_advance_phase(
    phase,
    frequency,
    sample_rate,
    t,
    *,
    fm_depth=0.0,
    fm_rate=1.0,
    phase_shift=0.0,
    meum_depth=0.0,
):
    """Advance oscillator phase using instantaneous FM frequency.
    Syntax: f_inst = f*(1 + depth*(LFO + MeumField)); phase += 2π*f_inst/SR.
    Frequency is clamped below Nyquist so the deterministic transform cannot
    create an invalid sample-rate-dependent identity.
    """

    sr = max(float(sample_rate), 1.0)
    frequency = max(float(frequency), 0.0)

    field = meum_phase_field(
        t,
        rate=fm_rate,
        phase=phase_shift,
    )

    fm = math.sin(
        2.0 * math.pi * t * float(fm_rate)
        + float(phase_shift)
    )

    modulation = fm + float(meum_depth) * field

    instantaneous_frequency = frequency * (
        1.0 + float(fm_depth) * modulation
    )

    instantaneous_frequency = max(
        0.0,
        min(sr * 0.45, instantaneous_frequency),
    )

    return (
        phase
        + (2.0 * math.pi * instantaneous_frequency / sr)
    )
def _meum_handle_add(a, b):
    return ot_equiv_add(a, b) if OP_THEORY_ENABLED else float(a) + float(b)

def _meum_handle_mul(a, b):
    return ot_equiv_mul(a, b) if OP_THEORY_ENABLED else float(a) * float(b)

def _meum_handle_div(a, b):
    return ot_equiv_div(a, b) if OP_THEORY_ENABLED else (0.0 if float(b) == 0.0 else float(a) / float(b))

def meum_spatial_operator_field(x, y, z):
    """Direct Meum x,y,z field used by the EQR spatial effect.

    Potential + standing-wave + neighboring-state terms are the expression; OT
    merely supplies equivalent arithmetic handles when enabled.
    """
    x, y, z = float(x), float(y), float(z)
    r = math.sqrt(max(0.0, x*x + y*y + z*z)) + 1e-9
    potential = _meum_handle_div(1.0, r)
    wave = math.sin(math.pi*x) * math.sin(math.pi*y) * math.sin(math.pi*z)
    state = (math.sin(2.0*math.pi*(x+1.0/3.0)) + math.sin(2.0*math.pi*(y+1.0/3.0)) + math.sin(2.0*math.pi*(z+1.0/3.0))) / 3.0
    return float(_meum_handle_add(_meum_handle_add(0.34*potential, 0.33*wave), 0.33*state))

def meum_spatial_audio_effect(signal, strength=0.025, phase=0.0):
    arr=np.asarray(signal,dtype=np.float32).ravel()
    if arr.size==0: return arr
    t=np.linspace(0.0,1.0,arr.size,endpoint=False)
    x=2.0*t-1.0; y=np.sin(2.0*math.pi*t+float(phase)); z=np.cos(2.0*math.pi*t+float(phase))
    field=np.asarray([meum_spatial_operator_field(a,b,c) for a,b,c in zip(x,y,z)],dtype=np.float32)
    return (arr*(1.0+np.float32(np.clip(float(strength),0.0,0.08))*field)).astype(np.float32)


def meum_phase_field(t, rate=1.0, phase=0.0):
    """Bounded nonlinear Meum modulation field."""
    t = float(t)
    rate = float(rate)
    phase = float(phase)

    a = math.sin(2.0 * math.pi * t * rate + phase)
    b = math.sin(
        2.0 * math.pi * t * rate * MEUM_INV + phase * MEUM_NORM
    )

    return 0.5 * (a + MEUM_NORM * b)

def _meum_panel_context(params=None, canonical_context=None):
    """
    Normalize synth-panel + canonical/unison modulation parameters.

    Synth panels remain user-facing/authoritative.
    Canonical context supplies modulation defaults/variation.
    """

    params = params if isinstance(params, dict) else {}
    canonical_context = (
        canonical_context
        if isinstance(canonical_context, dict)
        else {}
    )

    # Existing nested Meum state, if present.
    existing = params.get("meum_modulation", {})
    if not isinstance(existing, dict):
        existing = {}

    ctx = dict(existing)

    # --------------------------------------------------------------
    # Canonical/unison context
    # --------------------------------------------------------------

    canonical_unison = bool(
        canonical_context.get(
            "canonical_unison",
            params.get("canonical_unison", False),
        )
    )

    canonical_count = int(
        max(
            1,
            canonical_context.get(
                "canonical_count",
                params.get("canonical_count", 1),
            ),
        )
    )

    canonical_phase_lock = bool(
        canonical_context.get(
            "canonical_phase_lock",
            params.get("canonical_phase_lock", False),
        )
    )

    # --------------------------------------------------------------
    # Synth-panel parameters
    #
    # User panel values win if explicitly present.
    # --------------------------------------------------------------

    def panel(name, default):
        if name in params:
            return params[name]
        if name in ctx:
            return ctx[name]
        return default

    ctx["phase_shift"] = float(
        panel("phase_shift", 0.0)
    )

    ctx["am_depth"] = float(
        np.clip(
            panel("am_depth", 0.0),
            0.0,
            1.0,
        )
    )

    ctx["am_rate"] = float(
        max(
            0.0,
            panel("am_rate", 1.0),
        )
    )

    ctx["fm_depth"] = float(
        np.clip(
            panel("fm_depth", 0.0),
            -0.95,
            0.95,
        )
    )

    ctx["fm_rate"] = float(
        max(
            0.0,
            panel("fm_rate", 1.0),
        )
    )

    ctx["pm_depth"] = float(
        np.clip(
            panel("pm_depth", 0.0),
            -math.pi,
            math.pi,
        )
    )

    ctx["pm_rate"] = float(
        max(
            0.0,
            panel("pm_rate", 1.0),
        )
    )

    ctx["pm_feedback"] = float(
        np.clip(
            panel("pm_feedback", 0.0),
            -1.0,
            1.0,
        )
    )

    ctx["meum_depth"] = float(
        np.clip(
            panel("meum_depth", 0.0),
            0.0,
            1.0,
        )
    )

    # Preserve canonical state alongside the synth-panel controls.
    ctx["canonical_unison"] = canonical_unison
    ctx["canonical_count"] = canonical_count
    ctx["canonical_phase_lock"] = canonical_phase_lock

    # --------------------------------------------------------------
    # Canonical unison phase distribution
    # --------------------------------------------------------------

    if canonical_unison and canonical_count > 1:
        ctx["unison_phase_spread"] = float(
            params.get(
                "unison_phase_spread",
                math.tau,
            )
        )
    else:
        ctx["unison_phase_spread"] = float(
            params.get(
                "unison_phase_spread",
                0.0,
            )
        )

    # Phase lock deliberately suppresses independent spread.
    if canonical_phase_lock:
        ctx["unison_phase_spread"] = 0.0

    return ctx
def meum_waveform_from_phase(phase, waveform="isn"):
    """Evaluate a periodic waveform from phase (radians), vectorized.

    Default and primary cores are isn / ics (Meum-normalized sinusoids) and
    their inverses. Classical saw/square/triangle remain available by name.
    No tanh saturators.
    """
    phase = np.asarray(phase, dtype=np.float64)
    wf = str(waveform or "isn").strip().lower()
    u = np.mod(phase / (2.0 * np.pi), 1.0)
    if wf in ("saw", "sawtooth"):
        return (2.0 * u - 1.0).astype(np.float32)
    if wf in ("square", "pulse"):
        return np.where(u < 0.5, 1.0, -1.0).astype(np.float32)
    if wf in ("triangle", "tri"):
        return (4.0 * np.abs(u - 0.5) - 1.0).astype(np.float32)
    if wf in ("ics", "cos", "cosine"):
        return ics_vec(phase)
    if wf in ("arcisn", "isn_inv", "isn_inverse"):
        # Inverse of isn via the shared scalar inverter, vectorized elementwise.
        out = np.empty(phase.shape, dtype=np.float32)
        for i, v in enumerate(phase.ravel()):
            out.flat[i] = float(eqr_isn_inv(float(v) if abs(float(v)) <= 1.5 else math.copysign(1.0, float(v))))
        return out
    if wf in ("arcics", "ics_inv", "ics_inverse"):
        out = np.empty(phase.shape, dtype=np.float32)
        for i, v in enumerate(phase.ravel()):
            y = float(v)
            # ics range is roughly bounded; map phase fraction into that range.
            y = max(-1.0, min(1.0, y if abs(y) <= 1.0 else math.cos(y)))
            out.flat[i] = float(eqr_isn_inv(y))  # reuse odd inverter as phase-like map
        return out
    # Default: isn (Meum odd sinusoid) — also accepts "sine"/"sin" as aliases.
    return isn_vec(phase)


def meum_modulation_vectors(t, params=None):
    """
    Vectorized (numpy) canonical Meum AM/FM/PM contribution for a whole
    time-array buffer. Mirrors the per-sample math in MeumModulatedOscillator
    so the additive/live-wavefield engine and the discrete-voice engine share
    one canonical modulation definition.

    Returns (freq_ratio, phase_offset, am_gain), each shaped like `t`:
      freq_ratio  - multiplies the carrier frequency before phase integration (FM)
      phase_offset - added directly to the integrated phase, radians (PM + phase_shift)
      am_gain     - multiplies the finished waveform's amplitude (AM)
    """
    p = params if isinstance(params, dict) else {}
    t = np.asarray(t, dtype=np.float64)

    phase_shift = float(p.get("phase_shift", 0.0))
    am_depth = float(np.clip(p.get("am_depth", 0.0), 0.0, 1.0))
    am_rate = max(0.0, float(p.get("am_rate", 1.0)))
    fm_depth = float(np.clip(p.get("fm_depth", 0.0), -0.95, 0.95))
    fm_rate = max(0.0, float(p.get("fm_rate", 1.0)))
    pm_depth = float(np.clip(p.get("pm_depth", 0.0), -math.pi, math.pi))
    pm_rate = max(0.0, float(p.get("pm_rate", 1.0)))
    pm_feedback = float(np.clip(p.get("pm_feedback", 0.0), -1.0, 1.0))
    meum_depth = float(np.clip(p.get("meum_depth", 0.0), 0.0, 1.0))

    def field(rate):
        a = np.sin(math.tau * t * rate)
        b = np.sin(math.tau * t * rate * MEUM_INV)
        return 0.5 * (a + MEUM_NORM * b)

    # FM: instantaneous-frequency ratio (integrated into phase by the caller).
    fm_lfo = np.sin(math.tau * t * fm_rate + phase_shift)
    freq_ratio = 1.0 + fm_depth * (fm_lfo + meum_depth * field(fm_rate))
    freq_ratio = np.clip(freq_ratio, 0.0, None)

    # PM: direct phase displacement, radians (includes the static phase_shift).
    pm_lfo = np.sin(math.tau * t * pm_rate + phase_shift)
    phase_offset = (
        phase_shift
        + pm_depth * pm_lfo
        + pm_feedback * meum_depth * field(pm_rate)
    )

    # AM: post-waveform amplitude gain, never negative.
    am_lfo = np.sin(math.tau * t * am_rate + phase_shift)
    am_gain = np.clip(1.0 + am_depth * (am_lfo + meum_depth * field(am_rate)), 0.0, None)

    return (
        freq_ratio.astype(np.float32),
        phase_offset.astype(np.float32),
        am_gain.astype(np.float32),
    )
def meum_modulated_phase(
    phase,
    t,
    *,
    phase_shift=0.0,
    fm_depth=0.0,
    fm_rate=1.0,
    pm_depth=0.0,
    pm_rate=1.0,
    pm_feedback=0.0,
):
    field = meum_phase_field(t, rate=fm_rate, phase=phase_shift)

    # PM = direct phase displacement.
    pm = (
        float(pm_depth)
        * math.sin(
            2.0 * math.pi * float(t) * float(pm_rate)
            + float(phase_shift)
        )
    )

    # Optional Meum phase feedback.
    pm += float(pm_feedback) * field

    return float(phase) + float(phase_shift) + pm, field
class MeumModulatedOscillator:
    """
    Stateful Meum oscillator.

    Signal order:

        FM
         ↓
    instantaneous frequency
         ↓
    phase accumulator
         ↓
    phase shift + PM
         ↓
      waveform
         ↓
        AM
         ↓
       output

    All phase quantities are radians.
    """

    def __init__(self, sample_rate=44100.0, frequency=440.0):
        self.sample_rate = float(sample_rate)
        self.frequency = float(frequency)

        # Persistent oscillator state.
        self.phase = 0.0
        self.sample_index = 0

        # Modulation defaults.
        self.phase_shift = 0.0

        self.am_depth = 0.0
        self.am_rate = 1.0

        self.fm_depth = 0.0
        self.fm_rate = 1.0

        self.pm_depth = 0.0
        self.pm_rate = 1.0

        self.pm_feedback = 0.0
        self.meum_depth = 0.0

        self.waveform = "isn"

    # ------------------------------------------------------------------
    # PARAMETERS
    # ------------------------------------------------------------------

    def set_params(self, params=None):
        if not isinstance(params, dict):
            return self

        self.phase_shift = float(
            params.get("phase_shift", self.phase_shift)
        )

        self.am_depth = float(
            np.clip(
                params.get("am_depth", self.am_depth),
                0.0,
                1.0,
            )
        )

        self.am_rate = max(
            0.0,
            float(params.get("am_rate", self.am_rate)),
        )

        self.fm_depth = float(
            np.clip(
                params.get("fm_depth", self.fm_depth),
                -0.95,
                0.95,
            )
        )

        self.fm_rate = max(
            0.0,
            float(params.get("fm_rate", self.fm_rate)),
        )

        self.pm_depth = float(
            np.clip(
                params.get("pm_depth", self.pm_depth),
                -math.pi,
                math.pi,
            )
        )

        self.pm_rate = max(
            0.0,
            float(params.get("pm_rate", self.pm_rate)),
        )

        self.pm_feedback = float(
            np.clip(
                params.get("pm_feedback", self.pm_feedback),
                -1.0,
                1.0,
            )
        )

        self.meum_depth = float(
            np.clip(
                params.get("meum_depth", self.meum_depth),
                0.0,
                1.0,
            )
        )

        if "waveform" in params:
            self.waveform = str(params["waveform"])

        return self

    # ------------------------------------------------------------------
    # MEUM FIELD
    # ------------------------------------------------------------------

    def meum_field(self, t, rate=1.0):
        """
        Bounded nonlinear modulation field.

        This intentionally remains dimensionless.
        It modifies modulation rather than replacing Hz or radians.
        """

        t = float(t)
        rate = float(rate)

        a = math.sin(
            math.tau * t * rate
        )

        b = math.sin(
            math.tau
            * t
            * rate
            * MEUM_INV
        )

        field = 0.5 * (
            a
            + MEUM_NORM * b
        )

        return float(
            np.clip(field, -1.0, 1.0)
        )

    # ------------------------------------------------------------------
    # AM
    # ------------------------------------------------------------------

    def amplitude_modulation(self, t):
        """
        AM changes amplitude only.
        """

        lfo = math.sin(
            math.tau
            * t
            * self.am_rate
            + self.phase_shift
        )

        field = self.meum_field(
            t,
            self.am_rate,
        )

        gain = 1.0 + (
            self.am_depth
            * (
                lfo
                + self.meum_depth * field
            )
        )

        return max(0.0, gain)

    # ------------------------------------------------------------------
    # FM
    # ------------------------------------------------------------------

    def instantaneous_frequency(self, t):
        """
        FM changes instantaneous frequency.

        IMPORTANT:
        The returned frequency is subsequently integrated into phase.
        """

        lfo = math.sin(
            math.tau
            * t
            * self.fm_rate
            + self.phase_shift
        )

        field = self.meum_field(
            t,
            self.fm_rate,
        )

        modulation = (
            lfo
            + self.meum_depth * field
        )

        frequency = self.frequency * (
            1.0
            + self.fm_depth * modulation
        )

        return float(
            np.clip(
                frequency,
                0.0,
                min(self.sample_rate * 0.75, AUDIBLE_HI_HZ),
            )
        )

    # ------------------------------------------------------------------
    # PM
    # ------------------------------------------------------------------

    def phase_modulation(self, t):
        """
        PM directly displaces oscillator phase.
        """

        lfo = math.sin(
            math.tau
            * t
            * self.pm_rate
            + self.phase_shift
        )

        field = self.meum_field(
            t,
            self.pm_rate,
        )

        return (
            self.pm_depth * lfo
            +
            self.pm_feedback
            * self.meum_depth
            * field
        )

    # ------------------------------------------------------------------
    # WAVEFORMS
    # ------------------------------------------------------------------

    def waveform_sample(self, phase):
        """
        Evaluate waveform from radians.

        Primary cores: isn / ics / inverses. Classical shapes remain available.
        """

        u = (
            phase / math.tau
        ) % 1.0

        waveform = (
            self.waveform
            .strip()
            .lower()
        )

        if waveform in (
            "saw",
            "sawtooth",
        ):
            return (
                2.0 * u
                - 1.0
            )

        if waveform in (
            "square",
            "pulse",
        ):
            return (
                1.0
                if u < 0.5
                else -1.0
            )

        if waveform in (
            "triangle",
            "tri",
        ):
            return (
                4.0
                * abs(u - 0.5)
                - 1.0
            )

        if waveform in (
            "ics",
            "cos",
            "cosine",
        ):
            return ics_scalar(phase)

        if waveform in (
            "arcisn",
            "isn_inv",
            "isn_inverse",
        ):
            y = isn_scalar(phase)
            return float(eqr_isn_inv(y))

        if waveform in (
            "arcics",
            "ics_inv",
            "ics_inverse",
        ):
            y = ics_scalar(phase)
            # Map ics output through the odd inverter as a phase-like reading.
            return float(eqr_isn_inv(max(-1.0, min(1.0, y))))

        # Default: isn (aliases: sine, sin).
        return isn_scalar(phase)

    # ------------------------------------------------------------------
    # RENDER
    # ------------------------------------------------------------------

    def render(
        self,
        num_samples,
        amplitude=1.0,
        frequency=None,
    ):
        """
        Render a continuous block.

        Phase is persistent across calls.
        """

        n = int(num_samples)

        if n <= 0:
            return np.zeros(
                0,
                dtype=np.float32,
            )

        if frequency is not None:
            self.frequency = max(
                0.0,
                float(frequency),
            )

        sr = max(
            1.0,
            self.sample_rate,
        )

        out = np.zeros(
            n,
            dtype=np.float32,
        )

        phase = float(self.phase)
        sample_index = int(
            self.sample_index
        )

        for i in range(n):

            t = (
                sample_index
                / sr
            )

            # ==========================================================
            # FM
            #
            # FM changes instantaneous frequency.
            # ==========================================================

            inst_freq = (
                self.instantaneous_frequency(t)
            )

            # Integrate frequency into phase.
            phase += (
                math.tau
                * inst_freq
                / sr
            )

            # ==========================================================
            # PM
            #
            # PM is a direct phase displacement.
            # ==========================================================

            pm = self.phase_modulation(t)

            render_phase = (
                phase
                + self.phase_shift
                + pm
            )

            # ==========================================================
            # WAVEFORM
            # ==========================================================

            sample = self.waveform_sample(
                render_phase
            )

            # ==========================================================
            # AM
            #
            # AM happens after waveform generation.
            # ==========================================================

            gain = (
                self.amplitude_modulation(t)
            )

            out[i] = np.float32(
                amplitude
                * gain
                * sample
            )

            sample_index += 1

            # DRIFT_FIX_2026: phase used to only wrap once abs(phase) exceeded
            # 1e9 radians. A float64 keeps ~15-17 significant digits, so by the
            # time phase reaches the high end of that range, the increment
            # added each sample (a few hundredths of a radian) starts falling
            # below the representable precision at that magnitude — the phase
            # accumulator effectively "rounds off" tiny per-sample increments,
            # which is exactly what reads as slow harmonic/pitch drift over a
            # long session. Wrapping every sample keeps phase always small
            # (0..2π) so its precision never degrades, at negligible cost.
            phase %= math.tau

        self.phase = phase
        self.sample_index = sample_index

        return out

    # ------------------------------------------------------------------
    # RESET
    # ------------------------------------------------------------------

    def reset_phase(self, phase=0.0):
        self.phase = float(phase)
        self.sample_index = 0
        return self
def _parse_if_elif_shorthand(text):
    """Parse if/elif[/elif...] chains into a Python ternary expression string.

    Supports nested parentheses in conditions and values:
      if(cond) a elif b
      if(cond1) a elif(cond2) b elif c
      if(cond) (432 * 2) elif (216 + 10)

    Returns the ternary string, or None if not an if/elif form.
    """
    import re as _re
    text = str(text or "").strip()
    if not text:
        return None

    def _read_paren_expr(s, start_idx):
        if start_idx >= len(s) or s[start_idx] != "(":
            return None, start_idx
        depth = 0
        i = start_idx
        while i < len(s):
            ch = s[i]
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return s[start_idx + 1:i], i + 1
            i += 1
        return None, start_idx

    m = _re.match(r"\s*if\s*", text, flags=_re.I)
    if not m:
        return None
    pos = m.end()
    while pos < len(text) and text[pos].isspace():
        pos += 1
    if pos >= len(text) or text[pos] != "(":
        return None

    branches = []
    cond, pos = _read_paren_expr(text, pos)
    if cond is None:
        return None
    em = _re.search(r"\belif\b", text[pos:], flags=_re.I)
    if not em:
        return None
    yes = text[pos:pos + em.start()].strip()
    pos = pos + em.end()
    branches.append((cond.strip(), yes))

    while True:
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos >= len(text):
            break
        if text[pos] == "(":
            group, after = _read_paren_expr(text, pos)
            if group is None:
                return None
            rest_after = text[after:].strip()
            em2 = _re.search(r"\belif\b", text[after:], flags=_re.I)
            if em2:
                expr = text[after:after + em2.start()].strip()
                pos = after + em2.end()
                branches.append((group.strip(), expr if expr else "0"))
                continue
            if rest_after:
                branches.append((group.strip(), rest_after))
                break
            branches.append((None, f"({group.strip()})"))
            break
        else:
            em2 = _re.search(r"\belif\b", text[pos:], flags=_re.I)
            if em2:
                return None
            expr = text[pos:].strip()
            branches.append((None, expr))
            break

    if not branches:
        return None
    if branches[-1][0] is not None:
        branches.append((None, "0"))

    def _wrap(e):
        e = (e or "0").strip() or "0"
        return f"({e})"

    acc = _wrap(branches[-1][1])
    for cond_i, expr_i in reversed(branches[:-1]):
        acc = f"({_wrap(expr_i)} if ({cond_i}) else {acc})"
    return acc


def _write_wav_with_provenance(path, sample_rate, pcm_int16, comment_bytes=None):
    """Write mono 16-bit WAV with an optional custom 'eqrf' provenance chunk.

    The 'eqrf' chunk carries the plain-text export manifest (JSON) so any
    hexdump / RIFF reader sees the documented generation parameters — the
    product stays trivially reverse-engineerable back to the main window.
    Unknown chunks are ignored by standard WAV players.
    """
    import struct as _st
    data = np.asarray(pcm_int16, dtype=np.int16).tobytes()

    def _chunk(cid, payload):
        payload = bytes(payload)
        pad = b"\0" if (len(payload) & 1) else b""
        return cid + _st.pack("<I", len(payload)) + payload + pad

    fmt = _st.pack("<HHIIHH", 1, 1, int(sample_rate), int(sample_rate) * 2, 2, 16)
    body = _chunk(b"fmt ", fmt) + _chunk(b"data", data)
    if comment_bytes is not None:
        body += _chunk(b"eqrf", bytes(comment_bytes))
    header = b"RIFF" + _st.pack("<I", 4 + len(b"WAVE") + len(body)) + b"WAVE" + body
    with open(path, "wb") as f:
        f.write(header)


def _extract_wav_provenance(path):
    """Read back the 'eqrf' provenance chunk a WAV export carries (or None)."""
    import struct as _st
    try:
        with open(path, "rb") as f:
            head = f.read(12)
        if len(head) < 12 or head[:4] != b"RIFF" or head[8:12] != b"WAVE":
            return None
        size = _st.unpack("<I", head[4:8])[0]
        with open(path, "rb") as f:
            data = f.read(12 + size)
        chunks = data[12:]
        pos = 0
        while pos + 8 <= len(chunks):
            cid = chunks[pos:pos + 4]
            csz = _st.unpack("<I", chunks[pos + 4:pos + 8])[0]
            payload = chunks[pos + 8:pos + 8 + csz]
            if cid == b"eqrf":
                try:
                    return json.loads(payload.decode("utf-8"))
                except Exception:
                    return None
            pos += 8 + csz + (csz & 1)
    except Exception:
        return None
    return None


def _safe_int_seed(value):
    """Deterministically fold any seed value into a NumPy-safe non-negative
    int32-range integer. Whole-number floats map to their exact integer
    (so seed=7 and seed=7.0 behave identically); fractional or otherwise
    unrepresentable values are hashed so the mapping stays deterministic
    and well distributed instead of raising or truncating unpredictably."""
    import struct
    try:
        as_float = float(value)
    except Exception:
        as_float = 0.0
    if not math.isfinite(as_float):
        as_float = 0.0
    if as_float == int(as_float) and abs(as_float) < 2**31:
        return int(as_float) & 0x7FFFFFFF
    scaled = abs(as_float) * 1000.0
    if scaled < 2**31:
        n = int(round(scaled)) & 0x7FFFFFFF
        return n if n else 1
    import struct as _st
    hi, lo = _st.unpack(">II", _st.pack(">d", as_float))
    mixed = (hi ^ (lo * 0x9E3779B1) ^ int(scaled % (2**31))) & 0x7FFFFFFF
    return mixed if mixed else 1


def _stable_hash(value, modulus=None):
    """Process-stable string hash for canonical IDs/colors/phases.

    Python's built-in hash() on strings is salted per-process
    (PYTHONHASHSEED), so two runs of the same code could pick different
    hue/phase/RNG lanes for identical content. This folds any value through
    SHA-256 — identical bytes ⇒ identical integer on every machine/process.
    """
    try:
        blob = str(value).encode("utf-8", "replace")
    except Exception:
        blob = repr(value).encode("utf-8", "replace")
    d = hashlib.sha256(blob).digest()
    n = int.from_bytes(d[:8], "big")
    if modulus is not None and modulus > 0:
        return n % int(modulus)
    return n


# >>> GROK_EDIT_BEGIN: seed_pitch_identity
def _seed_to_pitch_ratio(seed_val, op_idx=0, step=0):
    """Map seed → pitch ratio across the full usable range (~±4.5 octaves).

    Uses a hash mix so successive steps look fully random (not a scrambled
    chromatic walk and not a residual sawtooth). Uniform in *cents* then
    converted to ratio so notes occupy the full range evenly rather than
    clustering near unison.
    """
    try:
        s = float(seed_val)
    except Exception:
        s = 0.0
    if not math.isfinite(s):
        s = 0.0
    si = int(_safe_int_seed(s))
    op = int(op_idx) & 0x7FFFFFFF
    st = int(step) & 0x7FFFFFFF
    # Avalanche mix — successive steps jump around the full cent span
    h = int(_safe_int_seed(
        (si * 0x9E3779B1)
        ^ ((op + 1) * 0x85EBCA6B)
        ^ ((st + 1) * 0xC2B2AE35)
        ^ ((si >> 3) * 0x27D4EB2D)
    ))
    # ±4.5 octaves = 10800 cents; map hash uniformly into that span
    cents = float(h % 10800) - 5400.0
    # OT significance: same formula 2^(cents/1200), but power uses book ot_pow
    # when OT is on — signed/handedness rules can matter for extreme seeds.
    # Without OT: ordinary IEEE power.  Expression is never rewritten.
    exp = cents / 1200.0
    if OP_THEORY_ENABLED:
        try:
            ratio = float(ot_pow(2.0, exp))
            # ot_pow uses abs bases; restore octave direction from cents sign
            if cents < 0.0 and ratio > 0.0:
                ratio = 1.0 / ratio if ratio != 0.0 else 1.0
        except Exception:
            ratio = 2.0 ** exp
    else:
        ratio = 2.0 ** exp
    # Hard floor/ceil for ratio safety (still ~9 octaves total span)
    if ratio < 1.0 / 32.0:
        ratio = 1.0 / 32.0
    if ratio > 32.0:
        ratio = 32.0
    return float(ratio)


def _seed_to_fundamental_hz(seed_val, base_hz=432.0, op_idx=0, step=0):
    """Seed → absolute fundamental Hz (base × unique ratio)."""
    try:
        base = float(base_hz)
    except Exception:
        base = 432.0
    if not math.isfinite(base) or base <= 0:
        base = 432.0
    return float(audible_hz(base * _seed_to_pitch_ratio(seed_val, op_idx, step)))
