def simplify_scalar_transforms(transforms, *, phase_cycle=None):
    """Canonicalize common scalar transforms before evaluating them once.

    Input items are (op, value) pairs where op is mul/add/phase. Multipliers
    collapse into one product, additions into one sum, and phase offsets into
    one modulo-cycle offset. Near-identity/no-op results are removed. This makes
    reversible writer/modulator results independent of activation order and
    avoids repeated floating-point mutation of the signal.
    """
    mul = 1.0
    add = 0.0
    phase = 0.0
    extras = []
    for item in transforms or ():
        try:
            op, value = item
            v = float(value)
        except Exception:
            extras.append(item)
            continue
        if not math.isfinite(v):
            continue
        op = str(op).lower().strip()
        if op in ("mul", "multiply", "scale", "gain"):
            mul *= v
        elif op in ("add", "offset", "translate"):
            add += v
        elif op in ("phase", "phase_add", "phase_offset"):
            phase += v
        else:
            extras.append((op, v))
    eps = 1e-12
    out = []
    if abs(mul - 1.0) > eps:
        out.append(("mul", mul))
    if abs(add) > eps:
        out.append(("add", add))
    if phase_cycle is not None:
        try:
            cyc = abs(float(phase_cycle))
            if cyc > eps:
                phase = math.fmod(phase, cyc)
        except Exception:
            pass
    if abs(phase) > eps:
        out.append(("phase", phase))
    out.extend(extras)
    return out

# CANONICAL_MACRO_DEFAULTS_2026: single source of truth for the engine-authored
# macro defaults. Both the generative writer (_mark_generated_synth_context) and
# the canonical reset that strips engine residue compute THE SAME numbers from
# the same frozen context, so the master synth store is a pure function of the
# final active engine set + user material, never of activation history.
def canonical_macro_defaults(ctx, i):
    return {
        "tuning": float(np.clip(MEUM_INV + (PHI - 1.0) * ctx, 0.75, 1.15)),
        "filter": float(np.clip(MEUM_NORM + MEUM_INV * ctx, 0.02, 0.98)),
        "drive": float(np.clip(MEUM_NORM * 0.5 + MEUM_NORM * ctx, 0.0, 0.9)),
        "amplitude": float(np.clip(MEUM_INV * 0.5 + MEUM_NORM * ctx, 0.05, 1.0)),
        "duration": float(np.clip(MEUM_NORM + MEUM_INV * (1.0 - ctx), 0.03, 1.0)),
        "phase_shift": float(math.tau * ((i * MEUM_NORM * PHI_INV) % 1.0)),
        "am_depth": float(np.clip(MEUM_NORM * 0.2 + MEUM_NORM * ctx * 0.5, 0.0, 0.40)),
        "am_rate": float(MEUM_NORM + MEUM * ctx),
        "fm_depth": float(np.clip(MEUM_NORM * 0.1 + MEUM_NORM * ctx * 0.1, 0.0, 0.18)),
        "fm_rate": float(MEUM_SQ * ctx + MEUM_INV),
        "pm_depth": float(np.clip(MEUM_NORM * 0.2 + MEUM_NORM * ctx * 0.2, 0.0, 0.35)),
        "pm_rate": float(MEUM_SQ * ctx + MEUM_INV),
        "pm_feedback": float(np.clip(MEUM_NORM * 0.1 + MEUM_NORM * ctx * 0.1, 0.0, 0.25)),
        "meum_depth": float(np.clip(MEUM_NORM * 0.5 + MEUM_NORM * ctx * 0.5, 0.0, 0.45)),
        # CANONICAL_SYNTH_SLIDER_CONTROL_2026: the canonical engines own the
        # five visible Synth Rack controls as well as the deeper modulation
        # macros.  These are deterministic projections, not a second source of truth.
        "morph": float(np.clip(0.75 + 2.25 * ctx, 0.01, 10.0)),
        "harmonic_freq": float(np.clip(432.0 * (MEUM_INV + (PHI - 1.0) * ctx), 20.0, 20000.0)),
        "chaos": float(np.clip(0.20 + 0.65 * ctx, 0.0, 1.0)),
        "fold_depth": float(np.clip(1.0 + 15.0 * (MEUM_INV * 0.5 + 0.5 * ctx), 1.0, 16.0)),
        "harmonic_lattice": float(np.clip(MEUM_INV * 0.35 + 0.65 * ctx, 0.0, 1.0)),
        "fractalizer": float(np.clip(MEUM_INV * 0.35 + 0.65 * ctx, 0.0, 1.0)),
    }

# The macro key names that engines author into the master synth store.  During
# the canonical context freeze these are excluded from the synth-signal blob so
# first-writer engagement residue can never factor into the frozen identity.
CANONICAL_MACRO_NAMES = frozenset(canonical_macro_defaults(0.5, 0))

def idealized_operator_struct(app, op_name, row=0, seed=0):
    """Build the canonical per-instrument data-struct set used by playlist cells.

    Returns dict with script_tag, domain_tag, synth_tag, patch_tag — compact
    labels that point at the live instrument_scripts / domain_eq_engine /
    instrument_param_state / patch_connections stores so Unison composition
    only needs time_offset + coverage/blend to recycle patterns.

    When Edit-panels-per-sequence is ON, prefers the active sequence's panel
    overrides (synth / script / domain / patch) over master instrument state.
    """
    op = str(op_name or "Operator")
    short = op.split(".")[-1].strip()[:18] if op else "Op"
    # Sequence-local panel overrides (engine-written result mods). Always load
    # when present so playlist-assigned patterns can blend with master panels;
    # do not gate solely on "Edit panels per sequence".
    seq_panels = None
    if app is not None and hasattr(app, "_sequence_panel_slot"):
        try:
            seq_panels = app._sequence_panel_slot(op)
            # Empty engine-less panels → treat as absent
            if isinstance(seq_panels, dict):
                has_content = bool(
                    seq_panels.get("synth")
                    or seq_panels.get("script")
                    or (seq_panels.get("domain") or {}).get("domains")
                    or seq_panels.get("patch")
                    or seq_panels.get("engine_contributions")
                )
                if not has_content:
                    seq_panels = None
        except Exception:
            seq_panels = None
    # Script
    script_body = ""
    if seq_panels and seq_panels.get("script"):
        script_body = str(seq_panels.get("script") or "")
    elif app is not None and hasattr(app, "instrument_scripts"):
        script_body = str((app.instrument_scripts or {}).get(op, "") or "")
    script_line = ""
    for line in script_body.splitlines():
        s = line.strip()
        if s and not s.startswith("#"):
            script_line = s[:48]
            break
    if not script_line:
        script_line = f"Script::{short.upper()[:6]}"
    script_tag = script_line

    # Domain — prefer a matching domain_eq_engine partition, else a Meum-stable tag
    domain_tag = f"Dom::{short[:8]}[t]"
    engine = getattr(app, "domain_eq_engine", None) if app is not None else None
    if engine is not None:
        for dom in getattr(engine, "domains", []) or []:
            if not isinstance(dom, dict):
                continue
            name = str(dom.get("name", ""))
            if short[:6].lower() in name.lower() or op[:8].lower() in name.lower():
                axis = dom.get("axis", "time")
                t0, t1 = dom.get("t0", 0.0), dom.get("t1", 1.0)
                domain_tag = f"{name[:16]}|{axis}|{float(t0):.2f}-{float(t1):.2f}"
                break
        else:
            # Seed-stable synthetic domain label from first partition template
            if engine.domains:
                d0 = engine.domains[min(row % max(len(engine.domains), 1), len(engine.domains) - 1)]
                domain_tag = f"{str(d0.get('name', 'Dom'))[:14]}@r{row}"

    # Synth snapshot: blend sequence result-mod with master non-sequence panel
    # data (the four synth/script/domain/patch panels). Playlist-assigned
    # patterns must carry both identities — pure sequence or pure master alone
    # is what made every row sound identical.
    synth_tag = f"Synth::{short[:10]}"
    params = {}
    master_params = {}

    if app is not None:
        state = getattr(app, "instrument_param_state", {}) or {}
        raw_params = state.get(op, {}) if isinstance(state, dict) else {}
        if isinstance(raw_params, dict):
            master_params = dict(raw_params)
        generated = getattr(app, "instrument_param_generated", {}) or {}
        raw_gen = generated.get(op, {}) if isinstance(generated, dict) else {}
        if isinstance(raw_gen, dict):
            for k, v in raw_gen.items():
                master_params.setdefault(k, v)

    seq_params = {}
    if seq_panels and seq_panels.get("synth"):
        raw_params = seq_panels.get("synth")
        if isinstance(raw_params, dict):
            seq_params = dict(raw_params)

    if seq_params and master_params:
        try:
            amt = float((seq_panels or {}).get("blend", 0.5) or 0.5)
        except Exception:
            amt = 0.5
        amt = max(0.0, min(1.0, amt))
        params = blend_master_sequence_params(master_params, seq_params, amount=amt)
    elif seq_params:
        params = seq_params
    else:
        params = master_params
    if params:
        # Compact key=val list of primary macros
        keys = ("eqr", "harmonic_lattice", "fractalizer", "pkp_envelope", "tuning", "filter", "drive", "amplitude")
        parts = []
        for k in keys:
            if k in params:
                try:
                    parts.append(f"{k[0:3]}={float(params[k]):.2f}")
                except Exception:
                    parts.append(f"{k[0:3]}={params[k]}")
        if parts:
            synth_tag = "|".join(parts[:5])

    # Modular patch — incident edges for this operator (sequence panel when enabled)
    patch_tag = f"Patch::{short[:8]}"
    edges = []
    patch_src = (seq_panels.get("patch") if seq_panels else None) or (
        getattr(app, "patch_connections", []) if app is not None else []
    ) or []
    for c in patch_src:
        if not isinstance(c, dict):
            continue
        src, tgt = c.get("source"), c.get("target")
        if src == op or tgt == op:
            w = c.get("weight", c.get("gain", 0.5))
            try:
                w = float(w)
            except Exception:
                w = 0.5
            other = tgt if src == op else src
            arrow = "→" if src == op else "←"
            edges.append(f"{arrow}{str(other).split('.')[-1].strip()[:10]}@{w:.2f}")
    if not edges and app is not None:
        try:
            for c in getattr(globals().get("GLOBAL_BUS", None), "global_cables", []) or []:
                src, tgt = c.get("src_module"), c.get("tgt_module")
                if src == op or tgt == op:
                    other = tgt if src == op else src
                    edges.append(f"{'→' if src == op else '←'}{str(other)[:10]}")
        except Exception:
            pass
    if edges:
        patch_tag = ",".join(edges[:3])

    return {
        "script_tag": script_tag,
        "domain_tag": domain_tag,
        "synth_tag": synth_tag,
        "patch_tag": patch_tag,
        "operator": op,
    }

def build_live_parametrics_script(app, row_idx=0, op_name=None, entry=None):
    """One predicted-phase parametric blob for playlist + patterns + panels.

    Returns a scriptable string stored in the playlist `live_parametrics` column.
    Until live composition runs, this is the authoritative placeholder that the
    master parametric engine can eval; live engines update the same field.
    """
    import json
    entry = entry if isinstance(entry, dict) else {}
    op = str(op_name or entry.get("operator") or entry.get("operators_csv") or "Operator")
    seed_v = 0.0
    try:
        if app is not None and hasattr(app, "get_numeric_seed"):
            seed_v = float(app.get_numeric_seed() or 0.0)
    except Exception:
        seed_v = 0.0

    # Master panel (non-sequence)
    master_synth = {}
    try:
        st = (getattr(app, "instrument_param_state", {}) or {}).get(op, {}) if app else {}
        if isinstance(st, dict):
            for k in ("am_depth", "am_rate", "fm_depth", "fm_rate", "pm_depth", "pm_rate",
                      "pm_feedback", "meum_depth", "drive", "filter", "tuning", "waveform",
                      "eqr", "fractalizer", "harmonic_lattice", "pkp_envelope", "phase_shift"):
                if k in st:
                    try:
                        master_synth[k] = float(st[k]) if k != "waveform" else str(st[k])
                    except Exception:
                        master_synth[k] = st[k]
    except Exception:
        pass

    # Sequence panel blend
    seq_synth = {}
    try:
        if app is not None and hasattr(app, "_sequence_panel_slot"):
            panels = app._sequence_panel_slot(op)
            if isinstance(panels, dict) and isinstance(panels.get("synth"), dict):
                seq_synth = dict(panels["synth"])
    except Exception:
        pass

    blended = blend_master_sequence_params(master_synth, seq_synth, amount=0.5) if seq_synth else dict(master_synth)

    # Pattern summary for this operator
    pattern = {"steps_on": 0, "length": 0, "amp_mean": 0.0, "pitch_mean": 1.0}
    try:
        mem = (getattr(app, "instrument_sequencer_memory", {}) or {}).get(op, {}) if app else {}
        if isinstance(mem, dict):
            steps = mem.get("steps") or []
            amps = mem.get("amplitudes") or []
            pitches = mem.get("pitches") or []
            pattern["length"] = int(mem.get("pattern_length", len(steps) or 0))
            pattern["steps_on"] = sum(1 for x in steps if x)
            if amps:
                pattern["amp_mean"] = float(sum(float(a) for a in amps) / max(1, len(amps)))
            if pitches:
                pattern["pitch_mean"] = float(sum(float(p) for p in pitches) / max(1, len(pitches)))
    except Exception:
        pass

    payload = {
        "phase": "predicted",
        "row": int(row_idx),
        "operator": op,
        "seed": seed_v,
        "synth": blended,
        "pattern": pattern,
        "velocity": float(entry.get("velocity", 1.0) or 1.0),
        "time_offset": float(entry.get("time_offset", 0.0) or 0.0),
    }
    # Compact scriptable form (JSON one-liner; seeds can embed/eval later)
    try:
        return "live_params = " + json.dumps(payload, separators=(",", ":"), default=str)
    except Exception:
        return f"live_params = {{'row':{row_idx},'operator':{op!r},'seed':{seed_v}}}"


def apply_live_parametrics_to_entry(app, entry, row_idx=0):
    """Write/refresh the live_parametrics column on a playlist entry (in-place)."""
    if not isinstance(entry, dict):
        return entry
    ops = entry.get("operators") or entry.get("operators_csv") or ""
    if isinstance(ops, list):
        op = str(ops[0]) if ops else "Operator"
    else:
        op = str(ops).split(",")[0].strip() or str(entry.get("operator") or "Operator")
    tag = build_live_parametrics_script(app, row_idx=row_idx, op_name=op, entry=entry)
    entry["live_parametrics"] = tag
    return entry


def blend_master_sequence_params(master, sequence, amount=0.5):
    """50/50 nominal mix of master instrument panel vs sequence-local panel.

    Used by the four non-GOAVA canonical engines so sequence-specific synth
    panels contribute without erasing master macros. Non-numeric keys prefer
    sequence when amount>=0.5 else master.
    """
    master = dict(master or {}) if isinstance(master, dict) else {}
    sequence = dict(sequence or {}) if isinstance(sequence, dict) else {}
    try:
        amt = float(amount)
    except Exception:
        amt = 0.5
    amt = max(0.0, min(1.0, amt))
    out = dict(master)
    keys = set(master) | set(sequence)
    for k in keys:
        a, b = master.get(k), sequence.get(k)
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            try:
                if math.isfinite(float(a)) and math.isfinite(float(b)):
                    out[k] = (1.0 - amt) * float(a) + amt * float(b)
                    continue
            except Exception:
                pass
        if amt >= 0.5 and k in sequence:
            out[k] = b
        elif k in master:
            out[k] = a
        else:
            out[k] = b
    return out

def blend_master_sequence_targets(master, targets, amounts=None):
    """Blend one master target against any number of sequence targets.

    ``targets`` is a sequence of parameter dictionaries. ``amounts`` are
    normalized internally, so N targets can participate without silently
    privileging the first secondary target. Non-numeric fields use the
    highest-weight target. This is the canonical multi-target blend primitive.
    """
    base = dict(master or {}) if isinstance(master, dict) else {}
    vals = [dict(x) for x in (targets or []) if isinstance(x, dict)]
    if not vals:
        return base
    if amounts is None:
        weights = [1.0] * len(vals)
    else:
        weights = [max(0.0, float(x)) for x in list(amounts)[:len(vals)]]
        if len(weights) < len(vals):
            weights += [1.0] * (len(vals) - len(weights))
    total = float(sum(weights))
    if total <= 0.0 or not math.isfinite(total):
        weights = [1.0 / len(vals)] * len(vals) if vals else []
    else:
        weights = [x / total for x in weights]
    out = dict(base)
    for key in set(base).union(*(v.keys() for v in vals)):
        nums = []
        for w, v in zip(weights, vals):
            x = v.get(key)
            if isinstance(x, (int, float)):
                try:
                    if math.isfinite(float(x)):
                        nums.append((w, float(x)))
                except Exception:
                    pass
        if nums:
            bw = max(0.0, 1.0 - sum(w for w, _ in nums))
            bx = base.get(key)
            if isinstance(bx, (int, float)):
                try:
                    if math.isfinite(float(bx)):
                        out[key] = bw * float(bx) + sum(w * x for w, x in nums)
                        continue
                except Exception:
                    pass
            sw = sum(w for w, _ in nums) or 1.0
            out[key] = sum((w / sw) * x for w, x in nums)
        else:
            best = max(zip(weights, vals), key=lambda z: z[0])
            if key in best[1]:
                out[key] = best[1][key]
    return out

def _coerce_instrument_param_state(state):
    """Return a safe {instrument_name: {param: value}} mapping.

    Legacy projects can contain malformed per-instrument values such as lists,
    tuples, strings, or other iterables. Preserve valid dictionaries and discard
    only malformed instrument payloads so UI/bootstrap/canonical painting remain
    recoverable.
    """
    if not isinstance(state, dict):
        return {}

    clean = {}

    for name, raw in state.items():
        if isinstance(raw, dict):
            clean[str(name)] = dict(raw)

    return clean

def blend_struct_labels(a, b, amount):
    """Blend two structure cell labels under coverage amount in [0,1].

    amount is the virtual-overlap fraction (same meaning as row_coverage /
    blend_max Half|Quarter). Result is a dual-label so Unison recycling can
    see both parents, weighted by overlap.
    """
    a = str(a or "").strip()
    b = str(b or "").strip()
    try:
        amt = float(amount)
    except Exception:
        amt = 0.5
    amt = max(0.0, min(1.0, amt))
    if not a and not b:
        return ""
    if not b or amt <= 0.02:
        return a
    if not a or amt >= 0.98:
        return b
    # Keep both parents visible; mark the dominant side.
    if amt < 0.5:
        return f"{a}~{b[:18]}@{amt:.0%}"
    return f"{b}~{a[:18]}@{(1.0 - amt):.0%}"


class FormulaModulatorWidget(QWidget):
    def __init__(self):
        super().__init__()
        layout = QVBoxLayout(self)
        layout.addWidget(QLabel("<b>Dynamic Coordinate Formula Inputs</b>"))

        # Formula Inputs
        self.x_input = self.create_formula_row(layout, "X-Axis Expr:", "np.sin(time * 2.0) + base_x")
        self.y_input = self.create_formula_row(layout, "Y-Axis Expr:", "np.cos(time * 1.5) * base_y")
        self.z_input = self.create_formula_row(layout, "Z-Axis Expr:", "abs(x + y) - time")

        # Compile Button
        self.compile_btn = QPushButton("Inject Formulas into Audio Thread")
        self.compile_btn.setStyleSheet("background-color: darkred; color: #101010; font-weight: bold;")
        layout.addWidget(self.compile_btn)

    def create_formula_row(self, parent_layout, label_text, default_expr):
        row = QHBoxLayout()
        row.addWidget(QLabel(label_text))

        line_edit = QLineEdit(default_expr)
        line_edit.setStyleSheet("background-color: #17233d; color: #0f0; font-family: monospace;")
        row.addWidget(line_edit)

        # Add a macro slider for manual offset tuning
        slider = QSlider(Qt.Orientation.Horizontal)
        slider.setRange(0, 100)
        slider.setValue(50)
        row.addWidget(slider)

        parent_layout.addLayout(row)
        return line_edit
class VisualOscilloscope(QFrame):
    """Meum-timed full-track waveform + live detail scope (left monitor).

    Shows seed-list preview ticks, ensemble RMS, and a filled waveform so
    multi-value scripts and multi-instrument mixes are visible at a glance.
    """
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(180, 180)
        self.setStyleSheet(
            "background-color: #0a0c0e; border: 1px solid #2a2e39; border-radius: 6px;"
        )
        self.wave_data = np.zeros(256, dtype=np.float32)
        self.track_overview = np.zeros(256, dtype=np.float32)
        self.playhead = 0.0  # 0..1
        self.mode = 0  # 0 master, 1 effected, 2 pattern, 3 activity
        self._title = "MEUM WAVEFORM"
        self.seed_values = []       # evaluated numeric seed list (preview)
        self.ensemble_voices = 0    # active render cluster size
        self.canonical_flags = []  # e.g. ["seeded","euclidean"]
        self._rms = 0.0
        self._peak = 0.0
        self._phosphor = np.zeros(256, dtype=np.float32)
        self._spark_phase = 0.0
        # OPERATOR-THEORY_DISPLAY: the visualizer waveform carries the book's
        # alternative arithmetic on its drawn points, and an optional shared
        # DSP follow-envelope is overplotted so the monitor reflects the same
        # full env-follow symmetry as the DSP pathway.
        self.operator_theory = True  # match global OT default ON
        self.follow_env = None
        self._universal_field_state = None
        self._universal_projection_state = None
        self._universal_self_procedure_state = None
        self._universal_correspondence_state = None

    def set_operator_theory(self, on):
        self.operator_theory = bool(on)
        self.update()

    def set_follow_env(self, env=None):
        if env is not None:
            self.follow_env = np.interp(
                np.linspace(0, len(env) - 1, 256),
                np.arange(len(env)),
                np.asarray(env, dtype=np.float32),
            ).astype(np.float32) if len(env) > 256 else np.resize(np.asarray(env, dtype=np.float32), 256)
        else:
            self.follow_env = None
        self.update()

    def set_mode(self, mode_idx):
        self.mode = int(mode_idx)
        if self.mode >= 6 and _universal_projection is not None and self._universal_field_state and UNIVERSAL_PROJECTION_TYPES:
            try:
                self._universal_projection_state = _universal_projection(self._universal_field_state, UNIVERSAL_PROJECTION_TYPES[(self.mode-6) % len(UNIVERSAL_PROJECTION_TYPES)])
            except Exception:
                self._universal_projection_state = None
        self.update()

    def set_seed_hud(self, seed_values=None, ensemble_voices=0, canonical_flags=None, engine_params=None):
        """HUD: seed list, ensemble, active engines, and live engine/macro parameters."""
        try:
            self.seed_values = [float(v) for v in (seed_values or []) if math.isfinite(float(v))][:12]
        except Exception:
            self.seed_values = []
        try:
            self.ensemble_voices = int(max(0, ensemble_voices or 0))
        except Exception:
            self.ensemble_voices = 0
        self.canonical_flags = list(canonical_flags or [])[:8]
        # engine_params: ordered list of "key=val" short strings or dict
        lines = []
        if isinstance(engine_params, dict):
            for k, v in list(engine_params.items())[:16]:
                try:
                    if isinstance(v, float):
                        lines.append(f"{k}={v:.3g}")
                    else:
                        lines.append(f"{k}={v}")
                except Exception:
                    lines.append(f"{k}=?")
        elif isinstance(engine_params, (list, tuple)):
            lines = [str(x)[:28] for x in engine_params[:16]]
        self.engine_param_lines = lines
        if _universal_field is not None:
            try:
                _seed = self.seed_values[0] if self.seed_values else 0.0
                self._universal_field_state = _universal_field(_seed, "live-visual", sequential_nums=self.seed_values, feature_vector=[self._rms, self._peak])
                self._universal_self_procedure_state = _universal_self_procedure(self._universal_field_state) if _universal_self_procedure else None
                self._universal_correspondence_state = _universal_correspondence(self._universal_field_state) if _universal_correspondence else None
                if self.mode >= 6 and UNIVERSAL_PROJECTION_TYPES:
                    self._universal_projection_state = _universal_projection(self._universal_field_state, UNIVERSAL_PROJECTION_TYPES[(self.mode-6) % len(UNIVERSAL_PROJECTION_TYPES)])
            except Exception:
                self._universal_field_state = self._universal_projection_state = None
                self._universal_self_procedure_state = self._universal_correspondence_state = None
        self.update()

    def update_waveform(self, new_data, overview=None, playhead=None, follow_env=None):
        if isinstance(new_data, np.ndarray) and new_data.size:
            self.wave_data = np.interp(
                np.linspace(0, new_data.size - 1, 256),
                np.arange(new_data.size),
                new_data.astype(np.float32),
            ).astype(np.float32)
            self._rms = float(np.sqrt(np.mean(self.wave_data ** 2)) + 1e-12)
            self._peak = float(np.max(np.abs(self.wave_data)) + 1e-12)
            if getattr(self, "_phosphor", None) is None or self._phosphor.size != 256:
                self._phosphor = np.zeros(256, dtype=np.float32)
            self._phosphor = (0.82 * self._phosphor + 0.18 * self.wave_data).astype(np.float32)
            self._spark_phase = (getattr(self, "_spark_phase", 0.0) + MEUM_NORM) % math.tau
        if isinstance(follow_env, np.ndarray) and follow_env.size:
            self.set_follow_env(follow_env)
        if isinstance(overview, np.ndarray) and overview.size:
            self.track_overview = np.interp(
                np.linspace(0, overview.size - 1, 256),
                np.arange(overview.size),
                overview.astype(np.float32),
            ).astype(np.float32)
        if playhead is not None:
            try:
                self.playhead = float(max(0.0, min(1.0, playhead)))
            except Exception:
                pass
        self.update()

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = max(self.width(), 1), max(self.height(), 1)
        vignette = QRadialGradient(w * 0.5, h * 0.58, max(w, h) * 0.72)
        vignette.setColorAt(0.0, QColor(8, 18, 24, 255))
        vignette.setColorAt(0.55, QColor(4, 8, 12, 255))
        vignette.setColorAt(1.0, QColor(0, 0, 0, 255))
        painter.fillRect(self.rect(), QBrush(vignette))

        painter.setPen(QColor("#00ffcc"))
        painter.setFont(QFont("Segoe UI", 8, QFont.Weight.Bold))
        painter.drawText(8, 14, self._title)
        painter.setFont(QFont("Segoe UI", 7))
        painter.setPen(QColor(0, 220, 180, 200))
        painter.drawText(max(8, w - 108), 14, f"RMS {self._rms:.3f}  Pk {self._peak:.2f}")

        ov_top, ov_bot = 22, int(h * 0.34)
        mid_ov = (ov_top + ov_bot) / 2.0
        amp_ov = (ov_bot - ov_top) * 0.42
        path_ov = QPainterPath()
        path_ov.moveTo(0, mid_ov)
        for i in range(256):
            x = i / 255.0 * (w - 1)
            y = mid_ov - float(self.track_overview[i]) * amp_ov
            path_ov.lineTo(x, y)
        path_ov.lineTo(w - 1, mid_ov)
        path_ov.closeSubpath()
        grad_ov = QLinearGradient(0, ov_top, 0, ov_bot)
        grad_ov.setColorAt(0.0, QColor(0, 255, 210, 70))
        grad_ov.setColorAt(1.0, QColor(0, 80, 120, 12))
        painter.fillPath(path_ov, QBrush(grad_ov))
        pen = QPen(QColor(0, 230, 200, 210))
        pen.setWidth(1)
        painter.setPen(pen)
        for i in range(255):
            x0 = int(i / 255.0 * (w - 1))
            x1 = int((i + 1) / 255.0 * (w - 1))
            y0 = mid_ov - float(self.track_overview[i]) * amp_ov
            y1 = mid_ov - float(self.track_overview[i + 1]) * amp_ov
            painter.drawLine(x0, int(y0), x1, int(y1))
        phx = int(self.playhead * (w - 1))
        glow = QPen(QColor(255, 140, 40, 90), 6)
        painter.setPen(glow)
        painter.drawLine(phx, ov_top, phx, ov_bot)
        painter.setPen(QPen(QColor("#ff6b00"), 2))
        painter.drawLine(phx, ov_top, phx, ov_bot)

        if self.seed_values:
            sv = self.seed_values
            mx = max(abs(v) for v in sv) or 1.0
            tick_y = ov_bot + 2
            for i, v in enumerate(sv):
                x = int((i + 0.5) / max(len(sv), 1) * (w - 1))
                ht = int(6 + 10 * abs(v) / mx)
                hue = int((abs(v) * 0.37) % 360)
                painter.setPen(QPen(QColor.fromHsv(hue, 200, 255, 220), 2))
                painter.drawLine(x, tick_y, x, tick_y + ht)

        det_top = ov_bot + (18 if self.seed_values else 6)
        mid_y = (det_top + h - 16) / 2.0
        amp = (h - det_top - 16) * 0.40 * MEUM_NORM * PHI
        amp = max(12.0, min((h - det_top - 16) * 0.5, amp * 4.0))
        hue_shift = (self.mode * 40) % 360
        c = QColor.fromHsv((hue_shift + 160) % 360, 210, 245)
        phos = getattr(self, "_phosphor", self.wave_data)

        def _wave_path(data, scale):
            path = QPainterPath()
            path.moveTo(0, mid_y)
            for i in range(256):
                x = i / 255.0 * (w - 1)
                y = mid_y - float(data[i]) * amp * scale
                path.lineTo(x, y)
            path.lineTo(w - 1, mid_y)
            path.closeSubpath()
            return path

        if self.mode >= 6:
            # UNIVERSAL_VISUAL_FIELD_2026: all extended views are selective /
            # subtractive projections of one count-independent canonical field.
            pr = self._universal_projection_state or {}
            vals = list((pr.get("selected") or {}).values())
            comp = list((pr.get("complement") or {}).values())
            vals = vals or comp or [0.5]
            kind = str(pr.get("kind") or "universal")
            painter.setPen(QPen(c, 2))
            cx, cy = w*0.5, (det_top+h-16)*0.5
            rad = max(18.0, min(w, h-det_top-16)*0.38)
            pts=[]
            for j,v in enumerate(vals):
                a=math.tau*(j/max(1,len(vals))) + float(v)*math.tau*(MEUM_MINUS_1)
                rr=rad*(0.25+0.75*float(v))
                pts.append(QPointF(cx+math.cos(a)*rr, cy-math.sin(a)*rr))
            if any(x in kind for x in ("graph","constellation","correspondence","map")):
                for j,p0 in enumerate(pts):
                    for k in range(j+1,min(len(pts),j+3)):
                        painter.drawLine(p0,pts[k])
                    painter.drawEllipse(p0,2.5,2.5)
            elif any(x in kind for x in ("terrain","surface","spectrogram","flow")):
                for j in range(max(2,len(vals)*3)):
                    x0=(j/max(1,len(vals)*3-1))*(w-1)
                    v=float(vals[j%len(vals)])
                    y0=cy-math.sin(j*(MEUM_MINUS_1)+v*math.tau)*rad*(0.2+0.8*v)
                    if j: painter.drawLine(prev,QPointF(x0,y0))
                    prev=QPointF(x0,y0)
            else:
                if pts:
                    for j in range(len(pts)): painter.drawLine(pts[j],pts[(j+1)%len(pts)])
            painter.setFont(QFont("Segoe UI",7,QFont.Weight.Bold))
            painter.setPen(QColor(220,255,240,210))
            painter.drawText(8, max(det_top+10, 30), kind.replace("_"," ").upper())
            _sp = self._universal_self_procedure_state or {}
            _co = self._universal_correspondence_state or {}
            _pc = (_sp.get("visual_projection_cover") or {}).get("projection_count", 0)
            _score = float(_co.get("correspondence_score", 0.0) or 0.0)
            painter.setFont(QFont("Segoe UI",6))
            painter.drawText(8, max(det_top+21, 41), f"SELF {int(_pc)}P · CORR {_score*100:.1f}% · FIELD {str((_sp or {}).get('field_id',''))[:8]}")
        elif self.mode == 4:
            # LISSAJOUS / XY VECTOR SCOPE: a genuinely different geometry, not
            # a hue-shifted copy of the amplitude-vs-time plot above. Plots
            # the live sample against a short-delayed copy of itself
            # (classic vector-scope self-delay trick), so harmonic content
            # and phase relationships show up as loop shapes instead of a
            # left-to-right trace.
            cx, cy = w / 2.0, (det_top + h - 16) / 2.0
            side = max(20.0, min(w, h - det_top - 16) * 0.5)
            painter.setPen(QPen(QColor(80, 90, 110, 100), 1))
            painter.drawEllipse(QPointF(cx, cy), side, side)
            delay = max(1, len(self.wave_data) // 9)
            pen = QPen(c)
            pen.setWidth(2)
            painter.setPen(pen)
            pts = []
            for i in range(len(self.wave_data)):
                x_v = float(self.wave_data[i])
                y_v = float(self.wave_data[(i + delay) % len(self.wave_data)])
                pts.append(QPointF(cx + x_v * side, cy - y_v * side))
            for i in range(len(pts) - 1):
                painter.drawLine(pts[i], pts[i + 1])
            painter.setPen(QPen(QColor(255, 255, 230, 200), 1))
            if pts:
                painter.drawEllipse(pts[-1], 3.0, 3.0)
        elif self.mode == 5:
            # PHOSPHOR PERSISTENCE SCOPE: stacks several recent decaying
            # phosphor layers (instead of the single 1.15x ghost used by the
            # other modes) so sustained/repeating material visibly builds up
            # brightness like a real analog scope's phosphor trail.
            if not hasattr(self, "_persist_layers") or len(self._persist_layers) != 6:
                self._persist_layers = [self.wave_data.copy() for _ in range(6)]
            self._persist_layers.pop()
            self._persist_layers.insert(0, self.wave_data.copy())
            layer_count = len(self._persist_layers)
            for li, layer in enumerate(self._persist_layers):
                fade = int(180 * (1.0 - li / layer_count) ** 1.6) if layer_count > 0 else 180
                if fade <= 2:
                    continue
                painter.setPen(QPen(QColor(c.red(), c.green(), c.blue(), fade), 2 if li == 0 else 1))
                for i in range(255):
                    x0 = int(i / 255.0 * (w - 1))
                    x1 = int((i + 1) / 255.0 * (w - 1))
                    y0 = mid_y - float(layer[i]) * amp
                    y1 = mid_y - float(layer[i + 1]) * amp
                    painter.drawLine(x0, int(y0), x1, int(y1))
            painter.setPen(QPen(QColor(80, 90, 110, 120), 1))
            painter.drawLine(0, int(mid_y), w, int(mid_y))
        else:
            # OPERATOR-THEORY_DISPLAY: when enabled the drawn waveform points
            # are re-bent through the book's scalar rules (band-hop add,
            # negative-run negating composition, divisor refinement) so the
            # visualizer carries the same arithmetic as the DSP pathway.
            # Operator Theory is an internal calculation route.  The display
            # consumes the same canonical waveform regardless of OT state; no
            # extra master-bus bend is permitted here.
            disp = self.wave_data
            disp_phos = phos
            painter.fillPath(_wave_path(disp_phos, 1.15), QColor(c.red(), c.green(), min(255, c.blue() + 40), 28))
            painter.fillPath(_wave_path(disp, 1.0), QColor(c.red(), c.green(), c.blue(), 55))
            glow_pen = QPen(QColor(c.red(), c.green(), c.blue(), 55))
            glow_pen.setWidth(6)
            painter.setPen(glow_pen)
            for i in range(255):
                x0 = int(i / 255.0 * (w - 1))
                x1 = int((i + 1) / 255.0 * (w - 1))
                y0 = mid_y - float(disp[i]) * amp
                y1 = mid_y - float(disp[i + 1]) * amp
                painter.drawLine(x0, int(y0), x1, int(y1))
            pen = QPen(c)
            pen.setWidth(2)
            painter.setPen(pen)
            for i in range(255):
                x0 = int(i / 255.0 * (w - 1))
                x1 = int((i + 1) / 255.0 * (w - 1))
                y0 = mid_y - float(disp[i]) * amp
                y1 = mid_y - float(disp[i + 1]) * amp
                painter.drawLine(x0, int(y0), x1, int(y1))
            # Cubic harmonic ribbon (shows stacked notes as extra motion)
            ribbon = QPen(QColor.fromHsv((hue_shift + 40) % 360, 180, 255, 140), 1)
            painter.setPen(ribbon)
            for i in range(255):
                a = float(disp[i])
                b = float(disp[i + 1])
                x0 = int(i / 255.0 * (w - 1))
                x1 = int((i + 1) / 255.0 * (w - 1))
                painter.drawLine(
                    x0, int(mid_y - (a * a * a) * amp * 0.85),
                    x1, int(mid_y - (b * b * b) * amp * 0.85),
                )
            painter.setPen(QPen(QColor(80, 90, 110, 120), 1))
            painter.drawLine(0, int(mid_y), w, int(mid_y))
            # Shared DSP follow-envelope overlay (full env-follow symmetry)
            fe = getattr(self, "follow_env", None)
            if isinstance(fe, np.ndarray) and fe.size:
                fep = QPainterPath()
                for i in range(256):
                    xv = i / 255.0 * (w - 1)
                    yv = mid_y - float(fe[i]) * amp * 0.6
                    if i == 0:
                        fep.moveTo(xv, yv)
                    else:
                        fep.lineTo(xv, yv)
                painter.setPen(QPen(QColor.fromHsv((hue_shift + 220) % 360, 180, 255, 160), 1.2, Qt.PenStyle.DashLine))
                painter.drawPath(fep)

        spark = getattr(self, "_spark_phase", 0.0)
        peak_i = int(np.argmax(np.abs(self.wave_data))) if self.wave_data.size else 0
        if abs(float(self.wave_data[peak_i])) > 0.08:
            sx = int(peak_i / 255.0 * (w - 1))
            sy = int(mid_y - float(self.wave_data[peak_i]) * amp)
            painter.setPen(QPen(QColor(255, 255, 230, 200), 1))
            rad = 3.0 + 2.0 * math.sin(spark)
            painter.drawEllipse(QPointF(sx, sy), rad, rad)

        painter.setFont(QFont("Segoe UI", 7))
        painter.setPen(QColor(160, 200, 220, 210))
        hud_parts = []
        if self.ensemble_voices:
            hud_parts.append(f"voices {self.ensemble_voices}")
        if self.seed_values:
            preview = ", ".join(f"{v:.3g}" for v in self.seed_values[:4])
            if len(self.seed_values) > 4:
                preview += "…"
            hud_parts.append(f"seed [{preview}]")
        if self.canonical_flags:
            hud_parts.append("ENG:" + "+".join(self.canonical_flags))
        if hud_parts:
            painter.drawText(8, h - 6, " · ".join(hud_parts)[: max(12, w // 5)])
        # Engine / macro parameter strip (right column)
        epl = getattr(self, "engine_param_lines", None) or []
        if epl:
            painter.setPen(QColor(180, 255, 200, 200))
            painter.setFont(QFont("Segoe UI", 6))
            x0 = max(8, w - 118)
            y0 = 22
            for i, line in enumerate(epl[:12]):
                painter.drawText(x0, y0 + i * 11, str(line)[:22])
            # Mini bar meters for numeric-looking params
            painter.setFont(QFont("Segoe UI", 6))
            for i, line in enumerate(epl[:8]):
                if "=" not in line:
                    continue
                try:
                    val = float(line.split("=", 1)[1])
                except Exception:
                    continue
                # normalize heuristically
                nv = abs(val)
                if nv > 1.5:
                    nv = min(1.0, nv / 100.0)
                nv = max(0.0, min(1.0, nv))
                by = y0 + i * 11 - 8
                painter.fillRect(x0 - 42, by, int(36 * nv), 6, QColor(80, 220, 160, 160))
                painter.setPen(QColor(60, 90, 80, 180))
                painter.drawRect(x0 - 42, by, 36, 6)
                painter.setPen(QColor(180, 255, 200, 200))


class SpectrumAnalyzer(QFrame):
    """Live FFT spectrum scanner (right monitor) — Meum-spaced bins.

    Seed-tinted hues and a peak tracer make multi-instrument energy readable.
    """
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(180, 180)
        self.setStyleSheet(
            "background-color: #0a0c0e; border: 1px solid #2a2e39; border-radius: 6px;"
        )
        self.mags = np.zeros(64, dtype=np.float32)
        self._smooth = np.zeros(64, dtype=np.float32)
        self.mode = 0
        self._title = "MEUM SPECTRUM"
        self.seed_hue = 0.0
        self.seed_values = []
        self.ensemble_voices = 0

    def set_mode(self, mode_idx):
        self.mode = int(mode_idx)
        self.update()

    def set_seed_hud(self, seed_values=None, ensemble_voices=0, canonical_flags=None):
        try:
            self.seed_values = [float(v) for v in (seed_values or []) if math.isfinite(float(v))][:12]
            if self.seed_values:
                self.seed_hue = float(abs(self.seed_values[0]) * 0.37) % 360.0
        except Exception:
            self.seed_values = []
            self.seed_hue = 0.0
        try:
            self.ensemble_voices = int(max(0, ensemble_voices or 0))
        except Exception:
            self.ensemble_voices = 0
        self.update()

    def update_spectrum(self, wave_data):
        if not isinstance(wave_data, np.ndarray) or wave_data.size < 8:
            return
        x = wave_data.astype(np.float32).ravel()
        n = min(len(x), 512)
        x = x[:n]
        tw = np.linspace(0, 1, n, endpoint=False)
        win = MEUM_NORM + (1.0 - MEUM_NORM) * 0.5 * (1.0 - np.cos(2 * np.pi * tw))
        x = x * win.astype(np.float32)
        nfft = 1
        while nfft < n:
            nfft <<= 1
        nfft = max(nfft, 64)
        if nfft > n:
            x = np.pad(x, (0, nfft - n))
        spec = np.fft.rfft(x)
        mag = np.abs(spec).astype(np.float32)
        if mag.size > 1:
            mag = mag[1:]
        target = 64
        idx = np.linspace(0, mag.size - 1, target)
        sampled = np.interp(idx, np.arange(mag.size), mag)
        sampled = np.log1p(MEUM * sampled)
        peak = float(np.max(sampled)) if sampled.size else 0.0
        target_mags = (sampled / peak).astype(np.float32) if peak > 0.0 and math.isfinite(peak) else np.zeros_like(sampled, dtype=np.float32)
        # Temporal smooth so multi-voice clusters don't flicker the bars
        self._smooth = (0.65 * self._smooth + 0.35 * target_mags).astype(np.float32)
        self.mags = self._smooth
        self.update()

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = max(self.width(), 1), max(self.height(), 1)
        bg = QLinearGradient(0, 0, 0, h)
        bg.setColorAt(0.0, QColor(12, 6, 4))
        bg.setColorAt(1.0, QColor(2, 2, 6))
        painter.fillRect(self.rect(), QBrush(bg))
        painter.setPen(QColor("#ff9a3c"))
        painter.setFont(QFont("Segoe UI", 8, QFont.Weight.Bold))
        painter.drawText(8, 14, self._title)
        if self.ensemble_voices:
            painter.setFont(QFont("Segoe UI", 7))
            painter.setPen(QColor(255, 180, 100, 200))
            painter.drawText(max(8, w - 70), 14, f"n={self.ensemble_voices}")

        n = len(self.mags)
        top = 20
        usable = h - top - 18
        bar_w = max(1.0, (w - 8) / max(n, 1))
        peak_i = int(np.argmax(self.mags)) if n else 0
        floor = h - 16

        if self.mode >= 6:
            # Same Universal Field projection family, rendered from spectral
            # measurements rather than from game state.  N changes sampling
            # density only; the projection kind remains upstream-defined.
            kind = UNIVERSAL_PROJECTION_TYPES[(self.mode-6) % len(UNIVERSAL_PROJECTION_TYPES)] if UNIVERSAL_PROJECTION_TYPES else "universal"
            vals=[float(x) for x in self.mags]
            cx,cy=w*0.5, top+(h-top-18)*0.5
            r=max(10.0,min(w,h-top-18)*0.34)
            pts=[]
            stride=max(1,len(vals)//24)
            for j,v in enumerate(vals[::stride]):
                a=math.tau*(j/max(1,len(vals[::stride]))) + v*(MEUM_MINUS_1)*math.tau
                rr=r*(0.3+0.8*v)
                pts.append(QPointF(cx+math.cos(a)*rr,cy+math.sin(a)*rr))
            painter.setPen(QPen(QColor.fromHsv(int(self.seed_hue)%360,200,240),1.5))
            if any(x in kind for x in ("graph","constellation","correspondence","map")):
                for j,p0 in enumerate(pts):
                    painter.drawEllipse(p0,2,2)
                    if j: painter.drawLine(pts[j-1],p0)
            else:
                for j in range(len(pts)-1): painter.drawLine(pts[j],pts[j+1])
                if len(pts)>2: painter.drawLine(pts[-1],pts[0])
            painter.setFont(QFont("Segoe UI",7,QFont.Weight.Bold))
            painter.drawText(8,h-5,kind.replace("_"," ").upper())
        elif self.mode == 4:
            # SPECTROGRAM WATERFALL: history of magnitude frames scrolling
            # downward, brightness = magnitude. A genuinely different
            # (time x frequency) view rather than a re-tinted bar chart.
            if not hasattr(self, "_waterfall_rows") or self._waterfall_rows is None:
                self._waterfall_rows = []
            self._waterfall_rows.insert(0, self.mags.copy())
            max_rows_hist = max(8, h - top - 4)
            del self._waterfall_rows[max_rows_hist:]
            row_h = max(1.0, (h - top - 4) / max_rows_hist)
            cell_w = max(1.0, (w - 8) / max(n, 1))
            for ri, row in enumerate(self._waterfall_rows):
                y = int(top + ri * row_h)
                for i, m in enumerate(row):
                    mag = float(m)
                    if mag < 0.02:
                        continue
                    hue = int((i / max(n - 1, 1)) * 280 + self.seed_hue) % 360
                    bright = 30 + int(220 * mag)
                    col = QColor.fromHsv(hue, 220, bright)
                    x = int(4 + i * cell_w)
                    painter.fillRect(x, y, max(1, int(cell_w) + 1), max(1, int(row_h) + 1), col)
        elif self.mode == 5:
            # RADIAL SPECTRUM: bins arranged around a circle instead of a
            # left-to-right bar chart — reads the same magnitude data as a
            # rotational shape, useful at a glance for overall energy/balance.
            cx, cy = w / 2.0, top + (h - top - 18) / 2.0
            r0 = min(w, h - top - 18) * 0.5
            r_span = min(w, h - top - 18) * 0.5
            for i, m in enumerate(self.mags):
                mag = float(m)
                ang = (i / max(n, 1)) * 2.0 * math.pi - math.pi / 2.0
                r1 = r0 + mag * r_span
                hue = int((i / max(n - 1, 1)) * 280 + self.mode * 25 + self.seed_hue) % 360
                col = QColor.fromHsv(hue, 210, 40 + int(200 * mag))
                x0 = cx + r0 * math.cos(ang)
                y0 = cy + r0 * math.sin(ang)
                x1 = cx + r1 * math.cos(ang)
                y1 = cy + r1 * math.sin(ang)
                painter.setPen(QPen(col, max(2, int(bar_w * 0.6))))
                painter.drawLine(QPointF(x0, y0), QPointF(x1, y1))
            painter.setPen(QPen(QColor(80, 90, 110, 120), 1))
            painter.drawEllipse(QPointF(cx, cy), r0, r0)
        else:
            for i, m in enumerate(self.mags):
                mag = float(m)
                bh = int(mag * usable)
                x = int(4 + i * bar_w)
                hue = int((i / max(n - 1, 1)) * 280 + self.mode * 25 + self.seed_hue) % 360
                bright = 40 + int(200 * mag)
                col = QColor.fromHsv(hue, 210, bright)
                bw = max(1, int(bar_w * 0.78))
                glow_h = min(usable, int(bh * 1.0) + 4)
                painter.fillRect(x - 1, floor - glow_h, bw + 2, glow_h, QColor(col.red(), col.green(), col.blue(), 40))
                painter.fillRect(x, floor - bh, bw, bh, col)
                # Mirror reflection
                painter.fillRect(x, floor, bw, max(1, bh // 5), QColor(col.red(), col.green(), col.blue(), 50))
                if i == peak_i and mag > 0.05:
                    painter.setPen(QPen(QColor(255, 255, 255, 210), 1))
                    painter.drawLine(x, floor - bh - 3, x + bw, floor - bh - 3)

        if self.seed_values:
            mx = max(abs(v) for v in self.seed_values) or 1.0
            for i, v in enumerate(self.seed_values):
                x = int(4 + (i + 0.5) / max(len(self.seed_values), 1) * (w - 8))
                painter.setPen(QPen(QColor.fromHsv(int(abs(v) * 0.37) % 360, 160, 220), 2))
                painter.drawPoint(x, h - 8)
                painter.drawLine(x, h - 8, x, h - 8 - int(6 * abs(v) / mx))


class InstrumentVisualObject:
    """Canonical one-route visual object bound to one live instrument.

    The object is dimension-agnostic: the same state vector can render as a
    1D filament, 2D closed surface, or 3D projected solid.  Dimension is a
    deterministic property of the instrument identity and composition schema,
    never a frame-random choice.  All geometry, motion, fade, and color are
    derived from the same live state used by audio: the five per-instrument
    patch parameters, sequence statistics, canonical voice parameters, seed,
    phase, harmonic spectrum, and engine flags.

    Critically, no term below depends on ensemble size for identity placement.
    N only determines how many instrument objects are present. Therefore the
    first two instruments in a 2-voice composition follow the same construction
    law as those same identities in a 64-voice composition.
    """
    PARAMS = ("morph", "harmonic_freq", "chaos", "fold_depth", "harmonic_lattice")

    def __init__(self, engine, index, name, canonical, schema):
        self.engine = engine
        self.index = int(index)
        self.name = str(name or f"Instrument {index+1}")
        self.canonical = dict(canonical or {})
        self.schema = dict(schema or {})
        self.seed = float(self.schema.get("seed", 0.0))
        self.phase0 = float(self.canonical.get("phase0", self.schema.get("phase", 0.0)))
        self.master_slot = int(self.canonical.get("master_slot", self.index)) % CANONICAL_MASTER_SLOTS
        self.identity = identity_unit("instrument-visual", self.seed, "master", self.master_slot)
        self.dimension = int(self.schema.get("dimension", 1 + int(self.identity * 3.0)))
        self.dimension = max(1, min(3, self.dimension))

    @staticmethod
    def _norm(v, lo, hi):
        try:
            return float(np.clip((float(v) - lo) / max(1e-9, hi-lo), 0.0, 1.0))
        except Exception:
            return 0.0

    def vector(self):
        p = self.schema.get("patch", {})
        seq = self.schema.get("sequence", {})
        c = self.canonical
        morph = self._norm(p.get("morph", 1.2), 0.01, 10.0)
        hf = self._norm(p.get("harmonic_freq", c.get("base_freq", 432.0)), 20.0, 20000.0)
        chaos = float(np.clip(float(p.get("chaos", 0.75)), 0.0, 1.0))
        fold = self._norm(p.get("fold_depth", 4.0), 1.0, 16.0)
        lattice = float(np.clip(float(p.get("harmonic_lattice", 0.33)), 0.0, 1.0))
        steps = self._norm(seq.get("steps_on", 0), 0.0, max(1.0, float(seq.get("length", 16))))
        amp = float(np.clip(seq.get("amp_mean", 0.0), 0.0, 1.0))
        pitch = float(np.clip(seq.get("pitch_mean", 1.0) / 2.0, 0.0, 1.0))
        ent = float(np.clip(c.get("entropy", 0.5), 0.0, 1.0))
        ratio = float(np.clip(abs(c.get("ratio", 1.0)) / 4.0, 0.0, 1.0))
        return dict(morph=morph, hf=hf, chaos=chaos, fold=fold, lattice=lattice,
                    steps=steps, amp=amp, pitch=pitch, ent=ent, ratio=ratio)

    def color(self, phase, energy):
        v = self.vector()
        # Bright continuous spectrum: identity selects the hue family; harmonic
        # frequency/lattice/phase sweep within it; energy controls luminance.
        hue = (360.0 * (self.identity + 0.31*v["hf"] + 0.17*v["lattice"] + phase / math.tau)) % 360.0
        sat = float(np.clip(0.58 + 0.30*v["chaos"] + 0.08*v["lattice"], 0.0, 1.0))
        val = float(np.clip(0.62 + 0.32*energy + 0.06*v["ent"], 0.0, 1.0))
        return self.engine._hsv(hue, sat, val)

    def geometry(self, t, energy, bands, w, h):
        v = self.vector()
        c = self.canonical
        # Placement is identity-seeded and N-independent.
        radial = 0.5 + 0.5 * math.sqrt(self.identity)
        angle0 = math.tau*self.identity + float(c.get("yaw", 0.0))
        phase = self.phase0 + t*(0.5 + 0.5*v["morph"] + 0.5*v["steps"])
        wobble = (0.0 + 0.5*v["chaos"]) * vg_sin(t*(0.5+2.0*v["fold"]) + self.identity*math.tau)
        cx = w*0.5 + vg_cos(angle0 + 0.5*vg_sin(t*0.5))*radial*w*0.70
        cy = h*0.5 + vg_sin(angle0*MEUM_INV + 0.5*vg_cos(t*0.5))*radial*h*0.5
        scale = (0.5 + 0.5*v["lattice"] + 0.5*v["amp"] + 0.5*energy) * min(w,h)
        harmonic_count = max(3, min(18, 3 + int(round(12*v["lattice"] + 4*v["fold"]))))
        band = float(bands[self.master_slot % len(bands)]) if len(bands) else 0.0
        scale *= 0.72 + 0.5*band + 0.5*abs(vg_sin(phase))
        return cx, cy, max(2.0, scale), phase, harmonic_count, v, wobble

    def draw(self, img, w, h, t, energy, bands):
        cx, cy, scale, phase, hc, v, wobble = self.geometry(t, energy, bands, w, h)
        dim = self.dimension
        # Always-visible breathe: opacity never drops to zero.
        breathe = 0.62 + 0.38*(0.5 + 0.5*vg_sin(phase + self.identity*math.tau))
        alpha = float(np.clip(0.38 + 0.42*breathe + 0.16*energy, 0.38, 0.98))
        col = self.color(phase, energy)
        core = self.engine._hsv((self.identity*360 + 180) % 360, 0.16, 1.0)

        if dim == 1:
            # 1D harmonic filament: one route, one canonical spectrum.
            pts=[]
            for k in range(hc*4):
                u=k/max(1,hc*4-1)
                a=phase + math.tau*(u*(1.0+v["fold"]*0.22))
                rr=scale*(0.45+0.85*u)*(1.0+0.24*vg_sin(a*hc*0.23+t))
                x=cx+vg_cos(a)*rr
                y=cy+vg_sin(a*MEUM_INV)*rr*(0.62+0.30*v["morph"])
                pts.append((x,y))
            for a,b in zip(pts,pts[1:]):
                self.engine._line(img,a[0],a[1],b[0],b[1],col,0.55*alpha)
            self.engine._dot(img,cx,cy,core,0.9*alpha,r=2)
        elif dim == 2:
            # 2D harmonic surface: closed radial contour with phase-locked folds.
            pts=[]
            count=max(16,hc*4)
            for k in range(count):
                a=phase+math.tau*k/count
                harmonic=sum((1.0/(j+1))*vg_sin(a*(j+1)+phase*(0.2+j*0.07)) for j in range(min(hc,8)))
                rr=scale*(0.82+0.10*vg_sin(a*hc)+0.06*harmonic+0.14*v["chaos"]*vg_sin(a*3+t))
                pts.append((cx+vg_cos(a)*rr,cy+vg_sin(a*MEUM_INV)*rr*(0.72+0.22*v["lattice"])))
            for k in range(len(pts)):
                a,b=pts[k],pts[(k+1)%len(pts)]
                self.engine._line(img,a[0],a[1],b[0],b[1],col,0.62*alpha)
            for k in range(1,len(pts)-1,2):
                self.engine._fill_tri(img,pts[0],pts[k],pts[k+1],col,0.14*alpha)
            self.engine._dot(img,cx,cy,core,0.65*alpha,r=2)
        else:
            # 3D shell: three projected rings plus depth-coupled cross edges.
            rings=[]
            for rix in range(3):
                pts=[]; rr0=scale*(0.58+0.22*rix)
                count=max(18,hc*3)
                for k in range(count):
                    a=phase+math.tau*k/count+rix*0.21
                    z=0.42*vg_sin(a*(1.0+v["fold"]*0.35)+t*0.8)+wobble
                    x3=rr0*vg_cos(a)
                    y3=rr0*vg_sin(a*MEUM_INV)
                    # lightweight 3D projection, consistent with the engine camera.
                    x3,y3,z3=self.engine._camera_transform(x3,y3,z)
                    depth=1.55+z3
                    sx=w*0.5+(cx-w*0.5+x3)/(depth)*1.0
                    sy=h*0.48+(cy-h*0.48+y3)/(depth)*1.0
                    pts.append((sx,sy))
                rings.append(pts)
            for ri,pts in enumerate(rings):
                for k in range(len(pts)):
                    a,b=pts[k],pts[(k+1)%len(pts)]
                    self.engine._line(img,a[0],a[1],b[0],b[1],col,(0.45+0.12*ri)*alpha)
                if ri:
                    prev=rings[ri-1]
                    for k in range(0,min(len(prev),len(pts)),max(1,len(pts)//12)):
                        self.engine._line(img,prev[k][0],prev[k][1],pts[k][0],pts[k][1],col,0.28*alpha)
            self.engine._dot(img,cx,cy,core,0.8*alpha,r=2)
        # Harmonic spectrum halo: same patch/lattice data, visible in all dimensions.
        for j in range(min(8, hc)):
            a=phase+math.tau*j/max(1,hc)
            rr=scale*(1.35+0.16*j)*(0.72+0.28*v["lattice"])
            self.engine._dot(img,cx+vg_cos(a)*rr,cy+vg_sin(a*MEUM_INV)*rr*0.70,
                             col,0.22*alpha,r=1+int(2*v["lattice"]))

class VideoSynthEngine:
    """
    Meum calculus-driven multi-subscene 2.5D/3D scenograph for live + export.

    Simplified Meum identities track the playhead and bulk audio state:
        u(t) = (M−1)/M · sin(M·t + φ) + (1/M)·centroid     [formation]
        ρ(t) = M^{k mod 6} · band_k · (1 + ε·seeded)         [radial scale]
        depth falloff via MEUM_POWERS; faces/segments/volumes from expanded
        or contracted vertex sets with selective constant insert/remove.

    Live engines (seeded / Euclidean) and playlist density drive substitutions.
    Oscilloscope/FFT are UI-only — never drawn into export frames.
    """

    SUBSCENE_COUNT = 6  # field, ribbon, volumes, faces, segments, particles

    def __init__(self, n_instruments=48):
        # Instrument count is a live engine input.  Keep a target count and a
        # render count so the scenograph can follow ensemble resizes without
        # popping, while the rest of the audio/UI engine can use the exact
        # target count immediately.
        self.n = int(max(2, min(128, n_instruments)))
        self._render_n = float(self.n)
        self._target_n = self.n
        self._n_resize_alpha = 1.0
        self.wave = np.zeros(256, dtype=np.float32)
        self.t = 0.0
        self.playhead = 0.0  # 0..1 composition progress
        self.mode = 0
        self.app = None
        self.export_mode = False  # True during video export (no UI chrome)
        self._band = np.zeros(8, dtype=np.float32)
        self._rms = 0.0
        self._centroid = 0.5
        self._peak = 0.0
        self._video_hue_shift = 0.0
        self._video_energy = 0.0
        self.width = 0.0
        self.height = 0.0
        self.center_x = self.width / 2.0
        self.center_y = self.height / 2.0
        self.MEUM_INV = 1.0 / 1.19758073433
        self.PHI = 1.61803398875
        # Fixed-input scenograph mesh: width/height/resolution/ctx never vary
        # frame-to-frame, so compute it once here instead of re-instantiating
        # MeumScenographController and recomputing the same mesh every
        # render_frame() call (its result was previously discarded unused).
        _t = np.linspace(0.0, math.tau, 64)
        _sx = np.sin(_t * PHI + 0.4759) * np.cos(_t * MEUM_INV)
        _sy = np.cos(_t * PHI + 0.4759) * np.sin(_t * MEUM_INV)
        _sz = np.sin(_t * MEUM_INV * 2.0)
        _depth = 1.0 / (1.0 + _sz * 0.1 * MEUM_INV)
        self._scenograph_points = [(float(400.0 + x * 512.0 * d), float(400.0 + y * 512.0 * d)) for x,y,d in zip(_sx,_sy,_depth)]
        # One visual object is created per live instrument. No independent
        # graphical-object count exists: visual population == instrument count.
        self.SCENOGRAPH_ITEM_CATALOG = [
            "field", "ribbon", "volumes", "faces", "particles", "bands", "goava",
            "filaments", "roses", "orbitals", "constellations", "lattice",
            "bursts", "spectral_comets", "rhythm_mandala", "pulse_grid",
            "goava_field", "meum_spiral", "phi_web", "silver_arcs", "harmonic_rings",
            "seed_sparks", "euclidean_spokes", "phase_ribbons", "tensor_sheets",
            "soliton_beads", "entropy_mist", "carrier_wake", "playlist_bars",
            "voice_orbs", "depth_fog", "polar_grid", "hex_lattice", "voronoi_cracks",
            "aurora_bands", "comet_trails", "pulse_halos", "node_links", "chord_fans",
            "sub_bass_bloom", "air_glitter", "mid_ribbons", "hi_spray", "fold_caustics",
            "lock_rings", "rand_static", "seeded_constellation", "goava_glyphs",
            "scan_lines", "radial_ticks", "soft_blobs", "crystal_shards", "wave_fronts",
            "orbit_dust", "magnet_lines", "plasma_wisps", "gravity_wells", "time_ticks",
            "identity_pins", "mix_meters", "wave_integration", "meum_residue", "silence_veil",
            "ensemble_cloud",
        ]
        while len(self.SCENOGRAPH_ITEM_CATALOG) < 64:
            self.SCENOGRAPH_ITEM_CATALOG.append(f"item_{len(self.SCENOGRAPH_ITEM_CATALOG)}")
        self.SCENOGRAPH_ITEM_CATALOG = self.SCENOGRAPH_ITEM_CATALOG[:64]
        self._module_fade = {name: 0.0 for name in self.SCENOGRAPH_ITEM_CATALOG}
        # Core defaults (legacy weights)
        _defaults = {
            "field": 0.62, "volumes": 0.52, "faces": 1.0, "particles": 1.0,
            "filaments": 0.72, "roses": 0.55, "orbitals": 0.62,
            "constellations": 0.48, "lattice": 0.36,
            "rhythm_mandala": 0.40, "pulse_grid": 0.35,
            "meum_spiral": 0.45, "phi_web": 0.38, "harmonic_rings": 0.42,
            "voice_orbs": 0.50, "ensemble_cloud": 0.40,
        }
        for k, v in _defaults.items():
            if k in self._module_fade:
                self._module_fade[k] = v
        self._module_target = dict(self._module_fade)
        self._item_phase = {name: (i * PHI * MEUM_NORM) % 1.0 for i, name in enumerate(self.SCENOGRAPH_ITEM_CATALOG)}
        self._scenograph_modules = {}
        self._rng = np.random.RandomState(7)
        self._visual_frame = 0
        self._visual_entropy = 0.5
        # CANONICAL_VISUAL_2026 ledger — visual dual of the audio union-entropy
        # ledger (same draw family, same 0.5 fixed point, same assertion rules).
        self._canonical = []
        self._canonical_ctx = {}
        self._canonical_flags = {}
        self._vled_n = 0.0
        self._vled_sum = 0.0
        self._vled_sumsq = 0.0
        self._vled_rmin = 1.0
        self._vled_rmax = 0.0
        self._vled_full_window = False
        self._vled_mean = ENTROPY_FIXED_POINT
        self._vled_std = 0.0
        self._vled_ok = True
        # Implode-to-fit: map scene bbox onto the full frame
        self._fit_cx = 0.0
        self._fit_cy = 0.0
        self._fit_sx = 1.0
        self._fit_sy = 1.0
        self._fit_ox = 0.0
        self._fit_oy = 0.0
        # Camera + packing: deterministic golden-angle placement with an
        # implosive scale law keeps instrument objects separated while the
        # camera gently rotates the whole 3D field.
        self._cam_yaw = 0.0
        self._cam_pitch = 0.0
        self._cam_roll = 0.0
        self._cam_distance = 1.0
        self._cam_fov_deg = 48.0
        self._cam_pan_x = 0.0
        self._cam_pan_y = 0.0
        self._camera_view_override = None
        self._visual_view_index = 0
        self._visual_view_count = 1
        self._manual_yaw = 0.0
        self._manual_pitch = 0.0
        self._pack_radius = 0.0
        self._pack_scale_floor = 0.28
        self.layers = []
        for i in range(self.n):
            # `MEUM_POWERS_36[i % 12]` and `4 + (i % 5)` repeated every 12 / 5
            # instruments (instrument 0 and 12 got the identical depth; 0 and
            # 5 the identical poly count). MEUM is irrational, so indexing the
            # same 36-entry table by the fractional position of `i * MEUM`
            # instead of `i % 12` never repeats for any i, while still
            # drawing from the same canonical power table used elsewhere.
            _tpos = (i * MEUM * 3.0) % 36.0
            _tlo = int(_tpos) % 36
            _thi = (_tlo + 1) % 36
            _tfrac = _tpos - int(_tpos)
            depth = 1.35 + 0.18 * (MEUM_POWERS_36[_tlo] * (1.0 - _tfrac) + MEUM_POWERS_36[_thi] * _tfrac)
            self.layers.append({
                "i": i,
                "distance": depth,
                "yaw": (i * PHI * MEUM_NORM) % (2 * np.pi),
                "pitch": 0.12 * np.sin(i * MEUM),
                "roll": 0.09 * np.cos(i * MEUM_INV),
                "hue": int((i * 360 / max(self.n, 1) + i * 7) % 360),
                "life": 0.3,
                "family": i // 8,
                "active_verts": 4 + int(((i * MEUM * 5.0) % 1.0) * 8),  # expanded/contracted poly size
            })

    def instruments_handler(self, index, count=None):
        """Pure instrument→visual translation with inverse-count compensation."""
        n = int(count if count is not None else self.n)
        return instruments_handler(index, n,
                                  seed=(self._canonical_ctx or {}).get("seed", 0.0),
                                  sequential_nums=(self._canonical_ctx or {}).get("sequential_nums", ()))

    def bind_app(self, app):
        self.app = app
        # Pull the current ensemble size when binding/rebinding so the visual
        # engine cannot remain stranded at its construction-time default.
        try:
            names = getattr(app, "instrument_names_48", None)
            if names:
                self.set_instrument_count(len(names), smooth=False)
        except Exception:
            pass

    def set_instrument_count(self, count, smooth=True):
        """UI ensemble size only — does NOT change seeded video identity.

        Canonical visual layers are always the fixed 16-slot master lattice
        (see ``_build_canonical_ctx_and_layers``).  ``self.n`` tracks the host
        instrument spinner for labels/admission fades, but seeded geometry,
        entropy, fractal set pick, and mode blends are functions of seed +
        engines + sequential numerics alone — same contract as the music
        canonical master.  Changing instrument count must not re-blend the
        video.
        """
        try:
            target = int(max(2, min(128, int(count))))
        except Exception:
            return
        old_n = int(getattr(self, "n", target))
        old_layers = list(getattr(self, "layers", []) or [])
        self.n = target
        self._target_n = target

        # Reuse existing layer state by index wherever possible.  This avoids
        # geometry jumps when the user adds/removes instruments.
        layers = []
        # Retain the old tail during a shrink so it can visually ease out.
        # During growth, the newly appended layers start at life=0 and ease in.
        layer_capacity = max(target, len(old_layers))
        for i in range(layer_capacity):
            if i < len(old_layers):
                layer = dict(old_layers[i])
                layer["i"] = i
                layer["family"] = i // 8
                # Fixed 128-slot hue lattice — not divided by live instrument count
                layer["hue"] = int((i * 360 / 128.0 + i * 7) % 360)
                if i >= target:
                    layer["life"] = float(layer.get("life", 0.3))
            else:
                _tpos = (i * MEUM * 3.0) % 36.0
                _tlo = int(_tpos) % 36
                _thi = (_tlo + 1) % 36
                _tfrac = _tpos - int(_tpos)
                depth = 1.35 + 0.18 * (MEUM_POWERS_36[_tlo] * (1.0 - _tfrac) + MEUM_POWERS_36[_thi] * _tfrac)
                layer = {
                    "i": i,
                    "distance": depth,
                    "yaw": (i * PHI * MEUM_NORM) % (2 * np.pi),
                    "pitch": 0.12 * np.sin(i * MEUM),
                    "roll": 0.09 * np.cos(i * MEUM_INV),
                    "hue": int((i * 360 / max(target, 1) + i * 7) % 360),
                    "life": 0.0,
                    "family": i // 8,
                    "active_verts": 4 + int(((i * MEUM * 5.0) % 1.0) * 8),
                }
            layers.append(layer)
        self.layers = layers

        # No temporal resize state: instrument count is a pure composition
        # input.  A resize must not depend on how many frames elapsed before
        # rendering, so there is no fade/interpolation in the canonical path.
        self._render_n = float(target)
        self._n_resize_alpha = 1.0

    def _advance_instrument_resize(self):
        """Ease the visible layer population toward the live synth count.

        Shrinks therefore stop admitting the removed tail immediately; the
        stale tail remains drawable until _render_n crosses it, then vanishes.
        """
        current = float(getattr(self, "_render_n", self.n))
        target = float(getattr(self, "_target_n", self.n))
        # PAINT_PERIOD_S is the engine's normal update cadence; this factor
        # gives a short, frame-rate-independent-feeling visual settling time.
        step = float(np.clip(PAINT_PERIOD_S * 8.0, 0.08, 0.24))
        current += (target - current) * step
        if abs(target - current) < 0.03:
            current = target
        self._render_n = current
        self._n_resize_alpha = float(np.clip(1.0 - abs(target - current) / max(abs(target - getattr(self, "_resize_start_n", target)), 1.0), 0.0, 1.0))

    def set_waveform(self, data, playhead=None):
        if data is None:
            return
        arr = np.asarray(data, dtype=np.float32).ravel()
        if arr.size == 0:
            return
        self.wave = np.interp(
            np.linspace(0, arr.size - 1, 256),
            np.arange(arr.size),
            arr,
        ).astype(np.float32)
        self.t += PAINT_PERIOD_S * MEUM_NORM
        if playhead is not None:
            try:
                self.playhead = float(max(0.0, min(1.0, playhead)))
            except Exception:
                pass
        self._analyze()

    def ingest_video_frame_stats(self, mean_rgb=None, energy=0.0):
        if mean_rgb is not None:
            r, g, b = [float(x) for x in mean_rgb[:3]]
            # RGB means are already in [0, 1]; map luminance directly across
            # the complete hue circle instead of compressing it into 60 degrees.
            self._video_hue_shift = (0.2126 * r + 0.7152 * g + 0.0722 * b) * 360.0
        self._video_energy = float(energy)

    def frame_stats(self, frame=None):
        """Deterministic (mean_rgb, energy) digest of a rendered video frame.

        This is the reverse signal direction: video output -> software output.
        mean_rgb is the per-channel mean normalized to [0, 1]; energy is the
        luminance RMS in [0, 1]. It is a pure function of the frame bytes, so
        the video -> software bridge is itself deterministic and
        seed-reproducible (the two-way signal-to-output cross-validation).
        """
        f = frame if frame is not None else getattr(self, "_frame", None)
        if f is None:
            return (0.0, 0.0, 0.0), 0.0
        arr = np.asarray(f, dtype=np.float32)
        if arr.ndim == 2:
            mean_rgb = tuple(float(np.mean(arr) / 255.0) for _ in range(3))
        else:
            mean_rgb = tuple(
                float(np.mean(arr[..., c]) / 255.0) for c in range(min(3, arr.shape[2]))
            )
        lum = arr
        if arr.ndim == 3 and arr.shape[2] >= 3:
            lum = arr[..., 0] * 0.2126 + arr[..., 1] * 0.7152 + arr[..., 2] * 0.0722
        energy = float(np.clip(np.sqrt(np.mean((lum / 255.0) ** 2)), 0.0, 1.0))
        return tuple(mean_rgb[:3]), energy

    def _analyze(self):
        w = self.wave
        self._rms = float(np.sqrt(np.mean(w ** 2)) + 1e-9)
        self._peak = float(np.max(np.abs(w)) + 1e-9)
        # Harmonic/octave-ish bands: use the spectral domain rather than
        # eight arbitrary waveform slices.  This makes visual population follow
        # actual doubling boundaries (and keeps the response stable as FFT
        # content changes).
        spec = np.abs(np.fft.rfft(w * np.hanning(len(w)))) + 1e-9
        freqs = np.fft.rfftfreq(len(w), d=1.0 / 256.0)
        edges = np.geomspace(1.0, max(2.0, float(freqs[-1])), 9)
        bands = []
        for b in range(8):
            mask = (freqs >= edges[b]) & (freqs < edges[b + 1])
            bands.append(float(np.sqrt(np.mean(spec[mask] ** 2))) if np.any(mask) else 1e-9)
        self._band = np.asarray(bands, dtype=np.float32)
        # Preserve the actual spectral distribution.  Peak-normalizing each
        # frame forced its loudest band to 1.0 and distorted every other band.
        # Energy-share normalization keeps all eight bands proportional to the
        # measured spectrum and does not invent a per-frame reference level.
        band_total = float(np.sum(self._band))
        if band_total > 1e-12:
            self._band /= band_total
        self._harmonic_activity = float(1.0 - float(np.max(self._band)))
        self._octave_boundary = (
            float(self._band[1] / self._band[0]) if self._band[0] > 1e-12 else float("inf")
        )
        idx = np.arange(256, dtype=np.float32)
        mag = np.abs(w) + 1e-9
        self._centroid = float(np.sum(idx * mag) / (np.sum(mag) * 255.0))

    def energy(self):
        return self._rms

    # ----- Meum calculus state (playhead-tracking simplified identities) -----
    def _meum_state(self):
        """Evaluate simplified Meum equations with live substitutions."""
        snap = self._live_snap()
        ph = self.playhead
        t = self.t
        # USER_TRACK_OFFSET_2026: user-set global track offset shifts visual time
        # the same way audio schedules shift — not a canonical rewrite handle.
        try:
            gto = float(snap.get("global_track_offset", snap.get("track_offset", 0.0)) or 0.0)
            if not math.isfinite(gto):
                gto = 0.0
            # Offset is in playlist-row units; map a fraction of a cycle into phase.
            t = float(t) + gto
            ph = (float(ph) + gto * 0.125) % 1.0
        except Exception:
            pass
        # Base identities
        u = MEUM_NORM * vg_sin(MEUM * t + ph * math.tau) + MEUM_INV * self._centroid
        # Dimensional expand/contract: insert/remove powers based on engines
        k_pow = 1
        if snap["seeded"]:
            k_pow += 1  # insert M^2 term
        if snap["euclid"]:
            k_pow += 1  # insert M^3 influence
        if snap["struct"] > 0.4:
            k_pow = max(0, k_pow - 1)  # contract: remove a power
        rho = float(MEUM_POWERS_36[min(k_pow, 35)]) * (0.4 + 0.6 * self._rms)
        # Variable substitution: ε from residual + live randomizer pulse
        eps = abs(MEUM_IDENTITY_RESIDUAL) * 10.0 + (0.08 if snap["seeded"] else 0.0)
        # 50%-floor stochastic perturbation: enough entropy to keep the
        # scenograph evolving without changing canonical audio determinism.
        eps += 0.035 * (self._visual_entropy - 0.5)
        # Group-theory reduction: instrument indices live in Z/n and are
        # permuted by a seed-stable affine orbit. GOAVA changes the action.
        ensemble_n = max(2, min(128, int(snap.get("ensemble", self.n) or self.n)))
        orbit_step = max(1, group_orbit_index(1, ensemble_n, snap.get("seed", 0.0), snap.get("goava", False)))
        if ensemble_n > 2 and math.gcd(max(1, orbit_step), ensemble_n) != 1:
            orbit_step = next((q for q in range(1, ensemble_n) if math.gcd(q, ensemble_n) == 1), 1)
        group_phase = (orbit_step / ensemble_n) if ensemble_n else 0.0
        form = float(np.clip(0.25 + 0.45 * abs(u) + 0.2 * rho + eps * self._band[int(ph * 7) % 8], 0.05, 1.0))
        # Seed-list modulates form so multi-value scripts reshape the scenograph.
        seed_list = snap.get("seed_list") or []
        if seed_list:
            smean = float(sum(abs(v) for v in seed_list) / len(seed_list)) if seed_list else 0.0
            form = float(np.clip(form * (0.5 + 0.5 * ((smean % 100.0) / 100.0)), 0.0, 1.0))
            k_pow = min(35, k_pow + max(0, len(seed_list) - 1) // 2)
        # Volume shell scale from 2^M / M^2 partner
        vol_s = float(MEUM_TWO_POW_OVER_SQ) * (0.5 + 0.5 * self._peak) * (0.6 + 0.4 * snap["eqr"])
        # Instrument Count does not create decorative complexity; spectral/audio
        # activity above is the source of this visual scale.
        vol_s *= float(np.clip(0.90 + 0.20 * self._harmonic_activity, 0.90, 1.10))
        # Line density from log2(M) · BPM coupling
        line_d = MEUM_LOG2 * (0.5 + 0.5 * (snap["bpm"] / 140.0)) * (0.4 + 0.6 * snap["fractal"])
        if snap.get("canonical_count"):
            line_d *= 1.0 + 0.08 * float(snap["canonical_count"])
        # CANONICAL_COMMAND_2026: master vector / xmod / resonance drive the
        # visual engine under canonical authority. Resonance is always 50–150%.
        resonance = 1.0
        master_vector = (0.0, 0.0, 0.0)
        master_drive = 0.5
        xmod = 1.0
        try:
            if self.app is not None:
                # Natural operating band is 50–150%; do not hard-clamp live values.
                resonance = float(getattr(self.app, "canonical_resonance_factor", CANONICAL_RESONANCE_DEFAULT) or CANONICAL_RESONANCE_DEFAULT)
                if not math.isfinite(resonance):
                    resonance = 1.50
                if hasattr(self.app, "_master_vector_effective"):
                    mv = self.app._master_vector_effective()
                    master_vector = (float(mv[0]), float(mv[1]), float(mv[2]))
                st = getattr(self.app, "master_vector_state", None) or {}
                master_drive = float(np.clip(st.get("drive", 0.50), 0.0, 1.0)) if bool(st.get("enabled", True)) else 0.0
                gms = getattr(self.app, "global_mod_state", None) or {}
                xmod = float(np.clip(gms.get("xmod", 1.0), 0.0, 2.0))
            # Apply resonance as activity/continuation drive (not volume)
            form = float(np.clip(form * (0.70 + 0.30 * resonance), 0.05, 1.5))
            rho = float(np.clip(rho * (0.80 + 0.20 * resonance), 0.05, 2.0))
            line_d = float(np.clip(line_d * (0.85 + 0.15 * resonance), 0.05, 2.0))
            # Master vector XYZ tilts formation and scale
            if master_drive > 1e-6:
                vx, vy, vz = master_vector
                form = float(np.clip(form * (1.0 + 0.12 * master_drive * vx), 0.05, 1.5))
                rho = float(np.clip(rho * (1.0 + 0.10 * master_drive * vy), 0.05, 2.0))
                vol_s = float(np.clip(vol_s * (1.0 + 0.08 * master_drive * vz), 0.05, 2.0))
            # Global XMOD deepens cross-modulation of the scenograph
            form = float(np.clip(form * (0.85 + 0.15 * xmod), 0.05, 1.5))
            eps = float(np.clip(eps * (0.90 + 0.10 * xmod), 0.0, 1.0))
        except Exception:
            resonance = 1.0
            master_vector = (0.0, 0.0, 0.0)
            master_drive = 0.5
            xmod = 1.0
        return {
            "u": u, "rho": rho, "form": form, "vol_s": vol_s, "line_d": line_d,
            "eps": eps, "k_pow": k_pow, "snap": snap, "ph": ph,
            "group_order": ensemble_n, "group_step": orbit_step, "group_phase": group_phase,
            "canonical_resonance_factor": resonance,
            "master_vector": master_vector,
            "master_vector_drive": master_drive,
            "global_xmod": xmod,
        }

    def _live_snap(self):
        snap = {
            "seeded": False, "euclid": False, "eqr": 0.2247, "fractal": 0.40,
            "struct": 0.0, "bpm": 120.0, "carrier": 0.0, "pkp": 0.5, "seed": 0.0,
            "goava": False, "phase_lock": False, "randomizer": False,
            "seed_list": [], "ensemble": 1, "canonical_count": 0,
            "live_dj_goava": False, "live_dj_random": False, "live_dj_pair_index": 0,
            "live_dj_pair_signature": 0,
        }
        app = self.app
        if app is None:
            return snap
        try:
            snap["seeded"] = bool(getattr(app, "btn_seeded_randomize", None) and app.btn_seeded_randomize.isChecked())
            snap["goava"] = bool(getattr(app, "btn_goava", None) and app.btn_goava.isChecked())
            snap["euclid"] = bool(getattr(app, "btn_idealize_rhythm", None) and app.btn_idealize_rhythm.isChecked())
            snap["phase_lock"] = bool(getattr(app, "btn_local_phase_lock", None) and app.btn_local_phase_lock.isChecked())
            snap["randomizer"] = bool(getattr(app, "btn_local_randomize", None) and app.btn_local_randomize.isChecked())
            snap["live_dj_goava"] = bool(getattr(app, "btn_live_dj_goava", None) and app.btn_live_dj_goava.isChecked())
            snap["live_dj_random"] = bool(getattr(app, "btn_live_dj_random", None) and app.btn_live_dj_random.isChecked())
            snap["live_dj_pair_index"] = int(getattr(app, "_live_dj_pair_index", 0))
            snap["live_dj_pair_signature"] = int(getattr(app, "_live_dj_pair_signature", 0))
            snap["canonical_count"] = sum(
                1 for k in ("seeded", "goava", "euclid", "phase_lock", "randomizer") if snap.get(k)
            )
            if hasattr(app, "slider_eqr"):
                snap["eqr"] = app.slider_eqr.value() / 100.0
            if hasattr(app, "slider_fractalizer"):
                snap["fractal"] = app.slider_fractalizer.value() / 100.0
            if hasattr(app, "slider_pkp_envelope"):
                snap["pkp"] = app.slider_pkp_envelope.value() / 1000.0
            if hasattr(app, "spin_bpm"):
                snap["bpm"] = float(app.spin_bpm.value())
            # Full seed list (not just first component) drives visual population
            if hasattr(app, "get_seed_values"):
                try:
                    vals = list(app.get_seed_values(t_value=float(getattr(self, "t", 0.0)) % 8.0) or [])
                    snap["seed_list"] = [float(v) for v in vals if math.isfinite(float(v))][:16]
                    if snap["seed_list"]:
                        snap["seed"] = float(snap["seed_list"][0])
                        snap["ensemble"] = max(1, min(len(snap["seed_list"]), int(getattr(self, "n", 8) or 8)))
                except Exception:
                    pass
            if not snap["seed_list"] and hasattr(app, "get_numeric_seed"):
                try:
                    snap["seed"] = float(app.get_numeric_seed() or 0.0)
                except Exception:
                    pass
            if getattr(app, "imported_waveform", None) is not None:
                snap["carrier"] = 1.0
            rows = getattr(app, "master_playlist_data", None) or []
            active = sum(1 for r in rows if isinstance(r, dict) and any(
                r.get(k) not in (None, "", [], {}) for k in
                ("operator", "operators_csv", "script_tag", "domain_tag", "synth_tag", "patch_tag")
            ))
            snap["struct"] = min(1.0, active / 24.0)
            if active:
                snap["ensemble"] = max(snap["ensemble"], min(48, max(1, active // 2)))
            # CANONICAL_COMMAND_2026: surface master vector / xmod / resonance
            # so every visual path under canonical authority sees them.
            try:
                snap["canonical_resonance_factor"] = float(getattr(app, "canonical_resonance_factor", CANONICAL_RESONANCE_DEFAULT) or CANONICAL_RESONANCE_DEFAULT)
                gms = getattr(app, "global_mod_state", None) or {}
                snap["global_xmod"] = float(np.clip(gms.get("xmod", 1.0), 0.0, 2.0))
                snap["global_input_xmod"] = float(np.clip(gms.get("input_xmod", 1.0), 0.0, 2.0))
                if hasattr(app, "_master_vector_effective"):
                    mv = app._master_vector_effective()
                    snap["master_vector"] = (float(mv[0]), float(mv[1]), float(mv[2]))
                st = getattr(app, "master_vector_state", None) or {}
                snap["master_vector_drive"] = float(np.clip(st.get("drive", 0.50), 0.0, 1.0))
                snap["master_vector_enabled"] = bool(st.get("enabled", True))
                # User-owned TrackOffset — engines respond; canonical does not own it
                try:
                    snap["global_track_offset"] = float(getattr(app, "global_track_offset", 0.0) or 0.0)
                    snap["track_offset"] = snap["global_track_offset"]
                except Exception:
                    snap["global_track_offset"] = 0.0
                    snap["track_offset"] = 0.0
            except Exception:
                pass
        except Exception:
            pass
        return snap

    def _reset_fit(self, w, h):
        self._fit_cx = w * 0.5
        self._fit_cy = h * 0.5
        self._fit_sx = 1.0
        self._fit_sy = 1.0
        self._fit_ox = w * 0.5
        self._fit_oy = h * 0.5

    def _update_camera_and_packing(self, st):
        """IDEAL_CAMERA_2026 — multi-band deterministic camera + identity packing.

        Six simultaneous degrees of freedom, all closed-form
        f(t, seed, composition, audio features) — never RNG:

          yaw      tempo-locked orbit + Meum slow drift + energy push
          pitch    spectral elevation + subharmonic nod
          roll     micro horizon (dimensional, never seasick)
          distance dolly in/out with RMS and structural density
          fov      mild breathe with harmonic activity
          pan      lateral shift from phase-lock / GOAVA

        Band rates are irrational multiples of BPM and MEUM so the path is
        dense on the torus (no short-period loops) while remaining
        bit-identical for the same seed + composition + time.

        Packing places each instrument by its *identity unit* (master-slot
        lattice), not by "index among N". Ensemble size N only scales density
        (implode); the same instrument identity occupies the same angular
        home in a 2-voice or 64-voice composition.
        """
        snap = st.get("snap", {}) if isinstance(st.get("snap"), dict) else {}
        ph = float(st.get("ph", 0.0))
        e = float(np.clip(self._rms, 0.0, 1.5))
        centroid = float(np.clip(getattr(self, "_centroid", 0.5), 0.0, 1.0))
        harm = float(getattr(self, "_harmonic_activity", 0.5))
        seed = float(snap.get("seed", 0.0))
        bpm = float(snap.get("bpm", 120.0) or 120.0)
        bpm = max(40.0, min(240.0, bpm))
        n = max(2, int(round(getattr(self, "_render_n", self.n))))
        t = float(self.t)

        # Tempo phase: one revolution per 8 bars at current BPM (locked to audio).
        beat = t * (bpm / 60.0)
        bar8 = beat / 32.0  # 8 bars of 4/4
        # Seed-derived phase offsets (closed-form, no RNG).
        s1 = (seed * MEUM_NORM + MEUM) % math.tau
        s2 = (seed * MEUM_INV + PHI) % math.tau
        s3 = (seed * PHI + MEUM_INV) % math.tau

        goava = bool(snap.get("goava", False))
        phase_lock = bool(snap.get("phase_lock", False) or snap.get("euclid", False))
        seeded = bool(snap.get("seeded", False) or snap.get("randomizer", False))
        goava_w = MEUM_NORM if goava else 0.0
        pl_w = 0.55 if phase_lock else 0.0
        sd_w = 0.35 if seeded else 0.0

        # ---- YAW: primary orbit (tempo) + Meum drift + energy punch ----
        base_yaw = math.radians(32.0)
        yaw = (base_yaw
               + 0.55 * bar8 * math.tau * (0.12 + 0.04 * e)          # slow orbit
               + 0.11 * vg_sin(t * 0.13 * MEUM + s1)                  # Meum band
               + 0.055 * vg_sin(t * 0.041 * MEUM_INV + s2)            # sub-band
               + 0.040 * vg_sin(beat * 0.25 * PHI + ph * math.tau)    # beat accent
               + 0.085 * e * vg_sin(t * 0.09 + centroid * math.tau)   # energy push
               + 0.07 * goava_w * vg_sin(t * MEUM_INV + s3)
               + 0.05 * pl_w * vg_sin(beat * 0.125 + s1)
               + float(getattr(self, "_manual_yaw", 0.0)))

        # ---- PITCH: spectral elevation + gentle nod ----
        base_pitch = math.radians(-14.0)
        pitch = (base_pitch
                 + 0.22 * (centroid - 0.5)                             # bright → look up
                 + 0.070 * vg_sin(t * 0.09 * MEUM + s2)
                 + 0.035 * vg_sin(t * 0.027 + ph * math.tau)
                 + 0.030 * e * vg_sin(beat * 0.5 + s3)
                 + 0.04 * goava_w * vg_sin(t * 0.07 + MEUM)
                 + float(getattr(self, "_manual_pitch", 0.0)))
        pitch = max(math.radians(-42.0), min(math.radians(28.0), pitch))

        # ---- ROLL: micro only ----
        roll = (0.5 * vg_sin(t * 0.5 * MEUM_INV + s1)
                + 0.5 * vg_sin(t * 0.5 + ph * math.tau)
                + 0.5 * goava_w * vg_sin(t * 0.5 + s2)
                + 0.5 * harm * vg_sin(beat * 0.5 + s3))
        roll = max(-0.5, min(0.5, roll))

        # ---- DISTANCE (dolly): closer on loud/dense, pull back on sparse ----
        # 1.0 = neutral; lower = closer (more perspective punch)
        form = float(st.get("form", 0.5))
        rho = float(st.get("rho", 1.0))
        dist = (1.0
                - 0.5 * e
                - 0.5 * form
                + 0.5 * vg_sin(t * 0.5 * MEUM + s1)
                + 0.5 * vg_sin(bar8 * math.tau + s2)
                - 0.5* goava_w * vg_sin(t * 0.5 + s3)
                + 0.5* (1.0 - min(1.0, rho)))
        dist = float(np.clip(dist, 0.5, 1.5))

        # ---- FOV breathe ----
        fov = (48.0
               + 6.0 * harm * vg_sin(t * 0.5 + s1)
               + 4.0 * e * vg_sin(t * 0.5 + s2)
               + 3.0 * goava_w
               - 2.0 * pl_w)
        fov = float(np.clip(fov, 36.0, 62.0))

        # ---- lateral pan (composition engines) ----
        pan_x = (0.5 * pl_w * vg_sin(t * 0.08 + s1)
                 + 0.5 * goava_w * vg_sin(t * 0.5 * MEUM + s2)
                 + 0.5 * sd_w * vg_sin(t * 0.5 + s3))
        pan_y = (0.5 * harm * vg_sin(t * 0.5 + s2)
                 + 0.5 * e * vg_sin(beat * 0.5 + s1))

        self._cam_yaw = float(yaw)
        self._cam_pitch = float(pitch)
        self._cam_roll = float(roll)
        self._cam_distance = float(dist)
        self._cam_fov_deg = float(fov)
        self._cam_pan_x = float(pan_x)
        self._cam_pan_y = float(pan_y)

        # ---- IDENTITY packing (N-independent homes) ----
        # Angle home = identity_unit on the 64-slot master lattice + golden spiral.
        # N only affects density implode, never the angular home of a slot.
        golden = math.tau * (1.0 - 1.0 / PHI)
        self._pack_radius = 0.5 + 0.10 * min(1.0, e + 0.5 * form) + 0.5 * goava_w
        for i, layer in enumerate(self.layers[:n]):
            # Prefer master_slot identity when present on the layer/canonical map
            slot = int(layer.get("master_slot", layer.get("index", i))) % CANONICAL_MASTER_SLOTS
            try:
                idu = float(identity_unit("instrument-visual", seed, "master", slot))
            except Exception:
                idu = (slot + 0.5) / float(CANONICAL_MASTER_SLOTS)
            # Angular home from identity (not from i/n)
            a_home = idu * math.tau + slot * golden * MEUM_INV
            a = a_home + t * (0.5 + 0.5 * e + 0.5 * goava_w) + ph * math.tau * 0.5
            # Radial home from identity rank on a golden spiral (stable under N change)
            q_id = (slot + 0.5) / float(CANONICAL_MASTER_SLOTS)
            rr = self._pack_radius * math.sqrt(0.5 + 0.5 * q_id)
            # Density implode: only place N affects scale of neighbors
            spacing = self._pack_radius * math.sqrt(2.0 * math.pi / n) * (0.5 + 0.5 * q_id)
            base = 0.5+ 0.5 * abs(float(self.wave[i % 256])) + 0.5 * e
            life = max(float(layer.get("life", 0.5)), 0.5)
            crowd = base * (0.5 + 0.5 * life) * max(rho, 0.5)
            crowd_den = 2.5 * crowd
            if not math.isfinite(float(crowd_den)) or crowd_den <= 0.0:
                implode = 1.0
            else:
                implode = float(np.clip(spacing / crowd_den, self._pack_scale_floor, 1.0))
            layer["field_x"] = rr * vg_cos(a) + pan_x * 0.5
            layer["field_y"] = rr * vg_sin(a) * 0.5 + pan_y * 0.5
            layer["implode"] = implode
            layer["field_z"] = 0.5 * vg_sin(a * MEUM + slot * MEUM_INV) * dist
            layer["identity_unit"] = idu
            layer["master_slot"] = slot

    def _camera_transform(self, x, y, z):
        """Apply canonical camera yaw/pitch/roll + dolly distance transform."""
        cyaw, cpitch, croll = self._cam_yaw, self._cam_pitch, self._cam_roll
        if isinstance(getattr(self, "_camera_view_override", None), dict):
            v = self._camera_view_override
            cyaw = math.radians(float(v.get("yaw_deg", 0.0)))
            cpitch = math.radians(float(v.get("pitch_deg", 0.0)))
            croll = math.radians(float(v.get("roll_deg", 0.0)))
            if "distance" in v:
                try:
                    self._cam_distance = float(v.get("distance") or self._cam_distance or 1.0)
                except Exception:
                    pass
        cy, sy = vg_cos(cyaw), vg_sin(cyaw)
        cp, sp = vg_cos(cpitch), vg_sin(cpitch)
        cr, sr = vg_cos(croll), vg_sin(croll)
        x1 = x * cy - z * sy
        z1 = x * sy + z * cy
        y1 = y * cp - z1 * sp
        z2 = y * sp + z1 * cp
        x2 = x1 * cr - y1 * sr
        y2 = x1 * sr + y1 * cr
        # Dolly: distance scales the view depth (1.0 neutral). Closer → larger
        # projected size and stronger perspective separation between layers.
        dist = float(getattr(self, "_cam_distance", 1.0) or 1.0)
        dist = max(0.45, min(1.8, dist))
        z2 = z2 * dist + (dist - 1.0) * 0.35
        x2 = x2 + float(getattr(self, "_cam_pan_x", 0.0))
        y2 = y2 + float(getattr(self, "_cam_pan_y", 0.0))
        return x2, y2, z2

    def _map_xy(self, x, y):
        """Implode a screen point into the fitted bounds and clamp each element."""
        px = self._fit_ox + (x - self._fit_cx) * self._fit_sx
        py = self._fit_oy + (y - self._fit_cy) * self._fit_sy
        # No stochastic pixel jitter: the image field is a pure function of
        # seed + composition state + time. This keeps frame regeneration exact.
        # Per-element safety clamp: stochastic geometry may evolve freely,
        # but no individual projected element is allowed to escape the frame.
        margin = 2.0
        return (
            float(np.clip(px, margin, max(margin, self._fit_ox * 2.0 - margin))),
            float(np.clip(py, margin, max(margin, self._fit_oy * 2.0 - margin))),
        )

    def _commit_fit(self, pts, w, h):
        """Scale every part so the union bbox fills the frame (padded outer bounds)."""
        if not pts:
            return
        xs = [p[0] for p in pts]
        ys = [p[1] for p in pts]
        minx, maxx = min(xs), max(xs)
        miny, maxy = min(ys), max(ys)
        bw = max(maxx - minx, 1.0)
        bh = max(maxy - miny, 1.0)
        # Meum-thin margin so geometry kisses the outer bounds without clipping
        m = max(3.0, min(w, h) * MEUM_NORM * 0.08)
        avail_w = max(w - 2.0 * m, 8.0)
        avail_h = max(h - 2.0 * m, 8.0)
        # Anisotropic implode: fill both axes (fills screen, stays inside bounds)
        self._fit_sx = avail_w / bw
        self._fit_sy = avail_h / bh
        self._fit_cx = 0.5 * (minx + maxx)
        self._fit_cy = 0.5 * (miny + maxy)
        self._fit_ox = w * 0.5
        self._fit_oy = h * 0.5

    def _project(self, x, y, z, w, h, fov=None):
        if fov is None:
            fov = math.tan(math.radians(float(getattr(self, "_cam_fov_deg", 48.0))) * 0.5) * 2.0
        x, y, z = self._camera_transform(float(x), float(y), float(z))
        z = max(z, 0.5)
        inv = 1.0 / z
        sx = (x * inv) * fov
        sy = (y * inv) * fov
        # Base projection uses ~half-frame so implode-to-fit has room to expand
        px = w * DEFAULT_SHIFTS.horizontal_center_video_synth + sx * (w * DEFAULT_SHIFTS.proj_width_factor)
        py = h * DEFAULT_SHIFTS.vertical_center_video_synth - sy * (h * DEFAULT_SHIFTS.proj_height_factor)
        px, py = self._map_xy(px, py)
        return px, py, inv

    def _hsv(self, h, s, v):
        c = QColor.fromHsv(int(h) % 360, int(max(0, min(1, s)) * 255), int(max(0, min(1, v)) * 255))
        return (c.red(), c.green(), c.blue())

    def _line(self, img, x0, y0, x1, y1, col, alpha=1.0):
        hh, ww, _ = img.shape
        steps = max(abs(int(x1) - int(x0)), abs(int(y1) - int(y0)), 1)
        a = float(np.clip(alpha, 0.0, 1.0))
        c = np.array(col, dtype=np.float32)
        for ti in range(int(steps) + 1):
            u = ti / steps
            x = int(x0 + (x1 - x0) * u)
            y = int(y0 + (y1 - y0) * u)
            if 0 <= x < ww and 0 <= y < hh:
                img[y, x] = img[y, x] * (1 - a) + c * a

    def _dot(self, img, x, y, col, alpha=1.0, r=1):
        hh, ww, _ = img.shape
        a = float(np.clip(alpha, 0.0, 1.0))
        c = np.array(col, dtype=np.float32)
        for dy in range(-r, r + 1):
            for dx in range(-r, r + 1):
                xx, yy = int(x) + dx, int(y) + dy
                if 0 <= xx < ww and 0 <= yy < hh:
                    img[yy, xx] = img[yy, xx] * (1 - a) + c * a

    def _fill_tri(self, img, p0, p1, p2, col, alpha):
        """Real rasterized face fill, followed by a crisp mathematical edge."""
        a = float(np.clip(alpha, 0.0, 1.0))
        pts = np.asarray([[p0[0], p0[1]], [p1[0], p1[1]], [p2[0], p2[1]]], dtype=np.float32)
        xmin = max(0, int(np.floor(np.min(pts[:, 0])))); xmax = min(img.shape[1]-1, int(np.ceil(np.max(pts[:, 0]))))
        ymin = max(0, int(np.floor(np.min(pts[:, 1])))); ymax = min(img.shape[0]-1, int(np.ceil(np.max(pts[:, 1]))))
        if xmin <= xmax and ymin <= ymax:
            yy, xx = np.mgrid[ymin:ymax+1, xmin:xmax+1]
            x0,y0=pts[0]; x1,y1=pts[1]; x2,y2=pts[2]
            den=((y1-y2)*(x0-x2)+(x2-x1)*(y0-y2))
            if abs(float(den)) >= 0.0:
                w0=((y1-y2)*(xx-x2)+(x2-x1)*(yy-y2))/den
                w1=((y2-y0)*(xx-x2)+(x0-x2)*(yy-y2))/den
                w2=1.0-w0-w1
                mask=(w0>=0)&(w1>=0)&(w2>=0)
                region=img[ymin:ymax+1,xmin:xmax+1]
                c=np.asarray(col,dtype=np.float32)
                region[mask]=region[mask]*(1-a)+c*a
        for i in range(3):
            self._line(img, pts[i,0], pts[i,1], pts[(i+1)%3,0], pts[(i+1)%3,1], col, min(1.0, a*1.5))

    def _subscene_image_synthesis(self, img, w, h, st):
        """Continuous deterministic image synthesis from the same composition.

        This is the visual counterpart of the audio renderer: instead of a
        small catalog of decorative shapes, the complete RGB field is generated
        from a compact latent vector derived from seed, spectrum, waveform,
        playhead, sequence density and the 64-slot master image lattice.
        Instrument Count only changes which master atoms are emphasized; it
        cannot invent a new visual identity.
        """
        op = float(self._module_fade.get("field", 0.62))
        if op <= 0.0:
            return
        yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
        xn = (xx / max(w - 1, 1) - DEFAULT_SHIFTS.horizontal_center_image_synthesis) * 2.0
        yn = (yy / max(h - 1, 1) - DEFAULT_SHIFTS.vertical_center_image_synthesis) * 2.0
        snap = st.get("snap", {})
        seed = float(snap.get("seed", 0.0))
        ph = float(st.get("ph", 0.0))
        e = float(self._rms)
        centroid = float(self._centroid)
        # Six basis waves: low/mid/high spectral structure plus spatial folds.
        bands = np.asarray(self._band, dtype=np.float32)
        b0,b1,b2 = [float(bands[k]) for k in (0, min(3, len(bands)-1), min(6, len(bands)-1))]
        # The image field is derived from the complete 64-slot master lattice,
        # not the live roster.  Therefore N=2 and N=64 see the same underlying
        # image latent; N only changes how that latent is factorized into voices.
        master = self._canonical_master if hasattr(self, "_canonical_master") else []
        active = master
        if active:
            atoms = [p.get("atom", {}) for p in active]
            atom_phase = float(np.mean([a.get("phase",0.0) for a in atoms]))
            atom_angle = float(np.mean([a.get("angle",0.0) for a in atoms]))
            atom_tex = float(np.mean([a.get("texture",0.5) for a in atoms]))
        else:
            atom_phase = atom_angle = 0.0; atom_tex = 0.5
        t = float(self.t)
        # Radial + angular latent coordinates. Every term is tied to a real
        # composition quantity; there are no purely decorative random fields.
        r = np.sqrt(xn*xn + yn*yn)
        a = np.arctan2(yn, xn)
        f1 = np.sin(a * (3.0 + 5.0*b1) + r * (7.0 + 9.0*b2) + ph + atom_angle)
        f2 = np.cos(r * (11.0 + 8.0*centroid) - t*(0.07 + 0.13*e) + seed*0.0017)
        f3 = np.sin((xn*vg_cos(atom_phase) + yn*vg_sin(atom_phase)) * (8.0 + 12.0*b0) + ph*2.0)
        f4 = np.cos((xn-yn) * (5.0 + 7.0*atom_tex) + t*0.11 + seed*0.0009)
        # Harmonic cross-modulation: multiplicative interaction prevents the
        # image from being a sum of unrelated overlays.
        field = 0.5 + 0.5*f1 + 0.5*f2 + 0.5*f3 + 0.5*f4 + 0.5*f1*f3
        field *= 0.5 + 0.5*np.clip(0.5 + 0.5*np.cos((r + ph)*math.tau), 0.0, 1.0)
        field = np.clip(field, 0.0, 1.0)
        hue = (DEFAULT_SHIFTS.hue_shift_base_image_synthesis + 170.0*centroid + 70.0*b2 + math.degrees(atom_phase)*0.5 + self._video_hue_shift + ph*55.0) % 360.0
        # Vectorized continuous RGB basis.  The three channels are phase-shifted
        # views of the same latent field, so color carries information instead
        # of being an unrelated decorative palette.
        c = field * (0.5 + 0.30*e)
        ang = hue / 60.0 + f1*0.5 + f3*0.5
        rr = np.clip(c * (0.5 + 0.5*np.cos(ang)), 0, 1)
        gg = np.clip(c * (0.5 + 0.5*np.cos(ang - 2)), 0, 1)
        bb = np.clip(c * (0.5 + 0.5*np.cos(ang - 4)), 0, 1)
        field_rgb = np.stack([rr,gg,bb], axis=-1) * 255.0
        alpha = 0.5 * (e + op)
        img[:] = img * (1.0-alpha) + field_rgb.astype(np.float32) * alpha

    def _subscene_field(self, img, w, h, st):
        """Background Meum gradient field; no playhead chrome."""
        e = self._rms
        hue_bg = (DEFAULT_SHIFTS.hue_shift_base_field + self._centroid * 360 + self._video_hue_shift + st["ph"] * 40) % 360
        c0 = np.array(self._hsv(hue_bg, 0.5, 0.5 + 0.5* e), dtype=np.float32)
        c1 = np.array(self._hsv((hue_bg + DEFAULT_SHIFTS.hue_shift_base_field + 55) % 360, 0.5, 0.5 + 0.5 * e), dtype=np.float32)
        for yy in range(h):
            u = (yy / max(h - 1, 1)) ** MEUM_INV
            img[yy, :] = c0 * (1 - u) + c1 * u

    def _subscene_ribbon(self, img, w, h, st):
        """Waveform ribbon — audio bulk as ground reference (not an oscilloscope chrome)."""
        e = self._rms
        for i in range(255):
            x0 = int(i / 255.0 * (w - 1))
            x1 = int((i + 1) / 255.0 * (w - 1))
            y0 = int(h * 0.80 - self.wave[i] * h * 0.5 * st["rho"])
            y1 = int(h * 0.80 - self.wave[i + 1] * h * 0.5 * st["rho"])
            col = self._hsv(DEFAULT_SHIFTS.hue_shift_base_ribbon + self._band[i // 32] * 360, 0.5, 0.5 + 0.5 * e)
            self._line(img, x0, y0, x1, y1, col, alpha=DEFAULT_SHIFTS.alpha_base_ribbon + 0.5 * e)

    def _subscene_volumes(self, img, w, h, st):
        """Partly transparent volume shells from Meum 2^M/M² scale."""
        snap = st["snap"]
        n_shells = 3 + int(2 * snap["struct"]) + (1 if snap["carrier"] else 0)
        for s in range(n_shells):
            rad = st["vol_s"] * (0.5 + 0.5 * s) * (0.5 + 0.5 * self._band[s % 8])
            cx, cy = w * DEFAULT_SHIFTS.horizontal_center_volumes, h * DEFAULT_SHIFTS.vertical_center_volumes
            segs = 16 + int(8 * st["line_d"])
            pts = []
            for k in range(segs):
                a = self.t * MEUM_NORM + k * (math.tau / segs) + s * 0.5
                # Meum ellipse: x·M vs y/M
                px = cx + rad * w * 0.5 * vg_cos(a) * MEUM_INV
                py = cy + rad * h * 0.5 * vg_sin(a) * MEUM
                pts.append(self._map_xy(px, py))
            col = self._hsv(int(DEFAULT_SHIFTS.hue_shift_base_volumes + s * 25 + self._video_hue_shift) % 360, 0.5, 0.5)
            alpha = 0.5 + 0.5 * st["form"]
            for k in range(len(pts)):
                self._line(img, pts[k][0], pts[k][1], pts[(k + 1) % len(pts)][0], pts[(k + 1) % len(pts)][1], col, alpha)

    def _live_instrument_visual_schema(self, i, name, canonical):
        """Resolve the complete live composition record for one instrument."""
        app = getattr(self, "app", None)
        state = dict((getattr(app, "instrument_param_state", {}) or {}).get(name, {}) or {}) if app else {}
        seq = {}
        if app is not None:
            try:
                seq = dict((getattr(app, "instrument_sequencer_memory", {}) or {}).get(name, {}) or {})
            except Exception:
                seq = {}
        steps = list(seq.get("steps") or [])
        amps = list(seq.get("amplitudes") or [])
        pitches = list(seq.get("pitches") or [])
        playlist = getattr(app, "master_playlist_data", None) or [] if app else []
        active_rows = []
        for row in playlist:
            if isinstance(row, dict) and str(row.get("operator", "")).strip() == str(name):
                active_rows.append(row)
        return {
            "seed": float(self._canonical_ctx.get("seed", 0.0)),
            "phase": float(canonical.get("phase0", 0.0)),
            "patch": {
                "morph": float(state.get("morph", 1.0)),
                "harmonic_freq": float(state.get("harmonic_freq", canonical.get("base_freq", 432.0))),
                "chaos": float(state.get("chaos", 0.5)),
                "fold_depth": float(state.get("fold_depth", 4.0)),
                "harmonic_lattice": float(state.get("harmonic_lattice", state.get("fractalizer", 0.5))),
            },
            "sequence": {
                "length": int(seq.get("pattern_length", len(steps) or 8)),
                "steps_on": sum(1 for x in steps if x),
                "amp_mean": float(sum(float(x) for x in amps)/len(amps)) if amps else 0.0,
                "pitch_mean": float(sum(float(x) for x in pitches)/len(pitches)) if pitches else 1.0,
            },
            "playlist_rows": len(active_rows),
            "canonical": canonical,
            "dimension": 1 + int(identity_unit("dimension", self._canonical_ctx.get("seed",0.0), "master", int(canonical.get("master_slot", i))) * 3.0),
        }

    def _subscene_faces_segments(self, img, w, h, st):
        """Canonical visual route: always the fixed slot lattice (not ensemble N).

        Music keeps a canonical master independent of instrument count; video
        must do the same.  Drawing ``len(self._canonical)`` (16 fixed slots)
        means seeded blend/geometry is identical for 2 instruments or 48.
        Labels may come from the host roster but never truncate the lattice.
        """
        names = list(getattr(self.app, "instrument_names_48", []) or []) if self.app is not None else []
        n = max(1, min(CANONICAL_MASTER_SLOTS, int(round(getattr(self, "_render_n", self.n)))))
        if not names:
            names = [f"Instrument {i+1}" for i in range(n)]
        # Pure translator: N changes only the number of samples and their
        # inverse-count contribution. Existing master slots never move.
        for i in range(n):
            name = names[i % len(names)] if names else f"Instrument {i+1}"
            c = self._canonical[i % len(self._canonical)]
            trans = instruments_handler(i, n, seed=self._canonical_ctx.get("seed", 0.0),
                                        sequential_nums=self._canonical_ctx.get("sequential_nums", ()))
            c = dict(c)
            c["master_slot"] = trans["master_slot"]
            c["compensation"] = trans["compensation"]
            schema = self._live_instrument_visual_schema(i, name, c)
            InstrumentVisualObject(self, i, name, c, schema).draw(img, w, h, self.t, 0.5, np.zeros(8, dtype=np.float32))

    def _subscene_particles(self, img, w, h, st):
        """Seed / engine particle field from Meum residual + seed value."""
        snap = st["snap"]
        if abs(snap["seed"]) < 1e-9 and not snap["seeded"] and not snap["euclid"]:
            n_part = 12 + int(16 * self._rms)
        else:
            n_part = 20 + int(28 * self._rms) + (10 if snap["seeded"] else 0)
        seed_i = int(abs(snap["seed"])) & 0xFFFF
        for p in range(n_part):
            ang = self.t * 0.5 + p * 0.5 + seed_i * 0.5 + st["ph"] * math.tau
            rr = 0.5 + 0.5 * abs(float(self.wave[p % 256])) * st["rho"]
            x = rr * vg_cos(ang)
            y = rr * vg_sin(ang * MEUM)
            px, py, _ = self._project(x, y, 1.0 + 0.5 * self._rms, w, h)
            col = self._hsv(int(DEFAULT_SHIFTS.hue_shift_base_particles + seed_i * 0.5 + p * 9) % 360, 0.5, 0.5)
            self._dot(img, px, py, col, 0.5 + 0.5 * self._rms, r=1)

    def _subscene_band_towers(self, img, w, h, st):
        """Spectral band columns — bulk spectrum as vertical volume lines."""
        n_vis = max(2, int(round(getattr(self, "_render_n", self.n))))
        reps = max(1, min(4, int(round(n_vis / 16.0))))
        for b in range(8):
            bx = int((b + 0.5) / 8.0 * w)
            boundary = 1.0 + 0.5 * getattr(self, "_octave_boundary", 0.0)
            bh = int(self._band[b] * h * 0.5 * st["rho"] * boundary)
            col = self._hsv(int(DEFAULT_SHIFTS.hue_shift_base_band_towers + 25 * b) % 360, 0.5, 0.5 + 0.5 * self._band[b])
            self._line(img, bx, h - 3, bx, h - 3 - bh, col, alpha=DEFAULT_SHIFTS.alpha_base_band_towers + 0.5 + 0.5 * self._band[b])
            if reps > 1:
                for q in range(1, reps):
                    yq = h - 3 - int(bh * q / reps)
                    self._line(img, bx - 2, yq, bx + 2, yq, col, alpha=DEFAULT_SHIFTS.alpha_base_band_towers * 0.5 * self._band[b])


    def _colorize_wave_sample(self, algo_idx, i, n, amp, band_val, angle_val):
        """Colorization algorithm bank for wave-derived geometry.

        Every mapping here is a pure function of the sample's own data
        (its index, its amplitude, its band energy, the viewing angle it's
        being drawn at) plus the shared video hue shift — never a lookup
        table and never state carried between samples — so color always
        stays tied to the actual waveform driving the shape, whatever
        conformity (1D/2D/3D) it's feeding.
        """
        hue_shift = self._video_hue_shift
        algo_idx = int(algo_idx) % 4
        if algo_idx == 0:
            # Spectral: band energy drives hue directly.
            hue = (140.0 + band_val * 140.0 + hue_shift) % 360.0
        elif algo_idx == 1:
            # Positional: hue sweeps across the sample index (rainbow ribbon).
            hue = ((i / max(n - 1, 1)) * 360.0 + hue_shift) % 360.0
        elif algo_idx == 2:
            # Amplitude + angle: louder samples and wider viewing angles shift hue.
            hue = (200.0 + 160.0 * amp + math.degrees(angle_val) * 0.5 + hue_shift) % 360.0
        else:
            # Golden-angle scatter: irrational step keeps neighboring samples
            # visually distinct instead of banding.
            hue = (60.0 + 300.0 * ((i * PHI) % 1.0) + hue_shift) % 360.0
        sat = 0.5 + 0.5 * abs(amp)
        val = 0.5 + 0.5 * (0.5 + 0.5 * band_val)
        return self._hsv(hue, sat, val)

    def _distort_wave_point(self, distort_idx, x, y, z, i, n, t, amp):
        """Parametric distortion bank applied to a wave-derived point before
        projection. Each entry is a closed-form function of (position, the
        sample's own amplitude, time) — deterministic and reproducible for
        the same audio + time, with no random draw and no lookup table.
        """
        distort_idx = int(distort_idx) % 4
        u = i / max(n - 1, 1)
        if distort_idx == 0:
            # Radial swirl: bends the point around the origin over time.
            ang = u * math.tau * 2.0 + t * 0.5
            r = math.hypot(x, y)
            x, y = r * vg_cos(ang), r * vg_sin(ang)
        elif distort_idx == 1:
            # Ripple: sinusoidal depth push, scaled by the sample's own amplitude.
            z = z + 0.5 * vg_sin(u * math.tau * 5.0 + t * 1.0) * (0.5 + abs(amp))
        elif distort_idx == 2:
            # Meum fractal fold: independent Meum/Meum-inverse breathing per axis.
            x = x * (1.0 + 0.5 * vg_sin(u * MEUM * math.tau + t))
            y = y * (1.0 + 0.5 * vg_cos(u * MEUM_INV * math.tau + t))
        else:
            # Spiral pinch: whole shape breathes in/out around the frame center.
            pinch = 0.85 + 0.5 * vg_sin(t * 1.0 + u * math.tau)
            x, y = x * pinch, y * pinch
        return x, y, z

    def _subscene_wave_integration(self, img, w, h, st):
        """Integrates the waveform + spectrum data into the main scenograph
        render itself, instead of leaving it to the separate oscilloscope /
        spectrum-analyzer UI monitors.

        Draws the same underlying wave/band data through the parametric
        distortion + colorization banks above, at several rotation angles,
        across three geometric conformities so it reads consistently no
        matter how it's being viewed:
          - 1D: a radial point sweep (one value per sample, no connecting
            geometry — the "purest" reduction of the waveform).
          - 2D: a planar ribbon (amplitude-vs-time), rotated to each angle
            and camera-projected like every other scenograph element
            instead of sitting as a flat overlay.
          - 3D: a meshed, textured surface — two concentric rings (a dry
            inner ring and an outer ring extruded by each sample's own
            amplitude/band energy) stitched into a triangle-strip mesh,
            with the same colorization bank acting as its texture.
        """
        op = self._module_fade.get("wave_integration", 0.0) if "wave_integration" in getattr(self, "SCENOGRAPH_ITEM_CATALOG", []) else 0.0
        if op <= 0.0:
            return
        wave = self.wave
        n = len(wave)
        if n < 8:
            return
        band = self._band
        t = self.t
        # Deterministic cycling through the distortion/colorization banks —
        # a function of elapsed time only, so it's reproducible run to run
        # for the same playback, never a per-frame random choice.
        distort_idx = int(t * 0.5) % 4
        colorize_idx = int(t * 0.5 + 1.0) % 4
        angles = (0.0, math.tau / 3.0, 2.0 * math.tau / 3.0)
        base_r = min(w, h) * DEFAULT_SHIFTS.vertical_center_wave_integration

        # --- 1D conformity: radial point sweep --------------------------
        for ang_i, base_ang in enumerate(angles):
            for i in range(0, n, 4):
                amp = float(wave[i])
                b = float(band[i % 8])
                u = i / max(n - 1, 1)
                r = base_r * (0.5 + 0.5 * abs(amp))
                ang = base_ang + u * 0.6 + t * 0.05
                x, y, z = r * vg_cos(ang), r * vg_sin(ang) * 0.5, 0.0
                x, y, z = self._distort_wave_point(distort_idx, x, y, z, i, n, t, amp)
                px, py, _ = self._project(x, y, 1.1 + 0.5 * ang_i, w, h)
                col = self._colorize_wave_sample(colorize_idx, i, n, amp, b, base_ang)
                self._dot(img, px, py, col, op * (0.50 + 0.5 * abs(amp)), r=1)

        # --- 2D conformity: planar ribbon at each angle ------------------
        for ang_i, base_ang in enumerate(angles):
            prev = None
            for i in range(0, n, 2):
                amp = float(wave[i])
                b = float(band[i % 8])
                u = i / max(n - 1, 1)
                lx = (u - 0.5) * base_r * 2.5
                ly = amp * base_r * 1.0
                rx = lx * vg_cos(base_ang)
                rz = lx * vg_sin(base_ang)
                x, y, z = self._distort_wave_point(distort_idx, rx, ly, rz, i, n, t, amp)
                px, py, _ = self._project(x, y, 1.5 + 0.5 * ang_i, w, h)
                col = self._colorize_wave_sample(colorize_idx, i, n, amp, b, base_ang)
                if prev is not None:
                    self._line(img, prev[0], prev[1], px, py, col, op * (0.5 + 0.30 * abs(amp)))
                prev = (px, py)

        # --- 3D conformity: meshed + textured extruded surface -----------
        ring_n = 32
        for ang_i, base_ang in enumerate(angles[:2]):  # 2 shells keeps per-frame cost bounded
            inner, outer = [], []
            for k in range(ring_n):
                u = k / ring_n
                i = int(u * (n - 1))
                amp = float(wave[i])
                b = float(band[i % 8])
                ang = base_ang + u * math.tau
                r_in = base_r * (0.5 + 0.50 * ang_i)
                r_out = r_in * (1.0 + 0.5 * abs(amp) + 0.5 * b)
                xi, yi, zi = r_in * vg_cos(ang), r_in * vg_sin(ang) * 0.5, 0.0
                xo, yo, zo = r_out * vg_cos(ang), r_out * vg_sin(ang) * 0.5, 0.5 * amp
                xi, yi, zi = self._distort_wave_point(distort_idx, xi, yi, zi, i, n, t, amp)
                xo, yo, zo = self._distort_wave_point(distort_idx, xo, yo, zo, i, n, t, amp)
                inner.append(self._project(xi, yi, 1.5 + 0.5 * ang_i, w, h))
                outer.append(self._project(xo, yo, 1.5 + 0.5 * ang_i, w, h))
            for k in range(ring_n):
                k2 = (k + 1) % ring_n
                u = k / ring_n
                i = int(u * (n - 1))
                amp = float(wave[i])
                b = float(band[i % 8])
                col = self._colorize_wave_sample(colorize_idx, i, n, amp, b, base_ang)
                alpha = op * (0.5 + 0.5 * (0.5 + 0.5 * abs(amp)))
                self._fill_tri(img, inner[k], outer[k], outer[k2], col, alpha)
                self._fill_tri(img, inner[k], outer[k2], inner[k2], col, alpha * 0.5)

    def _update_scenograph_module_schedule(self, st):
        """Compute relevance and smooth fade for every visual module.

        Presence is deterministic from audio energy, centroid, playhead,
        composition density, and GOAVA state.  Fades are shared so removal and
        re-addition never pop between modules.
        """
        snap = st["snap"]
        e = float(self._rms)
        c = float(self._centroid)
        ph = float(st["ph"])
        relevance = {
            "field": 0.5 + 0.5 * e,
            "ribbon": 0.0,  # disabled: waveform/scope chrome not drawn in scenograph
            "volumes": 0.30 + 0.70 * (0.5 + 0.5 * abs(vg_sin(ph * math.tau * MEUM))),
            "faces": 0.5 + 0.5 * max(e, float(snap.get("struct", 0.5))),
            "particles": 0.5 + 0.5 * (0.5 * e + 0.5 * abs(c - 0.5) * 2.0),
            "bands": 0.0,  # disabled: spectrum bars not drawn in scenograph
            "goava": 0.5 if snap.get("goava") else 0.0,
            "filaments":0.5 + 0.5 * abs(vg_sin((ph + c) * math.tau * MEUM_INV)),
            "roses": 0.5 + 0.5 * abs(vg_cos((ph * 0.5 + e) * math.tau)),
            "orbitals": 0.5 + 0.5* max(e, 1.0 - c),
            "constellations": 0.5 + 0.5 * (1.0 - e) * (0.5 + 0.5 * float(snap.get("struct", 0.5))),
            "lattice": 0.5 + 0.5 * (1.0 - min(1.0, e * 1.5)) * (0.5 + 0.5 * float(snap.get("fractal", 0.5))),
            "bursts": min(1.0, e * 2.5) ** 1.5,
            "spectral_comets": min(1.0, max(0.0, c) * 1.5) * min(1.0, e * 2.0),
            "rhythm_mandala": max(0.0, float(snap.get("struct", 0.5)) * (1.0 - abs(c - 0.5) * 1.5)) * (0.5 + 0.5 * float(snap.get("eqr", 0.5))),
            "pulse_grid": max(0.0, (1.0 - abs(float(snap.get("bpm", 120.0)) - 120.0) / 120.0)) * (0.5 + 0.65 * float(snap.get("struct", 0.5))),
            "goava_field": 0.92 if snap.get("goava") else 0.0,
            # Engine-tied ornaments — same flags that change the audible mix.
            "meum_spiral": 0.50 + 0.5 * float(np.clip(getattr(self, "_harmonic_activity", 0.5), 0.5, 1.0)),
            "phi_web": 0.5 + 0.50 * float(snap.get("struct", 0.0)),
            "harmonic_rings": 0.5 + 0.50 * e * (0.5 + 0.5 * c),
            "seed_sparks": 0.5 if (snap.get("seeded") or snap.get("randomizer")) else 0.0,
            "euclidean_spokes": 0.5 if snap.get("euclid") else 0.0,
            "phase_ribbons": 0.5 if snap.get("phase_lock") else 0.0,
            "lock_rings": 0.5 if snap.get("phase_lock") else 0.0,
            "seeded_constellation": 0.5 if snap.get("seeded") else 0.0,
            "goava_glyphs": 0.5 if snap.get("goava") else 0.0,
            "carrier_wake": 0.5 if float(snap.get("carrier", 0.0) or 0.0) > 0.0 else 0.0,
            "voice_orbs": 0.5 + 0.50 * e,
            "ensemble_cloud": 0.5 + 0.5 * float(snap.get("struct", 0.0)),
            "wave_integration": 0.5 + 0.50 * e,
            "sub_bass_bloom": 0.5 + 0.5 * float(self._band[0] if len(self._band) else e),
            "air_glitter": 0.5 + 0.5 * float(self._band[min(7, len(self._band)-1)] if len(self._band) else c),
            "chord_fans": 0.5 + 0.5 * float(np.clip(getattr(self, "_harmonic_activity", 0.5), 0.5, 1.0)),
            "depth_fog": 0.5 + 0.5 * (1.0 - e),
        }
        for name, target in relevance.items():
            # Exciting regions can suppress a module briefly; this is a
            # deterministic compositional scheduling decision, not randomness.
            # Chaotic moments attenuate delicate/minor modules; loud transients favor instantaneous ones.
            chaos = float(np.clip(abs(self._peak - e) * 2.4 + abs(c - 0.5) * 0.7, 0.0, 1.0))
            stable = float(np.clip(snap["struct"] * (1.0 - chaos) + snap["eqr"] * 0.25, 0.0, 1.0))
            if name in {"constellations", "lattice", "filaments", "roses"}:
                gate = 0.25 + 0.75 * (1.0 - chaos)
            elif name in {"bursts", "spectral_comets"}:
                gate = 0.25 + 0.75 * min(1.0, e * 2.2)
            elif name in {"rhythm_mandala", "pulse_grid", "faces"}:
                gate = 0.20 + 0.80 * stable
            else:
                gate = 1.0 if ((ph * 17.0 + c * 11.0 + e * 7.0 + len(name)) % 9.0) > 1.1 else 0.18
            if name in {"goava", "goava_field"}:
                gate = 1.0
            self._module_target[name] = float(np.clip(target * gate, 0.0, 1.0))
            old = float(self._module_fade.get(name, 0.0))
            # Smarter ease: faster attack, slower release (asymmetric fade)
            delta = self._module_target[name] - old
            rate = 0.28 if delta > 0 else 0.12
            self._module_fade[name] = old + delta * rate
            self._scenograph_modules[name] = {
                "target": self._module_target[name],
                "fade": self._module_fade[name],
                "active": self._module_fade[name] > 0.035,
                "playhead": ph,
            }

    def get_scenograph_module_state(self):
        return copy.deepcopy(self._scenograph_modules)

    def _build_canonical_ctx_and_layers(self, st=None):
        """CANONICAL_VISUAL_2026 — the visual analog of the audio instrument pass.

        Builds the SAME union context the audio renderer uses (shared seed, base
        pre-scaled by MEUM_POWERS_36[0], union ratio, union s_int, 4-engine
        full-unison collapse) and one canonical 2.5D layer per instrument slot.
        Stochastic noise is minimized: geometry is a pure function of the union
        context + slot + engine flags; the only optional stochastic element is
        GOAVA's own irrational stream, dependent on GOAVA being active.
        """
        snap = st.get("snap", {}) if isinstance(st, dict) else self._live_snap()
        flags = {k: bool(snap.get(k, False)) for k in _VISUAL_ENGINE_CHANNELS}
        seed = float(snap.get("seed", 0.0) or 0.0)
        base = 432.0
        sb = getattr(getattr(self, "app", None), "spin_base_frequency", None)
        if sb is not None:
            try:
                base = float(sb.value())
            except Exception:
                pass
        fu = False
        if self.app is not None and hasattr(self.app, "_full_four_engine_unison_active"):
            try:
                fu = bool(self.app._full_four_engine_unison_active())
            except Exception:
                fu = False
        # UNION_IDENTITY_2026: under full unison the visual pass registers the
        # SAME authoritative identity (seed, s_int, base, ratio, entropy point)
        # the audio renderer stashed — symmetry by construction on both media.
        ui = None
        if fu and self.app is not None and hasattr(self.app, "_union_identity"):
            try:
                ui = self.app._union_identity
            except Exception:
                ui = None
        if ui:
            seed = float(ui["seed"])
            s_int = int(ui["s_int"])
            base = float(ui["base"])   # already union pre-scaled (MEUM fold)
            ratio = float(ui["ratio"])
        else:
            base *= float(MEUM_POWERS_36[0])
            ratio = float(_seed_to_pitch_ratio(seed, 0, 0))
            s_int = int(_safe_int_seed(seed) or 1)
        # Sequential numeric inputs are canonical data, not live audio.  Keep
        # them attached to the context so the visual translator sees the exact
        # same numeric sequence that defined the composition.
        seq = snap.get("sequential_nums", snap.get("seed_numbers", ())) or ()
        if not seq and self.app is not None:
            seq = getattr(self.app, "goava_seed_numbers", ()) or ()
        ctx = {"seed": seed, "base": base, "ratio": ratio, "s_int": s_int,
               "full_unison": fu, "n_inst": CANONICAL_MASTER_SLOTS,
               "meum_depth": 1.0, "sequential_nums": list(seq)}
        self._canonical_ctx = ctx
        self._canonical_flags = flags
        # Build the complete seed identity once.  Live Instrument Count later
        # selects a deterministic subset/repartition of these slots.
        self._canonical_master = [canonical_visual_instrument(i, ctx, flags)
                                  for i in range(CANONICAL_MASTER_SLOTS)]
        # Fixed visual render slot count — instrument count must NOT change
        # video identity.  Engine flags (randomizer / phase_lock / goava) do.
        _VISUAL_RENDER_SLOTS = 16
        self._canonical = [self._canonical_master[canonical_master_slot(i, _VISUAL_RENDER_SLOTS)]
                           for i in range(_VISUAL_RENDER_SLOTS)]
        self._vled_full_window = fu
        if self._canonical:
            if fu:
                self._visual_entropy = float(self._canonical[0]["entropy"])
            else:
                self._visual_entropy = float(
                    self._canonical[int(getattr(self, "_render_frame_index", 0)) % len(self._canonical)]["entropy"])
        self._ledger_visual_entropy()

    def _ledger_visual_entropy(self):
        """Visual dual of the audio union-entropy ledger — per-slot draws, same
        draw family (entropy_draw_0_1), same 0.5 fixed point, same rules."""
        for p in self._canonical:
            e = float(p["entropy"])
            self._vled_n += 1
            self._vled_sum += e
            self._vled_sumsq += e * e
            self._vled_rmin = min(self._vled_rmin, e)
            self._vled_rmax = max(self._vled_rmax, e)
        if self._vled_n >= 64:
            self._finalize_visual_ledger()

    def _finalize_visual_ledger(self):
        n = max(1, self._vled_n)
        mean = float(self._vled_sum / n)
        var = max(0.0, float(self._vled_sumsq / n) - mean * mean)
        std = math.sqrt(var)
        r_span = float(self._vled_rmax - self._vled_rmin)
        spread = (r_span >= ENTROPY_REALIZED_SPREAD_MIN
                  and self._vled_rmax >= ENTROPY_REALIZED_TOP
                  and self._vled_rmin <= ENTROPY_REALIZED_BOTTOM)
        balanced = abs(mean - ENTROPY_FIXED_POINT) <= ENTROPY_FIXED_POINT_TOL
        # Full union = one genuine point per seed (some entropic, some not);
        # the 0.5 centre is a property of the draw family across the input
        # space (proved by the cross-seed battery), so the live check only
        # demands genuine spread when the roster lattice is actually visible.
        if self._vled_full_window:
            ok = True
        else:
            ok = bool(spread and balanced)
        self._vled_mean = mean
        self._vled_std = std
        self._vled_ok = ok
        self._vled_n = 0.0
        self._vled_sum = 0.0
        self._vled_sumsq = 0.0
        self._vled_rmin = 1.0
        self._vled_rmax = 0.0

    def _draw_canonical_constellation(self, img, w, h, st):
        """The instrument -> total-frame pass (visual dual of the audio per-voice
        mix): every instrument slot renders its canonical 2.5D layer.  Under the
        4-engine union every slot resolves to the SAME parameter set, so the
        constellation condenses into one union body — no registered subcomponent
        can be told apart from the frame (total unrecognizability, mirroring the
        audio identity cancellation).

        GOAVA is NOT hard-gated out of the union: when GOAVA is active its field
        (there is no hard gate) is woven into the canonicality with a weight that
        depends purely on GOAVA being active, and its fibres trace GOAVA's actual
        irrational waveform (see the stream sampling below) — resemblance in the
        waveform, exactly as in audio, where GOAVA contributes only its own voice
        while active.
        """
        if not self._canonical:
            return
        fu = bool(self._canonical_ctx.get("full_unison"))
        scale_px = float(min(w, h))
        try:
            for p in self._canonical:
                base_p = self._project(float(p["x"]), float(p["y"]),
                                       float(p["z"]) + (0.0 if fu else 0.0), w, h)
                sx, sy = float(base_p[0]), float(base_p[1])
                r0 = scale_px * 0.010 * float(p["pack"]) * (1.1 + 0.9 * float(p["life"]))
                v = 3 + (int(p["verts"]) % 9)
                hu = float(p["hue"]) + float(getattr(self, "_video_hue_shift", 0.0))
                shaded = float(p.get("shade", 0.5))
                col = self._hsv(hu % 360.0, 0.5 + 0.3 * float(p["life"]), shaded)
                al = float(p["life"])
                a0 = float(p["yaw"])
                poly = []
                for k in range(v):
                    a = a0 + k * math.tau / float(v)
                    poly.append(self._map_xy(sx + vg_cos(a) * r0, sy + vg_sin(a * MEUM_INV) * r0 * 0.72))
                for k in range(len(poly)):
                    x1, y1 = poly[k]; x2, y2 = poly[(k + 1) % len(poly)]
                    self._line(img, x1, y1, x2, y2, col, min(0.5, 0.10 + 0.34 * al))
                self._dot(img, sx, sy, col, 0.20 + 0.34 * al, r=1 + (int(p["max_partial"]) % 3))
                if al > 0.34 and v >= 5:
                    for k in range(1, v - 1):
                        self._fill_tri(img, poly[0], poly[k], poly[k + 1], col, 0.10 * al)
                # Transluent halo following the same shade envelope (2.5D depth
                # cue: foreground voices bright, receding voices washed).
                if al > 0.5:
                    hr = r0 * (1.6 + 0.8 * (1.0 - float(p["depth"]) / 1.7))
                    self._dot(img, sx, sy, col, 0.06 * al, r=1 + int(hr / (scale_px * 0.01)))
            # GOAVA field inside the union canonicality.  Presence depends ONLY
            # on GOAVA being active (mirror of the toggle); weight scales with
            # the equal-influence channel so it never dominates the union.
            goa_cole = getattr(self.app, "goava_active", False)
            if goa_cole and self.app is not None:
                flags = self._canonical_flags
                eng5 = sum(1 for _k in _VISUAL_ENGINE_CHANNELS if flags.get(_k))
                chg = (0.5 / max(1, eng5)) if flags.get("goava") else 0.0
                if chg > 0.01:
                    numbers = getattr(self.app, "goava_seed_numbers", None) or []
                    events = getattr(self.app, "goava_note_events", []) or []
                    for j, ev in enumerate(events[:8]):
                        hz = float(ev.get("frequency", 432.0) or 432.0)
                        key = _full_hue(
                            _range_unit(math.log2(max(hz, 1e-12)),
                                         math.log2(20.0), math.log2(20000.0)) / 360.0,
                            float(ev.get("raw", j) or j) * 0.01,
                        )
                        try:
                            txx = np.linspace(0.0, 0.30 + 0.55 * (hz / 260.0), 14)
                            stream = goava_irrational_stream(txx, numbers, base_frequency=hz, channel=j % len(numbers))
                        except Exception:
                            stream = np.sin(np.linspace(0.0, math.tau * 2.0, 14))
                        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_math_roses, h * DEFAULT_SHIFTS.vertical_center_math_roses
                        rad = float(min(w, h)) * (0.16 + 0.30 * float(self._visual_entropy)) * chg
                        pts = []
                        for k in range(14):
                            a = float(np.pi * 2.0 * k / 14.0) + float(key) * 0.017 + self.t * 0.05
                            sw = float(stream[k])
                            rr = rad * (0.45 + 0.85 * (0.5 * sw + 0.5))
                            pts.append(self._map_xy(cx + vg_cos(a) * rr, cy + vg_sin(a * MEUM_INV) * rr * 0.7))
                        gcol = self._hsv((140 + j * 24 + hz * 0.02 + self._video_hue_shift) % 360, 0.5 + 0.3 * float(self._visual_entropy), 0.55 + 0.35 * chg)
                        for k in range(len(pts)):
                            x1, y1 = pts[k]; x2, y2 = pts[(k + 1) % len(pts)]
                            self._line(img, x1, y1, x2, y2, gcol, 0.10 + 0.24 * chg)
        except Exception:
            pass

    def _current_goava_events(self, cache=False):
        """Return GOAVA events for the current evaluated numeric seed state.

        ``cache=False`` intentionally re-evaluates the seed at render time so
        time-varying numeric inputs are never replaced by a stale event cache.
        """
        if self.app is None:
            return []
        try:
            if not cache and hasattr(self.app, "_build_goava_composition"):
                t_value = float(getattr(self, "t", 0.0))
                # Force the same evaluated numeric seed path used by GOAVA.
                self.app._parse_goava_seed_values(t_value=t_value)
                events = self.app._build_goava_composition(t_value=t_value)
                return list(events or [])
            return list(getattr(self.app, "goava_note_events", []) or [])
        except Exception:
            return list(getattr(self.app, "goava_note_events", []) or [])

    def _subscene_goava(self, img, w, h, st):
        """GOAVA-native shape engine: Java-derived values + live Meum calculus keys.

        Each GOAVA number is retained as the numerical driver.  The live Meum state
        supplies audio-derived u/rho/form/line-density keys, so the same seed can
        produce different geometry as the music changes without changing GOAVA's
        underlying note calculation.
        """
        if not st["snap"].get("goava"):
            return
        fade = self._module_fade.get("goava", 0.0) * self._module_fade.get("goava_field", 0.0) ** 0.5
        events = self._current_goava_events(cache=False)
        if not events or fade <= 0.02:
            return
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_goava, h * DEFAULT_SHIFTS.vertical_center_goava
        n = len(events)
        # GOAVA count = seed count (one visual node per seed numeric entry).
        # Never instrument-count, never a fixed 16-slot budget.
        seed_count = 0
        try:
            seed_count = len(getattr(self.app, "goava_seed_numbers", None) or [])
        except Exception:
            seed_count = 0
        if seed_count <= 0 and self.app is not None and hasattr(self.app, "get_seed_values"):
            try:
                seed_count = len(list(self.app.get_seed_values(
                    t_value=float(getattr(self, "t", 0.0)) % 8.0) or []) or [])
            except Exception:
                seed_count = 0
        if seed_count <= 0:
            seed_count = n  # events already 1:1 with seeds when GOAVA built them
        goava_count = min(n, max(1, int(seed_count)))
        # GOAVA is intentionally a minor unison operator: it follows the
        # ensemble rather than dominating it.
        minor = 0.28
        # Meum calculus analysis becomes the visual control vector.
        u = float(st.get("u", 0.0))
        rho = float(st.get("rho", 1.0))
        form = float(st.get("form", 0.5))
        line_d = float(st.get("line_d", 0.5))
        # Numeric identity lanes use their actual observed ranges.  The old
        # raw/seed/modulo constants compressed arbitrary inputs into small
        # repeating intervals, so very different GOAVA values could look alike.
        active_events = list(events[:goava_count])
        raw_values = [float(ev.get("raw", 0.0) or 0.0) for ev in active_events]
        seed_values = [float(ev.get("seed", 0.0) or 0.0) for ev in active_events]
        raw_units = _sequence_units(raw_values)
        seed_units = _sequence_units(seed_values)
        freq_lo, freq_hi = 20.0, 20000.0
        for j, ev in enumerate(active_events):
            hz = float(ev.get("frequency", 432.0) or 432.0)
            raw = float(ev.get("raw", 0.0) or 0.0)
            seed = float(ev.get("seed", 0.0) or 0.0)
            raw_u = raw_units[j] if j < len(raw_units) else 0.5
            seed_u = seed_units[j] if j < len(seed_units) else 0.5
            freq_u = _range_unit(math.log2(max(hz, 1e-12)), math.log2(freq_lo), math.log2(freq_hi))
            # Direct normalized identity: raw, seed and frequency each occupy
            # the complete numeric visual range before composition is applied.
            key = (raw_u + seed_u + freq_u) / 3.0
            uidx = j / max(n - 1, 1)
            ang = self.t * (0.12 + 0.0008 * hz) + uidx * math.tau + key * math.tau
            depth = 0.72 + 0.28 * vg_sin(key * math.tau + self.t * MEUM)
            radius = (0.10 + 0.34 * key) * rho * depth
            hue = _full_hue(key, self._video_hue_shift)
            col = self._hsv(hue, 0.72 + 0.18 * form, 0.82 + 0.18 * float(self._rms + form))

            # 1D: a GOAVA numerical filament whose length responds to calculus line density.
            x1 = cx + vg_cos(ang) * radius * w * (0.25 + 0.30 * line_d)
            y1 = cy + vg_sin(ang) * radius * h * (0.20 + 0.25 * line_d)
            x2 = cx + vg_cos(ang + 0.10 + form * 0.12) * radius * w * (0.42 + 0.35 * line_d)
            y2 = cy + vg_sin(ang + 0.10 + form * 0.12) * radius * h * (0.28 + 0.28 * line_d)
            x1, y1 = self._map_xy(x1, y1); x2, y2 = self._map_xy(x2, y2)
            self._line(img, x1, y1, x2, y2, col, minor * 0.72 * fade)

            # 2D: polar/rose geometry keyed directly to GOAVA's numerical scalar.
            pts = []
            # Petal count keyed off each note's own identity (raw+seed+context,
            # folded into `key`) rather than its position in the event list —
            # `j % 5` gave every 5th-in-frame note the same petal count
            # regardless of pitch/seed, which is the same collision pattern the
            # DJ-pair orbit had. A hash-like fractional fold of `key` spreads
            # petal counts by what the note actually is, not where it sits.
            petals = 4 + int(abs(vg_sin(key * 12.9898)) * 100 % 5)
            # GOAVA_IRRATIONAL_2026 — waveform resemblance: the 2D/3D shapes
            # trace GOAVA's OWN irrational stream (sampled from the cached seed
            # numbers at this event's base frequency), so the glyph visibly
            # echoes the GOAVA voice's waveform rather than an abstract fold.
            _gstream = None
            _gn = getattr(self.app, "goava_seed_numbers", None) or []
            if _gn:
                try:
                    _txx = np.linspace(0.0, 0.30 + 0.55 * (hz / 260.0), 24)
                    _gstream = goava_irrational_stream(_txx, _gn, base_frequency=hz, channel=j % len(_gn))
                except Exception:
                    _gstream = None
            for k in range(24):
                a = ang + k * math.tau / 24.0
                if _gstream is not None:
                    sw = float(_gstream[k])
                    rr = radius * (0.45 + 0.85 * (0.5 * sw + 0.5))
                else:
                    rr = radius * (0.50 + 0.34 * vg_sin(petals * a + key * 0.021 + u))
                pts.append(self._map_xy(cx + vg_cos(a) * rr * w * 0.33,
                            cy + vg_sin(a * MEUM_INV) * rr * h * 0.25))
            # Filled 2D GOAVA petal sectors: visible surfaces, not merely outlines.
            face_col = self._hsv((hue + 18) % 360, 0.58 + 0.25 * form, 0.72 + 0.20 * form)
            for k in range(1, len(pts) - 1):
                self._fill_tri(img, pts[0], pts[k], pts[k + 1], face_col, minor * 0.12 * (0.48 + 0.34 * form) * fade)
            for k in range(len(pts)):
                self._line(img, pts[k][0], pts[k][1], pts[(k + 1) % len(pts)][0], pts[(k + 1) % len(pts)][1],
                           col, minor * (0.28 + 0.22 * form) * fade)

            # 3D: depth ring projected with Meum-controlled z and a seed-derived tilt.
            ring = []
            tilt = 0.15 + 0.45 * vg_sin(key * 0.007 + u)
            for k in range(18):
                a = ang + k * math.tau / 18.0
                if _gstream is not None:
                    swk = float(_gstream[k % len(_gstream)])
                    rr = radius * (0.62 + 0.30 * swk)
                else:
                    rr = radius * (0.62 + 0.12 * vg_sin(a * 3.0 + key))
                xx = rr * vg_cos(a)
                yy = rr * vg_sin(a) * 0.68
                zz = 1.0 + 0.34 * vg_sin(a * 2.0 + key * 0.011) * (0.6 + 0.4 * form)
                xr = xx * vg_cos(tilt) - zz * vg_sin(tilt)
                zr = xx * vg_sin(tilt) + zz * vg_cos(tilt)
                px, py, _ = self._project(xr, yy, zr, w, h)
                ring.append(self._map_xy(px, py))
            # 3D depth object: triangulated surface fan plus silhouette.
            center = ((sum(p[0] for p in ring)/len(ring), sum(p[1] for p in ring)/len(ring)) if ring else (0.0, 0.0))
            face_col3 = self._hsv((hue + 42) % 360, 0.62, 0.76)
            for k in range(len(ring)):
                self._fill_tri(img, center, ring[k], ring[(k + 1) % len(ring)], face_col3, minor * 0.10 * fade)
                self._line(img, ring[k][0], ring[k][1], ring[(k + 1) % len(ring)][0], ring[(k + 1) % len(ring)][1],
                           col, minor * 0.24 * fade)
            self._dot(img, x2, y2, col, minor * 0.60 * fade, r=1 + int(2 * depth))

    def _subscene_math_filaments(self, img, w, h, st):
        fade = self._module_fade.get("filaments", 0.0)
        if fade <= 0.02:
            return
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_math_filaments, h * DEFAULT_SHIFTS.vertical_center_math_filaments
        pts = []
        for k in range(96):
            u = k / 95.0
            a = self.t * MEUM_INV + u * math.tau * (1.0 + MEUM_NORM)
            r = (0.05 + 0.42 * u) * (0.65 + 0.35 * self._rms)
            pts.append((cx + vg_cos(a) * r * w * 0.46,
                        cy + vg_sin(a * MEUM) * r * h * 0.34))
        for k in range(len(pts) - 1):
            col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_math_filaments + k * 2 + self._video_hue_shift) % 360, 0.55, 0.72)
            self._line(img, *pts[k], *pts[k + 1], col, alpha=0.42 * fade)

    def _subscene_math_roses(self, img, w, h, st):
        fade = self._module_fade.get("roses", 0.0)
        if fade <= 0.02:
            return
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_math_roses, h * DEFAULT_SHIFTS.vertical_center_math_roses
        arms = int(np.clip(round(3 + 8.0 * getattr(self, "_harmonic_activity", 0.5)), 3, 11))
        for arm in range(arms):
            pts = []
            for k in range(72):
                u = k / 71.0
                a = u * math.tau * 3.0 + self.t * 0.3 + arm * math.pi / 2.0
                r = (0.06 + 0.58 * u) * (0.58 + 0.42 * self._centroid)
                pts.append((cx + vg_cos(a) * r * w * 0.47,
                            cy + vg_sin(a * MEUM_INV) * r * h * 0.40))
            col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_math_roses + arm * 70 + self._centroid * 360) % 360, 0.68, 0.82)
            for k in range(len(pts) - 1):
                self._line(img, *pts[k], *pts[k + 1], col, alpha=0.09 * fade)

    def _subscene_orbitals(self, img, w, h, st):
        fade = self._module_fade.get("orbitals", 0.0)
        if fade <= 0.02:
            return
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_orbitals, h * DEFAULT_SHIFTS.vertical_center_orbitals
        ring_count = int(np.clip(round(2 + 4.0 * getattr(self, "_octave_boundary", 0.0)), 2, 6))
        for ring in range(ring_count):
            pts = []
            rad = (0.18 + ring * 0.10) * st["rho"]
            ring_points = int(np.clip(round(28 + 44.0 * getattr(self, "_harmonic_activity", 0.5)), 28, 72))
            for k in range(ring_points):
                a = k * math.tau / ring_points + self.t * (0.12 + ring * 0.05)
                z = 1.0 + 0.15 * vg_sin(a * 3.0 + self.t * MEUM)
                pts.append((cx + vg_cos(a) * rad * w * 0.35 * z,
                            cy + vg_sin(a) * rad * h * 0.18))
            col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_orbitals + ring * 40 + self._video_hue_shift) % 360, 0.62, 0.78)
            for k in range(len(pts) - 1):
                self._line(img, *pts[k], *pts[k + 1], col, alpha=0.15 * fade)

    def _subscene_constellations(self, img, w, h, st):
        fade = self._module_fade.get("constellations", 0.0)
        if fade <= 0.02: return
        seed = abs(float(st["snap"].get("seed", 0.0)))
        pts = []
        for i in range(34):
            a = i * MEUM_INV + self.t * 0.035 + seed * 0.0007
            r = 0.12 + 0.34 * ((i * MEUM_NORM) % 1.0)
            x, y, _ = self._project(r * vg_cos(a), r * vg_sin(a * MEUM), 1.0 + 0.18 * vg_sin(a * 2), w, h)
            pts.append((x, y))
        col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_constellations + self._video_hue_shift) % 360, 0.35, 0.95)
        for i, p in enumerate(pts):
            self._dot(img, p[0], p[1], col, 0.65 * fade, r=1)
            if i and i % 2 == 0:
                self._line(img, p[0], p[1], pts[i-1][0], pts[i-1][1], col, 0.22 * fade)

    def _subscene_lattice(self, img, w, h, st):
        fade = self._module_fade.get("lattice", 0.0)
        if fade <= 0.02: return
        step = max(24, int(34 - 10 * self._centroid))
        col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_lattice + self._video_hue_shift) % 360, 0.55, 0.48)
        for x in range(-h, w + h, step):
            self._line(img, x, 0, x + h, h, col, 0.075 * fade)
            self._line(img, x, h, x + h, 0, col, 0.055 * fade)

    def _subscene_bursts(self, img, w, h, st):
        fade = self._module_fade.get("bursts", 0.0)
        if fade <= 0.02: return
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_bursts, h * DEFAULT_SHIFTS.vertical_center_bursts
        rings = 2 + int(5 * min(1.0, self._rms * 2.0))
        for r in range(rings):
            rad = (0.08 + 0.055 * r) * (1.0 + self._peak * 2.0)
            pts = []
            for k in range(28):
                a = k * math.tau / 28 + self.t * (0.9 + r * 0.2)
                rr = rad * (1.0 + 0.18 * vg_sin(a * (5 + r) + self.t * 4))
                pts.append((cx + vg_cos(a) * rr * w, cy + vg_sin(a) * rr * h * 0.55))
            col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_bursts + r * 28 + self._centroid * 360) % 360, 0.85, 0.95)
            for k in range(len(pts)-1): self._line(img, *pts[k], *pts[k+1], col, 0.34 * fade)

    def _subscene_spectral_comets(self, img, w, h, st):
        fade = self._module_fade.get("spectral_comets", 0.0)
        if fade <= 0.02: return
        for b in range(8):
            amp = float(self._band[b])
            if amp <= 0.0: continue
            a = self.t * (0.4 + amp * 1.7) + b * MEUM_INV
            r = 0.15 + amp * 0.38
            cx, cy = w * DEFAULT_SHIFTS.horizontal_center_bursts, h * DEFAULT_SHIFTS.vertical_center_bursts
            x = cx + vg_cos(a) * r * w
            y = cy + vg_sin(a * MEUM) * r * h * 0.48
            tx = cx + vg_cos(a - 0.28) * r * w * 0.72
            ty = cy + vg_sin((a - 0.28) * MEUM) * r * h * 0.36
            col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_spectral_comets + b * 42 + self._video_hue_shift) % 360, 0.9, 0.98)
            self._line(img, tx, ty, x, y, col, (0.35 + 0.55 * amp) * fade)
            self._dot(img, x, y, col, 0.8 * fade, r=1 + int(amp * 3))

    def _subscene_rhythm_mandala(self, img, w, h, st):
        fade = self._module_fade.get("rhythm_mandala", 0.0)
        if fade <= 0.02: return
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_bursts, h * DEFAULT_SHIFTS.vertical_center_bursts
        spokes = 12 + int(12 * st["snap"].get("struct", 0.0))
        for i in range(spokes):
            a = self.t * 0.12 + i * math.tau / spokes
            amp = 0.35 + 0.65 * float(self._band[i % 8])
            r = (0.12 + 0.25 * amp) * st["rho"]
            x = cx + vg_cos(a) * r * w
            y = cy + vg_sin(a) * r * h * 0.55
            col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_rhythm_mandala + i * 13 + self._video_hue_shift) % 360, 0.72, 0.9)
            self._line(img, cx, cy, x, y, col, 0.18 * fade + 0.25 * fade * amp)

    def _subscene_pulse_grid(self, img, w, h, st):
        fade = self._module_fade.get("pulse_grid", 0.0)
        if fade <= 0.02: return
        n = 8 + int(8 * st["snap"].get("struct", 0.0))
        pulse = abs(vg_sin(self.t * math.pi * max(1.0, st["snap"].get("bpm", 120.0)) / 60.0))
        col = self._hsv((DEFAULT_SHIFTS.hue_shift_base_pulse_grid + self._video_hue_shift) % 360, 0.8, 0.9)
        for i in range(n):
            u = i / max(n - 1, 1)
            x = u * w
            y = h * 0.5 + vg_sin(self.t * 0.4 + i * MEUM) * h * 0.16 * (0.3 + 0.7 * pulse)
            self._dot(img, x, y, col, (0.12 + 0.45 * pulse) * fade, r=1 + int(2 * pulse))

    def _collect_fit_points(self, w, h, st):
        """Sample volume / face / particle screen points (identity fit) for implode."""
        pts = []
        snap = st["snap"]
        n_shells = 3 + int(2 * snap["struct"]) + (1 if snap["carrier"] else 0)
        for s in range(n_shells):
            rad = st["vol_s"] * (0.15 + 0.12 * s) * (0.7 + 0.3 * self._band[s % 8])
            cx, cy = w * DEFAULT_SHIFTS.horizontal_center_bursts, h * DEFAULT_SHIFTS.vertical_center_bursts
            for k in range(8):
                a = self.t * MEUM_NORM + k * (math.tau / 8.0) + s * 0.4
                pts.append((
                    cx + rad * w * 0.35 * vg_cos(a) * MEUM_INV,
                    cy + rad * h * 0.28 * vg_sin(a) * MEUM,
                ))
        e = self._rms
        n_visible = int(round(getattr(self, "_render_n", self.n)))
        harmonic_mult = 0.72 + 0.85 * getattr(self, "_harmonic_activity", 0.5) + 0.45 * getattr(self, "_octave_boundary", 0.0)
        n_cap = 34 if self.mode != 3 else 52
        n_show = min(int(round(n_visible * harmonic_mult)), n_cap, len(self.layers))
        for i in range(n_show):
            layer = self.layers[i]
            local = float(self.wave[i % 256])
            life = max(layer.get("life", 0.3), 0.2)
            dist = layer["distance"] * (1.0 - 0.22 * e) + 0.28 * abs(local)
            # Slow object-local rotation plus an audio-reactive breathing
            # term. The old rates were visually busy; this keeps silhouettes
            # legible while still giving every instrument its own motion.
            yaw = (layer["yaw"]
                   + self.t * (0.105 + 0.16 * e + 0.055 * snap["eqr"])
                   + 0.10 * vg_sin(self.t * 0.23 + i * MEUM_INV)
                   + local * 0.22)
            pitch = layer["pitch"] + 0.095 * local + 0.035 * vg_sin(self.t * 0.19 + i * 0.37)
            roll = layer["roll"] + 0.055 * e * vg_sin(self.t * 0.31 + i * MEUM)
            n_v = max(3, 3 + int(((i * MEUM * 5.0) % 1.0) * 4))
            beat = abs(vg_sin(self.t * math.pi * max(1.0, float(snap.get("bpm", 120.0))) / 60.0))
            breathe = 1.0 + 0.045 * beat * (0.35 + 0.65 * e)
            scale = ((0.26 + 0.32 * abs(local) + 0.14 * e)
                     * (0.28 + 0.72 * life) * st["rho"]
                     * float(layer.get("implode", 1.0)) * breathe)
            ang0 = self.t * 0.35 + i * 0.2
            cosy, siny = vg_cos(yaw), vg_sin(yaw)
            cosp, sinp = vg_cos(pitch), vg_sin(pitch)
            cosr, sinr = vg_cos(roll), vg_sin(roll)
            for k in range(n_v):
                a = ang0 + k * (math.tau / n_v)
                px = layer.get("field_x", 0.0) + scale * vg_cos(a)
                py = layer.get("field_y", 0.0) + scale * vg_sin(a)
                pz = layer.get("field_z", 0.0) + 0.06 * vg_sin(a * 2 + self.t)
                xr = px * cosr - py * sinr
                yr = px * sinr + py * cosr
                yp = yr * cosp - pz * sinp
                zp = yr * sinp + pz * cosp
                xw = xr * cosy - zp * siny
                zw = xr * siny + zp * cosy + dist
                sx, sy, _ = self._project(xw, yp, zw, w, h)
                pts.append((sx, sy))
        # Include GOAVA geometry in the fit box so its shapes implode with the
        # rest of the scenograph instead of floating outside the fitted frame.
        if snap.get("goava"):
            events = getattr(self.app, "goava_note_events", []) if self.app is not None else []
            # GOAVA fit-box count = seed count (same as draw path).
            seed_count = 0
            try:
                seed_count = len(getattr(self.app, "goava_seed_numbers", None) or [])
            except Exception:
                seed_count = 0
            if seed_count <= 0 and self.app is not None and hasattr(self.app, "get_seed_values"):
                try:
                    seed_count = len(list(self.app.get_seed_values(
                        t_value=float(getattr(self, "t", 0.0)) % 8.0) or []) or [])
                except Exception:
                    seed_count = 0
            if seed_count <= 0:
                seed_count = len(events)
            gcount = min(len(events), max(1, int(seed_count)))
            for j, ev in enumerate(events[:gcount]):
                key = float(ev.get("raw", 0.0)) + float(ev.get("seed", 0.0)) * MEUM_INV
                a = self.t * 0.12 + j * math.tau / max(gcount, 1) + key * 0.017
                rad = (0.10 + 0.34 * (0.5 + 0.5 * vg_sin(key * MEUM_INV + st["form"] * 3.0))) * st["rho"]
                pts.append((w * DEFAULT_SHIFTS.horizontal_center_goava + vg_cos(a) * rad * w * 0.45, h * DEFAULT_SHIFTS.vertical_center_goava + vg_sin(a) * rad * h * 0.34))
        n_part = 12 + int(16 * self._rms)
        seed_i = int(abs(snap["seed"])) & 0xFFFF
        for p in range(min(n_part, 24)):
            ang = self.t * 0.65 + p * 0.37 + seed_i * 0.01 + st["ph"] * math.tau
            rr = 0.15 + 0.45 * abs(float(self.wave[p % 256])) * st["rho"]
            sx, sy, _ = self._project(
                rr * vg_cos(ang), rr * vg_sin(ang * MEUM),
                1.05 + 0.35 * self._rms, w, h,
            )
            pts.append((sx, sy))
        return pts



    def _subscene_generative_terrain(self, img, w, h, st):
        """Procedural heightfield / ridge mesh from seed + entropy + time.

        Pure visual generation: ridges, basins, and contour stitches whose
        density and orientation are closed-form in (seed, t, visual_entropy).
        Does not read or write any audio/music generator state.
        """
        snap = st.get("snap", {}) if isinstance(st.get("snap"), dict) else {}
        seed = float(snap.get("seed", 0.0) or getattr(self, "_canonical_ctx", {}).get("seed", 0.0) or 0.0)
        e = float(np.clip(getattr(self, "_visual_entropy", 0.5), 0.0, 1.0))
        rms = float(np.clip(getattr(self, "_rms", 0.2), 0.0, 1.0))
        # Skip if almost invisible
        fade = 0.20 + 0.55 * e + 0.25 * rms
        if fade < 0.08:
            return
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_generative_terrain, h * DEFAULT_SHIFTS.vertical_center_generative_terrain
        # Number of ridge polylines scales with entropy (more chaos → more folds)
        n_ridges = 3 + int(7 * e + 2 * ((seed * MEUM) % 1.0))
        for r in range(n_ridges):
            u0 = identity_unit("terrain", seed, "ridge", r)
            pts = []
            segs = 18 + int(14 * e)
            for k in range(segs):
                t_u = k / max(1, segs - 1)
                # Heightfield wave along a seed-tilted axis
                a = t_u * math.tau * (1.0 + 1.5 * u0) + self.t * (0.07 + 0.04 * r) + seed * 0.002
                height = 0.08 + 0.22 * abs(vg_sin(a * MEUM + r * PHI))
                height *= (0.6 + 0.4 * e)
                xw = (t_u - 0.5) * 1.15 + 0.08 * vg_cos(a * PHI)
                yw = height * vg_sin(a) - 0.05 * r
                zw = 0.7 + 0.25 * ((u0 + t_u) % 1.0)
                px, py, _ = self._project(xw, yw, zw, w, h)
                pts.append((px, py))
            hue = (30 + 40 * r + 80 * u0 + self._video_hue_shift) % 360
            col = self._hsv(hue, 0.35 + 0.25 * e, 0.45 + 0.35 * fade)
            alpha = 0.07 + 0.12 * fade
            for k in range(len(pts) - 1):
                self._line(img, pts[k][0], pts[k][1], pts[k + 1][0], pts[k + 1][1], col, alpha)
            # Contour dots on ridge peaks
            if r % 2 == 0 and pts:
                mid = pts[len(pts) // 2]
                self._dot(img, mid[0], mid[1], col, 0.15 + 0.2 * fade, r=1)

    def _subscene_numeric_fractal(self, img, w, h, st):
        """Book fractal sets — 12 z-iters/node, transparency, shared 3D xyz.

        Goal
        ----
        Each instrument is the same fractal object.  Each *node* runs at most
        **12** iterations of z-values (ESKI_FRACTAL_MAX_ITER).  OT never
        rewrites the book equations; it only changes arithmetic nature.
        Compositional X,Y,Z are shared with the music lattice so video/game
        nodes track the same numeric identity as pitch/FX pathways.

        Prevalence: sequential numerics → playlist/algo → music lattice → residual.
        """
        try:
            seed = 0.0
            seq = []
            if self.app is not None and hasattr(self.app, "get_seed_values"):
                try:
                    seq = [float(v) for v in (self.app.get_seed_values(
                        t_value=float(getattr(self, "t", 0.0)) % 8.0) or [])[:16]]
                except Exception:
                    seq = []
            if self.app is not None and hasattr(self.app, "get_numeric_seed"):
                try:
                    seed = float(self.app.get_numeric_seed() or 0.0)
                except Exception:
                    seed = 0.0
            if not seq:
                seq = [seed, seed * MEUM, seed * PHI, seed * MEUM_INV]
            s_int = int(_safe_int_seed(seed)) & 0x7FFFFFFF

            playlist_hash = 0
            try:
                app = self.app
                if app is not None:
                    pl = getattr(app, "master_playlist_data", None) or []
                    for row in pl[:32]:
                        if isinstance(row, dict):
                            playlist_hash ^= _stable_hash((
                                str(row.get("step_algorithm", ""))[:24],
                                str(row.get("operator", ""))[:16],
                                str(row.get("live_parametrics", ""))[:16],
                            ), modulus=0x80000000)
                    gas = getattr(app, "global_algo_state", None) or {}
                    if gas:
                        playlist_hash ^= _stable_hash(str(sorted(gas.items())[:12]), modulus=0x80000000)
            except Exception:
                playlist_hash = 0

            set_name = eski_fractal_pick(s_int, sequential_nums=seq, playlist_hash=playlist_hash)
            c_param = float(seq[0] * MEUM_INV) if seq else float(seed * MEUM_INV)
            c_param = ((c_param % 4.0) - 2.0) * 0.5

            canon = list(getattr(self, "_canonical", None) or [])
            if not canon:
                ctx = getattr(self, "_canonical_ctx", None) or {
                    "seed": seed, "base": 432.0, "ratio": 1.0, "s_int": s_int,
                    "full_unison": False, "n_inst": CANONICAL_MASTER_SLOTS, "sequential_nums": list(seq),
                }
                flags = getattr(self, "_canonical_flags", {}) or {}
                canon = [canonical_visual_instrument(i, ctx, flags)
                         for i in range(min(16, CANONICAL_MASTER_SLOTS))]

            flags = getattr(self, "_canonical_flags", {}) or {}
            boost = 1.0 + 0.25 * (1 if flags.get("randomizer") else 0) \
                    + 0.2 * (1 if flags.get("phase_lock") else 0) \
                    + 0.3 * (1 if flags.get("goava") else 0)
            ot_on = bool(OP_THEORY_ENABLED)
            self._last_fractal_family = f"eski:{set_name}:OT={int(ot_on)}:z12"

            t = float(getattr(self, "t", 0.0))
            cx, cy = w * DEFAULT_SHIFTS.horizontal_center_numeric_fractal, h * DEFAULT_SHIFTS.vertical_center_numeric_fractal
            # Shared compositional origin (seed xyz) — same for all nodes this frame
            ox, oy, oz = compositional_xyz(seed, sequential_nums=seq, t=t, slot=0)

            # Field graph: coarse lattice, 12 z-iters per node, transparency by escape
            # VISIBLE_FRACTAL_2026: this used to be a sparse grid of 1px dots
            # (step ~= min(w,h)//36, radius = step//3) capped at alpha<=0.80 —
            # at typical preview/export resolutions that is a handful of
            # barely-blended single pixels, i.e. "incredibly faint on the
            # scale". Denser sampling + larger dots + a full-range alpha
            # ceiling make the same deterministic field actually readable,
            # without changing any of the seed-derived math that picks it.
            step = max(3, min(w, h) // 24)
            for yy in range(0, h, step):
                for xx in range(0, w, step):
                    u = (xx / max(1, w) - 0.5) * 2.0 + ox * 0.15
                    v = (yy / max(1, h) - 0.5) * 2.0 + oy * 0.15
                    z0 = oz * 0.25
                    zs, n_done, escaped = eski_fractal_iterate_z(
                        set_name, u, v, z0, c_param, max_iter=12)
                    if not zs:
                        continue
                    z_last = zs[-1]
                    mag = abs(z_last)
                    norm = mag / (1.0 + mag)
                    # Transparency: deeper iter / non-escape → more opaque; early escape → translucent
                    alpha = (0.12 + 0.55 * (n_done / 12.0) * (0.35 if escaped else 1.0)) * boost
                    alpha = max(0.30, min(1.0, alpha))  # floor keeps it visible; no artificial ceiling below full opacity
                    # 3D adaptation: project (u,v,z_last) with shared compositional offset
                    px, py, depth = self._project(
                        u * 0.55, v * 0.55, 0.7 + 0.25 * max(-1.0, min(1.0, z_last * 0.15)) + oz * 0.1,
                        w, h)
                    col = self._hsv(
                        (norm * 220 + self._video_hue_shift + (35 if ot_on else 0) + n_done * 4) % 360,
                        0.45 + 0.2 * (n_done / 12.0), 0.35 + 0.5 * norm)
                    self._dot(img, px, py, col, alpha, r=max(2, step // 2))
                    # Trail of z-values (transparent trail along iteration)
                    if n_done >= 3:
                        for zi, zv in enumerate(zs[:: max(1, n_done // 3)]):
                            t_alpha = alpha * (0.25 + 0.2 * (zi / max(1, len(zs))))
                            qx, qy, _ = self._project(
                                u * 0.55, v * 0.55,
                                0.7 + 0.2 * max(-1.0, min(1.0, zv * 0.15)), w, h)
                            self._dot(img, qx, qy, col, t_alpha, r=1)

            # Instrument objects: follow composition geometry; blend/switch modes
            # at phase-points (instrument_geometry_mode). Same object schema always.
            for i, obj in enumerate(canon):
                if not isinstance(obj, dict):
                    continue
                ent = float(obj.get("entropy", 0.5) or 0.5)
                hue = float(obj.get("hue", (i * 37) % 360) or 0.0)
                depth_o = float(obj.get("depth", 0.5) or 0.5)
                phase0 = float(obj.get("phase0", 0.0) or 0.0)
                ratio = float(obj.get("ratio", 1.0) or 1.0)
                sx, sy, sz = compositional_xyz(seed, sequential_nums=seq, t=t, slot=i)
                live_phase = phase0 + t * (0.30 + 0.70 * ent)  # tracks composition time
                mode = instrument_geometry_mode(
                    i, live_phase, (sx, sy, sz), flags=flags, fractal_set=set_name)
                zs, n_done, escaped = eski_fractal_iterate_z(
                    set_name, sx, sy, sz, c_param, max_iter=12)
                z_last = zs[-1] if zs else 0.0
                # Mode blend: lattice vs book_set pulls position / alpha
                lat_w = float(mode.get("lattice", 0.5))
                book_w = float(mode.get("book_set", 0.2))
                yaw = live_phase + z_last * 0.08 * book_w
                rad_orb = (0.25 + 0.35 * depth_o) * (0.85 + 0.3 * lat_w)
                px, py, _ = self._project(
                    math.cos(yaw) * rad_orb + sx * 0.1,
                    math.sin(yaw * MEUM_INV) * rad_orb * 0.78 + sy * 0.1,
                    0.75 + 0.2 * depth_o + 0.1 * max(-1.0, min(1.0, z_last * 0.1)) * book_w + sz * 0.05,
                    w, h)
                alpha = (0.5 + 0.5 * ent * (n_done / 12.0) * (0.4 if escaped else 1.0)) * boost
                alpha *= (0.5 + 0.5 * lat_w + 0.5 * book_w)
                if mode.get("near_phase_point"):
                    alpha = min(1.0, alpha + 0.12 * float(mode.get("snap", 0)))
                alpha = max(0.5, min(1.0, alpha))
                hue_m = (hue + self._video_hue_shift + abs(z_last) * 6
                         + 25.0 * float(mode.get("goava", 0))
                         + 15.0 * float(mode.get("phase_lock", 0))) % 360
                col = self._hsv(hue_m, 0.5 + 0.5 * ent, 0.5 + 0.5 * ent)
                rad = max(1, int(2 + 4 * ent * boost * (0.5+ 0.5 * lat_w)))
                self._dot(img, px, py, col, alpha, r=rad)
                # Child sample — stronger when scatter/goava mode weight is up
                child_a = alpha * (0.35 + 0.25 * float(mode.get("scatter", 0))
                                   + 0.2 * float(mode.get("goava", 0)))
                cx2, cy2, _ = self._project(
                    math.cos(yaw * PHI) * (0.5 + 0.5 * depth_o),
                    math.sin(yaw * MEUM) * (0.5 + 0.5 * depth_o) * 0.7,
                    0.8 + 0.1 * depth_o, w, h)
                col2 = self._hsv((hue_m + 60) % 360, 0.4, 0.35 + 0.3 * ent)
                self._dot(img, cx2, cy2, col2, child_a, r=max(1, rad // 2))
                # Stash mode on object for cross-engine debug alignment
                try:
                    obj["_geom_mode"] = mode
                except Exception:
                    pass
        except Exception:
            pass


    def _subscene_seed_morph(self, img, w, h, st):
        """Instantaneous seed-morph glyphs: every evaluated seed number becomes
        a small generative glyph family that evolves with t.

        Cross-correlates list-seed length with visual population so a longer
        numeric seed field literally grows more shape identity on screen.
        Visual-only — does not touch the music generator.
        """
        seed_vals = []
        try:
            if self.app is not None and hasattr(self.app, "get_seed_values"):
                seed_vals = list(self.app.get_seed_values(
                    t_value=float(getattr(self, "t", 0.0)) % 16.0) or [])[:24]
        except Exception:
            seed_vals = []
        if not seed_vals:
            # Fall back to a single residue of the numeric seed
            try:
                if self.app is not None and hasattr(self.app, "get_numeric_seed"):
                    seed_vals = [float(self.app.get_numeric_seed() or 0.0)]
            except Exception:
                seed_vals = [0.0]
        e = float(np.clip(getattr(self, "_visual_entropy", 0.5), 0.0, 1.0))
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_orbitals, h * DEFAULT_SHIFTS.vertical_center_orbitals
        n = len(seed_vals)
        for i, val in enumerate(seed_vals):
            try:
                v = float(val)
            except Exception:
                v = float(i)
            if not math.isfinite(v):
                v = float(i)
            u = identity_unit("morph", v, i, int(self.t * 10) % 97)
            # Glyph center on a slow orbit whose radius depends on |v|
            ang = self.t * (0.09 + 0.02 * (i % 5)) + u * math.tau + i * MEUM
            rad = 0.12 + 0.38 * ((abs(v) * PHI) % 1.0) * (0.5 + 0.5 * e)
            px, py, _ = self._project(rad * vg_cos(ang), rad * vg_sin(ang) * 0.72,
                                      0.85 + 0.2 * u, w, h)
            # Petal count from seed magnitude
            petals = 3 + int(abs(v) * 7 + u * 5) % 6
            hue = (v * 17.3 + i * 41 + self._video_hue_shift) % 360
            col = self._hsv(hue, 0.55 + 0.3 * e, 0.7 + 0.2 * e)
            alpha = 0.10 + 0.18 * e
            for p in range(petals):
                a2 = ang + p * math.tau / petals + self.t * 0.15
                r2 = 8.0 + 18.0 * ((u + p * 0.13) % 1.0)
                x2 = px + r2 * vg_cos(a2)
                y2 = py + r2 * vg_sin(a2) * 0.85
                self._line(img, px, py, x2, y2, col, alpha)
                self._dot(img, x2, y2, col, alpha + 0.08, r=1)
            self._dot(img, px, py, col, 0.2 + 0.15 * e, r=1 + (i % 2))

    def _subscene_engine_ornaments(self, img, w, h, st):
        """Extra closed-form ornaments driven by the same engine flags as audio.

        Each ornament is a pure function of (seed, t, snap flags, spectrum).
        Enabling GOAVA / phase-lock / seeded / euclid changes which ornaments
        appear — mirroring how those engines change the audible mix — without
        inventing a second non-deterministic visual identity.
        """
        snap = st.get("snap", {}) if isinstance(st.get("snap"), dict) else {}
        seed = float(snap.get("seed", 0.0))
        e = float(self._rms)
        c = float(self._centroid)
        cx, cy = w * DEFAULT_SHIFTS.horizontal_center_math_roses, h * DEFAULT_SHIFTS.vertical_center_math_roses
        # phase-lock rings
        if snap.get("phase_lock") or snap.get("euclid"):
            rings = 2 + int(3 * e)
            for r in range(rings):
                pts = []
                rad = (0.14 + 0.11 * r) * (0.7 + 0.3 * e)
                segs = 24 + int(20 * e)
                for k in range(segs):
                    a = k * math.tau / segs + self.t * (0.08 + 0.03 * r) + seed * 0.001
                    px, py, _ = self._project(rad * vg_cos(a), rad * vg_sin(a) * 0.72,
                                              0.9 + 0.15 * r, w, h)
                    pts.append((px, py))
                col = self._hsv((190 + r * 25 + self._video_hue_shift) % 360, 0.55, 0.7)
                for k in range(len(pts)):
                    self._line(img, pts[k][0], pts[k][1],
                               pts[(k + 1) % len(pts)][0], pts[(k + 1) % len(pts)][1],
                               col, 0.12 + 0.10 * e)
        # seeded constellation sparks
        if snap.get("seeded") or snap.get("randomizer"):
            n_sparks = 8 + int(16 * e)
            for i in range(n_sparks):
                u = identity_unit("spark", seed, "ornament", i)
                a = u * math.tau + self.t * 0.11
                rr = 0.12 + 0.40 * ((u * PHI) % 1.0)
                px, py, _ = self._project(rr * vg_cos(a), rr * vg_sin(a * MEUM_INV) * 0.7,
                                          0.85 + 0.2 * ((u * MEUM) % 1.0), w, h)
                col = self._hsv((40 + 280 * u + self._video_hue_shift) % 360, 0.65, 0.85)
                self._dot(img, px, py, col, 0.18 + 0.22 * e, r=1 + (i % 2))
        # meum spiral (always mild, stronger with harmonic activity)
        harm = float(getattr(self, "_harmonic_activity", 0.5))
        fade_sp = 0.25 + 0.55 * harm
        if fade_sp > 0.05:
            pts = []
            for k in range(64):
                u = k / 63.0
                a = u * math.tau * 3.0 * MEUM + self.t * 0.22
                rr = (0.05 + 0.48 * u) * (0.6 + 0.4 * e)
                px, py, _ = self._project(rr * vg_cos(a), rr * vg_sin(a * MEUM_INV),
                                          1.0 + 0.1 * vg_sin(a), w, h)
                pts.append((px, py))
            col = self._hsv((280 + self._video_hue_shift) % 360, 0.5, 0.65)
            for k in range(len(pts) - 1):
                self._line(img, *pts[k], *pts[k + 1], col, 0.08 * fade_sp)
        # carrier wake
        if float(snap.get("carrier", 0.0) or 0.0) > 0.0:
            for k in range(20):
                u = k / 19.0
                a = self.t * 0.4 + u * math.tau
                rr = 0.35 + 0.15 * vg_sin(self.t * 0.5 + u * 4)
                px, py, _ = self._project(rr * vg_cos(a), rr * vg_sin(a) * 0.5,
                                          1.1, w, h)
                col = self._hsv((160 + 40 * u) % 360, 0.4, 0.55)
                self._dot(img, px, py, col, 0.10 + 0.08 * e, r=1)

    def fractal_spatial_snapshot(self, depth=3, roots=8, seed=None, goava=False):

        """Project the canonical visual composition into the audio-immutable spatial grammar."""
        if seed is None:
            seed = self._canonical_ctx.get("seed", 0.0) if isinstance(getattr(self, "_canonical_ctx", None), dict) else 0.0
        fp = self.visual_composition_fingerprint()
        return FractalSpatialEngine(seed, fp, goava).snapshot(depth=max(0, int(depth)), roots=max(1, int(roots)))

    def set_deterministic_camera_view(self, view_index=0, view_count=64, seed=None):
        """Select one reproducible view from the canonical low-discrepancy lattice."""
        if seed is None:
            seed = self._canonical_ctx.get("seed", 0.0) if isinstance(getattr(self, "_canonical_ctx", None), dict) else 0.0
        view = fibonacci_view(int(view_index), int(view_count), seed)
        self._camera_view_override = dict(view)
        self._visual_view_index = int(view_index)
        self._visual_view_count = max(1, int(view_count))
        self._cam_distance = float(view.get("distance", 1.0))
        self._cam_fov_deg = float(view.get("fov_deg", 48.0))
        return dict(view)

    def deterministic_viewset(self, count=32, seed=None, existing=()):
        if seed is None:
            seed = self._canonical_ctx.get("seed", 0.0) if isinstance(getattr(self, "_canonical_ctx", None), dict) else 0.0
        return select_views(int(count), seed, existing)

    def render_deterministic_view(self, w=640, h=360, view_index=0, view_count=64, seed=None, export=False):
        view = self.set_deterministic_camera_view(view_index, view_count, seed)
        actual_seed = seed if seed is not None else (self._canonical_ctx.get("seed", 0.0) if isinstance(getattr(self, "_canonical_ctx", None), dict) else 0.0)
        fp = self.visual_composition_fingerprint()
        sid = visual_signal_id(actual_seed, fp, view)
        return self.render_frame(w, h, export=export), sid

    def clear_deterministic_camera_view(self):
        self._camera_view_override = None

    def get_camera_state(self):
        return {
            "yaw_deg": math.degrees(float(self._cam_yaw)),
            "pitch_deg": math.degrees(float(self._cam_pitch)),
            "roll_deg": math.degrees(float(self._cam_roll)),
            "distance": float(getattr(self, "_cam_distance", 0.0)),
            "fov_deg": float(getattr(self, "_cam_fov_deg", 48.0)),
            "view_index": int(getattr(self, "_visual_view_index", 0)),
            "view_count": int(getattr(self, "_visual_view_count", 1)),
            "deterministic": isinstance(getattr(self, "_camera_view_override", None), dict),
            "composition_fingerprint": self.visual_composition_fingerprint(),
        }

    def visual_composition_fingerprint(self):
        objects=[]
        for i,p in enumerate(getattr(self, "_canonical", []) or []):
            objects.append({"id":i,"type":"instrument","x":p.get("x",0.0),"y":p.get("y",0.0),"z":p.get("z",0.0),"scale":p.get("pack",1.0),"rotation":p.get("yaw",0.0),"depth":p.get("depth",0.0),"role":"canonical_instrument"})
        seed=self._canonical_ctx.get("seed",0.0) if isinstance(getattr(self,"_canonical_ctx",None),dict) else 0.0
        return _visual_composition_fingerprint(objects, seed=seed, abstraction="structural")

    def composition_snapshot(self, t=None):
        """Unified composition state shared by music lattice, video, and game.

        Goal: prove video/game respond to the *same* canonicals as the music.
        Object/instrument count is deliberately omitted from identity fields so
        raising or lowering the ensemble leaves seeded geometry identical.
        """
        t = float(t if t is not None else getattr(self, "t", 0.0))
        ctx = dict(getattr(self, "_canonical_ctx", None) or {})
        flags = dict(getattr(self, "_canonical_flags", None) or {})
        seed = float(ctx.get("seed", 0.0) or 0.0)
        seq = []
        try:
            if self.app is not None and hasattr(self.app, "get_seed_values"):
                seq = [float(v) for v in (self.app.get_seed_values(t_value=t % 8.0) or [])]
        except Exception:
            seq = []
        if not seq:
            seq = [seed]
        seed_count = len(seq)
        try:
            gsn = getattr(self.app, "goava_seed_numbers", None) if self.app is not None else None
            if gsn:
                seed_count = max(seed_count, len(gsn))
        except Exception:
            pass
        set_name = eski_fractal_pick(
            int(_safe_int_seed(seed)) & 0x7FFFFFFF,
            sequential_nums=seq,
            playlist_hash=0,
        )
        ox, oy, oz = compositional_xyz(seed, sequential_nums=seq, t=t, slot=0)
        modes = []
        for i in range(min(8, len(getattr(self, "_canonical", []) or []) or 8)):
            c = (getattr(self, "_canonical", None) or [{}])[i] if getattr(self, "_canonical", None) else {}
            if not isinstance(c, dict):
                c = {}
            xyz = compositional_xyz(seed, sequential_nums=seq, t=t, slot=i)
            ph = float(c.get("phase0", 0.0) or 0.0) + t * (0.30 + 0.70 * float(c.get("entropy", 0.5) or 0.5))
            modes.append(instrument_geometry_mode(i, ph, xyz, flags=flags, fractal_set=set_name))
        # MASTER_VECTOR_XMOD_RESONANCE_2026: video + game engines must respond to
        # the same master-vector / xmod / resonance controls that drive audio,
        # all under canonical authority. Resonance is clamped 50–150% at all times.
        master_vector = (0.0, 0.0, 0.0)
        master_vector_drive = 0.50
        master_vector_enabled = True
        global_xmod = 1.0
        global_input_xmod = 1.0
        global_mod = {"xmod": 1.0, "input_xmod": 1.0, "synth": 1.0, "patch": 1.0, "script": 1.0, "domain": 1.0}
        resonance = 1.50
        try:
            if self.app is not None:
                if hasattr(self.app, "_master_vector_effective"):
                    mv = self.app._master_vector_effective()
                    master_vector = (float(mv[0]), float(mv[1]), float(mv[2]))
                st = getattr(self.app, "master_vector_state", None) or {}
                master_vector_drive = float(np.clip(st.get("drive", 0.50), 0.0, 1.0))
                master_vector_enabled = bool(st.get("enabled", True))
                gms = getattr(self.app, "global_mod_state", None) or {}
                global_xmod = float(np.clip(gms.get("xmod", 1.0), 0.0, 2.0))
                global_input_xmod = float(np.clip(gms.get("input_xmod", 1.0), 0.0, 2.0))
                global_mod = {k: float(np.clip(gms.get(k, 1.0), 0.0, 2.0)) for k in ("xmod", "input_xmod", "synth", "patch", "script", "domain")}
                # Natural operating band is 50–150%; do not hard-clamp live values.
                resonance = float(getattr(self.app, "canonical_resonance_factor", CANONICAL_RESONANCE_DEFAULT) or CANONICAL_RESONANCE_DEFAULT)
                if not math.isfinite(resonance):
                    resonance = 1.50
        except Exception:
            pass
        return {
            "t": t,
            "seed": seed,
            "seed_list": list(seq),
            "seed_count": int(seed_count),  # GOAVA count source
            "goava_count": int(seed_count),
            "fractal_set": set_name,
            "xyz": (ox, oy, oz),
            "flags": {
                "randomizer": bool(flags.get("randomizer")),
                "phase_lock": bool(flags.get("phase_lock")),
                "goava": bool(flags.get("goava")),
                "seeded": bool(flags.get("seeded")),
            },
            "ot_enabled": bool(OP_THEORY_ENABLED),
            "canonical_slots": int(len(getattr(self, "_canonical", []) or [])),  # fixed visual budget
            "mode_weights": modes,
            "fingerprint": self.visual_composition_fingerprint(),
            # identity ignores instrument/object count by design
            "identity_note": "N-independent: same seed+flags+seq → same visual/game geometry",
            # Canonical command surface for video + videogame engines
            "master_vector": master_vector,
            "master_vector_drive": master_vector_drive,
            "master_vector_enabled": master_vector_enabled,
            "global_xmod": global_xmod,
            "global_input_xmod": global_input_xmod,
            "global_mod_state": global_mod,
            "canonical_resonance_factor": resonance,
            "resonance_min": 0.50,
            "resonance_max": 1.50,
            "wavetable_projector": dict(getattr(self.app, "wavetable_projector_state", {}) or {}) if self.app is not None else {},
            "automator_timing_mode": str(getattr(self.app, "automator_timing_mode", "wrap") if self.app is not None else "wrap"),
            "algorithm_xmod_local": float(getattr(self.app, "local_algorithm_xmod", 1.0) if self.app is not None else 1.0),
            "algorithm_xmod_global": float(getattr(self.app, "global_algorithm_xmod", 1.0) if self.app is not None else 1.0),
            # User-owned TrackOffset (not a canonical modification handle)
            "global_track_offset": float(getattr(self.app, "global_track_offset", 0.0) if self.app is not None else 0.0),
            "track_offset": float(getattr(self.app, "global_track_offset", 0.0) if self.app is not None else 0.0),
        }

    def composition_readout_lines(self, t=None):
        """HUD/ESC lines: fractal set, GOAVA seed count, OT, mode blend."""
        snap = self.composition_snapshot(t=t)
        lines = []
        lines.append(f"fractal {snap['fractal_set']} · OT={'ON' if snap['ot_enabled'] else 'OFF'}")
        lines.append(f"GOAVA seeds {snap['goava_count']} · slots {snap['canonical_slots']} (N-independent)")
        xyz = snap.get("xyz") or (0, 0, 0)
        lines.append(f"xyz ({xyz[0]:+.3f},{xyz[1]:+.3f},{xyz[2]:+.3f})")
        flags = snap.get("flags") or {}
        eng = "+".join(k.upper()[:4] for k, v in flags.items() if v) or "none"
        lines.append(f"engines {eng}")
        if snap.get("mode_weights"):
            m0 = snap["mode_weights"][0]
            lines.append(
                f"mode0 lattice={m0.get('lattice',0):.2f} book={m0.get('book_set',0):.2f} "
                f"snap={m0.get('snap',0):.2f}{' · PHASEPOINT' if m0.get('near_phase_point') else ''}"
            )
        lines.append(f"fp {str(snap.get('fingerprint',''))[:12]}")
        return lines

    def reset_camera(self):
        """Return scenograph camera to origin view (shared by double-click + Quick Edit)."""
        self._camera_view_override = None
        for attr, val in (("_cam_yaw", 0.0), ("_cam_pitch", 0.0), ("_cam_roll", 0.0), ("_cam_distance", None),
                          ("_yaw", 0.0), ("_pitch", 0.0), ("view_yaw", 0.0), ("view_pitch", 0.0)):
            if hasattr(self, attr):
                try:
                    if val is None:
                        continue
                    setattr(self, attr, float(val))
                except Exception:
                    pass
        try:
            self.update()
        except Exception:
            pass

    def render_frame(self, w=640, h=360, export=False, frame_index=None):
        """Composite all Meum subscenes. export=True skips UI-only overlays.

        ``frame_index`` is explicit for deterministic offline rendering; live
        callers may omit it and advance the interactive frame counter normally.
        """
        self.export_mode = bool(export)
        w = max(int(w), 8)
        h = max(int(h), 8)
        img = np.zeros((h, w, 3), dtype=np.float32)
        self._advance_instrument_resize()
        if frame_index is None:
            self._visual_frame += 1
            self._render_frame_index = int(self._visual_frame)
        else:
            self._render_frame_index = int(frame_index)
            self._visual_frame = int(frame_index)

        # Seeded stochastic evolution from *evaluated* numeric seeds (not
        # SHA of the raw script text — that made visuals drift away from the
        # numbers the user typed). Same seed list + frame is reproducible.
        try:
            seed_key = 0
            if self.app is not None and hasattr(self.app, "get_seed_values"):
                try:
                    vals = list(self.app.get_seed_values(t_value=float(getattr(self, "t", 0.0)) % 8.0) or [])
                    if vals:
                        seed_key = int(_safe_int_seed(vals[0]))
                        for _vi, _vv in enumerate(vals[1:6]):
                            seed_key ^= (int(_safe_int_seed(_vv)) << (_vi % 8)) & 0x7FFFFFFF
                except Exception:
                    seed_key = 0
            if not seed_key and self.app is not None and hasattr(self.app, "get_numeric_seed"):
                try:
                    seed_key = int(_safe_int_seed(self.app.get_numeric_seed() or 0.0))
                except Exception:
                    seed_key = 0
            mixed = (seed_key ^ (int(self._render_frame_index) * 0x9E3779B1)) & 0x7FFFFFFF
            self._rng = np.random.RandomState(mixed if mixed else 1)
            # CANONICAL_VISUAL_2026: _visual_entropy is set by the canonical
            # build below (entropy_draw_0_1 / union context) — the old
            # `0.5 + 0.5*rng` convenience draw sat on a skewed 0.75 mean and was
            # the one place the visual side left the audio entropy family.
        except Exception:
            pass
        # CANONICAL_VISUAL_2026: build the analog of the audio instrument pass.
        # Every instrument slot -> one canonical 2.5D layer parameter set, from
        # the SAME latices and the SAME entropy draw the audio engine uses.
        # Stochastic noise is minimized: geometry is a pure function of the
        # union context + slot + engine flags.  The only optional stochastic
        # element is GOAVA's irrational stream (drives glyph shape, GOAVA-only).
        # Built BEFORE _meum_state so the frame's entropy draw is fresh.
        self._build_canonical_ctx_and_layers()
        st = self._meum_state()
        self._update_camera_and_packing(st)
        self._subscene_image_synthesis(img, w, h, st)
        self._update_scenograph_module_schedule(st)
        # Theory of the union: the per-instrument constellation is drawn FIRST
        # (the "registered subcomponents"); under the 4-engine union every slot
        # resolves to one parameter set, so no instrument subcomponent can be
        # told apart — exactly as on the audio side.
        self._draw_canonical_constellation(img, w, h, st)
        # Identity pass → union bbox → implode every part to fill outer bounds
        self._reset_fit(w, h)
        self._commit_fit(self._collect_fit_points(w, h, st), w, h)
        # ONE_ROUTE_VISUAL_2026: every normal instrument is rendered by the
        # same InstrumentVisualObject class. There are no catalog-count graphics,
        # independent shape generators, or n-dependent identity placements.
        self._subscene_faces_segments(img, w, h, st)
        # Full scenograph stack — every module is a closed-form function of the
        # same composition state the audio engine uses. Fade schedule (above)
        # decides presence; nothing here is random or N-dependent for identity.
        self._subscene_volumes(img, w, h, st)
        self._subscene_particles(img, w, h, st)
        self._subscene_math_filaments(img, w, h, st)
        self._subscene_math_roses(img, w, h, st)
        self._subscene_orbitals(img, w, h, st)
        self._subscene_constellations(img, w, h, st)
        self._subscene_lattice(img, w, h, st)
        self._subscene_bursts(img, w, h, st)
        self._subscene_spectral_comets(img, w, h, st)
        self._subscene_rhythm_mandala(img, w, h, st)
        self._subscene_pulse_grid(img, w, h, st)
        self._subscene_wave_integration(img, w, h, st)
        # Generative visual layers — visual-only (never mutates the music engine).
        # Prevalence hierarchy is documented on _subscene_numeric_fractal:
        # sequential numeric inputs → music lattice → game geometry → residuals.
        try:
            self._subscene_generative_terrain(img, w, h, st)
        except Exception:
            pass
        try:
            self._subscene_seed_morph(img, w, h, st)
        except Exception:
            pass
        # Core fractal: each instrument = same object; ensemble = the fractal.
        try:
            self._subscene_numeric_fractal(img, w, h, st)
        except Exception:
            pass
        # GOAVA remains a second graphical class, intentionally separate because
        # its identity is its own irrational numerical stream rather than an
        # ordinary instrument voice.
        self._subscene_goava(img, w, h, st)
        # Engine-flag ornaments + ambient field (deterministic, composition-tied).
        self._subscene_engine_ornaments(img, w, h, st)

        # Bright ambient phase field. This is not another object class: it is a
        # low-cost compositing envelope derived from the same canonical state.
        cx, cy = w*0.5, h*0.48
        for q in range(12):
            a = self.t*(0.045+0.006*q) + q*MEUM
            rr = min(w,h)*(0.12+0.035*q)*(0.75+0.25*self._visual_entropy)
            # Camera-aware ambient: orbit slightly with yaw so the field feels
            # attached to the world, not glued to the screen.
            yaw_bias = float(getattr(self, "_cam_yaw", 0.0)) * 0.15
            x = cx + vg_cos(a + yaw_bias)*rr
            y = cy + vg_sin(a*MEUM_INV + float(getattr(self, "_cam_pitch", 0.0))*0.1)*rr*0.72
            col = self._hsv((q*30 + self._video_hue_shift + self._canonical_ctx.get("seed",0.0)*0.17)%360, 0.45, 0.82)
            self._dot(img,x,y,col,0.10+0.08*self._rms,r=1)

        return np.clip(img, 0, 255).astype(np.uint8)


class _VideoRenderSignals(QObject):
    finished = pyqtSignal(object, int, int, int)


class _VideoRenderTask(QRunnable):
    """Render one latest-only scenograph frame off the Qt GUI thread."""
    def __init__(self, engine, width, height, export_mode, generation, signals):
        super().__init__()
        self.engine = engine
        self.width = int(width)
        self.height = int(height)
        self.export_mode = bool(export_mode)
        self.generation = int(generation)
        self.signals = signals
        self.setAutoDelete(True)

    def run(self):
        try:
            frame = self.engine.render_frame(self.width, self.height, export=self.export_mode)
        except Exception:
            frame = None
        # The viewer can be destroyed while this QRunnable is still finishing.
        # Emitting through a QObject that Qt has already deleted raises a second
        # RuntimeError; simply drop the frame in that case.
        try:
            self.signals.finished.emit(frame, self.width, self.height, self.generation)
        except RuntimeError:
            return


class VideoSynthViewer(QFrame):
    """Center square: Meum 2.5D/3D scenograph."""

    def __init__(self, parent=None, engine=None):
        super().__init__(parent)
        self.setMinimumSize(180, 180)
        self.setStyleSheet("background-color: #050608; border: 1px solid #2a2e39; border-radius: 6px;")
        self.engine = engine or VideoSynthEngine()
        if parent is not None:
            try:
                self.engine.bind_app(parent)
            except Exception:
                pass
        self._frame = np.zeros((180, 180, 3), dtype=np.uint8)
        self.show_scope_overlay = False
        self.scope_wave = np.zeros(100, dtype=np.float32)
        # Manual scenograph camera: +/-180° yaw and pitch from the origin view.
        # The animated camera remains additive, so the origin is a stable reference.
        self._manual_yaw_deg = 0.0
        self._manual_pitch_deg = 0.0
        self._drag_origin = None
        # Preview rendering is CPU-heavy. Keep it off the GUI thread and use a
        # latest-only queue so rapid audio/UI updates cannot accumulate a backlog.
        self._render_pool = QThreadPool(self)
        self._render_pool.setMaxThreadCount(1)
        self._render_signals = _VideoRenderSignals()
        self._render_signals.finished.connect(self._on_async_frame_ready)
        self._render_inflight = False
        self._render_pending = None
        self._render_generation = 0
        self.setMouseTracking(True)

    def _request_async_frame(self, width=None, height=None, export=None):
        """Schedule a latest-only frame render; never block the Qt paint path."""
        ww = max(int(width if width is not None else self.width()), 180)
        hh = max(int(height if height is not None else self.height()), 180)
        ex = self.engine.export_mode if export is None else bool(export)
        self._render_generation += 1
        request = (ww, hh, ex, self._render_generation)
        if self._render_inflight:
            self._render_pending = request
            return
        self._render_inflight = True
        self._render_pending = None
        self._render_pool.start(_VideoRenderTask(self.engine, ww, hh, ex, request[3], self._render_signals))

    def _on_async_frame_ready(self, frame, width, height, generation):
        self._render_inflight = False
        # Ignore stale frames if a newer request was made while rendering.
        if frame is not None and int(generation) == int(self._render_generation):
            self._frame = frame
            try:
                self.engine.ingest_video_frame_stats(*self.engine.frame_stats(frame))
            except Exception:
                pass
            self.update()
        pending = self._render_pending
        self._render_pending = None
        if pending is not None:
            ww, hh, ex, gen = pending
            self._render_inflight = True
            self._render_pool.start(_VideoRenderTask(self.engine, ww, hh, ex, gen, self._render_signals))

    def shutdown_rendering(self):
        """Stop preview rendering before Qt destroys the viewer/signals QObject."""
        try:
            self._render_pending = None
            self._render_generation += 1
            if hasattr(self, "_render_signals") and self._render_signals is not None:
                try:
                    self._render_signals.finished.disconnect(self._on_async_frame_ready)
                except (TypeError, RuntimeError):
                    pass
            if hasattr(self, "_render_pool") and self._render_pool is not None:
                self._render_pool.clear()
                self._render_pool.waitForDone(2500)
        except Exception:
            pass
        self._render_inflight = False

    def closeEvent(self, event):
        self.shutdown_rendering()
        super().closeEvent(event)

    def _apply_manual_camera(self):
        """Apply the user camera angles in the full [-180°, +180°] range."""
        if self.engine is None:
            return
        self.engine._manual_yaw = math.radians(float(self._manual_yaw_deg))
        self.engine._manual_pitch = math.radians(float(self._manual_pitch_deg))

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self._drag_origin = event.position()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._drag_origin is not None and (event.buttons() & Qt.MouseButton.LeftButton):
            pos = event.position()
            dx = float(pos.x() - self._drag_origin.x())
            dy = float(pos.y() - self._drag_origin.y())
            # 360° across two viewer widths/heights; clamped exactly to +/-180°.
            self._manual_yaw_deg = float(np.clip(self._manual_yaw_deg + dx * 0.5, -180.0, 180.0))
            self._manual_pitch_deg = float(np.clip(self._manual_pitch_deg + dy * 0.5, -180.0, 180.0))
            self._drag_origin = pos
            self._apply_manual_camera()
            ww = max(self.width(), 180); hh = max(self.height(), 180)
            self._request_async_frame(ww, hh, False)
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self._drag_origin = None
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self._manual_yaw_deg = 0.0
            self._manual_pitch_deg = 0.0
            self._apply_manual_camera()
            ww = max(self.width(), 180); hh = max(self.height(), 180)
            self._request_async_frame(ww, hh, False)
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def update_from_audio(self, wave_data, playhead=None):
        if self.engine.app is None and self.parent() is not None:
            self.engine.bind_app(self.parent())
        self.engine.set_waveform(wave_data, playhead=playhead)
        if isinstance(wave_data, np.ndarray) and wave_data.size:
            self.scope_wave = np.resize(wave_data.astype(np.float32), 100)
        ww = max(self.width(), 180)
        hh = max(self.height(), 180)
        # Live preview only — oscilloscope/FFT are separate widgets, not composited here.
        # Render asynchronously and coalesce rapid updates to the newest frame.
        self._request_async_frame(ww, hh, False)

    def set_mode(self, mode_idx):
        self.engine.mode = int(mode_idx)
        ww = max(self.width(), 180)
        hh = max(self.height(), 180)
        self._request_async_frame(ww, hh, False)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        ww = max(self.width(), 8)
        hh = max(self.height(), 8)
        if self._frame is None or self._frame.shape[1] != ww or self._frame.shape[0] != hh:
            self._request_async_frame(ww, hh, self.engine.export_mode)

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        if self._frame is not None:
            fh, fw = self._frame.shape[:2]
            qimg = QImage(self._frame.data, fw, fh, fw * 3, QImage.Format.Format_RGB888)
            painter.drawImage(self.rect(), qimg.copy())
        painter.setPen(QColor("#c8a2ff"))
        painter.setFont(QFont("Segoe UI", 8, QFont.Weight.Bold))
        painter.drawText(8, 14, "MEUM SCENOGRAPH")
        # Live HUD: seed list + active canonicals + ensemble (mirrors audio goals)
        try:
            snap = self.engine._live_snap() if self.engine else {}
        except Exception:
            snap = {}
        flags = []
        for k, label in (("seeded", "SEED"), ("euclid", "EUCL"), ("phase_lock", "PHASE"),
                         ("randomizer", "RAND"), ("goava", "GOAVA")):
            if snap.get(k):
                flags.append(label)
        seed_list = snap.get("seed_list") or []
        hud_y = 28
        painter.setFont(QFont("Segoe UI", 7))
        if flags:
            painter.setPen(QColor(200, 170, 255, 220))
            painter.drawText(8, hud_y, " · ".join(flags))
            hud_y += 12
        if seed_list:
            painter.setPen(QColor(180, 255, 220, 210))
            preview = ", ".join(f"{v:.3g}" for v in seed_list[:5])
            if len(seed_list) > 5:
                preview += "…"
            painter.drawText(8, hud_y, f"seed [{preview}]")
            hud_y += 12
        ens = int(snap.get("ensemble") or getattr(self.engine, "n", 0) or 0)
        if ens:
            painter.setPen(QColor(160, 200, 255, 200))
            painter.drawText(8, hud_y, f"ensemble {ens} · RMS {getattr(self.engine, '_rms', 0):.3f}")
            hud_y += 11
        # Composition readout (fractal / GOAVA seed count / OT / mode) — N-independent identity
        try:
            for line in (self.engine.composition_readout_lines() if self.engine else [])[:5]:
                painter.setPen(QColor(170, 230, 255, 210))
                painter.drawText(8, hud_y, str(line)[: max(20, self.width() // 6)])
                hud_y += 11
        except Exception:
            pass
        if snap.get("live_dj_goava") or snap.get("live_dj_random"):
            dj_labels = []
            if snap.get("live_dj_goava"):
                dj_labels.append("GOAVA DJ")
            if snap.get("live_dj_random"):
                dj_labels.append("PARAM DJ")
            painter.setPen(QColor(255, 220, 150, 230))
            painter.drawText(8, hud_y, f"DJ {' + '.join(dj_labels)} · pair #{int(snap.get('live_dj_pair_index', 0)) + 1}/1128")
        # Seed-list radial ticks around the origin (visual analogue of list[i])
        if seed_list and self.width() > 40 and self.height() > 40:
            cx, cy = self.width() * 0.5, self.height() * 0.5
            mx = max(abs(v) for v in seed_list) or 1.0
            for i, v in enumerate(seed_list[:12]):
                ang = (i / max(len(seed_list[:12]), 1)) * math.tau + float(getattr(self.engine, "t", 0.0)) * 0.5
                rr = min(self.width(), self.height()) * (0.5 + 0.5 * abs(v) / mx)
                x = cx + math.cos(ang) * rr
                y = cy + math.sin(ang * MEUM_INV) * rr * 0.5
                col = QColor.fromHsv(int(abs(v) * 0.5) % 360, 180, 230, 200)
                painter.setPen(QPen(col, 2))
                painter.drawEllipse(int(x - 2), int(y - 2), 4, 4)

class ModulationMatrixWidget(QFrame):
    def __init__(self):
        super().__init__()
        self.setFrameStyle(QFrame.Shape.StyledPanel | QFrame.Shadow.Sunken)
        layout = QGridLayout(self)

        layout.addWidget(QLabel("<b>Virtual Patch Matrix</b>"), 0, 0, 1, 4)
        layout.addWidget(QLabel("Source"), 1, 0)
        layout.addWidget(QLabel("Destination"), 1, 1)
        layout.addWidget(QLabel("Amount"), 1, 2)

        # Create 4 patch cables
        self.patches = []
        for i in range(4):
            source_combo = QComboBox()
            source_combo.addItems(["None", "X Coordinate", "Y Coordinate", "Z Coordinate", "LFO 1", "Step Sequencer"])

            dest_combo = QComboBox()
            dest_combo.addItems(["None", "Filter Cutoff", "Resonance", "Wave Drive", "Delay Time", "Delay Feedback", "Pitch Node"])

            amount_spin = QDoubleSpinBox()
            amount_spin.setRange(-1.0, 1.0)
            amount_spin.setSingleStep(0.01)
            amount_spin.setValue(0.5)

            layout.addWidget(source_combo, i+2, 0)
            layout.addWidget(dest_combo, i+2, 1)
            layout.addWidget(amount_spin, i+2, 2)

            self.patches.append({"source": source_combo, "dest": dest_combo, "amount": amount_spin})
