FREQUENCY_432HZ = 432.0
class StandardSynthInstance:
    """
    Standard synth voice with Meum Phase/AM/FM/PM modulation.
    """

    def __init__(self, freq, sr):
        self.freq = float(freq)
        self.sr = float(sr)

        self.phase = 0.0
        self.life = 100

        self.meum = MeumModulatedOscillator(
            sample_rate=self.sr,
            frequency=self.freq,
        )

        self.meum_params = {}

    # ------------------------------------------------------------------
    # MODULATION CONFIGURATION
    # ------------------------------------------------------------------

    def configure_meum_modulation(
        self,
        params=None,
    ):
        if not isinstance(params, dict):
            self.meum_params = {}
        else:
            self.meum_params = dict(params)

        self.meum.set_params(
            self.meum_params
        )

        return self

    # ------------------------------------------------------------------
    # RENDER
    # ------------------------------------------------------------------

    def render_block(
        self,
        num_samples,
        x,
        y,
        z,
    ):
        """
        Preserve the original x/y behavior while routing synthesis
        through the Meum oscillator.
        """

        x = float(x)
        y = float(y)

        # Preserve existing frequency mapping.
        carrier_frequency = (
            self.freq
            * (
                0.8
                + abs(x) * 0.4
            )
        )

        amplitude = (
            0.3
            * max(0.0, y)
        )

        self.meum.frequency = (
            carrier_frequency
        )

        self.meum.sample_rate = (
            self.sr
        )

        buffer = self.meum.render(
            num_samples,
            amplitude=amplitude,
        )

        # Maintain compatibility with code
        # that reads self.phase.
        self.phase = (
            self.meum.phase
        )

        self.life -= 1

        return buffer.tolist()

    # ------------------------------------------------------------------
    # RESET
    # ------------------------------------------------------------------

    def reset(self):
        self.phase = 0.0
        self.life = 100

        self.meum.reset_phase()

        return self
class AdditiveSynthInstance(StandardSynthInstance):

    def render_block(self, num_samples, x, y, z):
        if not hasattr(self, "meum"):
            self.meum = MeumModulatedOscillator(
                sample_rate=self.sr,
                frequency=self.freq,
            )

        self.meum.sample_rate = self.sr
        self.meum.frequency = self.freq

        if hasattr(self, "meum_params"):
            self.meum.set_params(
                self.meum_params
            )

        n = int(num_samples)
        out = np.zeros(
            n,
            dtype=np.float32,
        )

        harmonics = (
            1.0,
            2.0,
            3.5,
            4.0,
            6.0,
        )

        # Independent phase per partial so FM/PM/AM + complex waveforms
        # (saw/square/triangle) are not destroyed by shared phase advance.
        base_phase = float(self.meum.phase)
        base_index = int(self.meum.sample_index)
        original_frequency = float(self.meum.frequency)

        for hi, harmonic in enumerate(harmonics):
            self.meum.frequency = original_frequency * harmonic
            # Restore carrier phase state so each partial starts aligned
            self.meum.phase = base_phase * harmonic
            self.meum.sample_index = base_index

            partial = self.meum.render(
                n,
                amplitude=(
                    0.15
                    * max(0.0, float(y))
                    / max(1.0, math.sqrt(harmonic))
                ),
            )

            out += partial

        self.meum.frequency = original_frequency
        # Advance fundamental phase by one block for continuity
        self.meum.phase = base_phase + (
            math.tau * original_frequency * n / max(self.sr, 1.0)
        )
        self.meum.sample_index = base_index + n
        self.phase = self.meum.phase

        self.life -= 1

        return out.tolist()

class FormantSynthInstance(StandardSynthInstance):

    def render_block(self, num_samples, x, y, z):

        if not hasattr(self, "meum"):
            self.meum = MeumModulatedOscillator(
                sample_rate=self.sr,
                frequency=self.freq,
            )

        self.meum.sample_rate = self.sr

        if hasattr(self, "meum_params"):
            self.meum.set_params(
                self.meum_params
            )

        n = int(num_samples)

        carrier_frequency = max(
            1.0,
            self.freq
            * (
                0.5
                + abs(float(x)) * 0.5
            ),
        )

        self.meum.frequency = (
            carrier_frequency
        )

        carrier = self.meum.render(
            n,
            amplitude=(
                0.25
                * max(0.0, float(y))
            ),
        )

        # Second resonant/formant component.
        formant = MeumModulatedOscillator(
            sample_rate=self.sr,
            frequency=max(
                1.0,
                carrier_frequency
                * max(0.5, abs(float(x)) * 3.0),
            ),
        )

        formant.set_params(
            getattr(
                self,
                "meum_params",
                {},
            )
        )

        formant_audio = formant.render(
            n,
            amplitude=(
                0.12
                * max(0.0, float(y))
            ),
        )

        out = (
            np.asarray(carrier)
            + np.asarray(formant_audio)
        )

        self.phase = self.meum.phase

        self.life -= 1

        return out.tolist()

class DeterministicNoiseInstance(StandardSynthInstance):
    """Hash-derived noise processor; deterministic for the same seed/state.

    NO_INCREMENT_2026: the noise value is a pure function H(parameters,
    absolute_sample_index). The block base is advanced once per block (not per
    sample), so generating identical absolute samples anywhere yields the same
    number — no accumulated counter rides along in the generator itself.
    """
    def render_block(self, num_samples, x, y, z):
        buf = []
        base = int(getattr(self, "_noise_index", 0))
        for i in range(num_samples):
            # Deterministic noise is a hash-derived value, not process RNG.
            # The absolute sample index prevents block-boundary repetition
            # without any per-sample incrementation.
            key = deterministic_u64("noise", self.freq, self.sr, x, y, z, base + i)
            noise = ((key / 18446744073709551615.0) * 2.0) - 1.0
            val = noise * 0.0 * abs(x) * max(0.0, y)
            buf.append(val)
        self._noise_index = base + num_samples
        self.life -= 1
        self._meum_phase = 0.0
        self._meum_sample_index = 0
        return buf
