    def _refresh_live_dj_pair(self):
        """Choose one canonical unordered sound pair and expose its stable ID."""
        names = list(getattr(self, "instrument_names_48", []) or [])
        active = []
        for name in names:
            mem = (getattr(self, "instrument_sequencer_memory", {}) or {}).get(name, {})
            steps = mem.get("steps", []) if isinstance(mem, dict) else []
            if any(bool(x) for x in steps):
                active.append(names.index(name))
            if len(active) >= 2:
                break
        if len(active) < 2:
            active = [0, 1]
        self._live_dj_pair_space = CommutativePairSpace(len(names) if len(names) >= 2 else 2)
        desc = self._live_dj_pair_space.descriptor(active[0], active[1])
        self._live_dj_pair_ids = (desc.a, desc.b)
        self._live_dj_pair_index = int(desc.index)
        self._live_dj_pair_signature = int(desc.signature)
        if not hasattr(self, "_live_dj_engine") or self._live_dj_engine is None:
            self._live_dj_engine = LiveDJEffects(sample_rate=int(getattr(self, "play_sample_rate", TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE))
        self._live_dj_engine.pair_space = self._live_dj_pair_space
        self._live_dj_engine.set_context(seed=self.get_numeric_seed(), pair=self._live_dj_pair_ids, sample_rate=int(getattr(self, "play_sample_rate", TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE))

    def _live_dj_status(self):
        labels = []
        if getattr(self, "live_dj_goava", False):
            labels.append("GOAVA DJ")
        if getattr(self, "live_dj_random", False):
            labels.append("PARAM DJ")
        return " + ".join(labels) if labels else "OFF"

    def _on_live_dj_goava_toggled(self, checked):
        self.live_dj_goava = bool(checked)
        self.live_dj_goava_amount = 0.72 if checked else 0.0
        self._refresh_live_dj_pair()
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"🎛 LIVE DJ · {self._live_dj_status()} · pair #{self._live_dj_pair_index + 1}")

    def _on_live_dj_random_toggled(self, checked):
        self.live_dj_random = bool(checked)
        self.live_dj_random_amount = 0.68 if checked else 0.0
        self._refresh_live_dj_pair()
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"🎛 LIVE DJ · {self._live_dj_status()} · pair #{self._live_dj_pair_index + 1}")

    def _dj_row_samples(self, bpm, sr):
        """Row length in samples, measured in BEATS (master canonicals / user).

        SEQUENCE_SCALE_2026: the playlist row interval is a beat count, so the
        DJ lattice must slice rows the same way the render scheduler does:
        row_samples = sr · beats_per_row · seconds_per_beat. Any step length
        (16 vs 32 …) shares the same row wall-clock, so the DJ follows the
        same note-event lattice as audio/video/scenograph output.
        """
        try:
            if hasattr(self, "spin_row_beats"):
                beats_per_row = float(self.spin_row_beats.value())
            elif hasattr(self, "spin_playlist_beats"):
                beats_per_row = float(self.spin_playlist_beats.value())
            else:
                beats_per_row = 4.0
        except Exception:
            beats_per_row = 16.0
        return max(1, int(float(sr) * (60.0 / positive_bpm(bpm)) * max(0.002, min(64.0, beats_per_row))))

    def _media_carrier_energy(self, cursor_samples, sr):
        """Row energy (0..1) of the imported WAV/video carrier, or None.

        LIVE_DJ_MEDIA_2026: when a media carrier is loaded, the DJ responds to
        it — the per-row scalar blends the canonical note-event lattice with the
        carrier's actual energy at that row, so imported media drives the morph.
        """
        wave = getattr(self, "imported_waveform", None)
        if wave is None or not getattr(wave, "size", 0):
            return None
        try:
            arr = np.asarray(wave, dtype=np.float32).ravel()
            if arr.size == 0:
                return None
            row_samples = self._dj_row_samples(
                float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0,
                float(sr or TARGET_SAMPLE_RATE),
            )
            a = int(cursor_samples) % max(1, arr.size)
            b = min(arr.size, a + max(1, row_samples))
            seg = arr[a:b]
            return float(np.clip(float(np.sqrt(float(np.mean(seg.astype(np.float64) ** 2)) + 1e-12)) * 6.0, 0.0, 1.0))
        except Exception:
            return None

    def _live_dj_goava_scalar(self, cursor):
        events = getattr(self, "goava_note_events", []) or []
        if not events:
            return float(getattr(self, "get_numeric_seed", lambda: 0.0)())
        try:
            bpm = float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0
            sr = float(getattr(self, "play_sample_rate", TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE)
            row_samples = self._dj_row_samples(bpm, sr)
            ev = events[min(len(events) - 1, max(0, int(cursor) // row_samples))]
            scalar = float(ev.get("raw", ev.get("seed", 0.0)) or 0.0)
            # LIVE_DJ_MEDIA_2026: imported WAV/video drives the morph too.
            try:
                media_e = self._media_carrier_energy(cursor, sr)
                if media_e is not None:
                    # Energy-shaped proportional wobble keeps the scalar's own
                    # numerical scale; media simply steers the morph with its
                    # content instead of an auxiliary constant.
                    scalar = scalar + ((media_e - 0.5) * 2.0) * abs(float(scalar) + 1e-9) * 0.35
            except Exception:
                pass
            return scalar
        except Exception:
            return float(events[0].get("raw", events[0].get("seed", 0.0)) or 0.0)

    def _bake_dj_write(self, master, sample_rate):
        """Deterministic full-buffer DJ write for offline masters.

        When a DJ effect is enabled it must write onto the final file and the
        audio/video/scenograph outputs, not just the live bus.  This re-uses the
        exact live engine + context (amounts, numeric seed, commutative pair) and
        tracks the GOAVA scalar along the same note-event lattice the live cursor
        uses (row-indexed slices, start_sample = absolute position), so an exported
        file/video carries the same DJ character the live audio thread writes.
        Pure processing, zero RNG: disabling the DJ or re-rendering with identical
        state is bit-identical to before.
        """
        if not (getattr(self, "live_dj_goava", False) or getattr(self, "live_dj_random", False)):
            return master
        engine = getattr(self, "_live_dj_engine", None)
        if engine is None:
            return master
        try:
            engine.amount_goava = float(getattr(self, "live_dj_goava_amount", 0.0))
            engine.amount_random = float(getattr(self, "live_dj_random_amount", 0.0))
            _bj = getattr(self, "_live_dj_boost", None)
            if _bj:
                engine.set_boost(_bj["interval"], _bj["phase"], _bj["amount"])
            else:
                engine.set_boost(0)
            engine.set_context(
                seed=self.get_numeric_seed(),
                pair=getattr(self, "_live_dj_pair_ids", (0, 1)),
                sample_rate=int(sample_rate or TARGET_SAMPLE_RATE),
            )
            bpm = float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0
            events = getattr(self, "goava_note_events", []) or []
            arr = np.asarray(master, dtype=np.float32)
            n = int(arr.size)
            if n == 0:
                return master
            if not events:
                scalar = float(self.get_numeric_seed() if hasattr(self, "get_numeric_seed") else 0.0)
                return engine.process(arr, start_sample=0, goava_scalar=scalar, bpm=bpm)
            row_samples = self._dj_row_samples(bpm, sample_rate)
            scalars = np.asarray(
                [float(ev.get("raw", ev.get("seed", 0.0)) or 0.0) for ev in events],
                dtype=np.float32,
            )
            media_rows = None
            if getattr(self, "imported_waveform", None) is not None:
                media_rows = np.zeros(max(1, int(n // row_samples) + 1), dtype=np.float32)
                for r_i in range(media_rows.size):
                    seg = arr[r_i * row_samples:(r_i + 1) * row_samples]
                    if seg.size:
                        media_rows[r_i] = float(np.sqrt(float(np.mean(seg.astype(np.float64) ** 2)) + 1e-12))
            out = np.empty(n, dtype=np.float32)
            pos = 0
            row = 0
            while pos < n:
                seg_len = min(row_samples, n - pos)
                sc = float(scalars[min(row, len(scalars) - 1)])
                # LIVE_DJ_MEDIA_2026: imported WAV/video steers the morph with
                # its per-row energy (normalized after a 6× gain, like live).
                if media_rows is not None:
                    me = float(media_rows[min(row, media_rows.size - 1)])
                    sc = sc + (max(0.0, min(1.0, me * 6.0)) - 0.5) * 1.0 * abs(sc + 1e-9)
                out[pos:pos + seg_len] = engine.process(
                    arr[pos:pos + seg_len], start_sample=pos, goava_scalar=sc, bpm=bpm
                )
                pos += seg_len
                row += 1
            return out
        except Exception as exc:
            print(f"[LiveDJ] offline bake skipped: {exc}")
            return master

    def _apply_live_dj_chunk(self, chunk, start_sample):
        """Realtime-only DJ transform; composition stays canonical, exports/video
        pick the same write up via _bake_dj_write at materialization time."""
        if not (getattr(self, "live_dj_goava", False) or getattr(self, "live_dj_random", False)):
            return chunk
        try:
            self._live_dj_engine.amount_goava = float(getattr(self, "live_dj_goava_amount", 0.0))
            self._live_dj_engine.amount_random = float(getattr(self, "live_dj_random_amount", 0.0))
            _bj = getattr(self, "_live_dj_boost", None)
            if _bj:
                self._live_dj_engine.set_boost(_bj["interval"], _bj["phase"], _bj["amount"])
            else:
                self._live_dj_engine.set_boost(0)
            self._live_dj_engine.set_context(seed=self.get_numeric_seed(), pair=getattr(self, "_live_dj_pair_ids", (0, 1)), sample_rate=int(getattr(self, "play_sample_rate", TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE))
            bpm = float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0
            scalar = self._live_dj_goava_scalar(start_sample)
            return self._live_dj_engine.process(np.asarray(chunk, dtype=np.float32), start_sample=int(start_sample), goava_scalar=scalar, bpm=bpm)
        except Exception as exc:
            print(f"[LiveDJ] chunk skipped: {exc}")
            return chunk

    def _live_canonical_offset_and_effects(self, playhead_frac=0.0):
        """Live canonical engines: nudge playlist offsets + per-synth effect params.

        CRITICAL: modulate from frozen *baselines* captured at first call / engine
        toggle. Never multiply the already-modulated value each UI tick — that
        random-walked drive/rates/offsets into extremes and reintroduced the
        "starts clean, then sawtooth/erroneous over time" failure mode.
        """
        if not getattr(self, "is_playing", False):
            return
        active = set()
        for attr, key in (
            ("btn_local_randomize", "randomizer"),
            ("btn_local_phase_lock", "phase_lock"),
            ("btn_idealize_rhythm", "euclidean"),
            ("btn_seeded_randomize", "seeded"),
        ):
            btn = getattr(self, attr, None)
            if btn is not None and btn.isChecked():
                active.add(key)
        if not active and not getattr(self, "goava_active", False):
            return
        try:
            seed = _safe_int_seed(self.get_numeric_seed() if hasattr(self, "get_numeric_seed") else 1)
        except Exception:
            seed = 1
        t = float(playhead_frac)
        n_eng = max(1, len(active) + (1 if getattr(self, "goava_active", False) else 0))

        # ---- baselines (frozen once per play session / until cleared) ----
        off_base = getattr(self, "_live_offset_baselines", None)
        if not isinstance(off_base, dict):
            off_base = {}
            self._live_offset_baselines = off_base
        param_base = getattr(self, "_live_param_baselines", None)
        if not isinstance(param_base, dict):
            param_base = {}
            self._live_param_baselines = param_base

        # Playlist entry offset micro-modulation from baseline
        try:
            pl = getattr(self, "master_playlist_data", None) or []
            for ri, entry in enumerate(pl):
                if not isinstance(entry, dict):
                    continue
                if entry.get("user_owned") or entry.get("user_locked"):
                    continue
                om = entry.get("operator_time_offsets")
                if not isinstance(om, dict) or not om:
                    continue
                for op_name in list(om.keys()):
                    key = (ri, str(op_name))
                    if key not in off_base:
                        off_base[key] = float(om.get(op_name, 0.0) or 0.0)
                    base = float(off_base[key])
                    phase = (seed * 0.0001 + ri * MEUM + (_stable_hash(str(op_name),1000)) * 0.01) + t * math.tau
                    depth = 0.04 / n_eng
                    if "phase_lock" in active:
                        om[op_name] = base + depth * math.sin(phase)
                    elif "euclidean" in active:
                        om[op_name] = base + depth * 0.7 * math.sin(phase * 2.0)
                    elif "randomizer" in active or "seeded" in active:
                        om[op_name] = base + depth * math.sin(phase * MEUM)
                    else:
                        om[op_name] = base
                entry["operator_time_offsets"] = om
        except Exception:
            pass

        # Live effect parametrics from baseline (oscillate, never accumulate)
        try:
            state = getattr(self, "instrument_param_state", {}) or {}
            for i, name in enumerate(list(getattr(self, "instrument_names_48", []) or [])):
                if hasattr(self, "_instrument_has_net_effect") and self._instrument_has_net_effect(name):
                    continue
                pst = state.get(name)
                if not isinstance(pst, dict):
                    continue
                if name not in param_base:
                    param_base[name] = {
                        "drive": float(pst.get("drive", 0.0) or 0.0),
                        "am_rate": float(pst.get("am_rate", 1.0) or 1.0),
                        "pm_rate": float(pst.get("pm_rate", 1.0) or 1.0),
                        "fm_rate": float(pst.get("fm_rate", 1.0) or 1.0),
                        "filter": float(pst.get("filter", 0.0) or 0.0),
                        "am_depth": float(pst.get("am_depth", 1.0) or 1.0),
                        "pm_depth": float(pst.get("pm_depth", 1.0) or 1.0),
                    }
                b = param_base[name]
                phase = (seed * 0.001 + i * PHI_INV + t * math.tau * (1.0 + 0.1 * i))
                if "randomizer" in active or "seeded" in active:
                    pst["drive"] = float(np.clip(b["drive"] * (0.5 + 0.5  * (0.5 + 0.5 * math.sin(phase))), 0.0, 1.0))
                    pst["am_rate"] = float(max(0.05, b["am_rate"] * (0.5 + 0.5  * math.sin(phase * 1.0))))
                if "phase_lock" in active:
                    pst["pm_rate"] = float(max(0.05, b["pm_rate"] * (0.5 + 0.5  * math.cos(phase))))
                    pst["filter"] = float(np.clip(b["filter"] * (0.5 + 0.5  * math.sin(phase * MEUM)), 0.0, 1.0))
                if "euclidean" in active:
                    pst["fm_rate"] = float(max(0.05, b["fm_rate"] * (0.5 + 0.5  * math.sin(phase * 1.0))))
                if getattr(self, "goava_active", False) and pst.get("goava_sine_patch"):
                    pst["goava_mix_weight"] = 1.0 / n_eng
                    pst["am_depth"] = float(np.clip(b["am_depth"] * (0.5 + 0.5  * math.sin(phase)), 0.0, 1.0))
                    pst["pm_depth"] = float(np.clip(b["pm_depth"] * (0.5 + 0.5 * math.cos(phase)), 0.0, 1.0))
        except Exception:
            pass

    def _audio_callback(self, outdata, frames, time_info, status):
        """sounddevice stream callback — pulls from play_buffer under lock."""
        if status:
            pass  # underrun etc. ignored for now
        with self.play_lock:
            if self.play_buffer is None or not self.is_playing:
                outdata.fill(0)
                return
            remaining = len(self.play_buffer) - self.play_cursor
            n = min(frames, remaining)
            if n > 0:
                start_sample = int(self.play_cursor)
                # MASTER_HARDCLIP_2026: volume × clip-factors → hard clip only.
                # No video-energy bedding, no peak normalize, no soft limiter.
                # Default master vol 50% is the warning; hard clip is the ceiling.
                raw = self.play_buffer[start_sample:start_sample + n]
                try:
                    ratio_pct = float(self.spin_clip_ratio.value()) if hasattr(self, "spin_clip_ratio") else 50.0
                except Exception:
                    ratio_pct = 50.0
                drive = float(1.0 + 1.5 * (ratio_pct / 100.0))
                vol = float(getattr(self, "master_volume", 0.5) or 0.5)
                chunk = np.clip(raw * np.float32(vol * drive), -1.0, 1.0).astype(np.float32)
                chunk = self._apply_live_dj_chunk(chunk, start_sample)
                # Live DJ may boost; hard-clip again so no path escapes the ceiling.
                chunk = np.clip(chunk, -1.0, 1.0).astype(np.float32)
                outdata[:n, 0] = chunk
                # EQR_BAND_READOUT_2026: live peak + peak-hold numbers written by
                # the audio thread (plain floats — the labels are refreshed by the
                # UI-thread scope timer, never touched from here).
                try:
                    _cpk = float(np.max(np.abs(chunk))) if chunk.size else 0.0
                    self._live_peak = _cpk
                    _ph = float(getattr(self, "_live_peak_hold", 0.0))
                    self._live_peak_hold = max(_cpk, _ph * float(np.exp(-float(n) / max(0.0 * float(self.preferred_sample_rate), 1.0))))
                except Exception:
                    pass
                # stash a short window for the UI scope
                if n >= 100:
                    self._last_scope_chunk = chunk[::max(1, n // 100)][:100].copy()
                else:
                    pad = np.zeros(100, dtype=np.float32)
                    pad[:n] = chunk
                    self._last_scope_chunk = pad
                self.play_cursor += n
            if n < frames:
                outdata[n:, 0] = 0
            if remaining <= n:
                # Buffer exhausted: flip plain state flags only. This
                # callback runs on the sounddevice audio thread, not the Qt
                # UI thread — calling stop_playback() directly from here
                # touches QPushButton/style-sheet state from a non-UI thread,
                # which PyQt does not guarantee is safe and was leaving
                # btn_play stuck reading "⏸ PAUSE" instead of resetting to
                # "▶ PLAY" like a real Stop. The UI-thread scope timer
                # (_update_scope_from_playhead) already polls is_playing and
                # performs the actual stop_playback() on the correct thread.
                self.is_playing = False
                self._transport_finished = True
                self._composition_generation_guard = False
                return
    def _update_scope_from_playhead(self):
        """UI-thread timer: feed waveform, scenograph, and FFT spectrum during live play."""
        if not self.is_playing:
            if not getattr(self, "_stop_requested", False):
                self._transport_finished = True
            if getattr(self, "_audio_only_mode", False):
                self.stop_audio_playback()
            else:
                self.stop_playback()
            return
        if getattr(self, "_audio_only_mode", False):
            if hasattr(self, "scope_status_label"):
                total = max(1, int(getattr(self, "play_buffer", np.zeros(1)).size or 1))
                pct = int(100 * float(getattr(self, "play_cursor", 0)) / float(total))
                self.scope_status_label.setText(f"🔊 Audio Track  |  LIVE {pct}%")
            return
        # Live canonical engines: continuous offset + effect parametrics
        try:
            total = max(1, int(getattr(self, "play_buffer", np.zeros(1)).size or 1))
            frac = float(getattr(self, "play_cursor", 0)) / float(total)
            self._live_canonical_offset_and_effects(frac)
        except Exception:
            pass
        chunk = self._last_scope_chunk
        overview = None
        playhead = 0.0
        if self.play_buffer is not None and len(self.play_buffer) > 0:
            buf = self.play_buffer
            step = max(1, len(buf) // 512)
            overview = buf[::step]
            playhead = float(self.play_cursor) / float(len(buf))
            pct = int(100 * playhead)
            if hasattr(self, 'scope_status_label'):
                self.scope_status_label.setText(
                    f"📊 Meum monitors LIVE  {pct}%  ·  Vol {int(self.master_volume*100)}%"
                )
        # UI monitors: scope every tick; heavy scenograph throttled when UI lite.
        self._scope_tick_counter = int(getattr(self, "_scope_tick_counter", 0) or 0) + 1
        _lite = bool(getattr(self, "chk_ui_lite", None) and self.chk_ui_lite.isChecked())
        if isinstance(getattr(self, 'visual_oscilloscope', None), VisualOscilloscope):
            self.visual_oscilloscope.update_waveform(chunk, overview=overview, playhead=playhead)
        if hasattr(self, 'spectrum_analyzer') and self.spectrum_analyzer is not None:
            self.spectrum_analyzer.update_spectrum(chunk)
        # PERF_2026: scenograph / video viewer is the expensive paint; every 3rd tick
        # under UI lite keeps playhead feedback without constant full-frame work.
        if hasattr(self, 'video_synth_viewer'):
            if (not _lite) or (self._scope_tick_counter % 3 == 0):
                try:
                    self.video_synth_viewer.update_from_audio(chunk, playhead=playhead)
                except Exception:
                    pass
        if (not _lite) or (self._scope_tick_counter % 3 == 0):
            try:
                self._push_visualizer_seed_hud()
            except Exception:
                pass
        # EQR_Z_READOUT_2026: UI-thread refresh of the master EQR z-value
        # readout (single-point reality-tensor P·E+D) + peak-hold meter (tied
        # to the Clip/Gain report).  Offline z value comes from the last
        # render's _clip_gain_profile; the live peak hold is fed by the audio
        # callback.
        try:
            if hasattr(self, 'lbl_eqr_bands'):
                z_rel = float(getattr(self, "_eqr_z_rel", 0.0) or 0.0)
                if z_rel > 1e-9:
                    self.lbl_eqr_bands.setText(
                        f"Z {z_rel:+.3f}  (P·E+D)"
                    )
            if hasattr(self, 'lbl_peak_hold'):
                _ph = float(getattr(self, "_live_peak_hold", 0.0) or 0.0)
                _pk = float(getattr(self, "_live_peak", 0.0) or 0.0)
                _db = 20.0 * math.log10(max(max(_ph, _pk), 1e-9)) if max(_ph, _pk) > 1e-9 else -120.0
                self.lbl_peak_hold.setText(f"{_db:.1f} dBFS  (hold {100.0 * _ph:.0f}%)" if _ph > 1e-9 else f"{max(_db, -120.0):.1f} dBFS")
        except Exception:
            pass


    def _live_preview_max_rows(self):
        """PERF_2026: optional row cap for live Play only (export stays full).

        spin_preview_rows == 0 → None (full playlist).
        Otherwise clamp to [1, current playlist length].
        """
        try:
            n = int(self.spin_preview_rows.value()) if hasattr(self, "spin_preview_rows") else 0
        except Exception:
            n = 0
        if n <= 0:
            return None
        try:
            plen = int(self.spin_playlist_length.value()) if hasattr(self, "spin_playlist_length") else 64
        except Exception:
            plen = 64
        return max(1, min(int(n), max(1, plen)))

    def toggle_playback(self):
        """Unified PLAY/PAUSE/RESUME transport over the rendered audiovisual data stream."""
        # AUDIO_ONLY_CROSS_DEACTIVATE: audiovisual play always wins over the
        # audio-only transport.
        if getattr(self, "_audio_only_mode", False):
            self.stop_audio_playback()
        # A completed one-shot is NOT a paused stream.
        # Start a fresh transport on the next PLAY.
        if getattr(self, "_transport_finished", False):
            # Completed one-shot → fresh transport. Do not touch composition guards here.
            self.is_playing = False
            self.is_paused = False
            self.play_cursor = 0
            self._transport_finished = False
            self._stop_requested = False
            self._render_cancelled = False
        # Playing -> pause without destroying the rendered buffer/cursor.
        if self.is_playing:
            self.is_playing = False
            self.is_paused = True
            if getattr(self, 'audio_stream', None) is not None:
                try:
                    self.audio_stream.stop()
                    self.audio_stream.close()
                except Exception:
                    pass
                self.audio_stream = None
            if hasattr(self, '_scope_update_timer'):
                self._scope_update_timer.stop()
            self.btn_play.setText("▶ RESUME Audiovisual Track")
            self.btn_play.setStyleSheet(
                "QPushButton { background-color:#6b4d0b; color:#b8f7e6; border:2px solid #ffd75e; "
                "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; min-width:240px; }"
                "QPushButton:hover { background-color:#7d5c12; }"
            )
            if hasattr(self, 'scope_status_label'):
                self.scope_status_label.setText("📊 Audiovisual Track  |  PAUSED")
            return

        # Paused -> resume exactly where the audio cursor stopped.
        if self.is_paused and self.play_buffer is not None and self.play_cursor < len(self.play_buffer):
            try:
                self.is_playing = True
                self.is_paused = False
                self._audio_only_mode = False
                self._transport_finished = False
                self._play_finished_flag = False
                if HAS_SOUNDDEVICE:
                    self.audio_stream = sd.OutputStream(
                        samplerate=self.play_sample_rate, channels=1, dtype='float32',
                        callback=self._audio_callback, blocksize=1024, latency='low'
                    )
                    self.audio_stream.start()
                self.btn_play.setText("⏸ PAUSE Audiovisual Track")
                self.btn_play.setStyleSheet(
                    "QPushButton { background-color:#00aa55; color:#b8f7e6; border:2px solid #ffd166; "
                    "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; min-width:240px; }"
                    "QPushButton:hover { background-color:#00c464; }"
                )
                self._scope_update_timer.start()
                return
            except Exception as e:
                self.is_playing = False
                self.is_paused = False
                print(f"[Audio] Resume failed: {e}")

        if not HAS_SOUNDDEVICE:
            QMessageBox.warning(self, "Audio Engine", "sounddevice is not available. Install with: pip install sounddevice")
        try:
            _prev = self._live_preview_max_rows()
            if hasattr(self, 'scope_status_label'):
                if _prev is not None:
                    self.scope_status_label.setText(
                        f"📊 Rendering Audiovisual Track (preview {_prev} rows)…"
                    )
                else:
                    self.scope_status_label.setText("📊 Rendering Audiovisual Track…")
            QApplication.processEvents()
            buf, sr = self._render_mixdown_buffer(max_rows=_prev)
            with self.play_lock:
                self.play_buffer = buf
                self.play_sample_rate = sr
                self.play_cursor = 0
                self.is_playing = True
                self.is_paused = False
                self._audio_only_mode = False
                self._transport_finished = False
                self._play_finished_flag = False
            if HAS_SOUNDDEVICE:
                if self.audio_stream is not None:
                    try:
                        self.audio_stream.stop(); self.audio_stream.close()
                    except Exception:
                        pass
                self.audio_stream = sd.OutputStream(
                    samplerate=sr, channels=1, dtype='float32', callback=self._audio_callback,
                    blocksize=1024, latency='low'
                )
                self.audio_stream.start()
            self.btn_play.setText("⏸ PAUSE Audiovisual Track")
            self.btn_play.setStyleSheet("background-color: #00aa55; color: #101010; font-weight: bold;")
            self._scope_tick_counter = 0
            self._scope_update_timer.start()
            if hasattr(self, 'scope_status_label'):
                _tag = f" preview {_prev}r" if _prev is not None else ""
                self.scope_status_label.setText(f"📊 Audiovisual Track  |  LIVE{_tag}")
        except Exception as e:
            self.is_playing = False
            self.is_paused = False
            print(f"[Audio] Playback start failed: {e}")
            QMessageBox.critical(self, "Playback Error", str(e))


    def _on_nt_lattice_apply(self, checked=False):
        """Apply the ℤ-Lattice step algorithm at the selected global/local scope.

        Global mode walks every playlist row and applies the mask to each
        sequence bank referenced by that row. Local mode touches only the
        currently selected instrument/pattern. Snapshots are keyed by the same
        scope so Unapply reverses exactly the affected material.
        """
        import copy as _c
        mode_map = {
            "Prime steps": "primes", "Square steps": "quadratic", "Coprime steps": "totient",
            "Square-free steps": "mobius", "Fraction steps": "farey", "Tree-ratio steps": "stern",
            "Primes": "primes", "Quadratic residues": "quadratic", "Totient units": "totient",
            "Möbius support": "mobius", "Farey": "farey", "Stern–Brocot": "stern",
        }
        mode_ui = self.combo_nt_mode.currentText() if hasattr(self, "combo_nt_mode") else "Prime steps"
        mode_alg = mode_map.get(mode_ui, "primes")
        mod = int(self.spin_nt_modulus.value()) if hasattr(self, "spin_nt_modulus") else 12
        depth = int(self.spin_nt_depth.value()) if hasattr(self, "spin_nt_depth") else 5
        is_local = bool(hasattr(self, "mode_combo") and self.mode_combo.currentIndex() == 1)
        if bool(getattr(self, "edit_algorithm_per_sequence", False)):
            is_local = True
        self._nt_lattice_scope = "local" if is_local else "global"
        if bool(getattr(self, "edit_algorithm_per_sequence", False)):
            _sel_name = str(getattr(self, "current_instrument_name", self.instrument_names_48[0] if self.instrument_names_48 else ""))
            _sel_seq = int((getattr(self, "instrument_selected_sequence", {}) or {}).get(_sel_name, 0))
            self._nt_lattice_scope = f"local_sequence:{_sel_name}:{_sel_seq}"

        def apply_mem(mem, key):
            if not isinstance(mem, dict):
                return
            prior = self._nt_lattice_snapshot.get(key)
            if prior is not None:
                return
            length = max(1, min(128, int(mem.get("pattern_length", len(mem.get("steps") or []) or 8))))
            steps = list(mem.get("steps") or [])
            amps = list(mem.get("amplitudes") or [])
            pitches = list(mem.get("pitches") or [])
            offsets = list(mem.get("offsets") or [])
            probabilities = list(mem.get("probabilities") or [])
            gates = list(mem.get("gates") or [])
            while len(steps) < length: steps.append(False)
            while len(amps) < length: amps.append(1.0)
            while len(pitches) < length: pitches.append(1.0)
            while len(offsets) < length: offsets.append(0.0)
            while len(probabilities) < length: probabilities.append(100)
            while len(gates) < length: gates.append(True)
            self._nt_lattice_snapshot[key] = {
                "steps": _c.deepcopy(steps[:length]), "amplitudes": _c.deepcopy(amps[:length]),
                "pitches": _c.deepcopy(pitches[:length]), "offsets": _c.deepcopy(offsets[:length]),
                "probabilities": _c.deepcopy(probabilities[:length]), "gates": _c.deepcopy(gates[:length]),
                "pattern_length": length,
            }
            mask = _nt_step_mask(length, mode_alg, mod, depth)
            for i in range(length):
                steps[i] = bool(mask[i])
                if steps[i]:
                    residue = i % mod
                    scramble = (residue * 7 + i * 11) % max(1, mod)
                    pitches[i] = float(np.clip(_seed_to_pitch_ratio(scramble + mod * 0.01, residue, i), 1.0/32.0, 32.0))
                    amps[i] = float(0.55 + 0.45 * abs(_nt_mobius(residue + 1)))
            mem.update({"steps": steps[:length], "amplitudes": amps[:length], "pitches": pitches[:length],
                        "offsets": offsets[:length], "probabilities": probabilities[:length],
                        "gates": gates[:length], "pattern_length": length})

        if is_local:
            name = self.instrument_selector_dropdown.currentText() if hasattr(self, "instrument_selector_dropdown") else None
            if not name:
                names = list(getattr(self, "instrument_names_48", []) or [])
                name = names[0] if names else None
            if not name:
                return
            bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name, {})
            sid = int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1))
            mem = bank.get(sid) if isinstance(bank, dict) else None
            if not isinstance(mem, dict):
                mem = (getattr(self, "instrument_sequencer_memory", {}) or {}).get(name)
            key = f"local:{name}"
            if self._nt_lattice_snapshot.get(key) is not None:
                if not getattr(self, "_undo_in_flight", False): self._push_undo("Unapply step algorithm")
                prior = self._nt_lattice_snapshot.pop(key)
                target = mem if isinstance(mem, dict) else (getattr(self, "instrument_sequencer_memory", {}) or {}).get(name)
                if isinstance(target, dict): target.update(_c.deepcopy(prior))
            else:
                if not getattr(self, "_undo_in_flight", False): self._push_undo("Apply step algorithm")
                if isinstance(mem, dict): apply_mem(mem, key)
                elif isinstance((getattr(self, "instrument_sequencer_memory", {}) or {}).get(name), dict):
                    apply_mem(self.instrument_sequencer_memory[name], key)
        else:
            global_keys = [k for k in list(self._nt_lattice_snapshot) if str(k).startswith("global:")]
            if global_keys:
                if not getattr(self, "_undo_in_flight", False): self._push_undo("Unapply step algorithm")
                for key in global_keys:
                    try:
                        _, op, sid = str(key).split(":", 2)
                        mem = (getattr(self, "instrument_sequence_banks", {}) or {}).get(op, {}).get(int(sid))
                        if isinstance(mem, dict): mem.update(_c.deepcopy(self._nt_lattice_snapshot[key]))
                    except Exception: pass
                    self._nt_lattice_snapshot.pop(key, None)
            else:
                if not getattr(self, "_undo_in_flight", False): self._push_undo("Apply step algorithm")
                touched = 0
                seen = set()
                for r, entry in enumerate(getattr(self, "master_playlist_data", []) or []):
                    if not isinstance(entry, dict): continue
                    refs = entry.get("sequence_refs") or []
                    if isinstance(refs, str): refs = [x.strip() for x in refs.split(",") if x.strip()]
                    if not refs:
                        op = str(entry.get("operator") or "").strip()
                        sid = int((getattr(self, "instrument_selected_sequence", {}) or {}).get(op, 1)) if op else 1
                        refs = [f"{op}#S{sid}"] if op else []
                    row_applied = []
                    for ref in refs:
                        txt = str(ref).strip()
                        if "#S" in txt: op, sid_txt = txt.rsplit("#S", 1)
                        elif ":" in txt: op, sid_txt = txt.rsplit(":", 1)
                        else: continue
                        op = op.strip()
                        try: sid = int(sid_txt)
                        except Exception: continue
                        key = f"global:{op}:{sid}"
                        if key in seen or key in self._nt_lattice_snapshot: continue
                        mem = (getattr(self, "instrument_sequence_banks", {}) or {}).get(op, {}).get(sid)
                        if isinstance(mem, dict):
                            apply_mem(mem, key); seen.add(key); row_applied.append(key); touched += 1
                    if row_applied:
                        entry["step_algorithm_scope"] = "global"
                        entry["step_algorithm"] = mode_ui
                        entry["step_algorithm_refs"] = row_applied
                if touched == 0:
                    # A global sequence should still reach every row; fall back to
                    # each row's operator memory when no explicit #S reference exists.
                    for r, entry in enumerate(getattr(self, "master_playlist_data", []) or []):
                        if not isinstance(entry, dict): continue
                        op = str(entry.get("operator") or "").strip()
                        if not op: continue
                        mem = (getattr(self, "instrument_sequencer_memory", {}) or {}).get(op)
                        key = f"global:{op}:1"
                        if isinstance(mem, dict) and key not in self._nt_lattice_snapshot:
                            apply_mem(mem, key); entry["step_algorithm_scope"] = "global"; entry["step_algorithm"] = mode_ui
        try:
            self._refresh_step_ui()
        except Exception: pass
        try:
            self._sync_playlist_paint_table_from_memory()
        except Exception: pass
        try: self._on_live_source_changed()
        except Exception: pass
        self._sync_nt_lattice_button_state()
        try:
            self.btn_nt_apply.setText("HEURISTIC STEP WRITE · ON" if bool(checked) else "HEURISTIC STEP WRITE · OFF")
        except Exception:
            pass

    def _heuristic_values(self, family, bias, n, seed_value=None):
        """Return deterministic [0,1] structural values for the Heuristic Composer.

        The generator intentionally uses phase/modulus/index relations rather than
        wall-clock time. That makes every family reproducible and gives the
        T-Independent bias a literal implementation rather than a UI label.
        """
        n = max(1, min(1024, int(n)))
        mod = int(self.spin_nt_modulus.value()) if hasattr(self, "spin_nt_modulus") else 12
        depth = int(self.spin_nt_depth.value()) if hasattr(self, "spin_nt_depth") else 5
        fam = str(family or "ℤ-Lattice")
        bias = str(bias or "Balanced")
        seed = _safe_int_seed(seed_value if seed_value is not None else (self.get_numeric_seed() if hasattr(self, "get_numeric_seed") else 0))
        phase0 = ((seed & 0xFFFFFFFF) / float(0x100000000)) * math.tau
        vals = []
        mode_ui = str(self.combo_nt_mode.currentText()) if hasattr(self, "combo_nt_mode") else "Prime steps"
        qr = set(_nt_quadratic_residues(max(2, mod)))
        phi_n = max(1, _nt_euler_totient(max(2, mod)))
        for i in range(n):
            k = i + 1
            residue = k % max(2, mod)
            prime = 1.0 if _nt_is_prime(k) else 0.0
            cop = 1.0 if math.gcd(k, max(2, mod)) == 1 else 0.0
            square = 1.0 if int(math.isqrt(k)) ** 2 == k else 0.0
            sqfree = 1.0 if _nt_mobius(k) != 0 else 0.0
            lattice = prime
            if "Square-free" in mode_ui: lattice = sqfree
            elif "Square" in mode_ui: lattice = square
            elif "Coprime" in mode_ui: lattice = cop
            elif "Fraction" in mode_ui: lattice = ((k * phi_n) % max(2, mod)) / float(max(1, mod - 1))
            elif "Tree-ratio" in mode_ui: lattice = ((k * (depth + 1)) % (mod + depth)) / float(max(1, mod + depth - 1))
            if fam == "ℤ-Lattice":
                v = lattice
            elif fam == "Prime / Modular":
                v = 0.55 * prime + 0.25 * cop + 0.20 * (1.0 if residue in qr else 0.0)
            elif fam == "Farey / Fraction":
                v = ((k * phi_n + depth) % (mod * max(1, depth))) / float(max(1, mod * max(1, depth) - 1))
            elif fam == "Tree / Ratio":
                a = 1 + ((k + depth) % max(2, mod))
                b = 1 + ((k * max(1, depth)) % max(2, mod))
                v = (a / float(a + b))
            elif fam == "Geometric":
                v = 0.5 + 0.5 * math.sin(phase0 + k * MEUM * PHI_INV)
            elif fam == "Harmonic":
                v = 0.5 + 0.25 * math.sin(phase0 + k * PHI) + 0.25 * math.cos(k * MEUM_NORM * math.pi)
            elif fam == "Seed Function":
                try:
                    v = float(evaluate_seed_expression_at_time(self._seed_text(), k / float(max(1, n)), canonical_context={"step": k, "span": n}))
                    v = 0.5 + 0.5 * math.tanh(v)
                except Exception:
                    v = 0.5 + 0.5 * math.sin(phase0 + k * MEUM)
            else:  # Hybrid
                g = 0.5 + 0.5 * math.sin(phase0 + k * MEUM * PHI_INV)
                v = 0.40 * lattice + 0.25 * cop + 0.20 * g + 0.15 * (1.0 if residue in qr else 0.0)
            v = float(np.clip(v, 0.0, 1.0))
            if bias == "Sparse":
                v = v * v
            elif bias == "Dense":
                v = math.sqrt(v)
            elif bias == "Self-Similar":
                motif = max(2, min(n, 2 ** max(1, int(math.log2(max(2, depth + 1))))))
                mphase = ((i % motif) + 1) / float(motif)
                v = 0.60 * v + 0.40 * (0.5 + 0.5 * math.sin(math.tau * mphase + phase0))
            elif bias == "T-Independent":
                # No absolute t: residue/phase class only.
                v = 0.55 * v + 0.45 * (((residue * phi_n + depth) % max(2, mod)) / float(max(1, mod - 1)))
            vals.append(float(np.clip(v, 0.0, 1.0)))
        return vals

    def _transcribe_heuristic_into_sequence(self, name, sid, values, family, bias):
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(name, {})
        mem = bank.get(int(sid))
        if not isinstance(mem, dict):
            mem = copy.deepcopy((getattr(self, "instrument_sequencer_memory", {}) or {}).get(name, {}))
            bank[int(sid)] = mem
        n = max(1, len(values))
        self._ensure_seq_mem_length(mem, n)
        threshold = 0.58
        if bias == "Sparse": threshold = 0.70
        elif bias == "Dense": threshold = 0.42
        elif bias in ("Self-Similar", "T-Independent"): threshold = 0.52
        steps = [bool(v >= threshold) for v in values]
        if not any(steps):
            steps[max(range(n), key=lambda i: values[i])] = True
        mem["steps"] = steps
        mem["gates"] = [True] * n
        mem["amplitudes"] = [float(0.20 + 0.80 * v) for v in values]
        mem["pitches"] = [float(np.clip(2.0 ** ((v - 0.5) * 2.0), 1.0 / 32.0, 32.0)) for v in values]
        mem["probabilities"] = [int(np.clip(round(35.0 + 65.0 * v), 1, 100)) for v in values]
        mem["offsets"] = [float((v - 0.5) * 0.5) for v in values]
        mem["pattern_length"] = n
        mem["heuristic_family"] = str(family)
        mem["heuristic_bias"] = str(bias)
        mem["canonical_owner"] = "heuristic:transcribed"
        self.instrument_sequencer_memory[name] = mem
        self.instrument_selected_sequence[name] = int(sid)
        # Continuous heuristic state becomes a real editable automation lane.
        self._bake_automation_pattern_to_tiles(
            [100.0 * float(v) for v in values],
            pattern_name=f"Heuristic · {family} · {bias}", activate=True,
            instrument_name=name, sequence_id=int(sid)
        )
        return mem

    def _heuristic_target_list(self, scope=None):
        scope = str(scope if scope is not None else (self.combo_heuristic_scope.currentText() if hasattr(self, "combo_heuristic_scope") else "LOCAL")).upper()
        targets = []
        if scope == "GLOBAL":
            for name in list(getattr(self, "instrument_names_48", []) or []):
                bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name, {})
                if isinstance(bank, dict) and bank:
                    for sid in sorted(int(x) for x in bank.keys()): targets.append((name, sid))
                else:
                    targets.append((name, int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1))))
        else:
            name = str(self.instrument_selector_dropdown.currentText()) if hasattr(self, "instrument_selector_dropdown") else (list(getattr(self, "instrument_names_48", []) or ["Operator"])[0])
            sid = int(self.sequence_selector.currentData() or 1) if hasattr(self, "sequence_selector") and self.sequence_selector.currentData() is not None else int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1))
            targets = [(name, sid)]
        return targets

    def _heuristic_restore(self):
        """Remove only the currently-applied heuristic writer layer."""
        snap = getattr(self, "_heuristic_writer_snapshot", None)
        if not isinstance(snap, dict): return
        for key, prior in (snap.get("memories") or {}).items():
            try:
                name, sid = key
                bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(name, {})
                bank[int(sid)] = copy.deepcopy(prior)
                if int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1)) == int(sid):
                    self.instrument_sequencer_memory[name] = bank[int(sid)]
            except Exception: pass
        # Restore only automation scopes touched by this writer; unrelated/user
        # automation survives regardless of toggle order.
        scopes = set(tuple(x) for x in (snap.get("scopes") or []))
        current = []
        for point in list(getattr(self, "sequencer_automation_points", []) or []):
            if not isinstance(point, dict): continue
            sc=(str(point.get("from_instrument") or point.get("instrument") or ""), int(point.get("from_sequence", 1) or 1))
            if sc in scopes: continue
            current.append(point)
        current.extend(copy.deepcopy(snap.get("automation") or []))
        self.sequencer_automation_points = current
        self._heuristic_writer_snapshot = None

    def _on_heuristic_scope_changed(self, _index=0):
        if not hasattr(self, "btn_heuristic_transcribe") or not self.btn_heuristic_transcribe.isChecked(): return
        # Scope is mutually exclusive. Rebuild from the exact zero-state of the
        # previous scope rather than stacking GLOBAL and LOCAL writes.
        self._heuristic_restore()
        self._heuristic_apply_current_scope()

    def _heuristic_apply_current_scope(self):
        family = str(self.combo_heuristic_family.currentText()) if hasattr(self, "combo_heuristic_family") else "ℤ-Lattice"
        bias = str(self.combo_heuristic_bias.currentText()) if hasattr(self, "combo_heuristic_bias") else "Balanced"
        n = int(self.spin_heuristic_span.value()) if hasattr(self, "spin_heuristic_span") else 16
        scope = str(self.combo_heuristic_scope.currentText()) if hasattr(self, "combo_heuristic_scope") else "LOCAL"
        targets = self._heuristic_target_list(scope)
        values = self._heuristic_values(family, bias, n)
        memories={}; scopes=[]; automation=[]
        all_points=list(getattr(self, "sequencer_automation_points", []) or [])
        for name,sid in targets:
            bank=(getattr(self,"instrument_sequence_banks",{}) or {}).setdefault(name,{})
            mem=bank.get(int(sid))
            if not isinstance(mem,dict): mem=copy.deepcopy((getattr(self,"instrument_sequencer_memory",{}) or {}).get(name,{})); bank[int(sid)]=mem
            memories[(name,int(sid))]=copy.deepcopy(mem); scopes.append((name,int(sid)))
            for point in all_points:
                if not isinstance(point,dict): continue
                sc=(str(point.get("from_instrument") or point.get("instrument") or ""), int(point.get("from_sequence",1) or 1))
                if sc==(name,int(sid)): automation.append(copy.deepcopy(point))
        self._heuristic_writer_snapshot={"scope":scope,"memories":memories,"scopes":scopes,"automation":automation}
        for idx,(name,sid) in enumerate(targets):
            vv=list(values)
            if idx and vv:
                rot=int(identity_unit(name,"heuristic_rotation")*len(vv))%len(vv); vv=vv[rot:]+vv[:rot]
            self._transcribe_heuristic_into_sequence(name,sid,vv,family,bias)
        if hasattr(self,"scope_status_label"):
            self.scope_status_label.setText(f"Heuristic {scope} ON · {family} · {bias} · {len(targets)} sequence(s) · {n} steps")

    def _on_heuristic_transcribe(self, checked=False):
        """True reversible heuristic writer toggle: ON adds one derived layer; OFF removes it."""
        if not getattr(self, "_undo_in_flight", False): self._push_undo("Toggle heuristic writer")
        if bool(checked):
            self._heuristic_restore()  # protects against stale prior application
            self._heuristic_apply_current_scope()
            self.btn_heuristic_transcribe.setText(f"HEURISTIC WRITE · {self.combo_heuristic_scope.currentText()} · ON")
        else:
            self._heuristic_restore()
            self.btn_heuristic_transcribe.setText("HEURISTIC WRITE · OFF")
            if hasattr(self,"scope_status_label"): self.scope_status_label.setText("Heuristic writer OFF · zero-state restored")
        try: self.reload_active_instrument_sequencer_ui()
        except Exception: pass
        try: self._refresh_sequencer_automation_row()
        except Exception: pass
        try: self._canonical_write_sequence_runtime()
        except Exception: pass
        try: self._on_live_source_changed()
        except Exception: pass

    def _on_nt_to_seed(self):
        """Emit a seed script that number-theorists will recognize as structured.

        The prior seed is kept on the seed-revert history and on the project
        undo stack, so "Algorithm → Seed" is fully reversible.
        """
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Algorithm → Seed")
        mod = int(self.spin_nt_modulus.value()) if hasattr(self, "spin_nt_modulus") else 12
        depth = int(self.spin_nt_depth.value()) if hasattr(self, "spin_nt_depth") else 5
        phi = _nt_euler_totient(mod)
        mu = _nt_mobius(mod)
        qr = _nt_quadratic_residues(mod)
        qr_s = ", ".join(str(x) for x in qr[:12])
        # Time-varying script using φ(n), μ(n), and Meum
        script = (
            f"# NT seed · n={mod} φ={phi} μ={mu}\\n"
            f"# QR mod n: {qr_s}\\n"
            f"return (φ if False else {phi}) * (0.5 + 0.5 * isn(t * MEUM)) "
            f"+ {mod} * MEUM_NORM * cos(t * PHI) + ({mu}) * ics(t)"
        )
        # φ is not in env — use numeric phi only
        script = (
            f"# NT seed · n={mod} · φ(n)={phi} · μ(n)={mu}\\n"
            f"# quadratic residues mod n: {qr_s}\\n"
            f"({phi} * (0.5 + 0.5 * isn(t * MEUM)) + {mod} * MEUM_NORM * cos(t * PHI) "
            f"+ ({mu}) * ics(t))"
        )
        if hasattr(self, "_push_seed_history"):
            self._push_seed_history(script)
        if hasattr(self, "_apply_seed_script_text"):
            self._apply_seed_script_text(script, status_prefix=f"ℤ→Seed n={mod}")
        elif hasattr(self, "input_seed_val"):
            self.input_seed_val.setPlainText(script)
            try:
                self._on_live_source_changed()
            except Exception:
                pass

    def play_audio_only(self):
        """Play the rendered audio track without driving the audiovisual monitors."""
        # Mutually exclusive with audiovisual playback.
        if self.is_playing or self.is_paused:
            if not getattr(self, "_audio_only_mode", False):
                self.stop_playback()
            else:
                return
        try:
            _prev = self._live_preview_max_rows()
            if hasattr(self, "scope_status_label"):
                if _prev is not None:
                    self.scope_status_label.setText(
                        f"🔊 Rendering Audio Track (preview {_prev} rows)…"
                    )
                else:
                    self.scope_status_label.setText("🔊 Rendering Audio Track…")
            QApplication.processEvents()
            buf, sr = self._render_mixdown_buffer(max_rows=_prev)
            with self.play_lock:
                self.play_buffer = buf
                self.play_sample_rate = sr
                self.play_cursor = 0
                self.is_playing = True
                self.is_paused = False
                self._audio_only_mode = True
                self._transport_finished = False
                self._stop_requested = False
            if HAS_SOUNDDEVICE:
                if self.audio_stream is not None:
                    try:
                        self.audio_stream.stop(); self.audio_stream.close()
                    except Exception:
                        pass
                self.audio_stream = sd.OutputStream(
                    samplerate=sr, channels=1, dtype="float32", callback=self._audio_callback,
                    blocksize=1024, latency="low"
                )
                self.audio_stream.start()
            self.btn_audio_only.setText("🔊 AUDIO Track  |  LIVE")
            self.btn_audio_only.setStyleSheet(
                "QPushButton { background-color:#00aa55; color:#b8f7e6; border:2px solid #ffd166; "
                "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; }"
                "QPushButton:hover { background-color:#00c464; }"
            )
            self.btn_play.setText("▶ PLAY Audiovisual Track")
            if hasattr(self, "scope_status_label"):
                _tag = f" preview {_prev}r" if _prev is not None else ""
                self.scope_status_label.setText(f"🔊 Audio Track  |  LIVE{_tag}")
            self._scope_tick_counter = 0
            self._scope_update_timer.start()
        except Exception as e:
            self.is_playing = False
            self.is_paused = False
            self._audio_only_mode = False
            print(f"[Audio-only] Playback start failed: {e}")
            QMessageBox.critical(self, "Audio Playback Error", str(e))

    def stop_audio_playback(self):
        """Stop/reset audio-only transport without changing composition state."""
        was_active = self.is_playing and getattr(self, "_audio_only_mode", False)
        if not getattr(self, "_audio_only_mode", False) and not was_active:
            return
        self.is_playing = False
        self.is_paused = False
        self._audio_only_mode = False
        self._transport_finished = False
        self._stop_requested = True
        if hasattr(self, "_scope_update_timer") and self._scope_update_timer.isActive():
            self._scope_update_timer.stop()
        if getattr(self, "audio_stream", None) is not None:
            try:
                self.audio_stream.stop(); self.audio_stream.close()
            except Exception:
                pass
            self.audio_stream = None
        with getattr(self, "play_lock", threading.Lock()):
            self.play_cursor = 0
        if hasattr(self, "btn_audio_only"):
            self.btn_audio_only.setText("▶ PLAY Audio Track")
            self.btn_audio_only.setStyleSheet(
                "QPushButton { background-color:#14301c; color:#9dffb0; border:2px solid #46d158; "
                "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; }"
                "QPushButton:hover { background-color:#1f4228; }"
                "QPushButton:pressed { background-color:#0c1f10; }"
            )
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("📊 GLOBAL monitors · Wave · Scenograph · Spectrum  |  Idle")
        self._stop_requested = False
        if was_active:
            print("[Audio-only] Playback stopped.")

    def stop_playback(self):
        """Hard stop: reset the audiovisual transport to the beginning."""
        was_active = self.is_playing or self.is_paused
        self.is_playing = False
        self.is_paused = False
        self._audio_only_mode = False
        self._stop_requested = True
        self._transport_finished = False
        # Drop live modulation baselines so the next Play starts clean
        self._live_offset_baselines = {}
        self._live_param_baselines = {}
        if hasattr(self, '_scope_update_timer') and self._scope_update_timer.isActive():
            self._scope_update_timer.stop()
        if getattr(self, 'audio_stream', None) is not None:
            try:
                self.audio_stream.stop(); self.audio_stream.close()
            except Exception:
                pass
            self.audio_stream = None
        with getattr(self, 'play_lock', threading.Lock()):
            self.play_cursor = 0
        if hasattr(self, 'btn_play'):
            self.btn_play.setText("▶ PLAY Audiovisual Track")
            self.btn_play.setStyleSheet(
                "QPushButton { background-color:#14301c; color:#9dffb0; border:2px solid #46d158; "
                "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; }"
                "QPushButton:hover { background-color:#1f4228; }"
                "QPushButton:pressed { background-color:#0c1f10; }"
            )
        if hasattr(self, 'btn_audio_only'):
            self.btn_audio_only.setText("▶ PLAY Audio Track")
            self.btn_audio_only.setStyleSheet(
                "QPushButton { background-color:#14301c; color:#9dffb0; border:2px solid #46d158; "
                "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; }"
                "QPushButton:hover { background-color:#1f4228; }"
                "QPushButton:pressed { background-color:#0c1f10; }"
            )
        if hasattr(self, 'scope_status_label'):
            self.scope_status_label.setText("📊 Audiovisual Track  |  Stopped")
        if isinstance(getattr(self, 'visual_oscilloscope', None), VisualOscilloscope):
            self.visual_oscilloscope.update_waveform(np.zeros(100))
        if hasattr(self, 'video_synth_viewer'):
            self.video_synth_viewer.update_from_audio(np.zeros(100, dtype=np.float32))
        if was_active:
            print("[Audio] Audiovisual playback stopped.")
        self._stop_requested = False

    def _exports_dir(self):
        """Default export/render root: <groovebox root>/renders/"""
        import groovebox_paths
        return groovebox_paths.renders_dir()

    def _export_frame_size(self):
        """Video resolution = main window size at export time (even dims for yuv420p)."""
        try:
            w = max(320, int(self.width()))
            h = max(240, int(self.height()))
        except Exception:
            w, h = 1280, 720
        # Even dimensions required by most codecs
        w -= w % 2
        h -= h % 2
        return w, h

    def _export_provenance_payload(self):
        """Self-describing generation manifest embedded in every export (audio
        WAV chunk / ffmpeg comment / game provenance.mgpr).  Small, plain,
        standard metadata so reverse-engineering an export back onto the main
        window is a simple parameter copy — and re-rendering with these values
        reproduces the exact artifact.  Device-independent (no timestamps).
        """
        # Local helper — export must never fail with NameError on _safe_json
        # (was previously only defined inside _project_snapshot).
        def _safe_json(obj):
            try:
                return copy.deepcopy(obj)
            except Exception:
                try:
                    return json.loads(json.dumps(obj, default=str))
                except Exception:
                    return None

        def _num(widget, default=0.0):
            w = getattr(self, widget, None)
            if w is not None and hasattr(w, "value"):
                try:
                    return float(w.value())
                except Exception:
                    return default
            return default

        def _txt(widget, default=""):
            w = getattr(self, widget, None)
            if w is None:
                return default
            try:
                if hasattr(w, "toPlainText"):
                    return w.toPlainText()
                return str(w.text() if hasattr(w, "text") else default)
            except Exception:
                return default

        def _on(button):
            b = getattr(self, button, None)
            if b is None:
                return 0.0
            try:
                return 1.0 if b.isChecked() else 0.0
            except Exception:
                return 0.0

        manifest = {
            "doc": "eqr_export_manifest_v1",
            "fingerprint": None,
            # PI_MEDIA_HUB_2026: absolute project path so batch re-render can
            # reopen the linked .mgpr and re-export at new FPS/bitrate.
            "source_project_path": str(getattr(self, "_current_project_path", "") or "") or None,
            "seed": _txt("input_seed_val", ""),
            "bpm": _num("spin_bpm", 120.0),
            "seq_length": _num("spin_seq_length", 16.0),
            "track_offset": float(getattr(self, "global_track_offset", 0.0)),
            "base_frequency": _num("spin_base_frequency", 432.0),
            "global_convolve": _num("spin_global_convolve", 0.0),
            "clip_ratio_pct": _num("spin_clip_ratio", 50.0),
            "import_speed": _num("spin_import_speed", 1.0),
            "speed_scrub": 1.0 if (getattr(self, "chk_speed_scrub", None) and self.chk_speed_scrub.isChecked()) else 0.0,
            "speed_scrub_depth": _num("spin_speed_scrub", 0.0),
            "sparse_mask": 1.0 if (getattr(self, "chk_sparse_mask", None) and self.chk_sparse_mask.isChecked()) else 0.0,
            "sparse_density": _num("spin_sparse_density", 1.0),
            # Documented composition inputs that the canonical fingerprint reads:
            # re-applying these to a fresh window and recomposing deterministically
            # reproduces the exported artifact's identity.
            "engine_strength": _num("spin_engine_strength", CANONICAL_SEED_WEIGHT_DEFAULT),
            "synth_count": int(round(_num("spin_synth_count", 48.0))),
            "engines": {
                "goava": _on("btn_goava"),
                "randomizer": _on("btn_local_randomize"),
                "phase_lock": _on("btn_local_phase_lock"),
                "euclidean": _on("btn_idealize_rhythm"),
                "seeded": _on("btn_seeded_randomize"),
            },
            "master_volume": _num("slider_master_vol", 100.0),
            "dj": {
                "boost": _num("slider_pkp_boost", 0.0),
                "boost_pitch": _num("slider_pkp_boost_pitch", 0.0),
                "boost_steps": _num("slider_pkp_boost_steps", 1.0),
                "boost_offset": _num("slider_pkp_boost_offset", 0.5),
                "envelope": _num("slider_pkp_envelope", 0.0),
            },
            "fx": {
                "eqr": _num("slider_eqr", 0.0),
                "fractalizer": _num("slider_fractalizer", 0.0),
            },
            "operator_media_samples": {str(k): {"path": str(v.get("path", "")), "source_kind": str(v.get("source_kind", "audio")), "video_path": str(v.get("video_path", "")), "video_input_enabled": bool(v.get("video_input_enabled", False))} for k, v in (getattr(self, "instrument_media_samples", {}) or {}).items() if isinstance(v, dict) and v.get("path")},
            "sample_morph": _safe_json(getattr(self, "sample_morph_state", {})),
            "global_mod": _safe_json(getattr(self, "global_mod_state", {})),
            "canonical_blend_contract": {
                "canonical_control_min": 0.50,
                "userdata_share_min": 0.50,
                "carrier_as_modulation_source": True,
                "carrier_phase_lock": 0.50,
                "multi_target_blend": True,
                "arbitrary_time_offsets": True,
            },
            "canonical_user_blend_ledger": _safe_json(getattr(self, "_canonical_user_blend_ledger", {})),
            "canonical_user_carrier_proof": self._verify_canonical_user_carrier_contract(
                getattr(self, "imported_waveform", None) is not None
            ),
            "master_vector": {
                "x": float((getattr(self, "master_vector_state", {}) or {}).get("x", 0.0)),
                "y": float((getattr(self, "master_vector_state", {}) or {}).get("y", 0.0)),
                "z": float((getattr(self, "master_vector_state", {}) or {}).get("z", 0.0)),
                "drive": float((getattr(self, "master_vector_state", {}) or {}).get("drive", 0.5)),
                "enabled": bool((getattr(self, "master_vector_state", {}) or {}).get("enabled", True)),
                "guard": bool((getattr(self, "master_vector_state", {}) or {}).get("guard", True)),
                "canonical_weight": 0.5,
                "user_weight": 0.5,
            },
        }
        # GAME_AUDIO_CONTRACT_2026: the numeric triad (audio/visual/game
        # quantities) is the single cross-verification key between an audio/video
        # export and the exported game package.  It is a closed-form function of
        # the composition seed alone, so both artifacts derive the same value and
        # _triad_digest() can prove they came from one project.
        try:
            _gm = self._composition_meta_for_game()
            _gt = _vge.game_triad(_gm.get("seed"))
            if isinstance(_gt, dict):
                manifest["game_triad"] = _gt
        except Exception:
            pass
        try:
            manifest["fingerprint"] = self._canonical_fingerprint()
        except Exception:
            manifest["fingerprint"] = None
        return json.dumps(manifest, sort_keys=True, separators=(",", ":"))

    def _apply_provenance_payload(self, payload):
        """Restore the main-window inputs documented in an export manifest."""
        if not isinstance(payload, dict) or payload.get("doc") != "eqr_export_manifest_v1":
            return False
        setmap = {
            "bpm": ("spin_bpm", float),
            "seq_length": ("spin_seq_length", float),
            "track_offset": ("spin_global_track_offset", float),
            "base_frequency": ("spin_base_frequency", float),
            "global_convolve": ("spin_global_convolve", float),
            "clip_ratio_pct": ("spin_clip_ratio", float),
            "import_speed": ("spin_import_speed", float),
            "speed_scrub": ("chk_speed_scrub", bool),
            "speed_scrub_depth": ("spin_speed_scrub", float),
            "sparse_mask": ("chk_sparse_mask", bool),
            "sparse_density": ("spin_sparse_density", float),
            "master_volume": ("slider_master_vol", float),
            "engine_strength": ("spin_engine_strength", float),
            "synth_count": ("spin_synth_count", int),
        }
        for manifest_key, (attr, cast) in setmap.items():
            if manifest_key not in payload:
                continue
            w = getattr(self, attr, None)
            if w is None:
                continue
            try:
                w.blockSignals(True)
                if cast is bool and hasattr(w, "setChecked"):
                    w.setChecked(bool(payload[manifest_key]))
                elif hasattr(w, "setValue"):
                    w.setValue(cast(payload[manifest_key]))
            except Exception:
                try:
                    w.setValue(0)
                except Exception:
                    pass
            finally:
                try:
                    w.blockSignals(False)
                except Exception:
                    pass
        dj = payload.get("dj") if isinstance(payload.get("dj"), dict) else {}
        fx = payload.get("fx") if isinstance(payload.get("fx"), dict) else {}
        fills = list(dj.items()) + list(fx.items())
        for key, val in fills:
            w = getattr(self, key, None)
            if w is None or not hasattr(w, "setValue"):
                continue
            try:
                w.blockSignals(True)
                w.setValue(float(val))
                w.blockSignals(False)
            except Exception:
                pass
        if isinstance(payload.get("sample_morph"), dict):
            self.sample_morph_state.update({k: payload["sample_morph"][k] for k in ("enabled", "adaptive_fit", "phase_lock", "guard") if k in payload["sample_morph"]})
            try:
                self.chk_sample_precano.setChecked(bool(self.sample_morph_state.get("enabled", True)))
                self.slider_sample_adaptive_fit.setValue(int(round(float(self.sample_morph_state.get("adaptive_fit", .50))*50)))
                self.slider_sample_phase_lock.setValue(int(round(float(self.sample_morph_state.get("phase_lock", .50))*50)))
                self.chk_sample_guard.setChecked(bool(self.sample_morph_state.get("guard", True)))
            except Exception: pass

        # MASTER_VECTOR_PROVENANCE_2026: exports carry the explicit user-vector
        # settings so an exported artifact can be rehydrated onto the same render path.
        mv = payload.get("master_vector") if isinstance(payload.get("master_vector"), dict) else {}
        if mv:
            try:
                self.master_vector_state.update({
                    k: mv[k] for k in ("x", "y", "z", "drive", "enabled", "guard") if k in mv
                })
                for key in ("x", "y", "z"):
                    if key in getattr(self, "master_vector_sliders", {}):
                        sl, lab = self.master_vector_sliders[key]
                        sl.blockSignals(True); sl.setValue(int(round(float(self.master_vector_state.get(key, 0.0)) * 100.0))); sl.blockSignals(False)
                        lab.setText(f"{float(self.master_vector_state.get(key, 0.0)):+.2f}")
                if hasattr(self, "slider_master_vector_drive"):
                    self.slider_master_vector_drive.blockSignals(True); self.slider_master_vector_drive.setValue(int(round(float(self.master_vector_state.get("drive", 0.5)) * 100.0))); self.slider_master_vector_drive.blockSignals(False)
                if hasattr(self, "btn_master_vector_convert"):
                    self.btn_master_vector_convert.setChecked(bool(self.master_vector_state.get("enabled", True)))
                    self.btn_master_vector_convert.setText("VECTOR CONVERT · ON" if self.btn_master_vector_convert.isChecked() else "VECTOR CONVERT · OFF")
                if hasattr(self, "chk_master_vector_guard"):
                    self.chk_master_vector_guard.setChecked(bool(self.master_vector_state.get("guard", True)))
                self._master_vector_effective()
            except Exception:
                pass
        seed = str(payload.get("seed") or "")
        if hasattr(self, "input_seed_val") and self.input_seed_val is not None:
            try:
                self.input_seed_val.blockSignals(True)
                if hasattr(self.input_seed_val, "setPlainText"):
                    self.input_seed_val.setPlainText(seed)
                elif hasattr(self.input_seed_val, "setText"):
                    self.input_seed_val.setText(seed)
                self.input_seed_val.blockSignals(False)
            except Exception:
                pass
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        # Engine toggles are restored UNBLOCKED so activation regenerates the
        # composition from the documented inputs (seed/bpm/base + engine mask).
        engines = payload.get("engines") if isinstance(payload.get("engines"), dict) else {}
        for eng_name, attr in (
            ("goava", "btn_goava"), ("randomizer", "btn_local_randomize"),
            ("phase_lock", "btn_local_phase_lock"), ("euclidean", "btn_idealize_rhythm"),
            ("seeded", "btn_seeded_randomize"),
        ):
            if eng_name not in engines:
                continue
            b = getattr(self, attr, None)
            if b is None:
                continue
            try:
                b.setChecked(bool(engines[eng_name]))
            except Exception:
                pass
        # Let engine-triggered (possibly deferred) scope work complete, then
        # re-assert the documented instrument count/strength LAST so a faithful
        # rebuild reproduces the exported artifact's composition identity.
        from PyQt6.QtWidgets import QApplication as _SQ
        for _ in range(5):
            _SQ.processEvents()
        for mkey, attr in (("synth_count", "spin_synth_count"), ("engine_strength", "spin_engine_strength")):
            if mkey not in payload:
                continue
            w = getattr(self, attr, None)
            if w is None or not hasattr(w, "setValue"):
                continue
            try:
                # spin_synth_count is an int QSpinBox (PyQt6 rejects float).
                _val = int(round(float(payload[mkey]))) if mkey == "synth_count" else float(payload[mkey])
                w.setValue(_val)
            except Exception:
                pass
        return True

    def _recompose_project(self, pump=3):
        """Regenerate the composition deterministically from the documented
        inputs (seed / BPM / base frequency / engine mask), stop the live
        engines' timers, and commit perfect unison so the canonical fingerprint
        reflects the final committed state — not intermediate rebuild frames."""
        from PyQt6.QtWidgets import QApplication as _QA
        for t in (getattr(self, "_live_euclid_timer", None), getattr(self, "_live_seeded_timer", None)):
            if t is not None:
                try:
                    t.stop()
                except Exception:
                    pass
        for _ in range(pump):
            _QA.processEvents()
        try:
            self._ensure_perfect_unison()
        except Exception:
            pass
        for _ in range(2):
            _QA.processEvents()

    def _triad_digest(self, triad_obj):
        """Stable short digest of a numeric game triad (audio/visual/game)."""
        try:
            if not isinstance(triad_obj, dict):
                return ""
            compact = {}
            for p in ("audio", "visual", "game"):
                if isinstance(triad_obj.get(p), dict):
                    compact[p] = {
                        str(k): round(float(v), 6)
                        for k, v in triad_obj[p].items() if isinstance(v, (int, float))
                    }
            return hashlib.sha256(json.dumps(compact, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()[:12]
        except Exception:
            return ""

    def _triad_matches(self, manifest_triad, zip_triad):
        """GAME_AUDIO_CONTRACT_2026: field-wise cross-verification between the
        audio manifest's game_triad and the game package's triad.mgpr.  All
        audio/visual quantities and all game quantities except sigil_count must
        agree to float64 precision; sigil_count is classification-tracked (the
        package legitimately pins its own), so it is reported separately."""
        try:
            if not (isinstance(manifest_triad, dict) and isinstance(zip_triad, dict)):
                return None, ""
            note = []
            for p in ("audio", "visual"):
                a = manifest_triad.get(p) or {}
                b = zip_triad.get(p) or {}
                for k in set(a) | set(b):
                    if abs(float(a.get(k, 0.0)) - float(b.get(k, 0.0))) > 1e-6:
                        return False, f"{p}.{k} differs"
            a = manifest_triad.get("game") or {}
            b = zip_triad.get("game") or {}
            for k in set(a) | set(b):
                if k == "sigil_count":
                    if int(a.get(k, 0) or 0) != int(b.get(k, 0) or 0):
                        note.append(f"sigil_count {a.get(k)} vs {b.get(k)}")
                    continue
                if abs(float(a.get(k, 0.0)) - float(b.get(k, 0.0))) > 1e-6:
                    return False, f"game.{k} differs"
            return True, (" · " + "; ".join(note)) if note else ""
        except Exception:
            return None, ""

    def _extract_provenance_from_file(self, file_path):
        """Read the export manifest back out of a WAV / media file / game zip."""
        low = str(file_path).lower()
        if low.endswith((".wav", ".aiff", ".aif")):
            payload = _extract_wav_provenance(file_path)
            if payload:
                return payload
        low = str(file_path).lower()
        if low.endswith(".zip"):
            try:
                import zipfile as _zf
                with _zf.ZipFile(file_path) as zf:
                    names = set(zf.namelist())
                    for cand in ("provenance.mgpr", "main_window_settings.mgpr", "multimodal_contract.mgpr"):
                        if cand in names:
                            try:
                                payload = json.loads(zf.read(cand).decode("utf-8"))
                                # Legacy packages double-encode the manifest via
                                # json.dumps when embedding the provenance string;
                                # unwrap a single layer so payload is always a dict.
                                if isinstance(payload, str):
                                    payload = json.loads(payload)
                                # GAME_AUDIO_CONTRACT_2026: when this is a game zip,
                                # also surface the package's own triad.mgpr so the
                                # reconvert step can cross-verify the audio export's
                                # manifest against the game's numeric contract key.
                                for triad_cand in ("assets/triad.mgpr", "triad.mgpr"):
                                    if triad_cand in names:
                                        try:
                                            payload["_zip_triad"] = json.loads(zf.read(triad_cand).decode("utf-8"))
                                        except Exception:
                                            pass
                                        break
                                return payload
                            except Exception:
                                continue
            except Exception:
                pass
        ffprobe = shutil.which("ffprobe")
        if ffprobe:
            try:
                proc = subprocess.run(
                    [ffprobe, "-v", "error", "-show_entries", "format_tags=comment", "-of", "json", file_path],
                    capture_output=True, text=True, timeout=60,
                )
                tags = json.loads(proc.stdout or "{}").get("format", {}).get("tags", {})
                comment = tags.get("comment") or tags.get("COMMENT") or ""
                if comment:
                    return json.loads(comment)
            except Exception:
                pass
        return None

    def reconvert_export_dialog(self):
        """REVERSE-ENGINEERING: rebuild the main window from an exported
        artifact.  Reads the plain provenance manifest the export carried
        (WAV 'eqrf' chunk / ffmpeg 'comment' tag / game provenance.mgpr) and
        re-applies every documented input so a re-render reproduces the same
        artifact; the restored canonical fingerprint is shown for comparison.
        """
        filter_all = "Exports (*.wav *.flac *.mp3 *.ogg *.opus *.caf *.aiff *.mp4 *.webm *.avi *.zip);;All files (*)"
        file_path, _ = QFileDialog.getOpenFileName(self, "Reconvert Export → Main Window", self._exports_dir(), filter_all)
        if not file_path:
            return
        payload = self._extract_provenance_from_file(file_path)
        if not payload:
            QMessageBox.warning(
                self, "Reconvert Export",
                "No EQR export manifest found in this file.\n"
                "Only artifacts written by this app carry the document; a plain "
                "file cannot be reverse-engineered back to the original window."
            )
            return
        restored_ok = self._apply_provenance_payload(payload)
        if restored_ok and payload.get("engines"):
            try:
                self._recompose_project()
            except Exception:
                pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        fp = payload.get("fingerprint")
        cur = ""
        try:
            cur = self._canonical_fingerprint()
        except Exception:
            cur = ""
        # GAME_AUDIO_CONTRACT_2026: if the artifact is a game zip, cross-verify
        # the embedded triad.mgpr against the audio manifest's game_triad key —
        # both must be the same closed-form f(seed), proving the audio and game
        # came from one project.
        triad_note = ""
        try:
            _gt = payload.get("game_triad")
            _zt = payload.get("_zip_triad")
            if isinstance(_gt, dict) and isinstance(_zt, dict):
                _ok, _why = self._triad_matches(_gt, _zt)
                if _ok is True:
                    triad_note = " · 🎮⇄♫ game triad matches" + _why
                elif _ok is False:
                    triad_note = f" · game triad ≠ manifest ({_why})"
        except Exception:
            triad_note = ""
        if restored_ok:
            match = "✓ fingerprint matches" if (fp and cur and fp == cur) else ("≠ fingerprint differs" if fp else "")
            self.scope_status_label.setText(
                f"♻ Reconverted export → main window restored{(' · ' + match) if match else ''}{triad_note}"
            )
            if fp and cur:
                QMessageBox.information(
                    self, "Reconvert Export",
                    f"Main window restored from:\n{os.path.basename(file_path)}\n\n"
                    f"export fingerprint: {fp}\ncurrent fingerprint:  {cur}\n\n{match}{triad_note}"
                )
            else:
                QMessageBox.information(self, "Reconvert Export", "Main window restored from export manifest." + triad_note)
        else:
            QMessageBox.warning(self, "Reconvert Export", "Manifest recognized but could not be restored.")

    def _recover_program_bundle(self, zip_path):
        """REVERSE-ENGINEERING: a .zip export written by this app is fully
        self-describing.  Read the package back into its recoverable parts — the
        emitted program source, its identity, the audio<->game triad contract,
        the software-lattice proof, and the provenance manifest that rebuilds
        the original main window.  Returns a bundle dict for display/saving.
        """
        import zipfile as _zf
        import hashlib as _hl
        bundle = {
            "zip": str(zip_path),
            "files": [], "program": None, "identity": None, "triad": None,
            "payload": None, "lattice": None,
            "restored": False, "fp_match": None, "triad_ok": None, "triad_note": "",
        }
        try:
            with _zf.ZipFile(zip_path) as zf:
                names = zf.namelist()
                script_name = ""
                script_size = 0
                for n in names:
                    low = n.lower()
                    if not any(low.endswith(e) for e in (".py", ".mgpr", ".md", ".sh", ".bat", ".command", ".txt")):
                        continue
                    try:
                        data = zf.read(n)
                    except Exception:
                        continue
                    bundle["files"].append({
                        "name": n, "size": len(data),
                        "sha256": _hl.sha256(data).hexdigest()[ :16],
                    })
                    if low.endswith(".py"):
                        if len(data) > script_size:
                            script_size = len(data)
                            script_name = n
                            bundle["program"] = {
                                "name": n, "size": len(data),
                                "sha256": _hl.sha256(data).hexdigest(),
                                "head": data[:6000].decode("utf-8", "replace"),
                            }
                for n in names:
                    low = n.lower()
                    if not low.endswith(".mgpr"):
                        continue
                    try:
                        obj = json.loads(zf.read(n).decode("utf-8"))
                    except Exception:
                        continue
                    if isinstance(obj, str):
                        try:
                            obj = json.loads(obj)
                        except Exception:
                            continue
                    if not isinstance(obj, dict):
                        continue
                    base = os.path.basename(n).lower()
                    if "provenance" in base or "manifest" in base or "main_window_settings" in base:
                        if bundle["payload"] is None:
                            bundle["payload"] = obj
                    elif "triad" in base:
                        if bundle["triad"] is None:
                            bundle["triad"] = obj
                    elif base.startswith("game_") or "identity" in base:
                        if bundle["identity"] is None and isinstance(obj, dict) and "title" in obj:
                            bundle["identity"] = obj
                    elif "lattice" in base:
                        bundle["lattice"] = obj
            # The .py script name is discovered above; also accept the classic
            # launcher set as proof of a fully self-contained package.
            if script_name and bundle["program"]:
                bundle["program"]["name"] = script_name
        except Exception:
            return bundle
        payload = bundle["payload"]
        if payload:
            try:
                bundle["restored"] = bool(self._apply_provenance_payload(payload))
            except Exception:
                bundle["restored"] = False
            if bundle["restored"] and payload.get("engines"):
                try:
                    self._recompose_project()
                except Exception:
                    pass
            try:
                self._refresh_canonical_fingerprint()
            except Exception:
                pass
            try:
                cur = self._canonical_fingerprint()
                bundle["fp_match"] = bool(payload.get("fingerprint")) and payload["fingerprint"] == cur
            except Exception:
                bundle["fp_match"] = None
            if bundle["triad"]:
                try:
                    _ok2, _why2 = self._triad_matches(payload.get("game_triad"), bundle["triad"])
                    bundle["triad_ok"], bundle["triad_note"] = _ok2, _why2
                except Exception:
                    pass
        return bundle

    def _on_reverse_engineer_zip(self):
        """Import a game/software .zip export and recover the program it holds:
        the emitted source, its identity, the triad contract and the manifest,
        all demonstrated (fingerprint + triad cross-check) and optionally saved
        to a folder.  REVERSE_ENGINEERING: the export is the inverse of export.
        """
        filter_all = "Exports / Packages (*.zip);;All files (*)"
        path, _ = QFileDialog.getOpenFileName(self, "Reverse-Engineer Program from .zip", self._games_dir(), filter_all)
        if not path:
            return
        bundle = self._recover_program_bundle(path)
        if not bundle.get("program") and not bundle.get("payload") and not bundle.get("lattice"):
            QMessageBox.warning(
                self, "Reverse-Engineer Program",
                "This .zip holds no recoverable program source or manifest.\n"
                "Only packages exported by this app are self-describing inverses."
            )
            return
        prog = bundle.get("program")
        payload = bundle.get("payload")
        lines = []
        lines.append(f"$ reverse-engineer {os.path.basename(path)}")
        lines.append(f"  recovered files ............ {len(bundle.get('files', []))}")
        if prog:
            lines.append(f"  program .................... {prog['name']}")
            lines.append(f"  program sha256 ............. {prog['sha256'][:32]}…")
            lines.append(f"  program size ............... {prog['size']} bytes")
        if bundle.get("identity"):
            _id = bundle["identity"]
            lines.append(f"  identity ................... {_id.get('title', '?')} "
                         f"[{_id.get('genre', '?')} / {_id.get('camera', '?')} / {_id.get('objective', '?')}]")
        if payload:
            lines.append(f"  origin seed ................ {payload.get('seed')}")
            lines.append(f"  manifest fingerprint ....... {payload.get('fingerprint')}")
            lines.append(f"  main window restored ....... {'yes' if bundle.get('restored') else 'no'}")
            if bundle.get("fp_match") is True:
                lines.append("  fingerprint proof .......... ✓ reconstructs the exact original window")
            elif bundle.get("fp_match") is False:
                lines.append("  fingerprint proof .......... ≠ (window differs from manifest)")
        if bundle.get("triad"):
            t_ok = bundle.get("triad_ok")
            if t_ok is True:
                lines.append("  triad proof ................ ✓ audio<->game key matches the package" + (bundle.get("triad_note") or ""))
            elif t_ok is False:
                lines.append("  triad proof ................ ✗ differs from game_triad (%s)" % bundle.get("triad_note"))
        if bundle.get("lattice"):
            _lp = bundle["lattice"]
            if isinstance(_lp, dict):
                _keys = list(_lp.keys())
                lines.append(f"  lattice proof .............. {_keys[:6]}")
            else:
                lines.append(f"  lattice proof .............. {len(_lp)} entries")
        detail = "\n".join(lines)
        dlg = QDialog(self)
        dlg.setWindowTitle("🔓 Reverse-Engineered Program from .zip")
        dlg.resize(760, 560)
        dlg.setStyleSheet(DAW_STYLE if "DAW_STYLE" in dir() else "")
        lay = QVBoxLayout(dlg)
        lay.addWidget(QLabel(
            "<b>Reverse-engineered program</b> — the .zip export is the inverse of export: "
            "the program source, its identity, the triad contract and the provenance "
            "manifest are all recoverable, and re-applying the manifest reproduces the "
            "original main window."
        ))
        txt = QTextEdit()
        txt.setReadOnly(True)
        txt.setFont(QFont("Menlo", 10))
        body = detail + "\n\n" + ("— recovered program source —\n" + prog["head"] if prog else "")
        if not prog:
            body += "\n\n(no .py source embedded — manifest-only package)"
        txt.setPlainText(body)
        lay.addWidget(txt, 1)
        row = QHBoxLayout()
        save_btn = QPushButton("Save recovered program…")
        close_btn = QPushButton("Close")
        row.addWidget(save_btn)
        row.addStretch(1)
        row.addWidget(close_btn)
        lay.addLayout(row)
        close_btn.clicked.connect(dlg.accept)

        def _save():
            out_dir = QFileDialog.getExistingDirectory(
                self, "Save recovered program bundle to", self._games_dir()
            )
            if not out_dir:
                return
            saved = []
            try:
                if prog:
                    with open(os.path.join(out_dir, prog["name"]), "w", encoding="utf-8") as f:
                        f.write(prog["head"])
                        saved.append(prog["name"])
                for name_key, obj, label in (
                    ("identity", bundle.get("identity"), "identity_recovered.mgpr"),
                    ("triad", bundle.get("triad"), "triad_recovered.mgpr"),
                    ("payload", bundle.get("payload"), "provenance_recovered.mgpr"),
                ):
                    if isinstance(obj, dict):
                        with open(os.path.join(out_dir, label), "w", encoding="utf-8") as f:
                            json.dump(obj, f, indent=2, sort_keys=True)
                        saved.append(label)
                with open(os.path.join(out_dir, "recovered_README.md"), "w", encoding="utf-8") as f:
                    f.write("# Reverse-engineered from .zip\n\nSource: %s\n\n```\n%s\n```\n"
                            % (os.path.basename(path), detail))
                saved.append("recovered_README.md")
            except Exception as _ee:
                QMessageBox.warning(self, "Save recovered program", f"Could not save: {_ee}")
                return
            QMessageBox.information(
                self, "Save recovered program",
                "Recovered bundle written to:\n" + out_dir + "\n\n" + "\n".join("• " + s for s in saved)
            )

        save_btn.clicked.connect(_save)
        dlg.exec()
        self.scope_status_label.setText(
            f"🔓 Reverse-engineered program from {os.path.basename(path)} "
            f"({len(bundle.get('files', []))} files)"
        )

    def _bake_compare_render(self, payload):
        """Render the current window as one full canonical master (int16 pcm +
        sample rate + provenance).  Optionally applies a target manifest first
        (blocked, then restored) so A/B renders isolate the documented inputs."""
        pcm = None
        sr = 48000
        try:
            self.stop_playback()
        except Exception:
            pass
        try:
            master, sr = self._render_mixdown_buffer()
            master = np.nan_to_num(np.asarray(master, dtype=np.float32), nan=0.0, posinf=1.0, neginf=-1.0)
        except Exception as _rexc:
            print(f"[BakeCompare] render failed: {_rexc}")
            return None, sr
        try:
            master = self._bake_dj_write(master, sr)
        except Exception:
            pass
        try:
            # Export gets the same hardclip path as live: vol × factors → clip.
            master, _ = self._master_hardclip(master, sr, apply_master_vol=True)
            pcm = (np.clip(master, -1.0, 1.0) * 32767.0).astype(np.int16)
        except Exception:
            pcm = None
        return pcm, sr

    def bake_compare_export_dialog(self):
        """BAKE_AND_COMPARE_2026: bake the current main window and an exported
        artifact side by side and diff the actual sample streams.

        A = current window rendered to canonical pcm (as export would write).
        B = the SAME render after applying the artifact's provenance manifest
            (blocked, then everything restored to A's values).
        Reports duration, peak, RMS and per-sample difference so "reconverting"
        is verified in the sample domain, not just the fingerprint domain.
        """
        filter_all = "Exports (*.wav *.flac *.mp3 *.ogg *.opus *.caf *.aiff *.mp4 *.webm *.avi *.zip);;All files (*)"
        file_path, _ = QFileDialog.getOpenFileName(self, "Bake & Compare Export", self._exports_dir(), filter_all)
        if not file_path:
            return
        target = self._extract_provenance_from_file(file_path)
        if not target:
            QMessageBox.warning(
                self, "Bake & Compare",
                "No EQR export manifest found in this file — cannot bake a "
                "comparable render from it."
            )
            return
        try:
            self.stop_playback()
        except Exception:
            pass
        if hasattr(self, 'scope_status_label'):
            self.scope_status_label.setText("⚖ Bake & Compare: rendering current main window (A)…")
        QApplication.processEvents()
        cur_manifest = self._export_provenance_payload()
        try:
            cur_payload = json.loads(cur_manifest)
        except Exception:
            cur_payload = None
        A, sr = self._bake_compare_render(None)
        if A is None or len(A) == 0:
            QMessageBox.warning(self, "Bake & Compare", "Current render produced no audio.")
            return
        # Apply the artifact's documented inputs (blocked), render B, restore.
        try:
            self._apply_provenance_payload(target)
        except Exception:
            pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        if hasattr(self, 'scope_status_label'):
            self.scope_status_label.setText("⚖ Bake & Compare: rendering artifact manifest (B)…")
        QApplication.processEvents()
        B, _sr2 = self._bake_compare_render(None)
        try:
            if cur_payload:
                self._apply_provenance_payload(cur_payload)
        except Exception:
            pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        if hasattr(self, 'scope_status_label'):
            self.scope_status_label.setText("⚖ Bake & Compare complete — window restored.")
        if B is None or len(B) == 0:
            QMessageBox.warning(self, "Bake & Compare", "Artifact render produced no audio.")
            return
        n = min(len(A), len(B))
        if n == 0:
            QMessageBox.warning(self, "Bake & Compare", "Renders are empty.")
            return
        len_match = len(A) == len(B)
        segA = A[:n].astype(np.float64) / 32767.0
        segB = B[:n].astype(np.float64) / 32767.0
        diff = segA - segB
        rms_a = float(np.sqrt(np.mean(segA * segA))) if n else 0.0
        rms_b = float(np.sqrt(np.mean(segB * segB))) if n else 0.0
        max_abs = float(np.max(np.abs(diff))) if n else 0.0
        denom = float(np.sqrt(np.mean(segA * segA)) + np.sqrt(np.mean(segB * segB)))
        rms_ratio = float(np.sqrt(np.mean(diff * diff)) / denom) if denom > 0.0 and math.isfinite(denom) else 0.0
        identical = bool(np.array_equal(A[:n], B[:n])) and len_match
        peak_a = float(np.max(np.abs(segA))) if n else 0.0
        peak_b = float(np.max(np.abs(segB))) if n else 0.0
        dur_a = len(A) / max(float(sr), 1.0)
        dur_b = len(B) / max(float(_sr2 or sr), 1.0)
        fp_cur = ""
        fp_tgt = str(target.get("fingerprint") or "")
        try:
            fp_cur = self._canonical_fingerprint()
        except Exception:
            fp_cur = ""
        report = (
            f"Current main window (A)\n"
            f"  duration {dur_a:.2f}s · peak {20.0 * math.log10(max(peak_a, 1e-9)):+.1f} dBFS\n"
            f"  fingerprint {fp_cur or '—'}\n\n"
            f"Artifact manifest (B) from {os.path.basename(file_path)}\n"
            f"  duration {dur_b:.2f}s · peak {20.0 * math.log10(max(peak_b, 1e-9)):+.1f} dBFS\n"
            f"  fingerprint {fp_tgt or '—'}\n\n"
            f"Diff (first {n} samples)\n"
            f"  identical: {'yes — bit-for-bit' if identical else 'no'}\n"
            f"  rms ratio: {rms_ratio:.6f} (0 = identical, 1 = unrelated)\n"
            f"  max abs diff: {max_abs:.6f}\n"
            f"  length match: {'yes' if len_match else f'no ({len(A)} vs {len(B)})'}\n"
            f"  rms A {rms_a:.4f} · rms B {rms_b:.4f}\n\n"
            f"Fingerprints {'match' if (fp_cur and fp_tgt and fp_cur == fp_tgt) else 'differ'}: "
            f"{fp_cur or '—'} vs {fp_tgt or '—'}"
        )
        self.scope_status_label.setText(
            f"⚖ Bake & Compare: {('identical' if identical else f'rms {rms_ratio:.4f}')} — restored."
        )
        box = QMessageBox(self)
        box.setWindowTitle("Bake & Compare — report")
        box.setText(report)
        box.setStandardButtons(QMessageBox.StandardButton.Ok)
        box.exec()

    def _default_export_part_count(self, duration_s=None):
        """Heuristic default part count in 1–128 from duration (and prior choice)."""
        prev = int(getattr(self, "_last_export_part_count", 0) or 0)
        if 1 <= prev <= 128:
            return prev
        try:
            d = float(duration_s) if duration_s is not None else 0.0
        except Exception:
            d = 0.0
        if d <= 30:
            return 4
        if d <= 120:
            return 8
        if d <= 600:
            return 16
        if d <= 1800:
            return 32
        return 64

    def _export_part_count_dialog(self, title="Export Parts", default=16, hint=""):
        """Modal Part Count selector (1–128) for all long export jobs.

        Returns int part count, or None if the user cancels.
        """
        try:
            default = int(default)
        except Exception:
            default = 16
        default = max(1, min(128, default))
        dlg = QDialog(self)
        dlg.setWindowTitle(str(title or "Export Parts"))
        try:
            dlg.setStyleSheet(getattr(self, "styleSheet", lambda: "")() or "")
        except Exception:
            pass
        form = QFormLayout(dlg)
        spin = QSpinBox()
        spin.setRange(1, 128)
        spin.setSingleStep(1)
        spin.setValue(default)
        spin.setToolTip(
            "How many recoverable .part segments to write.\n"
            "1 = single file (no partition). 16 is the classic default.\n"
            "Higher counts lower peak temp disk and improve crash resume."
        )
        form.addRow("Part Count (1–128)", spin)
        note = QLabel(
            (hint or "")
            + ("\n" if hint else "")
            + "Parts are written next to the final file as "
            "<stem>.partNN.<ext> (and <stem>.audio.partNN.wav for A/V). "
            "Completed parts can be resumed after a crash."
        )
        note.setWordWrap(True)
        form.addRow(note)
        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel
        )
        btns.accepted.connect(dlg.accept)
        btns.rejected.connect(dlg.reject)
        form.addRow(btns)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return None
        n = max(1, min(128, int(spin.value())))
        self._last_export_part_count = n
        return n

    def _write_audio_parts_and_final(
        self,
        file_path,
        sample_rate,
        pcm_int16,
        n_parts=1,
        provenance_bytes=None,
        audio_format="wav",
        audio_bitrate_kbps=None,
    ):
        """Write optional audio .partNN files, then the final audio artifact.

        audio_bitrate_kbps: optional target bitrate for lossy formats (mp3/opus/ogg).
        WAV/FLAC/AIFF/CAF ignore it (lossless / PCM).

        Returns (final_path, list_of_part_paths).
        """
        pcm = np.asarray(pcm_int16, dtype=np.int16).reshape(-1)
        n_parts = max(1, min(128, int(n_parts or 1)))
        dest_dir = os.path.dirname(os.path.abspath(file_path)) or self._exports_dir()
        try:
            os.makedirs(dest_dir, exist_ok=True)
        except Exception:
            pass
        stem = os.path.splitext(os.path.basename(file_path))[0]
        total = int(pcm.shape[0])
        if total < 1:
            raise RuntimeError("No audio samples to export.")

        part_paths = []
        if n_parts > 1:
            # Even split with remainder on the last part.
            base = total // n_parts
            rem = total % n_parts
            offset = 0
            for pi in range(n_parts):
                take = base + (1 if pi < rem else 0)
                take = max(1, take) if offset < total else 0
                chunk = pcm[offset:offset + take] if take else pcm[0:1]
                offset += take
                part_path = os.path.join(dest_dir, f"{stem}.part{pi:02d}.wav")
                _write_wav_with_provenance(
                    part_path,
                    sample_rate,
                    chunk,
                    provenance_bytes if pi == 0 else None,
                )
                part_paths.append(part_path)
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText(
                        f"📊 Audio part {pi + 1}/{n_parts} → {os.path.basename(part_path)}"
                    )
                    QApplication.processEvents()

        audio_format = str(audio_format or "wav").lower().lstrip(".")
        try:
            br = int(audio_bitrate_kbps) if audio_bitrate_kbps is not None else None
        except Exception:
            br = None
        if br is not None:
            br = max(32, min(512, br))

        if audio_format == "wav":
            _write_wav_with_provenance(file_path, sample_rate, pcm, provenance_bytes)
        else:
            ffmpeg = self._resolve_ffmpeg_binary()
            if not ffmpeg:
                raise RuntimeError(f"FFmpeg is required for {audio_format.upper()} audio export.")
            tmp = os.path.join(
                dest_dir, f".groovebox_audio_tmp_{os.getpid()}_{getattr(self, 'export_counter', 0)}.wav"
            )
            _write_wav_with_provenance(tmp, sample_rate, pcm)
            # Bitrate-aware codec args for lossy formats; lossless stay fixed.
            if audio_format == "mp3":
                if br is not None:
                    codec_args = ["-c:a", "libmp3lame", "-b:a", f"{br}k"]
                else:
                    codec_args = ["-c:a", "libmp3lame", "-q:a", "2"]
            elif audio_format == "opus":
                codec_args = ["-c:a", "libopus", "-b:a", f"{br or 192}k"]
            elif audio_format == "ogg":
                # libvorbis prefers quality scale; approximate from bitrate when set.
                if br is not None:
                    # ~64kbps→q2 … ~320kbps→q9
                    q = max(0, min(10, int(round((br - 64) / 28.0))))
                    codec_args = ["-c:a", "libvorbis", "-q:a", str(q)]
                else:
                    codec_args = ["-c:a", "libvorbis", "-q:a", "6"]
            else:
                codec_args = {
                    "flac": ["-c:a", "flac"],
                    "aiff": ["-c:a", "pcm_s16be"],
                    "caf": ["-c:a", "pcm_s16le"],
                }.get(audio_format, ["-c:a", "flac"])
            meta = []
            if provenance_bytes:
                try:
                    meta = ["-metadata", f"comment={provenance_bytes.decode('utf-8')}"]
                except Exception:
                    meta = []
            proc = subprocess.run(
                [ffmpeg, "-y", "-hide_banner", "-loglevel", "error", "-i", tmp, *codec_args, *meta, file_path],
                capture_output=True,
                text=True,
                timeout=180,
            )
            try:
                os.remove(tmp)
            except OSError:
                pass
            if proc.returncode != 0:
                raise RuntimeError(proc.stderr or f"FFmpeg failed for {audio_format.upper()}")
        return file_path, part_paths

    def export_mixdown_dialog(self, audio_format="wav"):

        """Export the same canonical master mix in WAV/FLAC/OGG/AIFF/MP3/OPUS/CAF.

        Pathway (all formats share this — no alternate soft bus):
          1. ``_render_mixdown_buffer`` — composition identity (sum of voices)
          2. optional bake-DJ write (live parametric, not a normalizer)
          3. ``_master_hardclip`` — Master Volume × Clip/Gain factors → hard clip
             (NO peak normalizer, NO limiter, NO EQ/filter on this final bus)
          4. int16 quantize for container write

        50% default Master Volume is the intentional warning on play/preview;
        export uses the same hardclip path so offline files match what you heard.
        Video exports that embed this mixdown inherit the same hardclip stage.
        """
        audio_format = str(audio_format or "wav").lower().lstrip(".")
        if audio_format not in {"wav", "flac", "ogg", "aiff", "mp3", "opus", "caf"}:
            audio_format = "wav"
        filters = {
            "wav": "WAV Audio (*.wav)", "flac": "FLAC Audio (*.flac)",
            "ogg": "Ogg Vorbis Audio (*.ogg)", "aiff": "AIFF Audio (*.aiff *.aif)",
            "mp3": "MP3 Audio (*.mp3)", "opus": "Opus Audio (*.opus)",
            "caf": "Core Audio Format (*.caf)",
        }
        ext = ".aiff" if audio_format == "aiff" else "." + audio_format
        try:
            default_filename = os.path.join(self._exports_dir(), f"groovebox_mixdown_{self.export_counter:03d}{ext}")
            file_path, _ = QFileDialog.getSaveFileName(self, "Save Mixdown Audio", default_filename, filters[audio_format])
            if not file_path:
                return
            if not file_path.lower().endswith(ext):
                file_path += ext
            # Parts + optional bitrate (lossy formats only).
            opts_dlg = QDialog(self)
            opts_dlg.setWindowTitle(f"Audio Export — {audio_format.upper()}")
            opts_form = QFormLayout(opts_dlg)
            spin_parts = QSpinBox()
            spin_parts.setRange(1, 128)
            spin_parts.setValue(int(self._default_export_part_count()))
            spin_parts.setToolTip("Recoverable .part segments (1–128).")
            opts_form.addRow("Part Count (1–128)", spin_parts)
            lossy = audio_format in {"mp3", "opus", "ogg"}
            spin_br = QSpinBox()
            spin_br.setRange(32, 512)
            spin_br.setSingleStep(16)
            try:
                spin_br.setValue(int(getattr(self, "_last_audio_bitrate_kbps", 192) or 192))
            except Exception:
                spin_br.setValue(192)
            spin_br.setSuffix(" kbps")
            spin_br.setToolTip(
                "Target audio bitrate for lossy formats (mp3 / opus / ogg). "
                "WAV / FLAC / AIFF / CAF ignore this (lossless or PCM)."
            )
            spin_br.setEnabled(lossy)
            opts_form.addRow("Bitrate", spin_br)
            if not lossy:
                opts_form.addRow(QLabel("Bitrate applies to MP3 / Opus / OGG only."))
            opts_form.addRow(QLabel(f"Final file: {os.path.basename(file_path)}"))
            opts_btns = QDialogButtonBox(
                QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel
            )
            opts_btns.accepted.connect(opts_dlg.accept)
            opts_btns.rejected.connect(opts_dlg.reject)
            opts_form.addRow(opts_btns)
            if opts_dlg.exec() != QDialog.DialogCode.Accepted:
                return
            n_parts = max(1, min(128, int(spin_parts.value())))
            self._last_export_part_count = n_parts
            audio_bitrate_kbps = int(spin_br.value()) if lossy else None
            if audio_bitrate_kbps is not None:
                self._last_audio_bitrate_kbps = audio_bitrate_kbps
            if hasattr(self, 'scope_status_label'):
                _br_tag = f" @ {audio_bitrate_kbps}k" if audio_bitrate_kbps else ""
                self.scope_status_label.setText(
                    f"📊 Rendering canonical master mix → {audio_format.upper()}{_br_tag} "
                    f"({n_parts} part{'s' if n_parts != 1 else ''})…"
                )
            QApplication.processEvents()
            master, sample_rate = self._render_mixdown_buffer()
            master = np.nan_to_num(np.asarray(master, dtype=np.float32), nan=0.0, posinf=1.0, neginf=-1.0)
            master = self._bake_dj_write(master, sample_rate)
            # MASTER_HARDCLIP_2026: no normalize/limiter/EQ on the final bus.
            master, _ = self._master_hardclip(master, sample_rate, apply_master_vol=True)
            pcm = (np.clip(master, -1.0, 1.0) * 32767.0).astype(np.int16)
            provenance = self._export_provenance_payload()
            prov_bytes = provenance.encode("utf-8") if isinstance(provenance, str) else provenance
            file_path, audio_parts = self._write_audio_parts_and_final(
                file_path, sample_rate, pcm, n_parts=n_parts,
                provenance_bytes=prov_bytes, audio_format=audio_format,
                audio_bitrate_kbps=audio_bitrate_kbps,
            )
            if audio_parts and hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(
                    f"📊 Wrote {len(audio_parts)} audio .part file(s) + final {audio_format.upper()}"
                )
            if isinstance(getattr(self, 'visual_oscilloscope', None), VisualOscilloscope):
                prev = master[:min(len(master), sample_rate // 2)]
                if len(prev):
                    idx = np.linspace(0, len(prev)-1, 100).astype(int)
                    self.visual_oscilloscope.update_waveform(prev[idx])
            self.export_counter += 1
            if hasattr(self, 'scope_status_label'):
                self.scope_status_label.setText(f"📊 Export complete → {os.path.basename(file_path)}")
        except Exception as e:
            print(f"[System] Export error: {e}")
            if hasattr(self, 'scope_status_label'):
                self.scope_status_label.setText(f"📊 Export error: {e}")
            QMessageBox.critical(self, "Export Error", str(e))

    # =====================================================================
    # VIDEO_EXPORT_FEATURE — 2.5D render + audio mux + optional source-video blend
    # Supports Video+Audio / Video-only in mp4|webm|avi with encoder auto-fallback.
    # =====================================================================
    def _resolve_ffmpeg_binary(self):
        """Locate a usable ffmpeg binary (PATH, ./bin, /bin, common prefixes)."""
        candidates = []
        which = shutil.which("ffmpeg")
        if which:
            candidates.append(which)
        try:
            here = os.path.dirname(os.path.abspath(__file__))
        except Exception:
            here = os.getcwd()
        for p in (
            os.path.join(here, "bin", "ffmpeg"),
            os.path.join(here, "ffmpeg"),
            "/bin/ffmpeg",
            "/usr/bin/ffmpeg",
            "/usr/local/bin/ffmpeg",
            os.path.expanduser("~/bin/ffmpeg"),
        ):
            if p and os.path.isfile(p) and os.access(p, os.X_OK):
                candidates.append(p)
        seen, ordered = set(), []
        for c in candidates:
            if c not in seen:
                seen.add(c)
                ordered.append(c)
        return ordered[0] if ordered else None

    def _ffmpeg_encoder_args(self, ffmpeg_bin, container="mp4"):
        """Pick video/audio encoder args this ffmpeg build actually supports."""
        try:
            proc = subprocess.run(
                [ffmpeg_bin, "-hide_banner", "-encoders"],
                capture_output=True, text=True, timeout=12,
            )
            listing = (proc.stdout or "") + "\n" + (proc.stderr or "")
        except Exception:
            listing = ""

        def has(name):
            return (" " + name + " ") in (" " + listing.replace("\n", " ") + " ")

        container = (container or "mp4").lower().lstrip(".")
        vcodec, vargs = None, []

        # Container-aware preference
        if container == "webm":
            order = ["libvpx-vp9", "libvpx", "libx264", "mpeg4", "mjpeg"]
        elif container == "avi":
            order = ["mpeg4", "libxvid", "msmpeg4v2", "libx264", "mjpeg"]
        else:  # mp4 and default
            order = ["libx264", "libopenh264", "h264_mf", "libxvid", "mpeg4",
                     "libvpx-vp9", "libvpx", "mjpeg"]

        presets = {
            "libx264": ["-preset", "medium", "-crf", "18"],
            "libopenh264": ["-b:v", "2M"],
            "h264_mf": ["-b:v", "2M"],
            "libxvid": ["-qscale:v", "5"],
            "mpeg4": ["-qscale:v", "5"],
            "msmpeg4v2": ["-qscale:v", "5"],
            "libvpx-vp9": ["-b:v", "1.5M", "-row-mt", "1"],
            "libvpx": ["-b:v", "1.5M"],
            "mjpeg": ["-q:v", "5"],
        }
        for name in order:
            if has(name):
                vcodec, vargs = name, list(presets.get(name, ["-b:v", "2M"]))
                break
        if vcodec is None:
            vcodec, vargs = "mpeg4", ["-qscale:v", "5"]

        # Audio
        if container == "webm":
            a_order = ["libopus", "libvorbis", "aac", "libmp3lame"]
        elif container == "avi":
            a_order = ["libmp3lame", "aac", "libvorbis"]
        else:
            a_order = ["aac", "libmp3lame", "libvorbis", "libopus"]
        acodec, aargs = None, []
        a_presets = {
            "aac": ["-b:a", "192k"],
            "libmp3lame": ["-b:a", "192k"],
            "libvorbis": ["-b:a", "160k"],
            "libopus": ["-b:a", "128k"],
        }
        for name in a_order:
            if has(name):
                acodec, aargs = name, list(a_presets.get(name, ["-b:a", "192k"]))
                break
        if acodec is None:
            acodec, aargs = "aac", ["-b:a", "192k"]

        print(f"[Video] ffmpeg={ffmpeg_bin} container={container} vcodec={vcodec} acodec={acodec}")
        return vcodec, vargs, acodec, aargs


    def _composition_meta_for_game(self):
        """Snapshot for game classification — same lattice as save/export.

        Global Player algo fingerprint is included so the video-game interpreter
        responds to Script/Domain/Wire/Params without ever mutating the seed.
        """
        gas = getattr(self, "global_algo_state", {}) or {}
        try:
            algo_fp = hashlib.sha256(
                json.dumps(gas, sort_keys=True, default=str).encode("utf-8")
            ).hexdigest()[:16]
        except Exception:
            algo_fp = "0" * 16
        live_p = ""
        try:
            pl = getattr(self, "master_playlist_data", None) or []
            if pl and isinstance(pl[0], dict) and pl[0].get("live_parametrics"):
                live_p = str(pl[0].get("live_parametrics"))[:240]
        except Exception:
            pass
        notes = ""
        try:
            if getattr(self, "qe_notes", None) is not None:
                notes = self.qe_notes.toPlainText()[:200]
        except Exception:
            pass
        # Algorithm application is composition state, not merely UI state.
        # Export both the effective per-row step algorithms and their canonical
        # digest so video/audio/game consumers see the same applied composition.
        step_rows = []
        for _r, _e in enumerate(getattr(self, "master_playlist_data", []) or []):
            if not isinstance(_e, dict):
                continue
            step_rows.append({
                "row": int(_r),
                "scope": str(_e.get("step_algorithm_scope", "")),
                "algorithm": str(_e.get("step_algorithm", "")),
                "refs": list(_e.get("step_algorithm_refs") or []),
            })
        try:
            step_algo_fingerprint = hashlib.sha256(
                json.dumps(step_rows, sort_keys=True, default=str).encode("utf-8")
            ).hexdigest()[:16]
        except Exception:
            step_algo_fingerprint = "0" * 16
        # Engine bits from live toggles — these control game + video identity.
        # Instrument count is recorded for UI only; classify ignores it.
        rnd_on = bool(getattr(self, "btn_local_randomize", None) and self.btn_local_randomize.isChecked())
        pl_on = bool(getattr(self, "btn_local_phase_lock", None) and self.btn_local_phase_lock.isChecked())
        # CANONICAL_COMMAND_2026: master vector, xmods, synth features and
        # resonance (always 50–150%) travel with the game under canonical authority.
        master_vector = (0.0, 0.0, 0.0)
        try:
            if hasattr(self, "_master_vector_effective"):
                mv = self._master_vector_effective()
                master_vector = (float(mv[0]), float(mv[1]), float(mv[2]))
        except Exception:
            pass
        st = getattr(self, "master_vector_state", None) or {}
        gms = getattr(self, "global_mod_state", None) or {}
        resonance = float(getattr(self, "canonical_resonance_factor", CANONICAL_RESONANCE_DEFAULT) or CANONICAL_RESONANCE_DEFAULT)
        if not math.isfinite(resonance):
            resonance = 1.50
        return {
            "bpm": float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0,
            "seq_length": int(self.spin_seq_length.value()) if hasattr(self, "spin_seq_length") else 16,
            "playlist_rows": int(self.spin_playlist_length.value()) if hasattr(self, "spin_playlist_length") else 64,
            "n_instruments": len(getattr(self, "instrument_names_48", []) or []),
            "goava_active": bool(getattr(self, "goava_active", False)),
            "randomizer_active": rnd_on,
            "phase_lock_active": pl_on,
            "seed": float(self.get_numeric_seed()) if hasattr(self, "get_numeric_seed") else 0.0,
            "live_parametrics": live_p,
            "goava_group_phase": bool(getattr(self, "goava_active", False)),
            "global_algo": gas,
            "algorithm_xmod_local": float(getattr(self, "local_algorithm_xmod", 1.0)),
            "algorithm_xmod_global": float(getattr(self, "global_algorithm_xmod", 1.0)),
            "edit_algorithm_per_sequence": bool(getattr(self, "edit_algorithm_per_sequence", False)),
            "global_algo_fingerprint": algo_fp,
            "step_algorithms": step_rows,
            "step_algorithm_fingerprint": step_algo_fingerprint,
            "live_dj_goava": bool(getattr(self, "live_dj_goava", False)),
            "live_dj_random": bool(getattr(self, "live_dj_random", False)),
            "project_notes": notes,
            "master_vector": master_vector,
            "master_vector_drive": float(st.get("drive", 0.50) or 0.50),
            "master_vector_enabled": bool(st.get("enabled", True)),
            "global_xmod": float(gms.get("xmod", 1.0) or 1.0),
            "global_input_xmod": float(gms.get("input_xmod", 1.0) or 1.0),
            "global_mod_state": {k: float(gms.get(k, 1.0) or 1.0) for k in ("xmod", "input_xmod", "synth", "patch", "script", "domain")},
            "canonical_resonance_factor": resonance,
            "resonance_min": 0.50,
            "resonance_max": 1.50,
            "wavetable_projector": dict(getattr(self, "wavetable_projector_state", {}) or {}),
            "automator_timing_mode": str(getattr(self, "automator_timing_mode", "wrap")),
            "sequencer_automation_points": list(getattr(self, "sequencer_automation_points", []) or [])[:256],
            # User-owned TrackOffset (engines respond; not a canonical write handle)
            "global_track_offset": float(getattr(self, "global_track_offset", 0.0) or 0.0),
            "track_offset": float(getattr(self, "global_track_offset", 0.0) or 0.0),
        }

    def _classify_live_game(self):
        """Deterministic unique non-redundant game identity from the live seed."""
        global _vge
        if _vge is None:
            try:
                import videogame_engine as _vge
            except Exception as e:
                raise RuntimeError(f"videogame_engine not available: {e}")
        meta = self._composition_meta_for_game()
        # Prefer first playlist row live_parametrics if present
        try:
            pl = getattr(self, "master_playlist_data", None) or []
            if pl and isinstance(pl[0], dict) and pl[0].get("live_parametrics"):
                meta["live_parametrics"] = str(pl[0].get("live_parametrics"))[:240]
        except Exception:
            pass
        return _vge.classify_from_composition(
            meta["seed"],
            bpm=meta["bpm"],
            seq_length=meta["seq_length"],
            playlist_rows=meta["playlist_rows"],
            n_instruments=meta.get("n_instruments", 8),  # ignored by identity
            goava_active=meta["goava_active"],
            randomizer_active=bool(meta.get("randomizer_active", False)),
            phase_lock_active=bool(meta.get("phase_lock_active", False)),
            live_parametrics=meta.get("live_parametrics"),
            global_algo_fingerprint=meta.get("global_algo_fingerprint"),
            global_algo=meta.get("global_algo"),
            step_algorithm_fingerprint=meta.get("step_algorithm_fingerprint"),
            step_algorithms=meta.get("step_algorithms"),
            live_dj_goava=meta.get("live_dj_goava"),
            live_dj_random=meta.get("live_dj_random"),
        ), meta

    def _on_export_videogame_scripts(self):
        """Export the video game as one .zip package: deterministic script +
        identity JSON + Windows/macOS/Linux launchers, all from the live seed."""
        try:
            identity, meta = self._classify_live_game()
        except Exception as e:
            QMessageBox.warning(self, "Video Game", str(e))
            return
        default_name = os.path.join(
            self._games_dir(), f"game_{identity.composition_fingerprint}.zip"
        )
        path, _filter = QFileDialog.getSaveFileName(
            self, "Export Video Game Package", default_name,
            "Video Game Package (*.zip);;All files (*)",
        )
        if not path:
            return
        if not path.lower().endswith(".zip"):
            path = path + ".zip"
        try:
            global _vge
            _prov = json.loads(self._export_provenance_payload())
            out = _vge.package_game_zip(identity, path, meta, {"provenance.mgpr": _prov})
            self._last_videogame_path = out
            self._last_videogame_identity = identity.to_dict()
            QMessageBox.information(
                self, "Video Game Exported",
                f"{identity.title}\n\nPackage (.zip):\n{out}\n\n"
                f"Includes: game script · identity JSON · launch_windows.bat · "
                f"launch_macos.command · launch_linux.sh\n\n"
                f"genre={identity.genre} camera={identity.camera}\n"
                f"objective={identity.objective} difficulty={identity.difficulty}\n"
                f"level_type={identity.level_type} sigil_count={identity.sigil_count}\n"
                f"world_fingerprint={identity.world_fingerprint}"
            )
        except Exception as e:
            QMessageBox.warning(self, "Export failed", str(e))

    def _open_performance(self):
        """Open/toggle the live Performance workspace inside the main editor.

        Performance is deliberately non-modal: transport, fullscreen playback and
        the scientific editor remain live while the same host engine is manipulated.
        The dock can float on a second display/tablet-style layout or remain tabbed
        with other Qt docks.  Reopening the button toggles the existing instance.
        """
        try:
            dock = getattr(self, "_performance_dock", None)
            if dock is not None:
                dock.setVisible(not dock.isVisible())
                if dock.isVisible():
                    dock.raise_()
                return dock

            from performance import Performance
            panel = Performance(self, parent=self)
            # Embed the QDialog as an ordinary dock widget instead of executing it
            # modally. Qt accepts this once the window flag is changed to Widget.
            panel.setWindowFlags(Qt.WindowType.Widget)
            panel.setModal(False)

            dock = QDockWidget("Performance — Live Operation Station", self)
            dock.setObjectName("groovebox_performance_dock")
            dock.setAllowedAreas(
                Qt.DockWidgetArea.LeftDockWidgetArea | Qt.DockWidgetArea.RightDockWidgetArea |
                Qt.DockWidgetArea.TopDockWidgetArea | Qt.DockWidgetArea.BottomDockWidgetArea
            )
            dock.setFeatures(
                QDockWidget.DockWidgetFeature.DockWidgetMovable |
                QDockWidget.DockWidgetFeature.DockWidgetFloatable |
                QDockWidget.DockWidgetFeature.DockWidgetClosable
            )
            dock.setWidget(panel)
            self.addDockWidget(Qt.DockWidgetArea.RightDockWidgetArea, dock)
            self._performance_panel = panel
            self._performance_dock = dock
            dock.show()
            dock.raise_()
            return dock
        except Exception as e:
            QMessageBox.warning(self, "Performance", f"Could not open Performance:\n{e}")
            return None

    # Compatibility for project scripts that still call the old method.
    def _open_pi_media_hub(self):
        return self._open_performance()

    def _on_play_videogame(self):
        """Build a live game .py from the composition and open the start UI (splash + options)."""
        # GAME_CROSS_DEACTIVATE: launching the game always stops whichever
        # audio transport is active so two playback modes cannot overlap.
        try:
            self.stop_playback()
        except Exception:
            pass
        try:
            identity, meta = self._classify_live_game()
        except Exception as e:
            QMessageBox.warning(self, "Video Game", str(e))
            return
        dlg = QDialog(self)
        dlg.setWindowTitle(f"Play Video Game — {identity.title[:48]}")
        dlg.resize(520, 420)
        dlg.setStyleSheet(DAW_STYLE if "DAW_STYLE" in dir() else "")
        lay = QVBoxLayout(dlg)
        # Splash / identity
        lay.addWidget(QLabel(f"<b>{identity.title}</b>"))
        lay.addWidget(QLabel(
            f"genre=<b>{identity.genre}</b> · camera=<b>{identity.camera}</b> · "
            f"topology=<b>{identity.topology}</b><br>"
            f"social=<b>{identity.social}</b> · mood=<b>{identity.mood}</b> · "
            f"fingerprint=<code>{identity.composition_fingerprint}</code>"
        ))
        # WORLD_FACTORS_2026: objective / difficulty / level type / sigils are
        # part of the same f(seed) world coordinates as genre/camera.
        lay.addWidget(QLabel(
            f"objective=<b>{identity.objective}</b> · difficulty=<b>{identity.difficulty}</b>"
            f" · level=<b>{identity.level_type}</b><br>"
            f"sigil_count=<b>{identity.sigil_count}</b> · "
            f"world_fingerprint=<code>{identity.world_fingerprint}</code>"
        ))
        # Splash length = sequence bars of composition
        lay.addWidget(QLabel(
            f"Splash will play the composition bed for <b>{identity.splash_bars}</b> sequence steps "
            f"@ {meta['bpm']:.0f} BPM before the start screen."
        ))
        # LAN_GAME_UI_2026: expose the engine's existing authoritative TCP
        # transport for every generated identity. --host/--connect force LAN
        # networking even when the seed classified the social mode as solo.
        net_group = QGroupBox("📶 Local Wi‑Fi / Ethernet")
        net_form = QFormLayout(net_group)
        net_mode = QComboBox()
        net_mode.addItems(["Solo", "Host on local network", "Join local network"])
        try: net_mode.setCurrentIndex(max(0, min(2, int(getattr(self, "_preferred_game_net_mode", 0)))))
        except Exception: pass
        net_form.addRow("Mode", net_mode)
        port_spin = QSpinBox(); port_spin.setRange(1024, 65535)
        port_spin.setValue(int(getattr(self, "_preferred_game_net_port", identity.host_port) or identity.host_port))
        net_form.addRow("Port", port_spin)
        connect_edit = QLineEdit(); connect_edit.setPlaceholderText("192.168.1.42:27777")
        connect_edit.setText(str(getattr(self, "_preferred_game_connect", "") or ""))
        net_form.addRow("Join address", connect_edit)
        lan_note = QLabel("Host and Join synchronize live game state over the same local Wi‑Fi/LAN. Router port forwarding is only needed for Internet play.")
        lan_note.setWordWrap(True); net_form.addRow(lan_note)
        lay.addWidget(net_group)
        status = QLabel("Ready to build live test copy.")
        lay.addWidget(status)
        btn_row = QHBoxLayout()
        btn_build = QPushButton("▶ Build & Run Live Test")
        btn_export = QPushButton("📦 Export Scripts…")
        btn_close = QPushButton("Close")
        btn_row.addWidget(btn_build)
        btn_row.addWidget(btn_export)
        btn_row.addWidget(btn_close)
        lay.addLayout(btn_row)

        def _build_and_run():
            import tempfile, subprocess, sys as _sys
            global _vge
            try:
                td = tempfile.mkdtemp(prefix="groovebox_game_")
                script = _vge.export_game_files(identity, td, meta, {"provenance.mgpr": json.loads(self._export_provenance_payload())})
                self._last_videogame_path = script
                args = [_sys.executable, script]
                mode = int(net_mode.currentIndex())
                if mode == 1:
                    args += ["--host", f"--port={int(port_spin.value())}"]
                elif mode == 2:
                    addr = connect_edit.text().strip()
                    if not addr:
                        raise RuntimeError("Enter the host IP:port before joining a local-network game.")
                    if ":" not in addr:
                        addr = f"{addr}:{int(port_spin.value())}"
                    args.append(f"--connect={addr}")
                status.setText(f"Launching:\n{script}")
                subprocess.Popen(args, cwd=td)
            except Exception as e:
                status.setText(f"Error: {e}")
                QMessageBox.warning(dlg, "Run failed", str(e))

        btn_build.clicked.connect(_build_and_run)
        btn_export.clicked.connect(lambda: (dlg.accept(), self._on_export_videogame_scripts()))
        btn_close.clicked.connect(dlg.accept)
        dlg.exec()

    def export_video_dialog(self, include_audio=True, container="mp4"):
        """Render 2.5D frames in 16 recoverable .part segments inside the
        chosen render destination (never /tmp). User controls resolution;
        size is predicted before work starts. container: mp4|webm|avi.

        PART_FILE_2026 video path:
          - intermediates live next to the final file as
            <stem>.partNN.<container>.part  (16 parts)
          - each part is encoded independently so peak disk is ~1/16 of a
            full frame dump; completed parts survive a crash for resume
          - final output is written as <out>.part then atomically renamed
        """
        try:
            from PIL import Image
        except Exception as e:
            QMessageBox.critical(self, "Video Export Error", f"PIL required: {e}")
            return

        ffmpeg = self._resolve_ffmpeg_binary()
        if not ffmpeg:
            QMessageBox.critical(
                self, "Video Export Error",
                "ffmpeg not found. Install a full build (see Help) or place "
                "ffmpeg at ./bin/ffmpeg or on PATH."
            )
            return

        container = (container or "mp4").lower().lstrip(".")
        if container not in ("mp4", "webm", "avi"):
            container = "mp4"
        vcodec, vargs, acodec, aargs = self._ffmpeg_encoder_args(ffmpeg, container)

        # --- resolution control ---
        try:
            def_w, def_h = self._export_frame_size()
        except Exception:
            def_w, def_h = 1280, 720
        res_dlg = QDialog(self)
        res_dlg.setWindowTitle(
            "Video + Audio Export — Resolution, FPS & Parts" if include_audio else "Video Export — Resolution, FPS & Parts"
        )
        res_dlg.setStyleSheet(getattr(self, "styleSheet", lambda: "")() or "")
        form = QFormLayout(res_dlg)
        spin_w = QSpinBox(); spin_w.setRange(160, 7680); spin_w.setSingleStep(2); spin_w.setValue(int(def_w))
        spin_h = QSpinBox(); spin_h.setRange(120, 4320); spin_h.setSingleStep(2); spin_h.setValue(int(def_h))
        form.addRow("Width (px)", spin_w)
        form.addRow("Height (px)", spin_h)
        spin_fps = QSpinBox()
        spin_fps.setRange(1, 120)
        spin_fps.setSingleStep(1)
        try:
            spin_fps.setValue(int(getattr(self, "_last_export_fps", 24) or 24))
        except Exception:
            spin_fps.setValue(24)
        spin_fps.setToolTip(
            "Export frame rate (1–120 fps). Higher FPS = more frames, longer encode, smoother motion."
        )
        form.addRow("FPS", spin_fps)
        spin_audio_br = QSpinBox()
        spin_audio_br.setRange(32, 512)
        spin_audio_br.setSingleStep(16)
        try:
            spin_audio_br.setValue(int(getattr(self, "_last_audio_bitrate_kbps", 192) or 192))
        except Exception:
            spin_audio_br.setValue(192)
        spin_audio_br.setSuffix(" kbps")
        spin_audio_br.setEnabled(bool(include_audio))
        spin_audio_br.setToolTip("Audio bitrate for the muxed track (when Video + Audio is selected).")
        form.addRow("Audio bitrate", spin_audio_br)
        spin_parts = QSpinBox()
        spin_parts.setRange(1, 128)
        spin_parts.setSingleStep(1)
        spin_parts.setValue(int(self._default_export_part_count()))
        spin_parts.setToolTip(
            "Recoverable .part segments (1–128). Video writes <stem>.partNN.<container>; "
            "with audio, also <stem>.audio.partNN.wav. Completed parts can resume after a crash."
        )
        form.addRow("Part Count (1–128)", spin_parts)
        info = QLabel(
            "Video parts and (when enabled) matching audio parts are written next to the final file. "
            "Size estimate appears after you choose the output path."
        )
        info.setWordWrap(True)
        form.addRow(info)
        btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        btns.accepted.connect(res_dlg.accept)
        btns.rejected.connect(res_dlg.reject)
        form.addRow(btns)
        if res_dlg.exec() != QDialog.DialogCode.Accepted:
            return
        w = int(spin_w.value()); h = int(spin_h.value())
        w -= w % 2; h -= h % 2
        w = max(160, w); h = max(120, h)
        N_PARTS = max(1, min(128, int(spin_parts.value())))
        self._last_export_part_count = N_PARTS
        export_fps = max(1, min(120, int(spin_fps.value())))
        self._last_export_fps = export_fps
        if include_audio:
            self._last_audio_bitrate_kbps = max(32, min(512, int(spin_audio_br.value())))
            # Override encoder audio bitrate args for this export.
            aargs = ["-b:a", f"{int(self._last_audio_bitrate_kbps)}k"]

        default_name = os.path.join(
            self._exports_dir(), f"groovebox_video_{self.export_counter:03d}.{container}"
        )
        filters = {
            "mp4": "MP4 Video (*.mp4)",
            "webm": "WebM Video (*.webm)",
            "avi": "AVI Video (*.avi)",
        }
        file_filter = f"{filters[container]};;All Files (*)"
        out_path, _ = QFileDialog.getSaveFileName(
            self, "Export Video", default_name, file_filter
        )
        if not out_path:
            return
        if not out_path.lower().endswith("." + container):
            out_path = out_path + "." + container

        dest_dir = os.path.dirname(os.path.abspath(out_path)) or self._exports_dir()
        try:
            os.makedirs(dest_dir, exist_ok=True)
        except Exception:
            pass
        stem = os.path.splitext(os.path.basename(out_path))[0]
        # N_PARTS already chosen in the resolution/parts dialog above.

        if hasattr(self, 'scope_status_label'):
            mode = "Video + Audio" if include_audio else "Video only"
            self.scope_status_label.setText(f"🎬 Preparing {mode} ({container}) {w}x{h}…")
        QApplication.processEvents()

        master, sr = self._render_mixdown_buffer()
        master = np.nan_to_num(np.asarray(master, dtype=np.float32), nan=0.0, posinf=1.0, neginf=-1.0)
        master = self._bake_dj_write(master, sr)
        provenance = self._export_provenance_payload()
        fps = int(getattr(self, "_last_export_fps", 24) or 24)
        fps = max(1, min(120, fps))
        frame_samples = max(1, int(sr / fps))
        n_frames = max(1, int(np.ceil(len(master) / frame_samples)))
        n_frames = min(n_frames, fps * 60 * 30)  # soft 30 min ceiling
        duration_s = n_frames / float(fps)

        # --- size prediction ---
        # Rough final-video estimate: ~CRF18 ~0.15–0.35 bits/pixel/frame + audio.
        bpp = 0.22
        est_video_bytes = int(n_frames * w * h * bpp / 8.0)
        est_audio_bytes = int(duration_s * 192000 / 8.0) if include_audio else 0
        # Peak intermediate: one part's frames as PNG (~0.4 of raw RGB) + that part video
        frames_per_part = (n_frames + N_PARTS - 1) // N_PARTS
        est_peak_part_png = int(frames_per_part * w * h * 3 * 0.35)
        est_peak = est_peak_part_png + (est_video_bytes // N_PARTS) + est_audio_bytes
        def _fmt(n):
            for unit, div in (("GB", 1<<30), ("MB", 1<<20), ("KB", 1<<10)):
                if n >= div:
                    return f"{n / div:.2f} {unit}"
            return f"{n} B"
        size_msg = (
            f"Resolution: {w}×{h} @ {fps} fps\n"
            f"Frames: {n_frames}  (~{duration_s:.1f}s)  in {N_PARTS} video part(s)\n"
            + (
                f"Audio: {N_PARTS} × {stem}.audio.partNN.wav (plus full mux WAV)\n"
                if include_audio else "Audio: none (video only)\n"
            )
            + f"Predicted final size: ~{_fmt(est_video_bytes + est_audio_bytes)}\n"
            f"Predicted peak temp (1 part): ~{_fmt(est_peak)}\n"
            f"Part files will be written under:\n{dest_dir}\n\nContinue?"
        )
        reply = QMessageBox.question(
            self, "Export size prediction", size_msg,
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.Yes,
        )
        if reply != QMessageBox.StandardButton.Yes:
            return

        # Recovery: reuse completed part videos if present and non-empty
        part_paths = []
        for pi in range(N_PARTS):
            part_paths.append(os.path.join(dest_dir, f"{stem}.part{pi:02d}.{container}"))
        existing = [p for p in part_paths if os.path.isfile(p) and os.path.getsize(p) > 64]
        resume = False
        if existing:
            r = QMessageBox.question(
                self, "Recover partial export?",
                f"Found {len(existing)}/{N_PARTS} existing .part segment(s) in the render folder.\n"
                "Yes = resume (skip completed parts)\nNo = delete them and start fresh",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.Yes,
            )
            resume = (r == QMessageBox.StandardButton.Yes)
            if not resume:
                for p in part_paths:
                    try:
                        if os.path.isfile(p):
                            os.remove(p)
                    except Exception:
                        pass
                for p in part_paths:
                    try:
                        pp = p + ".part"
                        if os.path.isfile(pp):
                            os.remove(pp)
                    except Exception:
                        pass

        audio_path = None
        audio_part_paths = []
        if include_audio:
            n_audio = min(len(master), int(round(duration_s * sr)))
            audio_clip = master[:max(1, n_audio)]
            pcm = (np.clip(audio_clip, -1, 1) * 32767).astype(np.int16)
            # Full mux source (kept for final concat with video).
            audio_path = os.path.join(dest_dir, f".{stem}.audio.full.part.wav")
            try:
                _write_wav_with_provenance(audio_path, sr, pcm)
            except Exception as e:
                raise RuntimeError(f"Could not write audio temp: {e}")
            # Matching recoverable audio .partNN files alongside video parts.
            total = int(pcm.shape[0])
            base = max(1, total // max(1, N_PARTS))
            rem = total % max(1, N_PARTS)
            offset = 0
            for pi in range(N_PARTS):
                take = base + (1 if pi < rem else 0)
                if offset >= total:
                    chunk = pcm[-1:]
                else:
                    chunk = pcm[offset:offset + max(1, take)]
                    offset += max(1, take)
                ap = os.path.join(dest_dir, f"{stem}.audio.part{pi:02d}.wav")
                try:
                    _write_wav_with_provenance(ap, sr, chunk)
                    audio_part_paths.append(ap)
                except Exception as e:
                    print(f"[Export] audio part {pi}: {e}")
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(
                    f"🎬 Wrote {len(audio_part_paths)} audio .part file(s) + full mux WAV"
                )
                QApplication.processEvents()

        _aim = getattr(self, 'active_instrument_memory', None)
        _nmem = len(_aim) if hasattr(_aim, '__len__') else int(getattr(self, 'synth_count', 48) or 48)
        # Export is intentionally isolated from the live preview engine.  A fresh
        # renderer plus explicit frame indices makes the file a pure function of
        # the composition inputs rather than whatever the UI rendered beforehand.
        eng = VideoSynthEngine(_nmem)
        if hasattr(eng, 'bind_app'):
            eng.bind_app(self)

        pix = ["-pix_fmt", "yuv420p"] if vcodec not in ("mjpeg",) else []
        try:
            for pi in range(N_PARTS):
                part_out = part_paths[pi]
                if resume and os.path.isfile(part_out) and os.path.getsize(part_out) > 64:
                    if hasattr(self, 'scope_status_label'):
                        self.scope_status_label.setText(f"🎬 Part {pi+1}/{N_PARTS} already done — skip")
                        QApplication.processEvents()
                    continue

                f0 = pi * frames_per_part
                f1 = min(n_frames, (pi + 1) * frames_per_part)
                if f0 >= f1:
                    f1 = f0 + 1
                    f0 = max(0, n_frames - 1)

                part_tmp = part_out + ".part"
                _muxer = {"mp4": "mp4", "webm": "webm", "avi": "avi"}.get(container, container)
                cmd = [
                    ffmpeg, "-y",
                    "-f", "rawvideo", "-pix_fmt", "rgb24",
                    "-s", f"{w}x{h}", "-framerate", str(fps), "-i", "-",
                    "-map", "0:v:0",
                    "-c:v", vcodec, *vargs, *pix,
                    "-an", "-f", _muxer, part_tmp,
                ]
                proc = subprocess.Popen(
                    cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE
                )
                try:
                    for local_count, fi in enumerate(range(f0, f1), 1):
                        a = fi * frame_samples
                        b = min(len(master), a + frame_samples)
                        ph = fi / max(n_frames - 1, 1)
                        eng.set_waveform(master[a:b], playhead=ph)
                        frame = eng.render_frame(w, h, export=True, frame_index=fi)
                        if frame.dtype != np.uint8:
                            frame = np.asarray(frame, dtype=np.uint8)
                        proc.stdin.write(np.ascontiguousarray(frame).tobytes())
                        if local_count % 8 == 0 and hasattr(self, 'scope_status_label'):
                            self.scope_status_label.setText(
                                f"🎬 Part {pi+1}/{N_PARTS}  frames {local_count}/{f1-f0}…"
                            )
                            QApplication.processEvents()
                    proc.stdin.close()
                    proc.stdin = None
                    stdout, stderr = proc.communicate()
                except Exception:
                    try:
                        if proc.stdin is not None:
                            proc.stdin.close()
                    except Exception:
                        pass
                    try:
                        proc.kill()
                    except Exception:
                        pass
                    proc.wait()
                    raise
                if proc.returncode != 0:
                    err = (stderr.decode(errors="replace") if isinstance(stderr, bytes) else (stderr or stdout or ""))[-2200:]
                    raise RuntimeError(f"Part {pi+1}/{N_PARTS} encode failed:\\n{err}")
                os.replace(part_tmp, part_out)

            # Build concat list
            list_path = os.path.join(dest_dir, f".{stem}.concat.part.txt")
            with open(list_path, "w", encoding="utf-8") as lf:
                for pp in part_paths:
                    if not os.path.isfile(pp):
                        raise RuntimeError(f"Missing part segment: {pp}")
                    # ffmpeg concat demuxer needs escaped single quotes
                    esc = pp.replace("'", "'\\''")
                    lf.write(f"file '{esc}'\n")

            final_tmp = out_path + ".part"
            # Same issue as the per-part encode: final_tmp ends in ".part", so
            # ffmpeg can't infer the output muxer from the extension — set it
            # explicitly via -f, matching the target container.
            if include_audio and audio_path and os.path.isfile(audio_path):
                cmd = [
                    ffmpeg, "-y",
                    "-f", "concat", "-safe", "0", "-i", list_path,
                    "-i", audio_path,
                    "-map", "0:v:0", "-map", "1:a:0",
                    "-t", f"{duration_s:.6f}",
                    "-c:v", "copy",
                    "-c:a", acodec, *aargs,
                    "-metadata", f"comment={provenance}",
                    "-shortest",
                    "-f", _muxer,
                    final_tmp,
                ]
            else:
                cmd = [
                    ffmpeg, "-y",
                    "-f", "concat", "-safe", "0", "-i", list_path,
                    "-map", "0:v:0",
                    "-t", f"{duration_s:.6f}",
                    "-c:v", "copy",
                    "-metadata", f"comment={provenance}",
                    "-an",
                    "-f", _muxer,
                    final_tmp,
                ]
            proc = subprocess.run(cmd, capture_output=True, text=True)
            if proc.returncode != 0:
                # fallback: re-encode if stream copy fails (codec/container mismatch)
                err1 = (proc.stderr or proc.stdout or "")[-1200:]
                if include_audio and audio_path and os.path.isfile(audio_path):
                    cmd = [
                        ffmpeg, "-y",
                        "-f", "concat", "-safe", "0", "-i", list_path,
                        "-i", audio_path,
                        "-map", "0:v:0", "-map", "1:a:0",
                        "-t", f"{duration_s:.6f}",
                        "-c:v", vcodec, *vargs, *pix,
                        "-c:a", acodec, *aargs,
                        "-metadata", f"comment={provenance}",
                        "-shortest",
                        "-f", _muxer,
                        final_tmp,
                    ]
                else:
                    cmd = [
                        ffmpeg, "-y",
                        "-f", "concat", "-safe", "0", "-i", list_path,
                        "-map", "0:v:0",
                        "-t", f"{duration_s:.6f}",
                        "-c:v", vcodec, *vargs, *pix,
                        "-metadata", f"comment={provenance}",
                        "-an",
                        "-f", _muxer,
                        final_tmp,
                    ]
                proc = subprocess.run(cmd, capture_output=True, text=True)
                if proc.returncode != 0:
                    err = (proc.stderr or proc.stdout or "ffmpeg concat failed")[-2200:]
                    raise RuntimeError(f"Final mux failed:\n{err}\n(earlier copy attempt: {err1})")

            os.replace(final_tmp, out_path)

            # success: remove part segments + staging (optional keep for recovery —
            # user asked for .part in render dest; leave them unless clean succeeds)
            for pp in part_paths:
                try:
                    if os.path.isfile(pp):
                        os.remove(pp)
                except Exception:
                    pass
            try:
                if os.path.isfile(list_path):
                    os.remove(list_path)
            except Exception:
                pass
            if audio_path:
                try:
                    if os.path.isfile(audio_path):
                        os.remove(audio_path)
                except Exception:
                    pass
            self.export_counter += 1
            mode = "Video + Audio" if include_audio else "Video only"
            if hasattr(self, 'scope_status_label'):
                self.scope_status_label.setText(
                    f"🎬 {mode} exported → {os.path.basename(out_path)}  ({vcodec}/{acodec if include_audio else 'no-audio'}) {w}x{h}"
                )
            QMessageBox.information(
                self, "Export complete",
                f"Saved:\n{out_path}\n\n"
                f"Encoder: {vcodec}"
                + (f" + {acodec}" if include_audio else " (video only)")
                + f"\nResolution: {w}×{h}  ·  {n_frames} frames in {N_PARTS} video part(s)"
                + (
                    f"\nAudio parts: {len(audio_part_paths)} × {stem}.audio.partNN.wav"
                    if include_audio and audio_part_paths else ""
                )
            )
        except Exception as e:
            print(f"[Video] export error: {e}")
            QMessageBox.critical(self, "Video Export Error", str(e))
            # leave .part segments on disk for recovery

    def closeEvent(self, event):
        """Ensure audio, PKP, and background video rendering are torn down on close."""
        try:
            viewer = getattr(self, "video_synth_viewer", None)
            if viewer is not None:
                viewer.shutdown_rendering()
        except Exception:
            pass
        try:
            self.stop_playback()
        except Exception:
            pass
        try:
            self.pkp_pad_bank_active = False
        except Exception:
            pass
        super().closeEvent(event)


    def _open_global_algo_panel(self, which):
        """Open one of the four Global Player panels (script / domain / wire / params).

        Windows use the same translucent + math-decor chrome as the local synth
        editor. Edits write into self.global_algo_state only — never into the
        seed field or per-instrument seed scripts. Apply broadcasts to every
        instrument in parallel.
        """
        which = str(which or "script").lower()
        titles = {
            "script": "Global Script Algo",
            "domain": "Global Domain Algo",
            "wire": "Global Wire Algo",
            "params": "Global Algo Params",
        }
        title = titles.get(which, "Global Algo")
        attr = f"_gp_window_{which}"
        existing = getattr(self, attr, None)
        if existing is not None:
            try:
                if existing.isVisible():
                    existing.raise_()
                    existing.activateWindow()
                    return
            except Exception:
                pass

        if not hasattr(self, "global_algo_state") or not isinstance(self.global_algo_state, dict):
            self.global_algo_state = {
                "script": "# Global script algo\ndef global_script(t, name, i):\n    return 0.0\n",
                "domain": 'equation = "sin(t * MEUM)"\n',
                "wire": [],
                "params": {"mix": 0.35, "enable_script": True, "enable_domain": True, "enable_wire": True, "script_amount": 1.0, "domain_amount": 1.0, "wire_amount": 1.0},
            "apply_enabled": False,
            "user_data": True,
            "canonical_superwrite": True,
            }

        window = QWidget(None, Qt.WindowType.Window)
        window.setWindowTitle(title)
        window.resize(720, 560)
        window.setStyleSheet("""
            QWidget { background-color: rgba(28, 28, 32, 180); color: #b8f7e6; }
            QLabel { color: #8ff2dd; }
            QSlider::groove:horizontal { height: 4px; background: #1f2e44; border-radius: 2px; }
            QSlider::handle:horizontal { background: #ff6b00; width: 12px; margin: -4px 0; border-radius: 6px; }
            QPushButton { background-color: #17233d; color: #b8f7e6; border: 1px solid #3d7ea6; padding: 6px; }
            QPushButton:hover { background-color: #233a5d; }
        """)
        try:
            window.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, False)
            attach_math_decor(window, app=self, light=False)
        except Exception:
            pass
        main = QVBoxLayout(window)
        banner = QLabel(
            f"<b>{title}</b> — global-only · applies to <b>every instrument in parallel</b><br>"
            "<i>Does not read or write the composition seed.</i>"
        )
        banner.setWordWrap(True)
        main.addWidget(banner)

        if which == "script":
            editor = QTextEdit()
            editor.setPlainText(str(self.global_algo_state.get("script") or ""))
            main.addWidget(editor, 1)
            row = QHBoxLayout()
            btn_save = QPushButton("💾 Save Script Algo")
            btn_apply = QPushButton("▶ Apply to All Instruments")
            def _save_script():
                self.global_algo_state["script"] = editor.toPlainText()
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("🌐 Global Script Algo saved (seed untouched)")
            def _apply_script():
                self.global_algo_state["script"] = editor.toPlainText()
                self._apply_global_algo_to_ensemble("script")
            btn_save.clicked.connect(_save_script)
            btn_apply.clicked.connect(_apply_script)
            row.addWidget(btn_save)
            row.addWidget(btn_apply)
            main.addLayout(row)

        elif which == "domain":
            editor = QTextEdit()
            editor.setPlainText(str(self.global_algo_state.get("domain") or ""))
            main.addWidget(QLabel("Global domain equation / logic (ensemble-wide context)"))
            main.addWidget(editor, 1)
            row = QHBoxLayout()
            btn_save = QPushButton("💾 Save Domain Algo")
            btn_apply = QPushButton("▶ Apply to All Instruments")
            def _save_dom():
                self.global_algo_state["domain"] = editor.toPlainText()
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("🌐 Global Domain Algo saved (seed untouched)")
            def _apply_dom():
                self.global_algo_state["domain"] = editor.toPlainText()
                self._apply_global_algo_to_ensemble("domain")
            btn_save.clicked.connect(_save_dom)
            btn_apply.clicked.connect(_apply_dom)
            row.addWidget(btn_save)
            row.addWidget(btn_apply)
            main.addLayout(row)

        elif which == "wire":
            main.addWidget(QLabel("Global modular wires — routes applied across the full roster in parallel."))
            src_box = QComboBox()
            tgt_box = QComboBox()
            names = list(getattr(self, "instrument_names_48", []) or [])
            src_box.addItems(names)
            tgt_box.addItems(names)
            detector_box = QComboBox()
            detector_box.addItems(["phase", "energy", "spectrum", "rms", "onset", "harmonic", "seed", "domain", "pair"])
            question_edit = QLineEdit()
            question_edit.setPlaceholderText("algorithmic question / target")
            subject_edit = QLineEdit()
            subject_edit.setPlaceholderText("algorithmic subject")
            weight = QDoubleSpinBox()
            weight.setRange(0.0, 2.0)
            weight.setSingleStep(0.05)
            weight.setValue(0.5)
            weight.setDecimals(3)
            form = QHBoxLayout()
            form.addWidget(QLabel("Source"))
            form.addWidget(src_box, 1)
            form.addWidget(QLabel("→ Target"))
            form.addWidget(tgt_box, 1)
            form.addWidget(QLabel("Weight"))
            form.addWidget(weight)
            main.addLayout(form)
            sem = QHBoxLayout()
            sem.addWidget(QLabel("Detector")); sem.addWidget(detector_box, 1)
            sem.addWidget(QLabel("Question")); sem.addWidget(question_edit, 2)
            sem.addWidget(QLabel("Subject")); sem.addWidget(subject_edit, 2)
            main.addLayout(sem)
            log = QTextEdit()
            log.setReadOnly(True)
            wires = self.global_algo_state.get("wire") or []
            if not isinstance(wires, list):
                wires = []
                self.global_algo_state["wire"] = wires
            def _refresh_log():
                lines = ["# Global Wire Algo (ensemble)"]
                for w in self.global_algo_state.get("wire") or []:
                    if isinstance(w, dict):
                        lines.append(f"- {w.get('source')} ====> {w.get('target')}  w={float(w.get('weight', 0.5)):.3f}  detector={w.get('detector','phase')}  q={w.get('question','')}  subject={w.get('subject','')}")
                log.setPlainText("\n".join(lines))
            _refresh_log()
            main.addWidget(log, 1)
            row = QHBoxLayout()
            btn_add = QPushButton("＋ Add Wire")
            btn_clear = QPushButton("Clear Wires")
            btn_apply = QPushButton("▶ Apply Wires to Ensemble")
            def _add():
                self.global_algo_state.setdefault("wire", []).append({
                    "source": src_box.currentText(),
                    "target": tgt_box.currentText(),
                    "weight": float(weight.value()),
                    "detector": detector_box.currentText(),
                    "question": question_edit.text(),
                    "subject": subject_edit.text(),
                    "origin": "global_player",
                    "user_defined": True,
                    "user_data": True,
                    "apply_enabled": bool(gas.get("apply_enabled", False)),
                })
                _refresh_log()
            def _clear():
                self.global_algo_state["wire"] = []
                _refresh_log()
            def _apply_w():
                self._apply_global_algo_to_ensemble("wire")
            btn_add.clicked.connect(_add)
            btn_clear.clicked.connect(_clear)
            btn_apply.clicked.connect(_apply_w)
            row.addWidget(btn_add)
            row.addWidget(btn_clear)
            row.addWidget(btn_apply)
            main.addLayout(row)

        else:  # params
            params = dict(self.global_algo_state.get("params") or {})
            mix = QDoubleSpinBox()
            mix.setRange(0.0, 1.0)
            mix.setSingleStep(0.05)
            mix.setDecimals(3)
            mix.setValue(float(params.get("mix", 0.35)))
            mix.setToolTip("Blend of global algo into each instrument panel (0=off, 1=full). Seed is never touched.")
            chk_s = QCheckBox("Enable Script Algo")
            chk_d = QCheckBox("Enable Domain Algo")
            chk_w = QCheckBox("Enable Wire Algo")
            chk_s.setChecked(bool(params.get("enable_script", True)))
            chk_d.setChecked(bool(params.get("enable_domain", True)))
            chk_w.setChecked(bool(params.get("enable_wire", True)))
            main.addWidget(QLabel("Global algo mix into ensemble panels"))
            main.addWidget(mix)
            main.addWidget(chk_s)
            main.addWidget(chk_d)
            main.addWidget(chk_w)
            main.addStretch(1)
            row = QHBoxLayout()
            btn_save = QPushButton("💾 Save Params")
            btn_apply = QPushButton("▶ Apply All Enabled Algos")
            def _save_p():
                self.global_algo_state["params"] = {
                    "mix": float(mix.value()),
                    "enable_script": bool(chk_s.isChecked()),
                    "enable_domain": bool(chk_d.isChecked()),
                    "enable_wire": bool(chk_w.isChecked()),
                }
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("🌐 Global Algo Params saved (seed untouched)")
            def _apply_p():
                _save_p()
                p = self.global_algo_state["params"]
                if p.get("enable_script"):
                    self._apply_global_algo_to_ensemble("script")
                if p.get("enable_domain"):
                    self._apply_global_algo_to_ensemble("domain")
                if p.get("enable_wire"):
                    self._apply_global_algo_to_ensemble("wire")
            btn_save.clicked.connect(_save_p)
            btn_apply.clicked.connect(_apply_p)
            row.addWidget(btn_save)
            row.addWidget(btn_apply)
            main.addLayout(row)

        setattr(self, attr, window)
        window.show()
        window.raise_()
        window.activateWindow()

    def _global_domain_hints(self, expression):
        """Deterministically derive compact algorithmic hints/transmutor pathways from a domain expression."""
        text = str(expression or "").lower()
        hints = []
        families = (("sin", "phase oscillator"), ("cos", "quadrature / phase pair"),
                    ("tan", "nonlinear phase fold"), ("log", "logarithmic scale transmutor"),
                    ("exp", "exponential growth/decay transmutor"), ("sqrt", "root geometry"),
                    ("abs", "fold / symmetry detector"), ("mod", "residue-class detector"),
                    ("^", "power-law transmutor"), ("*", "gain/convolution pathway"))
        for token, desc in families:
            if token in text:
                hints.append(desc)
        if not hints:
            hints.append("identity / direct-domain pathway")
        if "t" in text:
            hints.append("time-domain detector")
        if "x" in text or "y" in text or "z" in text:
            hints.append("coordinate transmutor")
        return hints

    def _unapply_global_algo_from_ensemble(self):
        """Remove only the global-algo overlay, leaving user/canonical material intact."""
        try:
            for name, st in (getattr(self, "instrument_param_state", {}) or {}).items():
                if isinstance(st, dict):
                    st.pop("global_script_algo", None)
                    st.pop("global_algo_mix", None)
                    st.pop("global_algo_user_data", None)
                    st.pop("global_algo_apply_enabled", None)
            engine = getattr(self, "domain_eq_engine", None)
            if engine is not None:
                engine.domains = [d for d in (getattr(engine, "domains", []) or [])
                                  if not (isinstance(d, dict) and d.get("source") == "global_player")]
            self.patch_connections = [c for c in (getattr(self, "patch_connections", []) or [])
                                      if not (isinstance(c, dict) and c.get("origin") == "global_player")]
            for entry in (getattr(self, "master_playlist_data", []) or []):
                if isinstance(entry, dict):
                    entry.pop("global_algorithm_scope", None)
                    entry.pop("global_algorithm_applied", None)
                    entry.pop("global_algorithm_kinds", None)
            if hasattr(self, "_on_live_source_changed"):
                self._on_live_source_changed()
        except Exception as e:
            print(f"[GlobalAlgo] unapply: {e}")

    def _apply_global_algo_to_ensemble(self, which):
        """Broadcast a Global Player algo to every instrument in parallel.

        Never mutates input_seed_val / get_numeric_seed / seed scripts.
        Script → instrument_scripts (appended marker, global_algo store is source of truth)
        Domain → domain_eq_engine domains with source=global_player
        Wire → patch_connections with origin=global_player
        """
        which = str(which or "").lower()
        names = list(getattr(self, "instrument_names_48", []) or [])
        gas = getattr(self, "global_algo_state", {}) or {}
        params = gas.get("params") if isinstance(gas.get("params"), dict) else {}
        mix = float(params.get("mix", 0.35))
        amount_key = {"script":"script_amount", "domain":"domain_amount", "wire":"wire_amount"}.get(which)
        amount = float(params.get(amount_key, 1.0)) if amount_key else 1.0
        mix = max(0.0, min(1.0, mix * max(0.0, min(1.0, amount))))
        n_touched = 0

        # Playlist rows are the visible global composition surface. Mark every
        # global row so Save/Load/autosave and the canonical fingerprint retain
        # exactly which global algorithm overlays were applied.
        for _row in (getattr(self, "master_playlist_data", []) or []):
            if isinstance(_row, dict):
                _row["global_algorithm_scope"] = "global"
                _row["global_algorithm_applied"] = True
                _kinds = list(_row.get("global_algorithm_kinds") or [])
                if which not in _kinds: _kinds.append(which)
                _row["global_algorithm_kinds"] = _kinds

        if which == "script":
            body = str(gas.get("script") or "")
            if not hasattr(self, "instrument_scripts") or self.instrument_scripts is None:
                self.instrument_scripts = {}
            # Store parallel global overlay; do not clobber user local scripts blindly —
            # keep local script and attach a global_algo pointer in param state.
            for name in names:
                st = (getattr(self, "instrument_param_state", {}) or {}).setdefault(name, {})
                if not isinstance(st, dict):
                    continue
                st["global_script_algo"] = body
                st["global_algo_mix"] = mix
                st["global_algo_user_data"] = True
                st["global_algo_apply_enabled"] = bool(gas.get("apply_enabled", False))
                n_touched += 1

        elif which == "domain":
            body = str(gas.get("domain") or "")
            engine = getattr(self, "domain_eq_engine", None)
            if engine is not None:
                # Replace previous global_player domains only; keep user_defined
                existing = [d for d in (getattr(engine, "domains", None) or [])
                            if isinstance(d, dict) and d.get("source") != "global_player"]
                generated = []
                for i, name in enumerate(names):
                    generated.append({
                        "name": f"global_player::{name}",
                        "axis": "time",
                        "t0": 0.0, "t1": 1.0,
                        "x0": -1.0, "x1": 1.0, "y0": -1.0, "y1": 1.0,
                        "logic": "True",
                        "equation": body.split("equation =")[-1].strip().strip('"').strip("'") if "equation" in body else "sin(t * MEUM)",
                        "limit_lo": -1.0, "limit_hi": 1.0,
                        "weight": mix,
                        "user_defined": False,
                        "source": "global_player",
                        "user_data": True,
                        "apply_enabled": bool(gas.get("apply_enabled", False)),
                    })
                    n_touched += 1
                engine.domains = existing + generated

        elif which == "wire":
            wires = gas.get("wire") or []
            if not hasattr(self, "patch_connections") or self.patch_connections is None:
                self.patch_connections = []
            # Drop previous global_player wires, keep others
            self.patch_connections = [
                c for c in self.patch_connections
                if not (isinstance(c, dict) and c.get("origin") == "global_player")
            ]
            for w in wires:
                if not isinstance(w, dict):
                    continue
                self.patch_connections.append({
                    "source": w.get("source"),
                    "target": w.get("target"),
                    "weight": float(w.get("weight", 0.5)) * mix,
                    "origin": "global_player",
                    "user_defined": True,
                    "user_data": True,
                    "apply_enabled": bool(gas.get("apply_enabled", False)),
                })
                n_touched += 1

        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(
                f"🌐 Global {which} algo → {n_touched} ensemble writes · seed untouched"
            )
        return n_touched

    def spawn_floating_window(self, attr_name, window_title):
        window = getattr(self, attr_name, None)

        if window is None or not window.isVisible():
            window = QWidget(None, Qt.WindowType.Window)
            window.setWindowTitle(window_title)

            # UI_LAYOUT_2026: floating windows that scroll (Synth Editor / EDIT SYNTH,
            # Patch Modular) open sized to fit their contents but stay freely
            # resizable — a fixed cramped resize() no longer fights the scroll area.
            if attr_name == 'playlist_window':
                window.resize(1300, 875)
            elif attr_name == 'patch_bay_dialog':
                window.resize(1000, 780)
                window.setMinimumSize(640, 480)
            elif attr_name == 'synth_editor_window':
                window.resize(820, 640)
                window.setMinimumSize(520, 420)
            else:
                window.resize(750, 550)
            window.setSizeGripEnabled(True) if hasattr(window, "setSizeGripEnabled") else None

            main_layout = QVBoxLayout(window)

            current_instrument = self.instrument_selector_dropdown.currentText() if hasattr(self, 'instrument_selector_dropdown') else "Z-Pinch Resonator"
            inst_index = self.instrument_names_48.index(current_instrument) + 1 if current_instrument in self.instrument_names_48 else 1
            # When Edit-panels-per-sequence is ON, load the active sequence's
            # panel overrides into live stores before opening any of the four
            # panel editors so the floating UI shows sequence-local state.
            if attr_name in ('synth_editor_window', 'script_editor_window', 'patch_bay_dialog') or attr_name == 'domain_eq':
                if self._panels_per_sequence_enabled():
                    try:
                        self._apply_sequence_panels_to_live(current_instrument)
                    except Exception as _exc:
                        print(f"[Panels] pre-open apply: {_exc}")

            if attr_name == 'playlist_window':
                main_layout.addWidget(QLabel(
                    "📜 Unquantized Global Playlist — 96 blank rows · paint identity / steps / automation · "
                    "overlap blends synth params · snap-to-grid optional"
                ))

                time_scale_layout = QHBoxLayout()
                time_scale_layout.addWidget(QLabel("Row time base:"))
                time_scale_combo = QComboBox()
                time_scale_combo.addItems(["Unquantized Free-Time", "Snap to Grid"])
                time_scale_combo.setCurrentIndex(0)  # default = unquantized free time
                self.playlist_row_time_base = "free"
                time_scale_combo.currentIndexChanged.connect(
                    lambda idx: setattr(self, "playlist_row_time_base", "grid" if idx == 1 else "free")
                )
                time_scale_layout.addWidget(time_scale_combo)
                time_scale_layout.addStretch(1)
                main_layout.addLayout(time_scale_layout)

                # 48 rows unbound to a fixed instrument — activity painted freely
                rows = min(1024, max(1, int(self.spin_playlist_length.value()) if hasattr(self, 'spin_playlist_length') else 96))
                if hasattr(self, 'spin_playlist_length'):
                    self.spin_playlist_length.setValue(rows)
                track_table = PaintbrushTable(self, rows, PLAYLIST_COLUMN_COUNT)
                self.active_paint_table = track_table
                if not hasattr(self, 'playlist_automation') or self.playlist_automation is None:
                    self.playlist_automation = [{} for _ in range(rows)]

                track_table.setHorizontalHeaderLabels(list(PLAYLIST_HEADER_LABELS))
                try:
                    track_table.setColumnCount(PLAYLIST_COLUMN_COUNT)
                    _hdr = track_table.horizontalHeader()
                    for _ci in range(PLAYLIST_COLUMN_COUNT):
                        _hdr.setSectionResizeMode(_ci, QHeaderView.ResizeMode.Stretch)
                    _hdr.setStretchLastSection(False)
                except Exception:
                    pass

                palette_colors = [
                    QColor(20, 90, 100), QColor(70, 30, 90), QColor(20, 90, 40),
                    QColor(90, 50, 20), QColor(90, 20, 30), QColor(30, 40, 90)
                ]

                def safe_set_cell(r, c, text, bg_color=None):
                    # Safe helper to populate table cells bypassing binding strictness
                    item = track_table.item(r, c)
                    if item is None:
                        item = QTableWidgetItem(text)
                        if bg_color:
                            item.setBackground(bg_color)
                        track_table.model().setData(track_table.model().index(r, c), text, Qt.ItemDataRole.DisplayRole)
                        # Ensure cell background is correctly set via model if item is created raw
                        track_table.setItem(r, c, item)
                    else:
                        item.setText(text)
                        if bg_color:
                            item.setBackground(bg_color)

                def update_time_markers():
                    selection_text = time_scale_combo.currentText()
                    # POWER_V3_EMPTY_PLAYLIST: timing is generated only for rows that
                    # actually contain a painted/programmed event. Opening the editor
                    # therefore does not silently turn 96 blank rows into playlist data.
                    for row_idx in range(rows):
                        data_entry = self.master_playlist_data[row_idx] if row_idx < len(self.master_playlist_data) else {}
                        has_content = isinstance(data_entry, dict) and any(
                            v not in (None, "", [], {}) for k, v in data_entry.items()
                            if k not in ("time_marker",)
                        )
                        if not has_content:
                            continue
                        if "Unquantized" in selection_text:
                            time_str = f"Free-Time [{row_idx * MEUM_CONSTANT:.2f}s]"
                        else:
                            step_seconds = 60.0 if "60.0s" in selection_text else (30.0 if "30.0s" in selection_text else (15.0 if "15.0s" in selection_text else (3.5 if "3.5s" in selection_text else 1.0)))
                            total_seconds = row_idx * step_seconds
                            time_str = f"T + {int(total_seconds // 60)}m {int(total_seconds % 60)}s" if total_seconds >= 60 else f"T + {total_seconds:.1f}s"
                        track_table.set_cell_item(row_idx, 0, QTableWidgetItem(time_str))
                    self.sync_playlist_grid_to_memory()

                time_scale_combo.currentIndexChanged.connect(update_time_markers)

                for row_idx in range(rows):
                    data_entry = self.master_playlist_data[row_idx] if row_idx < len(self.master_playlist_data) else {}

                    empty = not any(v not in (None, "", [], {}) for v in data_entry.values())
                    item_inst = QTableWidgetItem("" if empty else str(data_entry.get("operator", "")))
                    if not empty:
                        item_inst.setBackground(palette_colors[row_idx % len(palette_colors)])
                    track_table.set_cell_item(row_idx, 0, QTableWidgetItem("" if empty else str(data_entry.get("time_marker", ""))))
                    track_table.set_cell_item(row_idx, 1, item_inst)
                    track_table.set_cell_item(row_idx, 2, QTableWidgetItem("" if empty else str(data_entry.get("script_tag", ""))))
                    track_table.set_cell_item(row_idx, 3, QTableWidgetItem("" if empty else str(data_entry.get("domain_tag", ""))))
                    track_table.set_cell_item(row_idx, 4, QTableWidgetItem("" if empty else str(data_entry.get("synth_tag", ""))))
